INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('059b4eb3-f42e-460b-b4bb-dd373cc0c964', 817, 'odd_one_out', 'B2', 'money', 'Three of these relate to economic problems. Which is the odd one out?', 'dividend', '["inflation", "recession", "deficit", "dividend"]', NULL, NULL, NULL, NULL, 'Inflation (rising prices), recession (economic decline), and deficit (spending more than you earn) are all economic problems. A dividend is a positive payout to investors — not a problem unless you are the one paying it!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3da3f215-3ad1-4b66-8141-12aeb97e4159', 744, 'multiple_choice', 'A1', 'home', 'Which of these is a room in a house?', 'All of these', '["balcony", "corridor", "kitchen", "All of these"]', NULL, NULL, NULL, NULL, 'A kitchen is where you cook, a corridor connects rooms, and a balcony is an outdoor platform. All are parts of a home!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('575b0d75-f7b3-4c49-8cea-32e82e9d7151', 72, 'gap_fill', 'B1', 'countable_uncountable', 'Would you like ___ (a / an / some) apple?', 'an', NULL, NULL, NULL, NULL, 'Apple is countable', 'Use a/an with singular countable nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d150a71-0027-4e0e-85b3-234a3b8faaaa', 746, 'multiple_choice', 'A2', 'health', 'Which word means "a doctor who looks after your teeth"?', 'dentist', '["dentist", "pharmacist", "surgeon", "optician"]', NULL, NULL, NULL, NULL, 'A dentist looks after your teeth. An optician checks your eyes, a pharmacist gives you medicine, and a surgeon performs operations.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('adc88b04-78bc-4be4-b09a-0096d9a141ec', 1122, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A tile with a rough, uneven surface texture is described as _______.', 'textured', '["textured", "matte", "glazed", "polished"]', NULL, NULL, NULL, NULL, 'A textured tile has an uneven, tactile surface. This increases grip — making textured tiles suitable for wet areas or floor applications where slip resistance matters.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d24c203b-4396-4a17-84c9-9a34cf7d1b78', 1123, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing which we sit or lay in to wash ourselves is called a _______.', 'bath', '["basin", "bath", "sink", "bowl"]', NULL, NULL, NULL, NULL, 'Some people may use bathtub as an equivalent to bath, it means the same thing.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('beaf4c35-6085-4c32-b9ca-bb1421760ecd', 1124, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'A _______ finish on a tile reflects light and appears shiny.', 'glossy', '["glossy", "matte", "satin", "textured"]', NULL, NULL, NULL, NULL, 'A glossy finish reflects light and gives tiles a shiny appearance. It is popular for walls but can be slippery underfoot, making it less suitable for floor applications in wet areas.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('204fd6de-f4ae-4ee6-8994-6da5cdc46972', 1125, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing which we look in to see ourselves is called a _______.', 'mirror', '["mirror", "reflection", "reflective", "miror"]', NULL, NULL, NULL, NULL, 'Mirrors come in many shpes and sizes, and sometimes we combine words to describe them: full-length mirror, fitted mirror etc. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0bd8542d-d05a-45b7-9b67-f6739cdb2429', 1126, 'multiple_choice', 'A2', 'bathroom_vocabulary', 'The thing we put our towels on is called a towel _______.', 'rail', '["rule", "rail", "rale", "rile"]', NULL, NULL, NULL, NULL, 'Towel rails are put close to baths, showers and basins to keep towels ''handy'', where we need them. Often now bathrooms have ''heated towel rails''. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('339f1888-38a9-4716-813b-73847b0b88e6', 752, 'multiple_choice', 'A2', 'social', 'What does "Can I have the bill, please?" mean in a restaurant?', 'I want to pay.', '["I want to pay.", "I want more food.", "I want a table.", "I want the menu."]', NULL, NULL, NULL, NULL, '"The bill" is the piece of paper showing how much you owe. Asking for it means you are ready to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9fdd76fe-fa5b-432c-a2b2-1bd65cb21d09', 754, 'multiple_choice', 'A2', 'money', 'Which of these is NOT a way to pay in a shop?', 'receipt', '["cash", "credit card", "contactless", "receipt"]', NULL, NULL, NULL, NULL, 'A receipt is the piece of paper you get AFTER paying — it is not a payment method. Cash, card, and contactless are all ways to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3df8a275-6cdc-409f-be67-f5ba282dbeed', 910, 'sentence_auction', 'A2', 'spanish', 'Theme: Tener Expressions', 'auction', '[{"correct": true, "sentence": "Tengo mucho frío — necesito un abrigo.", "explanation": "Correct! Use tener frío for the physical sensation of being cold."}, {"correct": false, "sentence": "Estoy mucha hambre después del entreno.", "explanation": "Wrong — use tener for physical sensations, not estar: Tengo mucha hambre."}, {"correct": true, "sentence": "El niño tiene sueño y quiere dormir.", "explanation": "Correct! Tener sueño means to be sleepy."}, {"correct": false, "sentence": "Soy veintiocho años.", "explanation": "Wrong — use tener for age, not ser: Tengo veintiocho años."}, {"correct": true, "sentence": "Tenemos prisa — el tren sale en cinco minutos.", "explanation": "Correct! Tener prisa means to be in a hurry."}, {"correct": false, "sentence": "¿Estás sed? Hay agua en la mesa.", "explanation": "Wrong — use tener for thirst: ¿Tienes sed?"}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6e2696bb-f2bc-4731-9e9d-f498afe3ebdb', 892, 'multiple_choice', 'A2', 'spanish', 'Which word means "always" in Spanish?', 'siempre', '["siempre", "nunca", "a veces", "también"]', NULL, NULL, NULL, NULL, '"Siempre" = always. Other frequency adverbs: "nunca" = never, "a veces" = sometimes, "también" = also/too.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('09b848ea-514d-4093-ad89-407963aee04e', 888, 'multiple_choice', 'A2', 'spanish', 'What does "el desayuno" mean in English?', 'Breakfast', '["Breakfast", "Lunch", "Dinner", "Snack"]', NULL, NULL, NULL, NULL, '"El desayuno" means breakfast. The other meals are: "la comida/el almuerzo" (lunch), "la cena" (dinner), and "la merienda" (afternoon snack).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5cf2fda-9578-4d72-a165-1f0f08a7ce97', 577, 'multiple_choice', 'C2', 'advanced_grammar', 'The proposal, ___ promising on paper, proved impractical.', 'while', '["despite", "while", "even", "however"]', NULL, NULL, NULL, NULL, 'While + adjective: concessive clause. While promising = although it was promising. Whilst would also work well here, and suits the formality of the rest of the text.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('22bfc29f-cc28-4b87-9c8f-679dfa6c9bcb', 891, 'multiple_choice', 'A2', 'spanish', 'What is the plural of "el libro"?', 'los libros', '["los libros", "las libros", "los libro", "el libros"]', NULL, NULL, NULL, NULL, 'To make a noun plural in Spanish, add -s to words ending in a vowel. The article also changes: "el" becomes "los". So "el libro" becomes "los libros".', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2961b1b-c283-47fb-abdc-36934feb2028', 904, 'multiple_choice', 'A2', 'spanish', 'How do you make a polite request in Spanish? "_____ un café, por favor."', 'Quisiera', '["Quisiera", "Quiero", "Tengo", "Necesito"]', NULL, NULL, NULL, NULL, '"Quisiera" (I would like) is the polite form for requests — it is the conditional of "querer". "Quiero" (I want) is correct but less polite. Use "quisiera" in shops and restaurants and formal settings. Me gustaría tener/tomar is similar: I would like to have. In Spanish we are often more direct.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c837c352-a8a4-407d-bc51-51c1e09e57ef', 895, 'multiple_choice', 'A2', 'spanish', 'Choose the correct sentence: "_____ las tres de la tarde."', 'Son', '["Son", "Es", "Están", "Hay"]', NULL, NULL, NULL, NULL, 'Use "son" for all times except 1 o''clock: "Son las tres." Use "es" only for "Es la una." "Están" and "hay" are never used for telling the time.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7ff3c738-9a7c-4f38-97d1-dc3e7bc3cf5c', 893, 'multiple_choice', 'A2', 'spanish', 'How do you say "I have a headache" in Spanish?', 'Tengo dolor de cabeza', '["Tengo dolor de cabeza", "Estoy dolor de cabeza", "Tengo duele de cabeza", "Soy dolor de cabeza"]', NULL, NULL, NULL, NULL, 'Use "tener dolor de + body part" for pain: "tengo dolor de cabeza" (headache), "tengo dolor de espalda" (backache), "tengo dolor de estómago" (stomach ache).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('119ee8aa-4e57-4cb3-93b5-e670f9067fa4', 894, 'multiple_choice', 'A2', 'spanish', 'What does "el ayuntamiento" mean in English?', 'Town hall', '["Town hall", "Hospital", "School", "Train station"]', NULL, NULL, NULL, NULL, '"El ayuntamiento" is the town hall or city hall. "El hospital" = hospital, "el colegio" = school, "la estación de tren" = train station. It is often used to describe the local authority as well as just the building.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d4ffc5a-e4fd-4f69-be1a-d9fd4b732635', 896, 'multiple_choice', 'A2', 'spanish', 'What does "tomar el sol" mean in English?', 'To sunbathe', '["To sunbathe", "To drink coffee", "To have lunch", "To go for a walk"]', NULL, NULL, NULL, NULL, '"Tomar el sol" literally means to take the sun — it means to sunbathe. Other "tomar" expressions: "tomar un café" (to have a coffee), "tomar el autobús" (to take the bus).', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c9fc51a-6c1c-4a05-b593-faaba543afa8', 897, 'multiple_choice', 'A2', 'spanish', 'Which adjective means "tired" in Spanish?', 'cansado', '["cansado", "contento", "enfadado", "aburrido"]', NULL, NULL, NULL, NULL, '"Cansado" = tired. "Contento" = happy, "enfadado" = angry, "aburrido" = bored. Remember adjectives change ending for gender: "cansada" for feminine.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8dbd53cd-4c78-4738-b364-42f6975cf564', 899, 'multiple_choice', 'A2', 'spanish', 'What does "cada día" mean in English?', 'Every day', '["Every day", "Some days", "All day", "The next day"]', NULL, NULL, NULL, NULL, '"Cada" means each/every, so "cada día" = every day. Compare: "todo el día" = all day, "al día siguiente" = the next day, "algunos días" = some days.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7ca22b50-1cee-4dfc-ad33-2b5573ce5c88', 900, 'multiple_choice', 'A2', 'spanish', 'Which sentence is grammatically correct?', 'Me gustan los libros', '["Me gusta los libros", "Me gustan los libros", "Me gusta el libros", "Me gustas los libros"]', NULL, NULL, NULL, NULL, '"Gustar" agrees with the subject (the thing that is liked), not the person. Since "los libros" is plural, use "gustan". Literally: books are pleasing to me.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('063bde28-8585-4e2c-8d9b-f1425ef95fee', 902, 'multiple_choice', 'A2', 'spanish', 'How do you say "I get up at 7 in the morning" in Spanish?', 'Me levanto a las 7', '["Me levanto a las 7", "Me levanto las 7", "Levanto a las 7", "Me levantó a las 7"]', NULL, NULL, NULL, NULL, '"Levantarse" is a reflexive verb, so it needs a reflexive pronoun: "me levanto". Always use "a las" before the time. "Me levantó" is a past tense form, not present.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dd0df7ca-6f0f-4341-afa5-5a31aa331fd9', 1250, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The legal team spent weeks _____ the terms of the licensing agreement.', 'thrashing out', '[]', NULL, NULL, NULL, NULL, 'Thrash out means to discuss something at length until an agreement is reached. Compare: hammer out, iron out, work out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a3beb944-2911-4887-9632-5abf78cbbe21', 903, 'multiple_choice', 'A2', 'spanish', 'What is the opposite of "barato" in Spanish?', 'caro', '["caro", "pequeño", "lejos", "tarde"]', NULL, NULL, NULL, NULL, '"Barato" = cheap, so its opposite is "caro" = expensive. "Pequeño" = small, "lejos" = far, "tarde" = late.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9382e0d4-1c93-4296-bf3c-4f56abf8875f', 905, 'multiple_choice', 'A2', 'spanish', 'Which sentence uses "estar" correctly?', 'El café está frío', '["El café está frío", "El café es frío", "El café está grande", "El café es delicioso"]', NULL, NULL, NULL, NULL, 'Use "estar" for temporary states or conditions. "El café está frío" = the coffee is cold right now. "Es grande" describes permanent size and "es delicioso" is a permanent characteristic, so "ser" is correct for those.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7dd1eacf-44f3-4924-aaa7-f9b4b0d36d65', 906, 'multiple_choice', 'A2', 'spanish', 'What does "¿Cuánto cuesta?" mean in English?', 'How much does it cost?', '["How much does it cost?", "How many are there?", "What time is it?", "How far is it?"]', NULL, NULL, NULL, NULL, '"¿Cuánto cuesta?" = How much does it cost? Essential for shopping. "¿Cuántos hay?" = How many are there?, "¿Qué hora es?" = What time is it?', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8a3e79a5-3502-4eaf-a517-ffdd60c9b1de', 907, 'multiple_choice', 'A2', 'spanish', 'Which word correctly completes the sentence: "Fui al supermercado _____ comprar leche."', 'para', '["para", "por", "que", "a"]', NULL, NULL, NULL, NULL, 'Use "para" to express purpose (in order to): "fui al supermercado para comprar leche" = I went to the supermarket to buy milk. "Por" is used for cause or reason, not purpose with an infinitive.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('00440d6d-f043-4484-ba89-40ac23b4bac5', 908, 'sentence_auction', 'A2', 'spanish', 'Theme: Ser vs Estar', 'auction', '[{"correct": true, "sentence": "El café está frío.", "explanation": "Correct! Use estar for a temporary state — the coffee is cold right now."}, {"correct": false, "sentence": "Ella es cansada hoy.", "explanation": "Wrong — use estar for temporary states: Ella está cansada hoy."}, {"correct": true, "sentence": "Mi hermano es médico.", "explanation": "Correct! Use ser for permanent characteristics like profession."}, {"correct": false, "sentence": "Estoy de España.", "explanation": "Wrong — use ser for origin: Soy de España."}, {"correct": true, "sentence": "La reunión es a las tres.", "explanation": "Correct! Use ser for scheduled events and times."}, {"correct": false, "sentence": "El mercado es cerrado los domingos.", "explanation": "Wrong — use estar for states and conditions: El mercado está cerrado los domingos."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0926-0926-0926-000000000926', 926, 'matching', 'A2', 'spanish', 'Match each Spanish verb to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "madrugar"}, "right": {"type": "text", "content": "to get up early"}}, {"left": {"type": "text", "content": "quedarse"}, "right": {"type": "text", "content": "to stay / to remain"}}, {"left": {"type": "text", "content": "llevar"}, "right": {"type": "text", "content": "to carry / to wear"}}, {"left": {"type": "text", "content": "tardar"}, "right": {"type": "text", "content": "to take a long time / to be late"}}, {"left": {"type": "text", "content": "apagar"}, "right": {"type": "text", "content": "to turn off / to switch off"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0927-0927-0927-000000000927', 927, 'matching', 'A2', 'spanish', 'Match each Spanish adjective to its opposite.', 'match_all_pairs', '[{"left": {"type": "text", "content": "temprano"}, "right": {"type": "text", "content": "tarde"}}, {"left": {"type": "text", "content": "lleno"}, "right": {"type": "text", "content": "vacío"}}, {"left": {"type": "text", "content": "limpio"}, "right": {"type": "text", "content": "sucio"}}, {"left": {"type": "text", "content": "tranquilo"}, "right": {"type": "text", "content": "ruidoso"}}, {"left": {"type": "text", "content": "seguro"}, "right": {"type": "text", "content": "peligroso"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0928-0928-0928-000000000928', 928, 'matching', 'A2', 'spanish', 'Match each sentence to the correct use of ser or estar.', 'match_all_pairs', '[{"left": {"type": "text", "content": "Soy profesora."}, "right": {"type": "text", "content": "ser — permanent identity / profession"}}, {"left": {"type": "text", "content": "Estoy cansada."}, "right": {"type": "text", "content": "estar — temporary state"}}, {"left": {"type": "text", "content": "La reunión es a las diez."}, "right": {"type": "text", "content": "ser — time / scheduled events"}}, {"left": {"type": "text", "content": "El café está frío."}, "right": {"type": "text", "content": "estar — current condition"}}, {"left": {"type": "text", "content": "Somos de Madrid."}, "right": {"type": "text", "content": "ser — origin"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0929-0929-0929-000000000929', 929, 'matching', 'A2', 'spanish', 'Match each Spanish time expression to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "a veces"}, "right": {"type": "text", "content": "sometimes"}}, {"left": {"type": "text", "content": "hace poco"}, "right": {"type": "text", "content": "a short time ago"}}, {"left": {"type": "text", "content": "de vez en cuando"}, "right": {"type": "text", "content": "from time to time"}}, {"left": {"type": "text", "content": "enseguida"}, "right": {"type": "text", "content": "straight away / immediately"}}, {"left": {"type": "text", "content": "a partir de ahora"}, "right": {"type": "text", "content": "from now on"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0930-0930-0930-000000000930', 930, 'matching', 'A2', 'spanish', 'Match each Spanish phrase to its English meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "¿Qué tal?"}, "right": {"type": "text", "content": "How are things? / How are you?"}}, {"left": {"type": "text", "content": "Me da igual."}, "right": {"type": "text", "content": "I don''t mind. / It''s all the same to me."}}, {"left": {"type": "text", "content": "No me apetece."}, "right": {"type": "text", "content": "I don''t feel like it."}}, {"left": {"type": "text", "content": "Está bien."}, "right": {"type": "text", "content": "It''s fine. / OK."}}, {"left": {"type": "text", "content": "¿A qué hora quedamos?"}, "right": {"type": "text", "content": "What time shall we meet?"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:54:35.474351+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be00554d-73f8-47b7-8e81-e1095e8e49aa', 505, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The police are ___ the case thoroughly.', 'looking into', '["looking over", "looking out", "looking up", "looking into"]', NULL, NULL, NULL, NULL, 'Look into = investigate, examine in detail.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('348c5757-568e-40a1-9565-194b6a6a2815', 51, 'gap_fill', 'B1', 'phrasal_verbs', 'Can you ___ (look _ _ _ _ _ ) my cats while I''m on holiday please?', 'look after', NULL, NULL, NULL, NULL, 'Look after means to take care of', 'Look after means to take care of someone or something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dadcecae-85d0-4b4d-8e88-041778061344', 124, 'multiple_choice', 'B2', 'phrasal_verbs', 'The meeting has been ___ until next week.', 'put off', '["put on", "put off", "put down", "put up"]', NULL, NULL, NULL, NULL, 'Put off means to postpone.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('33fa4021-27fb-47b6-9957-fcca93cc4d1f', 64, 'gap_fill', 'B1', 'too_enough', 'I''m not tall ___ (_ _ _ _ _ _) to reach the top shelf.', 'enough', NULL, NULL, NULL, NULL, 'Enough comes after adjectives', 'Enough comes after adjectives and means sufficient.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Too & enough"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('88d0ef97-75fc-41b7-8e4c-ccbba76d3cfe', 194, 'multiple_choice', 'B2', 'phrasal_verbs_separable', 'I need to ___ this word ___ in the dictionary.', 'look / up', '["look / after", "look / up", "look / for", "look / into"]', NULL, NULL, NULL, NULL, 'Look up = search for information.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3d250083-fd0c-4f03-b906-546c07311493', 68, 'gap_fill', 'B1', 'making_suggestions', 'Let''s ___ (_ _ _) that new restaurant for lunch.', 'try', NULL, NULL, NULL, NULL, 'Let''s + infinitive without ''to''', 'Let''s is followed by the infinitive without ''to''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Making suggestions"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('521aac83-c8bb-4e62-ad73-39f31c30fd15', 503, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The company is trying to ___ costs by reducing staff.', 'cut down on', '["cut up", "cut off", "cut out", "cut down on"]', NULL, NULL, NULL, NULL, 'Cut down on = reduce the amount of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a479ab25-edf1-4ebc-852c-1abe08cc329f', 504, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'She ___ the job offer because the salary was too low.', 'turned down', '["turned off", "turned out", "turned up", "turned down"]', NULL, NULL, NULL, NULL, 'Turn down = reject, refuse an offer or invitation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ef45b6cd-6b4d-4410-bc42-8c6a748a9c76', 507, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I ___ the idea of moving abroad when I was younger.', 'toyed with', '["messed about", "played up", "toyed with", "fooled around"]', NULL, NULL, NULL, NULL, 'Toy with an idea = consider something casually without commitment.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4ae86c05-2ec5-4f07-a4a6-92f8178abea7', 509, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'The initial enthusiasm has ___ and people are losing interest.', 'worn off', '["worn out", "worn through", "worn down", "worn off"]', NULL, NULL, NULL, NULL, 'Wear off = gradually disappear or lose effect.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3e07c7b3-3543-42f4-b6ef-a4d57b5c8154', 511, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The project ___ much more expensive than we expected.', 'turned out', '["turned in", "turned out", "turned over", "turned up"]', NULL, NULL, NULL, NULL, 'Turn out = end up being, prove to be in the end.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90e93878-5f18-404d-8575-5f91f2b9f02d', 514, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The fire ___ before the firefighters arrived.', 'broke out', '["broke down", "broke out", "broke off", "broke up"]', NULL, NULL, NULL, NULL, 'Break out = start suddenly (fire, war, disease, argument).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fcac3ac7-748d-45f8-905a-8862855d61ad', 515, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'She ___ her responsibilities admirably during the crisis.', 'lived up to', '["lived through", "lived down", "lived on", "lived up to"]', NULL, NULL, NULL, NULL, 'Live up to = meet expectations or standards.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('146e8950-78dd-4cbd-975f-885857e188f3', 756, 'multiple_choice', 'A2', 'travel', 'Which word means "a trip you take for pleasure, usually abroad"?', 'holiday', '["errand", "journey", "holiday", "commute"]', NULL, NULL, NULL, NULL, 'A holiday is time off for rest and enjoyment. A commute is your daily travel to work. A journey is the act of travelling. An errand is a short task.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f423eea-0d4c-44c3-89ed-fcb9ef70f12e', 818, 'odd_one_out', 'C1', 'language/rhetoric', 'Three of these are figures of speech. Which is the odd one out?', 'conjunction', '["metaphor", "simile", "alliteration", "conjunction"]', NULL, NULL, NULL, NULL, 'Metaphor, simile, and alliteration are all literary or rhetorical figures of speech. A conjunction (and, but, because) is a grammatical function word — useful, but not a figure of speech.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c18ddb51-0cbc-47ee-8a00-892ce523ca48', 824, 'odd_one_out', 'C2', 'academic vocabulary', 'Three of these are philosophical traditions or schools of thought. Which is the odd one out?', 'capitalism', '["empiricism", "rationalism", "utilitarianism", "capitalism"]', NULL, NULL, NULL, NULL, 'Empiricism, rationalism, and utilitarianism are philosophical traditions concerned with knowledge and ethics. Capitalism is primarily an economic and political system — though it intersects with philosophy, it belongs to a different category here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f638c126-6af9-4863-99ac-ecee6483e125', 1199, 'sentence_building', 'B2', 'routines', 'La mayoría deseamos poder desarrollar mejores hábitos de sueño.', 'Most of us wish we could develop better sleep habits.', '["most", "of", "us", "wish", "we", "could", "develop", "better", "sleep", "habits", "all", "want", "build", "improve"]', NULL, NULL, NULL, NULL, 'Wish + could expresses a desire about the present that is not currently true. Could is the past form of can used in wish clauses.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9e6506e1-8e1c-41ed-8bcb-a79fd4949ac6', 1200, 'sentence_building', 'B1', 'routines', 'Me cuesta un rato sentirme completamente despierto por la mañana.', 'It takes me a while to feel fully awake in the morning.', '["it", "takes", "me", "a", "while", "to", "feel", "fully", "awake", "in", "the", "morning", "long", "be", "totally"]', NULL, NULL, NULL, NULL, 'It takes someone a while to do something describes the time needed to reach a state. Fully awake is more natural than totally awake.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2c100f83-064f-4bd4-b5e8-750d70173455', 1201, 'sentence_building', 'B2', 'routines', 'Mucha gente ha reducido poco a poco la cantidad de café que bebe.', 'Many people have gradually cut down on the amount of coffee they drink.', '["many", "people", "have", "gradually", "cut", "down", "on", "the", "amount", "of", "coffee", "they", "drink", "reduce", "slow", "quantity"]', NULL, NULL, NULL, NULL, 'Cut down on is a phrasal verb meaning to reduce the amount of something. The present perfect shows a change that connects past to present.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e211ba1f-744a-43d5-92ae-e33f03ebc604', 1202, 'sentence_building', 'B1', 'routines', 'Siempre se me olvida tomar las vitaminas por la mañana.', 'I keep forgetting to take my vitamins in the morning.', '["I", "keep", "forgetting", "to", "take", "my", "vitamins", "in", "the", "morning", "forget", "missed", "always", "remember"]', NULL, NULL, NULL, NULL, 'Keep + gerund describes a repeated action, often one that is frustrating or unintentional. Forgetting to take means repeatedly failing to remember.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('47c8a61c-9cf3-4524-8704-9b367bac048f', 1203, 'sentence_building', 'B2', 'routines', 'Dormir lo suficiente ha marcado una gran diferencia en mi productividad.', 'Getting enough sleep has made a huge difference to my productivity.', '["getting", "enough", "sleep", "has", "made", "a", "huge", "difference", "to", "my", "productivity", "make", "big", "sleeping", "great"]', NULL, NULL, NULL, NULL, 'A gerund (Getting) can be the subject of a sentence. Make a difference to is the correct collocation — not make a difference for.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('17663dea-889f-445c-a1cb-c9ade387608c', 1238, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'The new CEO plans to _____ the entire management structure.', 'shake up', '["shake up", "shake off", "shake down", "shake out"]', NULL, NULL, NULL, NULL, 'Shake up means to make major changes to an organisation or system. It implies disruption intended to improve things.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8df9564b-3a34-4754-a36c-64e288798356', 1239, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'We need to _____ our competitors'' pricing strategy before we set our own.', 'look into', '["look into", "go over", "draw up", "bring forward"]', NULL, NULL, NULL, NULL, 'Look into means to research or investigate something carefully before making a decision.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fc6c17f4-1c58-422f-bdcc-a1fe08c63289', 52, 'gap_fill', 'B1', 'phrasal_verbs', 'I need to ___ (find _ _ _ ) what time the train leaves.', 'find out', NULL, NULL, NULL, NULL, 'Find out means to discover information', 'Find out means to discover or learn information.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('87a926c3-95ae-4193-801e-7d32eae0e839', 53, 'gap_fill', 'B2', 'phrasal_verbs', 'The meeting has been ___ (put _ _ _) until next week.', 'put off', NULL, NULL, NULL, NULL, 'Put off means to postpone', 'Put off means to postpone or delay something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9bf53a6e-cdc7-4595-b08f-b8058b52b707', 54, 'gap_fill', 'B2', 'phrasal_verbs', 'It took me ages to ___ (work _ _ _) the answer to that problem.', 'work out', NULL, NULL, NULL, NULL, 'Work out means to solve or calculate', 'Work out means to solve a problem or calculate something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c2daee1-6154-4e35-963b-86befb122726', 760, 'multiple_choice', 'B1', 'phrasal verbs', 'Which phrasal verb means "to cancel something that was planned"?', 'call off', '["call off", "call out", "call up", "call on"]', NULL, NULL, NULL, NULL, '"Call off" means to cancel. "Call up" means to phone. "Call on" means to visit or ask someone. "Call out" means to shout or to challenge.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('314fa5e9-31b5-4dbb-ab56-df3496965c03', 683, 'odd_one_out', 'B2', 'phrasal_verbs', 'Which phrasal verb does NOT mean "to cancel"?', 'carry out', '["call off", "put off", "carry out", "pull out of"]', NULL, NULL, NULL, NULL, '"Carry out" means to complete or execute something, not cancel it.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('35f6829d-dbcc-439b-9a0a-328ddd607090', 848, 'error_correction', 'C1', 'collocations', 'The findings lend credibility for the hypothesis.', 'The findings lend credibility to the hypothesis.', '[]', NULL, NULL, NULL, NULL, '"Lend credibility to something" is the fixed collocation — not "lend credibility for". Similarly: "lend weight to", "give credibility to". Preposition errors at C1 are often collocation errors.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('769465a5-7786-4b6c-a921-70414584c8d9', 73, 'gap_fill', 'B2', 'have_something_done', 'I need to ___ (have / my car / service).', 'have my car serviced', NULL, '["have the car serviced", "get the car serviced"]', NULL, NULL, 'Have + object + past participle', 'Have/get something done means to arrange for someone else to do something for you.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5968c5e0-d61f-40e8-b7ef-58f29d00c632', 1121, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The thing which water comes out of is called a _______.', 'tap', '["tap", "top", "tip", "trap"]', NULL, NULL, NULL, NULL, 'A tap if it is singular, or a mixer, but pluralised if there are two separate ''taps''. They also control the flow of water. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('744e2c6f-c1cc-41bd-b1e0-f8a96ceb45f4', 664, 'sentence_building', 'C1', 'concessive_clauses', 'Por mucho que lo intente, no consigo entenderlo.', 'no matter how hard I try I cannot seem to understand it', '["no", "matter", "how", "hard", "I", "try", "I", "cannot", "seem", "to", "understand", "it", "can", "trying", "hardly"]', NULL, NULL, '["no matter how hard I try I cannot understand it", "I cannot understand it no matter how hard I try "]', NULL, 'No matter how + adjective/adverb + subject + verb: concessive clause.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ea79ba2a-31ee-4f50-b0ca-d443a666a9bb', 1240, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The lawyers need to _____ the contract before we can proceed.', 'draw up', '[]', NULL, NULL, NULL, NULL, 'Draw up means to prepare a formal document such as a contract, plan, or list.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8eb8b013-c6c8-4b38-b779-2148740de0d3', 444, 'gap_fill', 'C1', 'collocations', 'She ___ a complaint about the noise.', 'made', NULL, NULL, NULL, NULL, NULL, 'Make/file/lodge a complaint = formally report dissatisfaction.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ab5b66ad-c2ed-40d9-af56-95e6232d2f47', 445, 'gap_fill', 'C1', 'collocations', 'The doctor ___ her a thorough examination.', 'gave', NULL, NULL, NULL, NULL, NULL, 'Give someone an examination. Also: carry out an examination.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7f21df04-48b9-46c2-a024-5b31ad03ad5a', 1241, 'gap_fill', 'B2', 'business_phrasal_verbs', 'After months of negotiation, the two companies finally _____ a deal.', 'hammered out', '[]', NULL, NULL, NULL, NULL, 'Hammer out means to reach an agreement after long and difficult negotiations. Compare: iron out, thrash out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ce555b13-f404-4849-afd8-0d86bd66efff', 446, 'gap_fill', 'C1', 'collocations', 'We need to ___ into account all the possible risks.', 'take', NULL, NULL, NULL, NULL, NULL, 'Take into account = consider. A very common formal collocation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2c9f090-91e6-48b0-9c06-350fdc70e153', 447, 'gap_fill', 'C1', 'collocations', 'The news ___ a huge impact on the stock market.', 'had', NULL, NULL, NULL, NULL, NULL, 'Have an impact on = affect or influence something significantly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1880fa4-effa-418f-b868-f81f96935d87', 448, 'gap_fill', 'C2', 'collocations', 'The government is ___ under pressure to reform the healthcare system.', 'coming', NULL, NULL, NULL, NULL, NULL, 'Come under pressure = face increasing demands to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d3d1989-a1a5-4f9a-b366-de1552eff9e6', 449, 'gap_fill', 'C1', 'collocations', 'I''d like to ___ your attention to the safety instructions.', 'draw', NULL, NULL, NULL, NULL, NULL, 'Draw attention to = make people notice something important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f4301a47-603b-454c-8eb7-324d0718a340', 450, 'gap_fill', 'C1', 'collocations', 'We must ___ priority to the most urgent cases.', 'give', NULL, NULL, NULL, NULL, NULL, 'Give priority to = treat something as most important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a7214dfe-c3ca-4176-b609-55dea2903e72', 451, 'gap_fill', 'C1', 'collocations', 'The committee has ___ to the conclusion that changes are needed.', 'come', NULL, NULL, NULL, NULL, NULL, 'Come to a conclusion / reach a conclusion = decide after consideration.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4b8b293d-71b8-4e62-b7a3-b375fa1e4e6a', 452, 'gap_fill', 'C2', 'collocations', 'The results ___ a sharp contrast with last year''s figures.', 'draw', NULL, NULL, NULL, NULL, NULL, 'Draw/present a contrast = show differences between two things.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('94e96897-2b74-44ce-aeff-28217d5a9147', 774, 'multiple_choice', 'B2', 'collocations', '"The new policy has been met ___ considerable opposition."', 'with', '["with", "by", "from", "of"]', NULL, NULL, NULL, NULL, '"Met with" is a fixed expression meaning "received" or "encountered". The policy was met with opposition = it received opposition.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('91784d39-3c29-47ac-932e-62cded490d47', 776, 'multiple_choice', 'B1', 'collocations', '"I am not ___ this change — I think it will cause more problems than it solves."', 'in favour of', '["in favour of", "in support to", "for favour of", "in the favour of"]', NULL, NULL, NULL, NULL, '"In favour of" is the correct fixed expression meaning "supporting something". British English spells it "favour"; American English spells it "favor".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0302fa0a-8945-4fef-b32b-85382367a7a6', 443, 'gap_fill', 'C1', 'collocations', 'The company needs to ___ measures to reduce pollution.', 'take', NULL, '["introduce", "investigate"]', 'Alternate verb possibilities, investigate sounds as if the measures will not happen any time soon.', NULL, NULL, 'Take measures = implement actions to deal with a problem. Common business collocation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e4411fd6-5b11-44af-bd0d-fd2ff7713c48', 826, 'odd_one_out', 'C2', 'collocations', 'Three of these can precede the word "reform" as a natural collocation. Which is the odd one out?', 'deliberate', '["sweeping", "radical", "wide-ranging", "deliberate"]', NULL, NULL, NULL, NULL, 'We speak of "sweeping reform", "radical reform", and "wide-ranging reform" — all describe the scope or extent of change. "Deliberate reform" is grammatically possible, but not a standard collocation; it sounds awkward.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2f983c80-60e6-4717-beca-e916c030063a', 89, 'gap_fill', 'B2', 'causative_make_let', 'My parents don''t let me ___ (_ _ _ _) out late.', 'stay', NULL, NULL, NULL, NULL, 'Let + object + infinitive without ''to''', 'Let + object + infinitive (without ''to'') means to allow someone to do something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4a1b40c8-8cf1-4cb4-a71d-bb5d3e1fea47', 889, 'multiple_choice', 'A2', 'spanish', 'Which Spanish verb means "to live"?', 'vivir', '["vivir", "volver", "comer", "dormir"]', NULL, NULL, NULL, NULL, '"Vivir" means to live. "Volver" = to return, "comer" = to eat, "dormir" = to sleep.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('30afa853-58ed-4749-b13a-05ce00ce4151', 890, 'multiple_choice', 'A2', 'spanish', 'How do you say "I am cold" in Spanish?', 'Tengo frío', '["Tengo frío", "Estoy frío", "Soy frío", "Hace frío"]', NULL, NULL, NULL, NULL, 'In Spanish, use "tener" (to have) for physical sensations: tengo frío, tengo calor, tengo hambre. "Estoy frío" and "soy frío" are incorrect for this meaning. "Hace frío" means it''s cold.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('179c0a59-9c62-4268-b202-679add5c0cd9', 90, 'gap_fill', 'B2', 'causative_make_let', 'The teacher made us ___ (_ _) the exercise again.', 'do', NULL, NULL, NULL, NULL, 'Make + object + infinitive without ''to''', 'Make + object + infinitive (without ''to'') means to force someone to do something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fbc90041-1cbc-4c91-b992-e2167968f2d8', 1127, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'Tiles made from clay fired at very high temperatures, making them very dense and water-resistant, are called _______ tiles.', 'porcelain', '["porcelain", "ceramic", "terracotta", "marble"]', NULL, NULL, NULL, NULL, 'Porcelain tiles are fired at higher temperatures than ceramic tiles, making them denser, harder, and more water-resistant. They are ideal for wet areas and high-traffic floors.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f9a6ee7d-68b1-4297-aafb-d09521ef6ed8', 1128, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A bath that stands alone in the room, not fixed against a wall, is called a _______ bath.', 'freestanding', '["freestanding", "floating", "standalone", "open"]', NULL, NULL, NULL, NULL, 'A freestanding bath stands independently from the walls and creates a focal point in the bathroom. It is a popular choice in high-end and contemporary bathroom designs.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5b052a00-c4ce-4b40-a82d-aa0a442307ff', 1130, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A shower room where the floor is waterproofed and slopes to a drain, with no tray or door, is called a _______ room.', 'wet', '["wet", "open", "drain", "level"]', NULL, NULL, NULL, NULL, 'A wet room is a fully waterproofed bathroom where the shower has no enclosure — the floor is graded to a drain. It is a popular choice in contemporary bathroom design.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('785c40ba-c669-42c2-9225-9204fbe1ac8d', 1131, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'A piece of bathroom furniture that combines a sink with storage cupboards underneath is called a _______ unit.', 'vanity', '["vanity", "storage", "basin", "cabinet"]', NULL, NULL, NULL, NULL, 'A vanity unit combines a basin with a cabinet below, providing storage and a clean, finished look. It is a standard feature in both contemporary and traditional bathroom designs.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2504fde5-2139-4573-a453-e21a462781c7', 1132, 'gap_fill', 'B2', 'bathroom_vocabulary', 'The time between when a customer places an order and when the goods arrive is called the _______ time.', 'lead', NULL, NULL, NULL, NULL, NULL, 'Lead time is the period between placing an order and receiving delivery. In a bathroom showroom, lead times for special-order tiles or bespoke items can be several weeks.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9380ab9e-169e-4912-84e3-130313c99748', 1133, 'gap_fill', 'B2', 'bathroom_vocabulary', 'The price charged before tax is added is called the _______ price.', 'net', NULL, NULL, NULL, NULL, NULL, 'The net price is the price before IVA (or VAT) or other taxes are applied. The gross price is the total including tax. Trade customers are usually quoted net prices.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('95f28280-5265-4547-abbb-ade9709c95f8', 1134, 'gap_fill', 'B2', 'bathroom_vocabulary', 'A tile with a surface that provides extra grip to prevent slipping is described as _______.', 'slip-resistant', NULL, NULL, NULL, '["non-slip", "anti-slip"]', NULL, 'Slip-resistant tiles have a textured or treated surface that provides grip underfoot. They are essential for wet floors such as shower trays, bathroom floors, and outdoor spaces.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e58027a4-8637-4abf-9326-0bf85baebf4e', 1135, 'gap_fill', 'B2', 'bathroom_vocabulary', 'A document listing all the items in an order, with their quantities and prices, and the total amount owed, is called an _______.', 'invoice', NULL, NULL, NULL, NULL, NULL, 'An invoice is a formal document issued after a sale that lists items supplied, quantities, unit prices, and the total amount due. It is used for payment and record-keeping.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('882295fa-8e39-4513-b0e3-69958edfd6e7', 1136, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A tile whose edges have been precisely machine-cut after firing, allowing it to be laid with very thin grout joints, is called a _______ tile.', 'rectified', NULL, NULL, NULL, NULL, NULL, 'Rectified tiles are cut to exact dimensions after firing, ensuring perfectly straight edges. This allows them to be laid with minimal grout joints — as thin as 1–2mm — creating a seamless, contemporary finish.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dc731af0-b7b5-4db2-ba6d-5e6bd7856801', 1137, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A liquid applied to natural stone or porous tiles after installation to protect the surface from stains and moisture is called a _______.', 'sealant', NULL, NULL, NULL, '["sealer"]', NULL, 'A sealant penetrates the surface of porous materials such as natural stone, slate, or unglazed tiles, protecting them from water and staining. Regular reapplication is recommended, particularly in wet areas.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4d5f394d-716c-436a-9d8f-bf926587a8d8', 1138, 'gap_fill', 'C1', 'bathroom_vocabulary', 'When a product is no longer manufactured and cannot be reordered, we say it has been _______.', 'discontinued', NULL, NULL, NULL, NULL, NULL, 'A discontinued product has been taken out of production by the manufacturer. It is important to inform customers early if a tile is being discontinued so they can order extra stock for future repairs or extensions.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('377e35e2-e110-42bf-a191-19d40253c2fd', 1139, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The detailed document listing all materials, finishes, dimensions, and quantities for a bathroom project is called the _______.', 'specification', NULL, NULL, NULL, '["spec"]', NULL, 'A specification (or spec) sets out exactly what will be supplied — tile references, dimensions, finishes, and quantities. It forms the basis of a formal quotation and avoids misunderstandings during the project.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('823a2852-ecaa-476c-90bc-3ee8beabd094', 1129, 'multiple_choice', 'B1', 'bathroom_vocabulary', 'When a customer asks for a price before they decide to buy, we give them a _______.', 'quote', '["quote", "invoice", "receipt", "bill"]', NULL, NULL, NULL, NULL, 'A quote (or quotation) gives the customer a fixed price before they commit to a purchase. An invoice is issued after the sale has been agreed and goods have been supplied.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1fdfb436-3c68-44c6-970f-f8e7f5331cd1', 1251, 'gap_fill', 'C1', 'business_phrasal_verbs', 'She _____ an impressive performance in the boardroom despite the hostile questioning.', 'pulled off', '[]', NULL, NULL, NULL, NULL, 'Pull off means to succeed in doing something difficult or unexpected. Compare: bring off, carry off.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a3efbf29-67c9-4e64-a449-c8a54a47da8c', 1252, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The CEO was forced to _____ after the scandal became public.', 'step down', '[]', NULL, NULL, NULL, NULL, 'Step down means to resign from a senior position, usually under pressure or voluntarily. Compare: stand down, resign.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c18341f0-d84e-4937-a451-f6ca29c42655', 1140, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A finish that makes tiles appear worn and aged rather than new is called a _______ finish.', 'distressed', NULL, NULL, NULL, '["aged", "antique"]', NULL, 'A distressed finish is created by tumbling, sandblasting, or acid-treating tiles to give them a worn, weathered appearance. It is popular in rustic, industrial, and vintage-style interiors.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('54ba30af-f9cf-409a-a99a-f1804c3894ae', 909, 'sentence_auction', 'A2', 'spanish', 'Theme: Gustar and Similar Verbs', 'auction', '[{"correct": true, "sentence": "Me gustan las películas de acción.", "explanation": "Correct! Gustan agrees with the plural noun las películas."}, {"correct": false, "sentence": "Me gusta los libros de historia.", "explanation": "Wrong — los libros is plural so use gustan: Me gustan los libros de historia."}, {"correct": true, "sentence": "A mi hermana le encanta el chocolate.", "explanation": "Correct! Encantar works like gustar — it agrees with el chocolate (singular)."}, {"correct": false, "sentence": "Nos gustan mucho la música.", "explanation": "Wrong — la música is singular so use gusta: Nos gusta mucho la música."}, {"correct": true, "sentence": "¿Te apetece un café?", "explanation": "Correct! Apetecer works like gustar. Un café is singular so use apetece."}, {"correct": false, "sentence": "A ellos les gusta los deportes.", "explanation": "Wrong — los deportes is plural so use gustan: A ellos les gustan los deportes."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 14:15:59.915911+00', NULL, NULL, 'es', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f6b8d853-226d-41e0-b253-818c04d46bc2', 1141, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The manufacturer''s written promise to repair or replace a product that develops a fault within a stated period is called a _______.', 'warranty', NULL, NULL, NULL, '["guarantee"]', NULL, 'A warranty is the manufacturer''s formal commitment to address defects within a specified period. High-end tiles and sanitaryware often carry extended warranties of 10 to 25 years, which can be a strong selling point.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa35fb32-2c9d-4b4b-825a-fa6ebee4cab1', 708, 'odd_one_out', 'B1', 'collocations', 'Which does NOT collocate with "make"?', 'homework', '["a decision", "a mistake", "homework", "progress"]', NULL, NULL, NULL, NULL, 'We say "do homework", not "make homework".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2564c26c-05a7-4bfd-8242-ad1f97a50f25', 679, 'odd_one_out', 'B2', 'collocations', 'Which does NOT collocate with "take"?', 'a decision', '["a break", "a decision", "advantage", "a chance"]', NULL, NULL, NULL, NULL, 'We usually say "make a decision", not "take a decision" (in British English both kind of work, but "make" is more standard).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('94bfbd4d-4d8a-4e27-b681-55c0e640fd63', 839, 'error_correction', 'B1', 'collocations', 'He insisted in paying for dinner.', 'He insisted on paying for dinner.', '[]', NULL, NULL, NULL, NULL, '"Insist on + ing" is the correct pattern: "He insisted on paying." "Insist in" is not correct in English — common error for Spanish speakers as "insistir en" exists in Spanish!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1da8949c-ab8d-429a-816c-4f5334aef738', 547, 'multiple_choice', 'C1', 'confusing_words', 'I would strongly ___ against making any hasty decisions.', 'advise', '["device", "advise", "devise", "advice"]', NULL, NULL, NULL, NULL, 'Advise (verb) = give advice. Advice (noun) = the recommendation itself.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('26707361-68a0-4e13-9331-2a8e1fb0c41a', 546, 'multiple_choice', 'C1', 'confusing_words', 'The new law will ___ everyone equally.', 'affect', '["inflict", "infect", "effect", "affect"]', NULL, NULL, NULL, NULL, 'Affect (verb) = influence. Effect (noun) = result. Common confusion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3ccb05b2-84f0-464d-8147-b6f41337b668', 549, 'multiple_choice', 'C2', 'confusing_words', 'She ___ to the new environment remarkably quickly.', 'adapted', '["adept", "adopted", "adapted", "adhered"]', NULL, NULL, NULL, NULL, 'Adapt = adjust to new conditions. Adopt = take on/accept something new.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0435ca21-8e56-4334-ad58-f714005f74bd', 550, 'multiple_choice', 'C1', 'confusing_words', 'The report ___ several important factors.', 'overlooks', '["oversees", "overtakes", "overcomes", "overlooks"]', NULL, NULL, NULL, NULL, 'Overlook = fail to notice. Oversee = supervise.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5cb70e00-a280-4503-b72b-df4848d6cc74', 551, 'multiple_choice', 'C1', 'confusing_words', 'I found her argument very ___.', 'compelling', '["compulsive", "competitive", "compulsory", "compelling"]', NULL, NULL, NULL, NULL, 'Compelling = powerfully convincing. Compulsory = obligatory.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('31f44de4-1283-4378-8281-020af06640b0', 552, 'multiple_choice', 'C2', 'confusing_words', 'His comments were taken completely out of ___.', 'context', '["content", "contact", "contract", "context"]', NULL, NULL, NULL, NULL, 'Out of context = without the surrounding information that gives meaning.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c428d849-eb35-4e82-9a62-886da9a5b6a1', 553, 'multiple_choice', 'C1', 'confusing_words', 'The two concepts are often ___ but they are quite different.', 'confused', '["confided", "confused", "confirmed", "confusing"]', NULL, NULL, NULL, NULL, 'Confused = mistaken for each other. Often used in passive voice.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8120f8df-ed7a-44e7-9065-de50b65be3fd', 555, 'multiple_choice', 'C2', 'confusing_words', 'The data ___ our hypothesis about climate trends.', 'corroborates', '["communicates", "corroborates", "commemorates", "collaborates"]', NULL, NULL, NULL, NULL, 'Corroborate = confirm or give support to evidence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8d38f87e-af22-4f1c-85d8-da647572de41', 556, 'multiple_choice', 'C1', 'confusing_words', 'The ___ of residents opposed the construction project.', 'majority', '["mass", "most", "main", "majority"]', NULL, NULL, NULL, NULL, 'The majority of = more than half. Used with countable nouns.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a67f1c84-da8f-469a-871e-3a70dafa946d', 557, 'multiple_choice', 'C1', 'confusing_words', 'Her ___ reaction was one of disbelief.', 'initial', '["initiative", "initiated", "initiating", "initial"]', NULL, NULL, NULL, NULL, 'Initial = first, happening at the beginning.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9177c4e1-ba58-4c5e-9ad5-46b32454f4d7', 558, 'multiple_choice', 'C2', 'confusing_words', 'The government''s response was widely ___ as inadequate.', 'perceived', '["conceived", "deceived", "perceived", "received"]', NULL, NULL, NULL, NULL, 'Perceive as = see or regard something in a particular way.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f9eff91c-6b93-405c-92f7-6891692dcb3d', 559, 'multiple_choice', 'C1', 'confusing_words', 'She made a ___ effort to improve her presentation skills.', 'conscious', '["conscientious", "consecutive", "conspicuous", "conscious"]', NULL, NULL, NULL, NULL, 'Conscious effort = deliberate, intentional effort.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('59f9778a-1b2c-4252-a986-986e61ab99c7', 201, 'gap_fill', 'A1', 'present_simple', 'She ___ (live) in Madrid.', 'lives', NULL, NULL, NULL, NULL, NULL, 'Third person singular: add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('488b3b32-c3ef-4847-85a1-b3ad92b63ddb', 622, 'sentence_building', 'A2', 'present_simple', 'Ella trabaja en un hospital.', 'she works in a hospital', '["she", "works", "in", "a", "hospital", "is", "one", "work"]', NULL, NULL, NULL, NULL, 'In present simple, we add -s to the verb for he/she/it. ''She works'' not ''she work''. In English we normally use ''a/an'' not ''one'' in situations like these. ', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6960f3cd-1150-4913-9fe9-9f15e8352e99', 970, 'multiple_choice', 'A1', 'hotel_vocabulary', 'A _______ room has two separate single beds.', 'twin', '["twin", "double", "shared", "standard"]', NULL, NULL, NULL, NULL, 'A twin room has two separate single beds. A double room has one large bed for two people. This is a common source of confusion when booking.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a3911dfe-1576-487f-afc4-10859d5db15d', 560, 'multiple_choice', 'C1', 'confusing_words', 'The ___ between the two reports is striking.', 'disparity', '["dispute", "disparity", "display", "dispatch"]', NULL, NULL, NULL, NULL, 'Disparity = a great difference, inequality.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('349991fb-3866-4742-830a-589cdd638bb0', 581, 'multiple_choice', 'C1', 'nuance', 'I ___ to inform you that your application has been unsuccessful.', 'regret', '["apologise", "regret", "am afraid", "sorry"]', NULL, NULL, NULL, NULL, 'I regret to inform you = very formal way of delivering bad news.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cd58f689-5c0b-4ccf-a090-adf7f3a75981', 583, 'multiple_choice', 'C2', 'nuance', 'His remarks were ___ inappropriate for such a formal occasion.', 'wholly', '["solely", "wholly", "holy", "lonely"]', NULL, NULL, NULL, NULL, 'Wholly = completely, entirely. Formal emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('195942a0-a0bf-459b-8609-0538af3fdfb9', 584, 'multiple_choice', 'C1', 'nuance', 'The decision was taken ___ the interests of public safety.', 'in', '["by", "at", "for", "in"]', NULL, NULL, NULL, NULL, 'In the interests of = for the sake of, to protect or promote.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ac3557b3-6b15-445d-a7ad-73bb8a614a1a', 585, 'multiple_choice', 'C1', 'nuance', 'She was ___ critical of the government''s handling of the crisis.', 'outspokenly', '["outspoken", "outspoking", "outspoke", "outspokenly"]', NULL, NULL, NULL, NULL, 'Outspokenly critical = openly and directly critical.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4d827185-9a98-4ee7-990c-f5ab6ee414ba', 586, 'multiple_choice', 'C2', 'nuance', 'The scandal ___ a shadow over the entire organisation.', 'cast', '["threw", "put", "set", "cast"]', NULL, NULL, NULL, NULL, 'Cast a shadow over = have a negative effect on. Formal/literary.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e8e7c4d-0b7b-407c-88bd-39e6b26bcc4f', 587, 'multiple_choice', 'C1', 'nuance', 'He made a passing ___ to the incident but didn''t elaborate.', 'reference', '["comment", "mention", "remark", "reference"]', NULL, NULL, NULL, NULL, 'Make a passing reference to = mention briefly without detail.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4d668676-b713-47de-9e6b-f7c44123d1d0', 588, 'multiple_choice', 'C1', 'nuance', 'The scheme was abandoned ___ to a lack of funding.', 'due', '["since", "due", "owe", "because"]', NULL, NULL, NULL, NULL, 'Due to = because of. Slightly more formal than because of.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('80a91e1f-0533-4bed-a2f5-af65e08b1ce1', 589, 'multiple_choice', 'C2', 'nuance', 'Her contribution to the field cannot be ___.', 'overstated', '["overlooked", "overturned", "overrated", "overstated"]', NULL, NULL, NULL, NULL, 'Cannot be overstated = is extremely important (so important you can''t exaggerate it).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a6962694-5c66-48c5-b356-eb14903d5647', 590, 'multiple_choice', 'C1', 'nuance', 'The two countries have a ___ of cooperation going back decades.', 'track record', '["track line", "track route", "track path", "track record"]', NULL, NULL, NULL, NULL, 'Track record = history of past achievements or performance.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e42b2d2c-12fa-4685-8cea-4fbcf2cb3ee7', 592, 'multiple_choice', 'C2', 'nuance', 'The author ___ a convincing case for educational reform.', 'makes', '["does", "makes", "puts", "sets"]', NULL, NULL, NULL, NULL, 'Make a case for = argue persuasively in favour of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('74d740b1-7f36-4722-a176-949f27621a79', 596, 'multiple_choice', 'C1', 'nuance', 'I''m writing to ___ my interest in the position.', 'express', '["suppress", "press", "express", "impress"]', NULL, NULL, NULL, NULL, 'Express interest = formally communicate that you are interested.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('323fbde7-b66e-4e7d-83c1-b29221dac944', 597, 'multiple_choice', 'C1', 'nuance', 'The evidence ___ to a clear pattern of negligence.', 'points', '["guides", "directs", "points", "aims"]', NULL, NULL, NULL, NULL, 'Point to = indicate, suggest. Evidence points to a conclusion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6b914f5a-4aca-46bc-968f-09cdea9aedce', 598, 'multiple_choice', 'C2', 'nuance', 'She delivered the speech with remarkable ___ and grace.', 'poise', '["pause", "noise", "pose", "poise"]', NULL, NULL, NULL, NULL, 'Poise = calm confidence and composure, especially under pressure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ec9fe704-b4a9-43a0-b5f9-b9c961afc0ff', 599, 'multiple_choice', 'C1', 'nuance', 'The negotiations have reached a ___ point.', 'critical', '["critique", "critical", "critic", "criteria"]', NULL, NULL, NULL, NULL, 'Critical point = very important, decisive moment.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07216aac-ad16-449b-9595-7c140d2789a1', 600, 'multiple_choice', 'C1', 'nuance', 'His explanation left a lot to be ___.', 'desired', '["wished", "hoped", "wanted", "desired"]', NULL, NULL, NULL, NULL, 'Leave a lot to be desired = be unsatisfactory, not good enough.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bba6c793-c923-4d29-817a-947e24931adb', 591, 'multiple_choice', 'C1', 'nuance', 'We need to ___ a balance between cost and quality.', 'strike', '["hit", "make", "strike", "search"]', NULL, NULL, NULL, NULL, 'Strike a balance = find a satisfactory compromise between two things.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e28bcf2d-7505-43a9-b4ba-c488a97f5169', 720, 'odd_one_out', 'B2', 'synonyms', 'Which word is NOT a synonym for "big"?', 'moderate', '["vast", "enormous", "moderate", "immense"]', NULL, NULL, NULL, NULL, '"Moderate" means medium or average, the opposite of big.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('76d0f589-1ecf-4908-9379-116a662152e1', 126, 'multiple_choice', 'B1', 'countable_uncountable', 'Could I have ___ information about the course?', 'some', '["an", "some", "a", "many"]', NULL, NULL, NULL, NULL, 'Some with uncountable nouns in requests.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d3685bff-2700-4873-8905-2b95860fe0f4', 175, 'multiple_choice', 'B1', 'countable_a_an', 'She''s ___ engineer.', 'an', '["a", "an", "the", "-"]', NULL, NULL, NULL, NULL, 'An before vowel sounds.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2f540098-4aee-4d8b-aba1-f64a6370ff55', 386, 'multiple_choice', 'A2', 'countability', 'Can you give me some ___?', 'advice', '["the advices", "advice", "advices", "an advice"]', NULL, NULL, NULL, NULL, 'Advice is uncountable: some advice (never advices).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c815ea6d-8da5-4e99-b34c-872ca34f5bbe', 387, 'multiple_choice', 'A2', 'countability', 'I need ___ information about the course.', 'some', '["a", "an", "some", "many"]', NULL, NULL, NULL, NULL, 'Information is uncountable: some information.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('980df10b-ff24-4a90-a9e4-8a9d8453c251', 388, 'multiple_choice', 'A2', 'countability', 'She has long ___.', 'hair', '["a hair", "the hairs", "hair", "hairs"]', NULL, NULL, NULL, NULL, 'Hair (on your head) is uncountable in English.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ea513d84-2854-4cda-ae69-b04b310682ed', 389, 'multiple_choice', 'A2', 'countability', 'We bought some new ___.', 'furniture', '["furnitures", "the furnitures", "a furniture", "furniture"]', NULL, NULL, NULL, NULL, 'Furniture is uncountable: some furniture, a piece of furniture.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2595671-f2f4-4bf9-944b-4ec23b46d7b0', 723, 'error_correction', 'B2', 'uncountable_nouns', 'The informations you gave me was very useful.', 'The information you gave me was very useful.', '[]', NULL, NULL, NULL, NULL, '"Information" is uncountable — no plural "s".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fd29a711-cf01-4384-a5dc-2d9e310d8425', 71, 'gap_fill', 'B1', 'countable_uncountable', 'Can I have ___ (a / an / some) water, please?', 'some', NULL, '["a", "", "-"]', NULL, NULL, 'Water is uncountable', 'Some is used with uncountable nouns in requests and offers.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aaf582a6-007e-4b27-a071-a83af2728a91', 266, 'gap_fill', 'A1', 'prepositions_of_place', 'He is ___ home.', 'at', NULL, NULL, NULL, NULL, NULL, 'Use at with home: at home (not in home).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('60712c31-92de-4b78-b7bc-245f2477b270', 1142, 'gap_fill', 'C1', 'bathroom_vocabulary', 'The overall visual identity of a bathroom — its combination of materials, colours, textures, and style — is referred to as its _______.', 'aesthetic', NULL, NULL, NULL, NULL, NULL, 'The aesthetic of a bathroom describes its overall look and feel — the coherent combination of tiles, fixtures, lighting, and accessories that creates a distinctive style. High-end clients often arrive with a clear aesthetic vision.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('373ce6b5-1fe2-4b0b-a21f-513244e55160', 1143, 'gap_fill', 'C2', 'bathroom_vocabulary', 'A product designed and made to meet one specific customer''s exact requirements is described as _______.', 'bespoke', NULL, NULL, NULL, '["custom-made", "custom", "made-to-order"]', NULL, 'Bespoke means made specifically to a customer''s individual requirements — custom dimensions, finishes, or configurations not available off the shelf. Bespoke products command a premium and require longer lead times.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('17544e4c-0749-4629-87fc-64659941fbdb', 267, 'gap_fill', 'A2', 'prepositions_of_place', 'The restaurant is ___ front of the cinema.', 'in', NULL, NULL, NULL, NULL, NULL, 'In front of = on the opposite side from behind.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('346f782a-be23-4f61-b1e2-9d7f55f44163', 268, 'gap_fill', 'A1', 'prepositions_of_place', 'There are books ___ the shelf.', 'on', NULL, NULL, NULL, NULL, NULL, 'Use on with shelves and surfaces.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6ba720d8-246e-4b66-b5b2-6c152589f68f', 269, 'gap_fill', 'A2', 'prepositions_of_place', 'The pharmacy is ___ to the bakery.', 'next', NULL, NULL, NULL, NULL, NULL, 'Next to = very close, beside.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa86a31a-edcd-4b92-8111-1ee8998147f9', 270, 'gap_fill', 'A1', 'prepositions_of_place', 'The keys are ___ my bag.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in with containers and enclosed spaces.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('55e75a98-06c0-4bb5-a44b-76efad5462a2', 261, 'gap_fill', 'A1', 'prepositions_of_place', 'The cat is ___ the table.', 'on', NULL, NULL, NULL, NULL, NULL, 'On = on top of the surface. Under = below.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7869b196-24c1-4d22-95c8-c3ff49ca0fca', 38, 'gap_fill', 'B1', 'prepositions_place', 'The café is ___ (under / at / on / in) the corner of the street.', 'on', NULL, NULL, NULL, NULL, 'Both ''on'' and ''at'' can be used for corners', 'Both on and at can be used when referring to corners.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a5e97fd5-4873-4efc-a582-cbc4857422a1', 263, 'gap_fill', 'A1', 'prepositions_of_place', 'I''ll meet you ___ the bus stop.', 'at', NULL, NULL, NULL, NULL, NULL, 'Use at with specific points or locations.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0b97bb3e-99e2-4f7c-a17b-01aadc460cb5', 137, 'multiple_choice', 'B1', 'prepositions_place', 'The post office is ___ the bank and the supermarket.', 'between', '["in", "among", "at", "between"]', NULL, NULL, NULL, NULL, 'Between for two things.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53697f20-6e27-4f2d-9a1a-884a23e0c861', 264, 'gap_fill', 'A1', 'prepositions_of_place', 'The picture is ___ the wall.', 'on', NULL, NULL, NULL, NULL, NULL, 'Use on with surfaces: on the wall, on the floor.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('168e04de-e384-4081-9758-bde6a0c3d559', 265, 'gap_fill', 'A2', 'prepositions_of_place', 'The bank is ___ the supermarket and the pharmacy.', 'between', NULL, NULL, NULL, NULL, NULL, 'Between shows position in the middle of two things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a457037b-b24c-4e24-8a5c-909208b347ee', 255, 'gap_fill', 'A1', 'prepositions_of_time', 'The class starts ___ 9 am.', 'at', NULL, NULL, NULL, NULL, NULL, 'Use at with specific times.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f4e392d6-016d-4251-983a-cc4125d3e7b0', 256, 'gap_fill', 'A2', 'prepositions_of_time', 'We have a meeting ___ Friday morning.', 'on', NULL, NULL, NULL, NULL, NULL, 'Use on with specific days, even with morning/afternoon.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('14a45468-155d-4851-a56c-9d763cbeb3ea', 257, 'gap_fill', 'A1', 'prepositions_of_time', 'I go to bed ___ night.', 'at', NULL, NULL, NULL, NULL, NULL, 'Use at with night: at night (not in night).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b6aebd34-6567-4c05-ad24-8c5bcda1e9da', 259, 'gap_fill', 'A1', 'prepositions_of_time', 'It''s very cold ___ winter.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in with seasons: in winter, in summer.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f015c55c-0d78-4b92-a0d1-3305f353c861', 260, 'gap_fill', 'A2', 'prepositions_of_time', 'I''ll see you ___ two weeks.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in for future time periods: in two weeks, in an hour.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa21c418-81af-48a8-9655-397d47faf5f1', 36, 'gap_fill', 'B1', 'prepositions_time', 'The meeting is ___ (at / on / in) Monday morning.', 'on', NULL, NULL, NULL, NULL, 'Use ''on'' for days and dates', 'On is used for days of the week and specific dates.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cda9cdd9-bffe-46a9-a69a-eb5d32263258', 37, 'gap_fill', 'B1', 'prepositions_time', 'I usually go to the gym ___ (at / on / in) the evening.', 'in', NULL, NULL, NULL, NULL, 'Use ''in'' for parts of the day', 'In is used for parts of the day (morning, afternoon, evening).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f1ddfdc6-2061-4ac3-b8f0-aa8e89194b09', 118, 'multiple_choice', 'B1', 'prepositions_time', 'The meeting is ___ Tuesday morning.', 'on', '["at", "on", "in", "by"]', NULL, NULL, NULL, NULL, 'On for days of the week.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8534e842-fe3d-47b2-9f69-ee9dee04f271', 119, 'multiple_choice', 'B1', 'prepositions_time', 'I usually go swimming ___ the weekend.', 'at', '["by", "on", "in", "at"]', NULL, NULL, NULL, NULL, 'At the weekend (British English) or on the weekend (American English).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('212d2a13-04e5-4d1f-926c-3ff1eafb6ba1', 1144, 'gap_fill', 'C1', 'bathroom_vocabulary', 'When a customer is unhappy with a product, the process of resolving the problem professionally is called handling a _______.', 'complaint', NULL, NULL, NULL, NULL, NULL, 'Handling complaints effectively is essential in high-end retail. A professional response — acknowledging the issue, apologising sincerely, and offering a clear solution — protects the customer relationship and the company''s reputation.', '2026-03-11 18:12:09.553883+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b186bc25-fa90-4d8c-b703-9edaf57c0563', 1032, 'multiple_choice', 'A2', 'prepositions', 'We drove _______ the tunnel to get to the other side of the mountain.', 'through', '["through", "across", "over", "past"]', NULL, NULL, NULL, NULL, 'Through means entering one side and exiting the other — used for enclosed spaces like tunnels, forests, and buildings. Compare: across = moving from one side to the other of an open surface.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of movement"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('845db5a9-0b44-41be-9756-88033d086225', 1033, 'multiple_choice', 'A2', 'prepositions', 'She''s been working at this company _______ 2018.', 'since', '["since", "for", "from", "during"]', NULL, NULL, NULL, NULL, 'Since refers to a specific point in time when something started and is still continuing: since 2018. For refers to a duration: for six years. Both are used with the present perfect.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a0c0134e-fe49-4d5a-b5f8-80b3e60f4cfa', 1035, 'multiple_choice', 'A2', 'prepositions', 'The train leaves _______ ten minutes — you need to hurry!', 'in', '["in", "at", "after", "by"]', NULL, NULL, NULL, NULL, 'In ten minutes means after a period of ten minutes has passed — it refers to a future moment. Compare: at ten minutes past = a specific clock time.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f28cf70c-43c1-4ca2-b010-0483068fdaa9', 1036, 'multiple_choice', 'A2', 'prepositions', 'My flat is _______ the third floor.', 'on', '["on", "at", "in", "by"]', NULL, NULL, NULL, NULL, 'Use on with floors of a building: on the third floor, on the ground floor. In British English, the ground floor is the bottom floor; the first floor is above it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6f3ec0d8-8049-404d-a786-89f6f1c6013e', 258, 'gap_fill', 'A2', 'prepositions_of_time', 'The shop is open ___ 9 am ___ 6 pm.', 'from...to', NULL, NULL, NULL, NULL, NULL, 'From...to/until shows a period of time with start and end.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b31d017d-7dbf-49e9-aa0d-8440df31d4f5', 188, 'multiple_choice', 'B2', 'be_used_to', 'Don''t worry about the noise. I ___ in the city.', 'am used to living', '["used to living", "am used to living", "use to live", "am using to live"]', NULL, NULL, NULL, NULL, 'Be used to + gerund (accustomed to).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e798b78-d217-440c-9e7e-e31584e8e2f5', 663, 'sentence_building', 'C1', 'complex_sentences', '', 'the project is unlikely to be completed on time unless additional funding is approved', '["the", "project", "is", "unlikely", "to", "be", "completed", "on", "time", "unless", "additional", "funding", "is", "approved", "will", "complete", "probable"]', '["unless additional funding is approved the project is unlikely to be completed on time."]', NULL, NULL, NULL, 'Complex sentence combining "unlikely to be" (passive probability) with "unless" (conditional).', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('301baacd-b52e-4fad-a4b5-5909edce6291', 39, 'gap_fill', 'B2', 'prepositions_dependent', 'I''m not very good ___ (at / in / on) mathematics.', 'at', NULL, NULL, NULL, NULL, 'Good at + subject/activity', 'Good is followed by at when talking about skills or subjects.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a9793213-2ff3-4dc8-a537-81063fb6bc3f', 610, 'sentence_building', 'C1', 'concessive_clauses', 'A pesar de las dificultades, conseguimos terminar a tiempo.', 'despite the difficulties we managed to finish on time', '["despite", "the", "difficulties", "we", "managed", "to", "finish", "on", "time", "although", "succeeded", "at"]', NULL, NULL, NULL, NULL, '"Despite" + noun (no "of"). "Managed to" = conseguir (implies effort and success). "On time" = a tiempo.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f4a8977b-8eb7-4b71-94d0-153275e30bdf', 661, 'sentence_building', 'C1', 'inversion', '', 'had I known about the delay I would have taken a different route', '["had", "I", "known", "about", "the", "delay", "I", "would", "have", "taken", "a", "different", "route", "did", "took", "taking"]', '["I would have taken a different route had I known about the delay.", "I would have taken a different route had I known about the delay ."]', NULL, NULL, NULL, 'Inverted third conditional: Had + subject + past participle (formal alternative to If I had known...).', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('174ead82-20ad-4c43-b68a-9c8c926bda0e', 649, 'sentence_building', 'A2', 'comparatives', 'Hay mas restaurantes que el año pasado.', 'there are more restaurants than last year', '["there", "are", "more", "restaurants", "than", "last", "year", "less", "is", "next", "fewer"]', NULL, NULL, NULL, NULL, 'Comparatives with nouns: more + noun + than.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('950424c1-5e17-4dcb-ad25-e1fb0c6d9fc5', 1204, 'sentence_building', 'B2', 'routines', 'Tener una hora de dormir constante ha mejorado enormemente la calidad de mi sueño.', 'Having a consistent bedtime has improved my sleep quality enormously.', '["having", "a", "consistent", "bedtime", "has", "improved", "my", "sleep", "quality", "enormously", "regular", "make", "better", "very"]', NULL, NULL, NULL, NULL, 'A gerund (Having) acts as the subject of this sentence. Consistent means happening at the same time every day.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70be9156-a889-497d-838d-eaa8784c5699', 658, 'sentence_building', 'B2', 'gerunds_and_infinitives', 'Me arrepiento de no haber ido a la universidad.', 'I regret not having gone to university', '["I", "regret", "not", "having", "gone", "to", "university", "going", "go", "the", "have", "being"]', NULL, NULL, NULL, NULL, 'Regret + not having + past participle: expressing regret about a past decision.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6585e4e8-0017-474e-a901-490201f2cace', 1206, 'sentence_building', 'C1', 'routines', 'Está haciendo un esfuerzo consciente por relajarse antes de acostarse.', 'She has been making a conscious effort to wind down before bed.', '["she", "has", "been", "making", "a", "conscious", "effort", "to", "wind", "down", "before", "bed", "deliberate", "relax", "sleep", "make"]', NULL, NULL, NULL, NULL, 'Wind down is a phrasal verb meaning to relax gradually after a period of activity. Conscious effort means a deliberate, intentional attempt.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1fdd20db-c846-4067-ba64-1cd07824408c', 40, 'gap_fill', 'B2', 'prepositions_dependent', 'She''s interested ___ (at / in / on) learning Japanese.', 'in', NULL, NULL, NULL, NULL, 'Interested in + activity', 'Interested is followed by in.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('19e0204d-ce1c-44dd-9a45-87a708af7e02', 158, 'multiple_choice', 'B1', 'prepositions_dependent', 'She''s afraid ___ spiders.', 'of', '["from", "of", "about", "with"]', NULL, NULL, NULL, NULL, 'Afraid of + noun/gerund.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('df1fc12a-87e5-45af-b516-9366bde73db0', 174, 'multiple_choice', 'B2', 'gerunds_prepositions', 'I''m looking forward to ___ you again.', 'seeing', '["see", "seeing", "saw", "seen"]', NULL, NULL, NULL, NULL, 'Prepositions (to, for, of, etc.) are followed by gerunds.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('86a1ba68-9cc3-42e9-bda2-562917e9e4f2', 99, 'gap_fill', 'B1', 'everyday_expressions', '___ (H_ _  / W_ _ _) about going for a walk?', 'how', NULL, NULL, NULL, NULL, 'Making suggestions', 'Both ''How about'' and ''What about'' are used for making suggestions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('60c3614f-2ff7-44d1-b7f9-e302ae7e7d82', 531, 'multiple_choice', 'C1', 'idioms', 'Let''s not beat around the ___. What''s the real problem?', 'bush', '["hedge", "bush", "tree", "garden"]', NULL, NULL, NULL, NULL, 'Beat around the bush = avoid talking about something directly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('800a10d7-60b0-4009-8bbf-7f42b4b8abb8', 534, 'multiple_choice', 'C2', 'idioms', 'He''s been burning the ___ at both ends lately and needs rest.', 'candle', '["fire", "candle", "torch", "lamp"]', NULL, NULL, NULL, NULL, 'Burn the candle at both ends = work excessively, leaving little time for rest.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70c79614-6515-42cc-835a-b1e6838e4eb6', 535, 'multiple_choice', 'C1', 'idioms', 'The new regulations are a ___ in the right direction.', 'step', '["jump", "walk", "move", "step"]', NULL, NULL, NULL, NULL, 'A step in the right direction = positive progress toward a goal.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a3773e49-58e7-4bc1-bfca-01231777ce5b', 539, 'multiple_choice', 'C1', 'idioms', 'We''re all in the same ___ when it comes to rising costs.', 'boat', '["ship", "boat", "car", "bus"]', NULL, NULL, NULL, NULL, 'In the same boat = in the same difficult situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ffaf23e2-0c19-4d64-99dd-1b38031c198c', 532, 'multiple_choice', 'C1', 'idioms', 'She''s feeling under the ___ today so she stayed home.', 'weather', '["rain", "weather", "cloud", "storm"]', NULL, NULL, NULL, NULL, 'Under the weather = feeling ill or unwell.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ffdac307-d148-4ba7-90b1-102f3a88460f', 1207, 'sentence_building', 'C2', 'routines', 'A menudo se subestima hasta qué punto los hábitos diarios conforman nuestro sentido de identidad.', 'The extent to which daily habits shape our sense of identity is often underestimated.', '["the", "extent", "to", "which", "daily", "habits", "shape", "our", "sense", "of", "identity", "is", "often", "underestimated", "routine", "degree"]', NULL, NULL, NULL, NULL, 'The extent to which is a sophisticated structure introducing a degree or measure. The whole noun clause is the subject of is often underestimated.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1adc56b9-a8ab-4ba1-88d9-e1ab1aac3a30', 654, 'sentence_building', 'B1', 'present_perfect_continuous', 'Llevo tres años estudiando inglés.', 'I have been studying English for three years', '["I", "have", "been", "studying", "english", "for", "three", "years", "since", "studied", "am", "to"]', NULL, NULL, NULL, NULL, 'Present perfect continuous with "for" + duration. Llevar + verb + ing = have been + verb + ing.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5701133d-de55-4f69-9d42-71503d559958', 533, 'multiple_choice', 'C1', 'idioms', 'The exam was a piece of ___. I finished in 30 minutes.', 'cake', '["pie", "cake", "biscuit", "bread"]', NULL, NULL, NULL, NULL, 'A piece of cake = very easy to do.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c9842212-d7b5-41be-bf1c-6af0f8d4bee6', 536, 'multiple_choice', 'C1', 'idioms', 'I think we should call it a ___ and finish the meeting.', 'day', '["break", "night", "day", "time"]', NULL, NULL, NULL, NULL, 'Call it a day = decide to stop working on something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2d904451-d63c-4665-bc15-531edadabe5b', 537, 'multiple_choice', 'C2', 'idioms', 'The company is in hot ___ after the financial scandal.', 'water', '["air", "fire", "steam", "water"]', NULL, NULL, NULL, NULL, 'In hot water = in trouble, facing serious problems.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b550d44b-bb0b-49c6-a6ba-cc89bb054219', 538, 'multiple_choice', 'C1', 'idioms', 'She always goes the extra ___ for her students.', 'mile', '["step", "length", "way", "mile"]', NULL, NULL, NULL, NULL, 'Go the extra mile = make more effort than expected.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c0dd33ea-cd68-44bb-a6b3-cb742feea2e4', 540, 'multiple_choice', 'C2', 'idioms', 'He let the cat out of the ___ about the surprise party.', 'bag', '["house", "box", "bag", "hat"]', NULL, NULL, NULL, NULL, 'Let the cat out of the bag = reveal a secret accidentally.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b1ec8bd9-50ee-4c26-9dfd-19df821a3561', 541, 'multiple_choice', 'C1', 'idioms', 'Don''t put all your eggs in one ___.', 'basket', '["bowl", "box", "bag", "basket"]', NULL, NULL, NULL, NULL, 'Don''t put all your eggs in one basket = don''t risk everything on one plan.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6e5dd919-46ba-4fd3-9d2c-9d7b6e9d6710', 542, 'multiple_choice', 'C1', 'idioms', 'The project is still up in the ___.', 'air', '["sky", "air", "wind", "clouds"]', NULL, NULL, NULL, NULL, 'Up in the air = uncertain, not yet decided.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f550e604-cea9-4b0c-be66-53cca5985660', 544, 'multiple_choice', 'C1', 'idioms', 'The new policy has opened a ___ of worms.', 'can', '["tin", "box", "can", "bag"]', NULL, NULL, NULL, NULL, 'Open a can of worms = create a complicated problem.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c4986b53-d8e2-4074-acd9-eb69844cf231', 545, 'multiple_choice', 'C1', 'idioms', 'He hit the ___ on the head with his analysis.', 'nail', '["hammer", "nail", "screw", "pin"]', NULL, NULL, NULL, NULL, 'Hit the nail on the head = describe exactly what is true.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3895390d-c54d-4176-80af-3a28b49239a3', 100, 'gap_fill', 'B1', 'everyday_expressions', 'I''m not sure. ___ (May be / Maybe) we should wait.', 'maybe', NULL, NULL, NULL, NULL, 'Maybe (one word) means perhaps', 'Maybe (one word) is an adverb meaning perhaps. May be expresses a different idea, like could be: it may be a good idea to get the car serviced.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be46389f-6905-4252-86b1-10d05ec6844f', 711, 'odd_one_out', 'C1', 'idioms', 'Which idiom does NOT relate to success?', 'break the ice', '["hit the nail on the head", "break the ice", "make headway", "bear fruit"]', NULL, NULL, NULL, NULL, '"Break the ice" means to start a conversation in a social setting, not about success.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1bc76918-eeb8-426e-9fb6-ee77d2b3867d', 636, 'sentence_building', 'A2', 'question_forms', '', 'are you coming to the party', '["are", "you", "coming", "to", "the", "party", "do", "will"]', NULL, NULL, NULL, NULL, 'To make a present continuous question, put ''are'' before the subject: ''Are you coming?'' not ''You are coming?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('599b4b5a-61c2-4992-94b1-7ab3b6c485a4', 1087, 'multiple_choice', 'A1', 'business_vocabulary', 'The money a company earns from selling its products is called _______.', 'revenue', '["revenue", "profit", "salary", "budget"]', NULL, NULL, NULL, NULL, 'Revenue is the total money a company earns from sales before any costs are deducted. Profit is what remains after costs. These are commonly confused.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('103a5537-6214-47a7-a615-46e613e5e955', 1088, 'multiple_choice', 'A1', 'business_vocabulary', 'A(/an) _______ is a formal meeting between a job applicant and an employer.', 'interview', '["interview", "appointment", "session", "review"]', NULL, NULL, NULL, NULL, 'An interview is a formal meeting to assess a candidate for a job. Compare: appraisal = a performance review for an existing employee.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('76420909-2d40-4ee3-ac03-eb2df4d58c58', 1089, 'multiple_choice', 'A1', 'business_vocabulary', 'Your _______ is the money you receive each month for your work.', 'salary', '["salary", "budget", "bonus", "revenue"]', NULL, NULL, NULL, NULL, 'A salary is a fixed regular payment, usually monthly. Compare: wage = typically paid weekly or hourly; bonus = extra payment for good performance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7e5b24c8-bfb1-4af3-b0e2-0c628eabbf07', 1090, 'multiple_choice', 'A1', 'business_vocabulary', 'A _______ is a person who owns part of a company.', 'shareholder', '["shareholder", "stakeholder", "creditor", "debtor"]', NULL, NULL, NULL, NULL, 'A shareholder owns shares in a company and has a financial stake in its profits. A stakeholder is broader — anyone affected by the company''s activities, including employees and customers.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('62c989ca-3082-43f6-af81-ca242cf89919', 1091, 'multiple_choice', 'A1', 'business_vocabulary', 'A written plan that shows how money will be spent is called a _______.', 'budget', '["budget", "invoice", "receipt", "forecast"]', NULL, NULL, NULL, NULL, 'A budget is a financial plan — what money is available and how it will be spent. Compare: forecast = a prediction of future financial performance; invoice = a request for payment.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90fcd7a6-14cb-4f19-ac77-84dfbe4ea100', 1092, 'multiple_choice', 'A2', 'business_vocabulary', 'The people responsible for running a company are called the _______.', 'board of directors', '["board of directors", "shareholders", "investors", "workforce"]', NULL, NULL, NULL, NULL, 'The board of directors is the group of people elected to govern a company on behalf of the shareholders. They set strategy and oversee senior management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bdef8a57-6448-4e08-94ab-ddbbc708251e', 1102, 'gap_fill', 'B1', 'business_vocabulary', 'The company invested in a new _______ system to track everything from raw materials to delivery.', 'supply chain', NULL, NULL, NULL, NULL, NULL, 'A supply chain is the full network of people, processes, and organisations involved in producing and delivering a product — from raw materials to the end customer.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fc322493-02dd-46fc-964c-5503aa388659', 382, 'multiple_choice', 'A1', 'plurals', 'There are three ___ on the table.', 'boxes', '["box", "boxs", "boxes", "boxen"]', NULL, NULL, NULL, NULL, 'Nouns ending in -x: add -es. Box → boxes.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e4783b4a-b78a-421f-b523-76d40e83cb68', 811, 'odd_one_out', 'B1', 'business', 'Three of these words relate to job applications. Which is the odd one out?', 'payslip', '["CV", "covering letter", "reference", "payslip"]', NULL, NULL, NULL, NULL, 'A CV, cover letter, and references are all things you provide when applying for a job. A payslip is what your employer gives you after you''ve got the job and been paid — so save it for later!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('876e6f44-b13a-404a-bac8-d3ad1dde98d4', 763, 'multiple_choice', 'B2', 'business', 'Which word best completes the sentence? "The company ___ a significant loss last quarter."', 'made', '["made", "did", "took", "had"]', NULL, NULL, NULL, NULL, '"Make a loss" and "make a profit" are fixed business collocations. You can also "make a decision", "make progress" — "make" is very busy in business English!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fbcd1e44-305e-4d2e-8fed-4943f9e7263e', 768, 'multiple_choice', 'B2', 'business', 'Which word means "to officially end a business relationship or agreement"?', 'terminate', '["terminate", "resign", "retire", "dismiss"]', NULL, NULL, NULL, NULL, '"Terminate" is used for contracts and agreements. "Resign" is when an employee leaves voluntarily. "Dismiss" is when an employer removes an employee. "Retire" is when someone stops work permanently at the end of their career.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4340f0e3-6dd6-478f-ade4-7f6e503f09a0', 777, 'multiple_choice', 'B2', 'business', '"The figures ___ that sales increased significantly in Q3."', 'indicate', '["indicate", "say", "tell", "speak"]', NULL, NULL, NULL, NULL, 'Data, figures, and statistics "indicate" or "suggest" things — they don''t "say" or "tell" like people do. "Indicate" is the professional choice here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d6d6f332-346d-4ccf-83c0-cc405398c46d', 519, 'multiple_choice', 'C1', 'formal_register', 'The proposal was met with ___ opposition from the board.', 'fierce', '["strongly", "hard", "heavy", "fierce"]', NULL, NULL, NULL, NULL, 'Fierce opposition = very strong, intense resistance to something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2903e7e4-3697-4213-9127-682953c81daf', 528, 'multiple_choice', 'C1', 'formal_register', 'The committee will ___ their findings next month.', 'publish', '["promote", "publish", "publicise", "presenting"]', NULL, NULL, NULL, NULL, 'Publish findings = formally release research results.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7a2b416e-051f-43f5-99ff-22bdc1b597bf', 516, 'multiple_choice', 'C1', 'formal_register', 'The results are ___ with previous research findings.', 'consistent', '["resistant", "consistent", "persistent", "insistent"]', NULL, NULL, NULL, NULL, 'Consistent with = in agreement with, matching previous evidence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ebea0f4e-706c-4d4e-863e-c135f8d45e50', 517, 'multiple_choice', 'C1', 'formal_register', 'The study ___ several important questions about the methodology.', 'raises', '["rises", "arises", "raises", "arouses"]', NULL, NULL, NULL, NULL, 'Raise questions = bring questions to attention. Raise is transitive (needs an object).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ac21427-d608-48e7-b2d2-ec91bb04a7b8', 518, 'multiple_choice', 'C2', 'formal_register', 'The evidence is largely ___, making it difficult to draw conclusions.', 'anecdotal', '["applicable", "anecdotal", "analogous", "analytical"]', NULL, NULL, NULL, NULL, 'Anecdotal = based on personal accounts rather than systematic research.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f52134d3-c63f-4012-a769-f021484c4ca9', 520, 'multiple_choice', 'C1', 'formal_register', 'We need to ___ this issue before it escalates.', 'address', '["access", "address", "assess", "dress"]', NULL, NULL, NULL, NULL, 'Address an issue = deal with or discuss a problem formally.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1134201-e5a2-4814-a0d3-05da49e3429a', 521, 'multiple_choice', 'C2', 'formal_register', 'The findings ___ a complex relationship between diet and health.', 'reveal', '["reverse", "revise", "reveal", "revolve"]', NULL, NULL, NULL, NULL, 'Reveal = show or make known something previously hidden.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('37e23b91-8471-47d6-bbc2-429085b2b521', 522, 'multiple_choice', 'C1', 'formal_register', 'The report provides a ___ analysis of the economic situation.', 'comprehensive', '["comprehensible", "compulsory", "compulsive", "comprehensive"]', NULL, NULL, NULL, NULL, 'Comprehensive = complete, covering all aspects thoroughly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('177ee61d-ad10-4206-9bad-f2a06025071c', 523, 'multiple_choice', 'C1', 'formal_register', 'The policy has been ___ criticised by human rights organisations.', 'widely', '["broadly", "largely", "vastly", "widely"]', NULL, NULL, NULL, NULL, 'Widely criticised = criticised by many people/groups.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9b016624-d7d9-40cd-bd8e-44f623e5520f', 524, 'multiple_choice', 'C2', 'formal_register', 'The minister ___ allegations of corruption.', 'refuted', '["referred", "refused", "reflected", "refuted"]', NULL, NULL, NULL, NULL, 'Refute = deny and disprove allegations or claims.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d31d3461-4bcc-4be3-847d-045662d96961', 525, 'multiple_choice', 'C1', 'formal_register', 'There are ___ implications for public health policy.', 'significant', '["signified", "signed", "significant", "signalling"]', NULL, NULL, NULL, NULL, 'Significant implications = important consequences or effects.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ef80fd09-49fd-4a07-b6c7-c9938ba61753', 526, 'multiple_choice', 'C1', 'formal_register', 'The project is ___ to be completed by December.', 'due', '["set", "bound", "owed", "due"]', NULL, NULL, NULL, NULL, 'Due to = scheduled/expected to happen at a particular time.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ee18f988-d95e-4239-ac82-e0bd99979bd3', 527, 'multiple_choice', 'C2', 'formal_register', 'The government has ___ new legislation to combat online fraud.', 'enacted', '["enforced", "endorsed", "enacted", "engaged"]', NULL, NULL, NULL, NULL, 'Enact legislation = formally pass a new law.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('71b4a5d4-465c-4473-9e93-8cc2f30c9d4d', 529, 'multiple_choice', 'C2', 'formal_register', 'The new policy is ___ to affect millions of workers.', 'poised', '["paused", "placed", "poised", "posed"]', NULL, NULL, NULL, NULL, 'Poised to = ready and about to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('726f10f8-9f18-48ad-80e7-03de6f1de1cf', 530, 'multiple_choice', 'C1', 'formal_register', 'Further research is ___ to confirm these initial findings.', 'warranted', '["willed", "warranted", "wanted", "wished"]', NULL, NULL, NULL, NULL, 'Warranted = justified, necessary. Formal academic usage.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61b146d3-8e4f-4d2f-9801-223e030e4097', 601, 'sentence_building', 'B1', 'business_english', 'Necesitamos programar una reunión para la próxima semana.', 'we need to schedule a meeting for next week', '["we", "need", "to", "schedule", "a", "meeting", "for", "next", "week", "organise", "on", "last"]', NULL, NULL, NULL, NULL, '"Schedule/organise a meeting" are both standard business collocations. "For next week" is the correct preposition for future time reference.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8aab570e-cf89-4a25-bff5-f12ea6411f50', 701, 'odd_one_out', 'C1', 'formal_register', 'Which word is NOT formal register?', 'ain''t', '["nevertheless", "furthermore", "ain''t", "notwithstanding"]', NULL, NULL, NULL, NULL, '"Ain''t" is very informal/slang. The others are formal discourse markers. If you want to upset an English teacher, you can use "ain''t". Especially with another negative... ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3033adcb-8555-4ff1-ab94-fb236aefbafe', 498, 'gap_fill', 'C1', 'formal_structures', 'Much ___ I admire her work, I disagree with her conclusions.', 'as', NULL, NULL, NULL, NULL, NULL, 'Much as/though = although/even though. Formal concessive structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6d1e725e-113d-4d08-92f2-c1178c675d7b', 499, 'gap_fill', 'C2', 'formal_structures', '___ it not been for your support, we would have failed.', 'Had', NULL, NULL, NULL, NULL, NULL, 'Had it not been for = If it had not been for. Formal inversion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('091207f2-f6ff-4135-a79d-603863bb715d', 500, 'gap_fill', 'C1', 'formal_structures', 'However hard she ___ (try), she couldn''t solve the problem.', 'tried', NULL, NULL, NULL, NULL, NULL, 'However + adjective/adverb + subject + verb. Means no matter how hard.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('34841080-5e5f-4890-9ceb-3d57e0d9e493', 778, 'multiple_choice', 'C1', 'formal vocabulary', '"The proposal was met with ___ opposition from community groups who had not been consulted."', 'vociferous', '["vociferous", "loud", "strong", "heavy"]', NULL, NULL, NULL, NULL, '"Vociferous" means loud and forceful in making one''s views known. While "loud" and "strong" are technically possible, "vociferous opposition" is the established formal collocation.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('322f8bc7-daad-452f-a75a-354115779127', 781, 'multiple_choice', 'C1', 'formal vocabulary', '"The new data ___ previous assumptions about consumer behaviour."', 'upended', '["upended", "uplifted", "updated", "upgraded"]', NULL, NULL, NULL, NULL, '"Upend" means to turn something on its head — to overturn established ideas completely. It is vivid and precise in academic and journalistic writing.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('72f8a632-a3da-4ac3-bdcc-6ccd6389e5fb', 787, 'multiple_choice', 'C1', 'formal/legal vocabulary', '"The treaty was ___ by both parliaments after a lengthy ratification process."', 'ratified', '["ratified", "validated", "endorsed", "approved"]', NULL, NULL, NULL, NULL, '"Ratify" specifically means to formally approve an agreement at the highest level (parliament, government). It is the precise legal term here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be4a4a4d-2b02-47c9-8023-0795454e0b37', 820, 'odd_one_out', 'C1', 'formal/legal vocabulary', 'Three of these are legal terms. Which is the odd one out?', 'curriculum', '["plaintiff", "defendant", "verdict", "curriculum"]', NULL, NULL, NULL, NULL, 'A plaintiff (the person who brings a case), a defendant (the person accused), and a verdict (the court''s decision) are all legal terms. A curriculum is an educational concept — entirely the wrong courtroom.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('01ae60bb-1130-455c-9de9-dd9735e05602', 852, 'error_correction', 'C1', 'formal/legal vocabulary', 'The contract is legally bounding for both parties.', 'The contract is legally binding for both parties.', '[]', NULL, NULL, NULL, NULL, '"Legally binding" means that parties are legally required to honour the contract. "Bounding" relates to jumping or forming a boundary — not a legal term.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7ad3453a-b240-43f1-b6b2-895c3b7b1425', 69, 'gap_fill', 'B2', 'reported_questions', 'She asked me where I ___ (live).', 'lived', NULL, '["live"]', NULL, NULL, 'No question word order in reported questions', 'In reported questions, use statement word order (not question order). Native speakers might keep the verb in the present.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6580bd53-0090-44df-ab0a-9666bf36d3ef', 165, 'multiple_choice', 'B2', 'reported_commands', 'She told me ___ quietly.', 'to speak', '["speak", "to speak", "speaking", "spoke"]', NULL, NULL, NULL, NULL, 'Tell + object + to + infinitive for reported commands.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1a2942b9-7215-433d-8f7b-8b1952dfd731', 31, 'gap_fill', 'B2', 'reported_speech', 'She said that she ___ (be) tired and wanted to go home.', 'was', NULL, NULL, NULL, NULL, 'Backshift the verb tense in reported speech', 'When reporting past statements, present simple becomes past simple.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07367138-d70b-4a20-9ce8-6edf87fedc82', 120, 'multiple_choice', 'B2', 'reported_speech', 'She said that she ___ feeling well.', 'wasn''t', '["weren''t", "wasn''t", "doesn''t", "didn''t"]', NULL, NULL, NULL, NULL, 'Backshift: present simple becomes past simple in reported speech.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('46466e63-a143-45ef-998b-25a4e3f5c889', 133, 'multiple_choice', 'B2', 'reported_questions', 'He asked me ___ I wanted to go to the cinema.', 'if', '["that", "if", "what", "which"]', NULL, NULL, NULL, NULL, 'If or whether for reported yes/no questions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e5ef099a-a90a-4fe8-8a9b-deb4368e3e91', 192, 'multiple_choice', 'B2', 'reported_thoughts', 'I thought you ___ coming to the party.', 'were', '["wasn''t", "were", "will", "would"]', NULL, NULL, NULL, NULL, 'Backshift in reported thoughts (present → past).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c9fea382-29de-4057-8bfb-48d38c3917cc', 1028, 'multiple_choice', 'A1', 'prepositions', 'The supermarket is right _______ the bank — they''re beside each other.', 'next to', '["next to", "at", "between", "in front of"]', NULL, NULL, NULL, NULL, 'Next to means directly beside something. Compare: between = in the middle of two things; in front of = facing something; opposite = directly across from something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7362d9d4-e940-44a1-898a-729d7e7bd27a', 70, 'gap_fill', 'B2', 'reported_questions', 'He wanted to know if I ___ (can / help) him.', 'could help', NULL, NULL, NULL, NULL, 'Can changes to could in reported questions', 'When reporting, can changes to could.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('953be6a5-a278-41e1-85d9-53230a0f1620', 487, 'gap_fill', 'C1', 'reported_speech', 'He urged the committee ___ (reconsider) their decision.', 'to reconsider', NULL, NULL, NULL, NULL, NULL, 'Urge + object + to infinitive: urge someone to do something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ca04b67-b697-4961-bc78-46881fcf7b33', 489, 'gap_fill', 'C2', 'reported_speech', 'The witness ___ to having seen the suspect near the scene.', 'admitted', NULL, NULL, NULL, NULL, NULL, 'Admit to + gerund: formally accept that something is true.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6a7be384-f159-4d11-9da5-f755a324b7da', 490, 'gap_fill', 'C1', 'reported_speech', 'He accused me ___ lying about the incident.', 'of', NULL, NULL, NULL, NULL, NULL, 'Accuse someone of + gerund: claim someone did something wrong.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5d86bbc0-0ec2-4918-b12b-d38f3d865f5c', 491, 'gap_fill', 'C1', 'reported_speech', 'She warned us ___ (not / go) near the river.', 'not to go', NULL, NULL, NULL, NULL, NULL, 'Warn + object + not to + infinitive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bf3acb47-a3ec-401c-afe3-2da5049d9cb9', 492, 'gap_fill', 'C1', 'reported_speech', 'He congratulated her ___ passing the exam.', 'on', NULL, NULL, NULL, NULL, NULL, 'Congratulate someone on + gerund/noun.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('924de50a-0141-4e57-8fc8-156a3b97b450', 493, 'gap_fill', 'C2', 'reported_speech', 'The spokesperson ___ to comment on the allegations.', 'declined', NULL, NULL, NULL, NULL, NULL, 'Decline/refuse to + infinitive: politely or firmly say no.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a11750f2-c78d-4451-9d76-7a14e4c12abc', 488, 'gap_fill', 'C1', 'reported_speech', 'She insisted ___ paying for the dinner.', 'on', NULL, NULL, NULL, NULL, NULL, 'Insist on + gerund: She insisted on paying.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5763dfc5-3d8a-4f76-91f3-ebc3f73100bf', 691, 'error_correction', 'B1', 'reported_speech', 'He told me that he will leave the company.', 'He told me that he would leave the company.', '[]', NULL, NULL, NULL, NULL, 'In reported speech, "will" changes to "would". Normally, technically, but native speakers sometimes use either if the situation remains the same: in this case he still ''will'' leave the company at the time of speaking. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8428878b-3f06-458a-af23-22c916a6351e', 32, 'gap_fill', 'B2', 'reported_speech', 'He told me that he ___ (will / help) me tomorrow.', 'would help', NULL, '["will help", "''ll help"]', NULL, NULL, 'Will changes to would in reported speech', 'When reporting, will changes to would technically, but natives might use both if the condition remains the same.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53a69356-407a-412d-b5f5-c4e4e9793bbb', 689, 'odd_one_out', 'C1', 'reporting_verbs', 'Which is NOT a reporting verb?', 'enumerate', '["claim", "deny", "enumerate", "insist"]', NULL, NULL, NULL, NULL, '"Enumerate" means ''to mention a number of things one by one", it is not a typical reporting verb.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d836d08d-d827-4bdb-94e5-ec82c6a897cc', 79, 'gap_fill', 'B1', 'zero_conditional', 'If you ___ (_ _ _ _) ice, it melts.', 'heat', NULL, NULL, NULL, NULL, 'Zero conditional: If + present, present', 'Zero conditional is used for general truths and scientific facts.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3bc5b128-b313-4b89-91a0-a862fa639245', 80, 'gap_fill', 'B1', 'zero_conditional', 'Water ___ (_ _ _ _ _) if you heat it to 100 degrees Celsius.', 'boils', NULL, NULL, NULL, NULL, 'Zero conditional uses present simple in both clauses', 'Zero conditional: If + present simple, present simple for general truths.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1bd98e99-b3cf-40fe-8ac1-4e6d70f6062e', 81, 'gap_fill', 'B2', 'mixed_conditional', 'If I ___ (be) better at maths, I would have studied engineering.', 'were', NULL, '["was"]', 'Were is more elegant and sounds more educated here. Native speakers judge each other for this use of was. ', NULL, 'Mixed conditional: present condition, past result', 'Mixed conditional combines elements of second and third conditional.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ce2be98-dbc9-4865-bbf4-30cae777acd4', 407, 'gap_fill', 'C1', 'mixed_conditionals', 'She wouldn''t have got the promotion if she ___ (not work) so hard.', 'hadn''t worked', NULL, NULL, NULL, NULL, NULL, 'Third conditional negative: hadn''t + past participle in the if-clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ce47455f-ae55-4d03-8db6-806142d9d17b', 5, 'gap_fill', 'B1', 'first_conditional', 'If the weather ___ (be) nice tomorrow, we''ll go to the beach.', 'is', NULL, NULL, NULL, '[{"answer": "is being", "feedback": "This isn''t wrong, but ''is'' is more natural in first conditional sentences."}]', 'First conditional uses present simple in the if-clause', 'First conditional: If + present simple, will + infinitive.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be62cd4a-2eb2-45b1-99b6-10edc4825ae9', 9, 'gap_fill', 'B1', 'second_conditional', 'If I ___ (have) more time, I would learn to play the guitar.', 'had', NULL, NULL, NULL, NULL, 'Second conditional uses past simple in the if-clause', 'Second conditional: If + past simple, would + infinitive (for hypothetical situations).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ebfea555-1327-42e7-9347-6c2867713e81', 10, 'gap_fill', 'B2', 'second_conditional', 'If she ___ (be) here now, she would know what to do.', 'were', NULL, NULL, NULL, '[{"answer": "was", "feedback": "''Was'' is acceptable in modern English, but ''were'' is preferred as it clearly signals a hypothetical situation."}]', 'Use ''were'' for all persons in second conditional', 'In second conditional, ''were'' is traditionally preferred for all persons to show the situation is hypothetical.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cfc8c7c1-3e11-47e2-a7e3-2a7e615ac256', 49, 'gap_fill', 'B2', 'third_conditional', 'If I ___ (know) about the party, I would have come.', 'had known', NULL, NULL, NULL, NULL, 'Third conditional: If + past perfect, would have + past participle', 'Third conditional is used for hypothetical past situations.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53d997f5-9793-4e59-942d-4a4946b05aa7', 207, 'gap_fill', 'A1', 'present_simple', 'We ___ (go) to the beach every summer.', 'go', NULL, NULL, NULL, NULL, NULL, 'Present simple for habits and routines.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa4fc414-318f-4f3e-94e3-f37c1032a7fd', 898, 'multiple_choice', 'A2', 'spanish', 'How do you say "Turn left" when giving directions in Spanish?', 'Gira a la izquierda', '["Gira a la izquierda", "Gira a la derecha", "Sigue recto", "Para aquí"]', NULL, NULL, NULL, NULL, '"Gira a la izquierda" = turn left. "Gira a la derecha" = turn right, "sigue recto" = go straight on, "para aquí" = stop here.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('62742ac6-c568-4f14-a40c-1c87b48a36f8', 1034, 'multiple_choice', 'A2', 'prepositions', 'He walked _______ the bridge and stopped to look at the river below.', 'across', '["across", "through", "around", "under"]', NULL, NULL, NULL, NULL, 'Across means from one side to the other of an open surface — a bridge, a road, a room. Compare: through = passing inside something enclosed; along = following the length of something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of movement"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a50e3fa8-fda9-48ae-9be2-727a1f67dce7', 501, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'The meeting has been ___ until next week.', 'put off', '["put down", "put off", "put out", "put up"]', NULL, NULL, NULL, NULL, 'Put off = postpone, delay to a later time.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bbd30fcc-ac6c-403d-aa11-b0406af7ff06', 502, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I can''t ___ with his constant complaining any longer.', 'put up', '["put on", "put off", "put up", "put away"]', NULL, NULL, NULL, NULL, 'Put up with = tolerate, endure something annoying.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('901f7a3a-97a4-4775-9ac3-6e6b6e22f70e', 486, 'gap_fill', 'C1', 'reported_speech', 'She denied ___ (take) the money.', 'taking', NULL, NULL, NULL, NULL, NULL, 'Deny + gerund: She denied taking / having taken.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0bfc6191-f3f2-41a5-b98a-5404b24e6fa4', 50, 'gap_fill', 'B2', 'third_conditional', 'She ___ (pass) the exam if she had studied harder.', 'would have passed', NULL, NULL, NULL, NULL, 'Would have + past participle in the result clause', 'Third conditional result clause: would have + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4a71930d-d550-430d-a8eb-558d124bfe64', 122, 'multiple_choice', 'B2', 'third_conditional', 'If I ___ you were coming, I would have prepared dinner.', 'had known', '["know", "known", "had known", "would know"]', NULL, NULL, NULL, NULL, 'Third conditional: If + past perfect, would have + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9b054453-7186-4ed8-ae74-c7261b2dbd16', 128, 'multiple_choice', 'B1', 'first_conditional', 'If it ___ tomorrow, we''ll cancel the picnic.', 'rains', '["will rain", "rains", "is raining", "rained"]', NULL, NULL, NULL, NULL, 'First conditional: If + present simple, will + infinitive.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c1187cf5-6cba-4b6b-97d2-ac5e5dc287ea', 138, 'multiple_choice', 'B2', 'second_conditional', 'If I ___ you, I would accept the job offer.', 'were', '["am", "are", "were", "will be"]', NULL, NULL, NULL, NULL, 'Were for all persons in second conditional (preferred form).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5c96c6d3-b82d-4421-9066-00e0aca63f94', 161, 'multiple_choice', 'B2', 'mixed_conditionals', 'If I ___ rich, I would have bought that house last year.', 'were', '["am", "was", "were", "had been"]', NULL, NULL, NULL, NULL, 'Mixed conditional: present condition, past result. Was here is inelegant English, were is better. ', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d857d004-8c83-47fb-80f8-54c0381dd333', 184, 'multiple_choice', 'B2', 'unless_if_not', '___ you hurry, we''ll miss the train.', 'Unless', '["If", "Unless", "When", "Although"]', NULL, NULL, NULL, NULL, 'Unless = if not.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7159c2be-dccd-4cd2-8e16-ecf562003830', 109, 'multiple_choice', 'B1', 'zero_conditional', 'If you ___ water to 100°C, it boils.', 'heat', '["will heat", "heat", "would heat", "heated"]', NULL, NULL, NULL, NULL, 'Zero conditional (general truths): If + present, present.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3af4d5ce-0f4c-4829-bb54-ae0c6ec5602e', 401, 'gap_fill', 'C1', 'mixed_conditionals', 'If I ___ (study) harder at school, I would have a better job now.', 'had studied', NULL, NULL, NULL, NULL, NULL, 'Mixed conditional (past → present): If + past perfect, would + base verb. Past action affecting present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('57952f81-2e0b-4b0a-bab1-893df7137913', 406, 'gap_fill', 'C1', 'mixed_conditionals', 'If I ___ (know) you were coming, I would have prepared dinner.', 'had known', NULL, NULL, NULL, '["knew"]', NULL, 'Third conditional: If + past perfect, would have + past participle. Natives might use "If I knew..." but it itsn''t technically correct.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('192952b7-114c-4170-ae48-e315c428a76f', 411, 'gap_fill', 'C2', 'mixed_conditionals', 'Should you ___ (require) any further assistance, do not hesitate to contact us.', 'require', NULL, NULL, NULL, NULL, NULL, 'Formal inversion: Should you require = If you should require. Very formal correspondence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0aa28f70-bc20-4616-91a0-47128745059d', 403, 'gap_fill', 'C1', 'mixed_conditionals', 'I ___ (not be) in this mess if I hadn''t listened to your advice.', 'wouldn''t be', NULL, NULL, NULL, NULL, NULL, 'Mixed conditional: would + base verb in the result clause when describing a present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('39568314-cd0a-4479-95b4-0ffb32ddac59', 404, 'gap_fill', 'C1', 'mixed_conditionals', 'If we ___ (leave) earlier, we wouldn''t be stuck in traffic now.', 'had left', NULL, '["''d left"]', NULL, NULL, NULL, 'Mixed conditional: If + past perfect for the unreal past condition.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('09a6cb5e-1a88-4af4-b4ff-dc67a1631fc5', 409, 'gap_fill', 'C1', 'mixed_conditionals', 'If he ___ (not be) so stubborn, he wouldn''t have lost all his friends.', 'weren''t', NULL, '["wasn''t"]', 'Was is inelegant here, native speakers judge each other on these things. Were always sounds better in hypotheticals. ', NULL, NULL, 'This can be either mixed conditional (present trait → past result) or third conditional.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c1c1256f-4536-45a9-a4c9-2fc03ffd36d6', 208, 'gap_fill', 'A2', 'present_simple', 'The shop ___ (close) at 9 pm.', 'closes', NULL, NULL, NULL, NULL, NULL, 'Present simple for schedules and timetables.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a33f3b06-bcbe-48d8-b5ee-1307bb87d9b7', 606, 'sentence_building', 'C1', 'third_conditional', 'Si hubiéramos sabido antes, habríamos cambiado el plan.', 'if we had known earlier we would have changed the plan', '["if", "we", "had", "known", "earlier", "we", "would", "have", "changed", "the", "plan", "will", "kept", "early"]', NULL, NULL, NULL, NULL, 'Third conditional: if + past perfect, would have + past participle. Used for hypothetical past situations.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fb217e11-668d-4476-a4fc-48ae1047d7e8', 513, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'I''ll ___ to you once I have more information.', 'get back', '["get on", "get through", "get back", "get by"]', NULL, NULL, NULL, NULL, 'Get back to someone = contact them again later with information.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e5a8b66a-7fb4-4a01-9e9f-36bee91cb546', 1072, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The new director has been asked to _______ the company''s unprofitable southern division and restore it to profitability.', 'turn around', NULL, NULL, NULL, NULL, NULL, 'To turn around a struggling business means to make it successful again after a period of poor performance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e53bb309-370c-4b9c-868c-ea1990c28548', 410, 'gap_fill', 'C1', 'mixed_conditionals', 'They ___ (still / live) in London if they hadn''t found jobs abroad.', 'would still be living', NULL, '["''d still be living", "''d still live"]', NULL, NULL, NULL, 'Mixed conditional: would + be living (continuous) for an ongoing present result.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07d2d978-a528-4cac-8e9b-f05cca3f3419', 412, 'gap_fill', 'C1', 'mixed_conditionals', 'If it ___ (not be) for the traffic, we would have arrived on time.', 'hadn''t been', NULL, NULL, NULL, NULL, NULL, 'If it hadn''t been for = without. Describes a factor that changed the outcome.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b89245a0-6ce3-4f61-8173-07b0e857187a', 408, 'gap_fill', 'C2', 'mixed_conditionals', 'Had I ___ (realise) the consequences, I would never have agreed.', 'realised', NULL, NULL, NULL, NULL, NULL, 'Formal inversion: Had I realised = If I had realised. Literary/formal style. Realized is the American spelling.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('578b4121-b096-46fe-837c-9ac6cfd5281a', 692, 'error_correction', 'B1', 'first_conditional', 'If I had time, I will help you.', 'If I have time, I will help you.', '[]', NULL, NULL, NULL, NULL, 'In first conditional, the "if" clause uses present simple, not the past simple "had".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1651ffaa-b0da-4a3f-9679-ffe6ba059ff5', 673, 'error_correction', 'C1', 'third_conditional', 'Had I knew about the problem, I would have acted sooner.', 'Had I known about the problem, I would have acted sooner.', '[]', NULL, NULL, NULL, NULL, 'Inverted third conditional uses the past participle: "Had I known", not "Had I knew".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eb91681d-0eb4-4c82-b438-39c60982d39e', 402, 'gap_fill', 'C1', 'mixed_conditionals', 'If she ___ (be) more confident, she would have applied for that job.', 'were', NULL, '["was"]', 'Was is inelegant here, native speakers judge each other on these things. Were always sounds better in hypotheticals. ', NULL, NULL, 'Mixed conditional (present → past): If + past simple, would have + past participle. Present characteristic affecting past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('27642820-b8f1-421f-9ead-17d1c000839b', 681, 'error_correction', 'B2', 'second_conditional', 'If I have more time, I would learn another language.', 'If I had more time, I would learn another language.', '[]', NULL, NULL, NULL, NULL, 'In the second conditional, the "if" clause uses past simple, not  the infinitive " have".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('96757144-3c45-44bb-ae85-e008530fb0f4', 705, 'error_correction', 'C2', 'mixed_conditionals', 'Were it not of his help, the project would have failed.', 'Were it not for his help, the project would have failed.', '[]', NULL, NULL, NULL, NULL, 'The correct structure is "Were it not for", not "Were it not of".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('005d5a36-1319-45d3-ba3c-17b2f23861b4', 671, 'odd_one_out', 'B2', 'conditionals', 'Which is NOT a conditional form?', 'I am going to', '["If I had known", "I wish I could", "Unless you try", "I am going to"]', NULL, NULL, NULL, NULL, '"I am going to" expresses future plans, not a conditional structure.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d73a611e-2188-43af-ba2a-e0fd996b6999', 405, 'gap_fill', 'C2', 'mixed_conditionals', 'Were it not for her dedication, she ___ (never / achieve) such success.', 'would never have achieved', NULL, '["''d never have achieved"]', NULL, NULL, NULL, 'Formal inversion: Were it not for = If it were not for. Quite formal register.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('077da184-5046-4e0f-a776-16b401836d8c', 6, 'gap_fill', 'B2', 'passive_voice', 'This building ___ (construct) in 1892 and it''s still standing today.', 'was constructed', NULL, NULL, NULL, NULL, 'Use passive voice in past simple', 'Passive voice past: was/were + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('985da192-f802-4851-99a7-6af12fef3a31', 57, 'gap_fill', 'B2', 'passive_voice_present', 'Spanish ___ (speak) in many countries around the world.', 'is spoken', NULL, NULL, NULL, NULL, 'Passive present: is/are + past participle', 'Passive voice present: is/are + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7de86c65-cb28-4421-b611-3721a70e50f5', 131, 'multiple_choice', 'B2', 'passive_present_perfect', 'The work ___ yet.', 'hasn''t been finished', '["hasn''t finishing", "hasn''t been finished", "isn''t finishing", "wasn''t finished"]', NULL, NULL, NULL, NULL, 'Present perfect passive: has/have been + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3d3e50af-a83e-403d-8adb-5577dc44c546', 58, 'gap_fill', 'B2', 'passive_voice_future', 'The new hospital ___ (open) next month.', 'will be opened', NULL, NULL, NULL, NULL, 'Passive future: will be + past participle', 'Passive voice future: will be + past participle.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bc97ba6f-6d42-4b3f-a6a1-f7fd7eb359c0', 435, 'gap_fill', 'C1', 'advanced_passive', 'The new policy is said ___ (benefit) thousands of workers.', 'to benefit', NULL, NULL, NULL, NULL, NULL, 'Impersonal passive: Subject + is said/believed/thought + to + infinitive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b5027639-61e2-4a58-b13e-ce51c04fe31e', 436, 'gap_fill', 'C1', 'advanced_passive', 'He is believed ___ (leave) the country last week.', 'to have left', NULL, NULL, NULL, NULL, NULL, 'Impersonal passive with past reference: is believed + to have + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70b4e724-424e-4a42-8f91-62c9003d1448', 439, 'gap_fill', 'C1', 'advanced_passive', 'She doesn''t like ___ (tell) what to do.', 'being told', NULL, NULL, NULL, NULL, NULL, 'Passive gerund: being + past participle after verbs like like, hate, enjoy.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9caea07b-f114-42f3-b5ab-e70be6aed0f1', 440, 'gap_fill', 'C2', 'advanced_passive', 'The proposal is expected ___ (approve) by the board tomorrow.', 'to be approved', NULL, NULL, NULL, NULL, NULL, 'Impersonal passive + passive infinitive: is expected + to be + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bd0466a0-af58-404c-83aa-b5ed3f202b62', 614, 'sentence_building', 'B2', 'second_conditional', NULL, 'if I had more time I would learn another language', '["if", "I", "had", "more", "time", "I", "would", "learn", "another", "language", "will", "other", "learning"]', NULL, NULL, NULL, NULL, 'Second conditional: if + past simple, would + infinitive. For unreal present/future situations.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d645901b-656b-46b3-9ffd-170ac2e4ea14', 901, 'multiple_choice', 'A2', 'spanish', 'What does "el semáforo" mean in English?', 'Traffic light', '["Traffic light", "Roundabout", "Crossroads", "Car park"]', NULL, NULL, NULL, NULL, '"El semáforo" = traffic light. "La rotonda" = roundabout, "el cruce" = crossroads, "el aparcamiento" = car park.', '2026-03-03 14:10:39.181019+00', NULL, NULL, 'both', '{Vocabulario}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('54333d78-c6ab-46ee-8e6e-a09d13283cb2', 554, 'multiple_choice', 'C1', 'confusing_words', 'She showed great ___ in handling the crisis.', 'sensitivity', '["sensibility", "sensitivity", "sense", "sensation"]', NULL, NULL, NULL, NULL, 'Sensitivity = awareness of others'' feelings. Sensibility = ability to appreciate art/feelings.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c738504f-3351-44e2-8d86-696bb531ced4', 543, 'multiple_choice', 'C2', 'idioms', 'She''s been sitting on the ___ about whether to accept the offer.', 'fence', '["gate", "fence", "bench", "wall"]', NULL, NULL, NULL, NULL, 'Sit on the fence = avoid making a decision or taking a side.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5653194-849b-41e8-b946-edd28b163658', 442, 'gap_fill', 'C1', 'advanced_passive', 'Having ___ (inform) of the changes, the staff adapted quickly.', 'been informed', NULL, NULL, NULL, NULL, NULL, 'Perfect passive participle: Having been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7954114a-c723-40d4-9caf-b51af0e2ef52', 438, 'gap_fill', 'C1', 'advanced_passive', 'The building ___ (demolish) by the time we arrived.', 'had been demolished', NULL, NULL, NULL, NULL, NULL, 'Past perfect passive: had been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f995dfb3-8ba0-411f-9d40-b91f625f0c6a', 441, 'gap_fill', 'C1', 'advanced_passive', 'They want ___ (promote) by the end of the year.', 'to be promoted', NULL, '["a promotion"]', 'An alternative structure, says the same thing.', NULL, NULL, 'Passive infinitive: to be + past participle after want, expect, hope.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f470558e-522d-40f1-b752-ca95c0f925a8', 437, 'gap_fill', 'C2', 'advanced_passive', 'The suspect is thought ___ (hide) in the mountains at the moment.', 'to be hiding', NULL, '["to be in hiding"]', NULL, NULL, NULL, 'Impersonal passive + continuous: is thought + to be + verb-ing.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dcdd0082-1218-4dd8-ab8a-08bfb34d00e2', 717, 'error_correction', 'B1', 'passive_voice', 'The meeting was cancel due to bad weather.', 'The meeting was cancelled due to bad weather.', '[]', NULL, NULL, NULL, NULL, 'In the passive voice, we need the past participle: "was cancelled".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f3e48bbb-7914-4364-bce3-e426095d5c25', 155, 'multiple_choice', 'B2', 'relative_clauses_whose', 'That''s the woman ___ son won the competition.', 'whose', '["who", "which", "whose", "that"]', NULL, NULL, NULL, NULL, 'Whose for possession in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c0b7b387-3be5-44fb-8207-d3aed45ed99e', 28, 'gap_fill', 'B2', 'relative_clauses', 'That''s the man ___ (who / that) wife works with my sister.', 'whose', NULL, NULL, NULL, NULL, 'Possessive relative pronoun', 'Whose is used to show possession in relative clauses.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('560b3803-e40d-4a37-90cc-8dd1f11ca7b6', 105, 'multiple_choice', 'B1', 'relative_clauses', 'That''s the woman ___ lives next door to us.', 'who', '["which", "what", "where", "who"]', NULL, NULL, NULL, NULL, 'Who for people in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4aeb9af7-723f-48dd-b9bc-83193369b8a0', 127, 'multiple_choice', 'B2', 'relative_clauses', 'That''s the hotel ___ we stayed last summer.', 'where', '["which", "where", "when", "who"]', NULL, NULL, NULL, NULL, 'Where for places in relative clauses.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cb3e5741-df83-4dd5-9107-786a7ff149a9', 564, 'multiple_choice', 'C1', 'relative_clauses', 'The reason ___ she left has never been explained.', 'why', '["which", "why", "that", "what"]', NULL, NULL, NULL, NULL, 'The reason why + clause. Why introduces the relative clause. This sentence would be fine without why. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b3b13993-33a4-412e-8a90-b3ab4454249a', 176, 'multiple_choice', 'B2', 'relative_clauses_which', 'My car, ___ I only bought last year, has broken down.', 'which', '["that", "which", "who", "what"]', NULL, NULL, NULL, NULL, 'Which in non-defining relative clauses (with commas).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e7cd320d-9192-4b5e-9f7b-236e36e24d53', 1057, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Can we _______ the meeting until Thursday? I have a conflict on Tuesday.', 'put off', '["put off", "put on", "put up", "put away"]', NULL, NULL, NULL, NULL, 'To put off means to postpone — to move something to a later date. Compare: put on = to add or start something; put up = to tolerate or display.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('68e033ab-26a0-4b93-871c-0477e2273ed7', 190, 'multiple_choice', 'B2', 'nominal_relative_clauses', '___ matters most is your happiness.', 'What', '["That", "What", "Which", "Who"]', NULL, NULL, NULL, NULL, 'What as subject of the sentence (= the thing that).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b60b5479-122c-4814-b989-bca4b23be04c', 563, 'multiple_choice', 'C1', 'relative_clauses', 'The report, ___ was published yesterday, confirms our findings.', 'which', '["what", "that", "which", "it"]', NULL, NULL, NULL, NULL, 'Non-defining relative clause: use which (not that) with commas.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9f7e7173-c7fb-441b-a0bd-b0d0c53e71f3', 27, 'gap_fill', 'B1', 'relative_clauses', 'The book ___ (which / who / that / why) I''m reading is really interesting.', 'which', NULL, NULL, NULL, NULL, 'Relative pronoun for things', 'Which or that can be used for things in relative clauses.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d927433-c8f8-4737-9904-bbe816dcafcd', 657, 'sentence_building', 'B2', 'passive_voice', '', 'the report must be finished by Friday at the latest', '["the", "report", "must", "be", "finished", "by", "friday", "at", "the", "latest", "is", "finishing", "has"]', NULL, NULL, NULL, NULL, 'Passive modal: must + be + past participle. Expresses obligation with passive voice.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6d976b3e-ce26-4fd0-ad7c-10d90f757ff0', 612, 'sentence_building', 'B1', 'passive_voice', NULL, 'the meeting was cancelled due to bad weather', '["the", "meeting", "was", "cancelled", "due", "to", "bad", "weather", "because", "of", "good", "held"]', NULL, NULL, NULL, NULL, 'Passive voice (was cancelled) + "due to" or "because of" to give the reason.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2b25c47-337c-4aef-bac8-bd0521d1361d', 724, 'error_correction', 'C2', 'relative_clauses', 'The research paper, that was published last year, has been widely cited.', 'The research paper, which was published last year, has been widely cited.', '[]', NULL, NULL, NULL, NULL, 'Non-defining relative clauses (with commas) use "which", not "that".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Relative clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('00385849-a740-46aa-8df9-be59237d395f', 82, 'gap_fill', 'B2', 'inversion', 'Never ___ (I / see) such a beautiful sunset.', 'have I seen', NULL, NULL, NULL, NULL, 'Inversion after negative adverbs', 'After negative adverbs like ''never'', we use question word order.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1016dcc5-c087-4729-bcbb-9e216ed719de', 157, 'multiple_choice', 'B2', 'inversion_negative', 'Never ___ such a beautiful sunset.', 'have I seen', '["I have seen", "have I seen", "I saw", "did I saw"]', NULL, NULL, NULL, NULL, 'Inversion after negative adverbs (question word order).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5ceec80f-2bba-427f-89c9-b2874942bd48', 180, 'multiple_choice', 'B2', 'inversion_conditional', '___ I known, I would have told you.', 'Had', '["If", "Had", "Would", "Should"]', NULL, NULL, NULL, NULL, 'Inversion in third conditional (Had I known = If I had known).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('920b2b09-469c-43c3-a44f-fca083edd6c9', 413, 'gap_fill', 'C1', 'inversion', 'Not only ___ she speak French, but she also speaks Mandarin.', 'does', NULL, NULL, NULL, NULL, NULL, 'Inversion after Not only: Not only + auxiliary + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('002bee35-cf92-41bb-915f-50bfe663d67a', 415, 'gap_fill', 'C1', 'inversion', 'Never before ___ the company faced such a crisis.', 'had', NULL, NULL, NULL, NULL, NULL, 'Inversion after Never before: Never before + had + subject + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('11556980-6811-4ab9-a353-888d54d27001', 416, 'gap_fill', 'C2', 'inversion', 'Under no circumstances ___ you to leave the building.', 'are', NULL, NULL, NULL, NULL, NULL, 'Inversion after Under no circumstances: Under no circumstances + auxiliary + subject.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cc0b81ec-077a-44e8-9aa4-bd77e5382e5e', 417, 'gap_fill', 'C1', 'inversion', 'No sooner ___ we arrived than it started to rain.', 'had', NULL, NULL, NULL, NULL, NULL, 'No sooner + had + subject + past participle + than. Describes two quick past events.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('10fc99e5-6f0f-449f-92c4-630e7f4e01d4', 418, 'gap_fill', 'C1', 'inversion', 'Hardly ___ she finished speaking when the phone rang.', 'had', NULL, NULL, NULL, NULL, NULL, 'Hardly + had + subject + past participle + when. Similar to no sooner...than.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7313c298-e261-4b77-b422-166fb54ce200', 419, 'gap_fill', 'C2', 'inversion', 'Not until the results were published ___ the extent of the problem become clear.', 'did', NULL, NULL, NULL, NULL, NULL, 'Not until + clause, + auxiliary + subject + verb. Emphatic structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c32ce406-0552-464f-8811-4cadd2cccda6', 573, 'multiple_choice', 'C1', 'advanced_grammar', 'He spoke ___ he were an expert, but he clearly wasn''t.', 'as if', '["what if", "as if", "only if", "even if"]', NULL, NULL, NULL, NULL, 'As if + past subjunctive (were) for unreal present comparisons.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06ff545a-7543-497a-8c8c-abdae5848c3b', 574, 'multiple_choice', 'C2', 'advanced_grammar', '___ the weather been better, we would have gone hiking.', 'Had', '["If", "Should", "Had", "Were"]', NULL, NULL, NULL, NULL, 'Had + subject + past participle = If the weather had been better. Formal inversion.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8be4800b-b9f6-4a3f-a7c6-b586e59a7594', 1074, 'gap_fill', 'B2', 'business_phrasal_verbs', 'The legal team is _______ the terms of the contract very carefully before anything is signed.', 'going over', NULL, NULL, NULL, '["going through"]', NULL, 'To go over (or go through) a contract means to review it carefully, checking all the terms and conditions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('84f88bbf-409c-439f-9d50-4cd0c22c7b87', 1075, 'gap_fill', 'B2', 'business_phrasal_verbs', 'After the failed product launch, it took the brand two years to _______ its reputation.', 'build up', NULL, NULL, NULL, '["rebuild", "restore", "recover"]', NULL, 'To build up a reputation means to develop it gradually over time. After damage, rebuild and restore are also common alternatives.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f1dbe941-058b-4f5c-aeaf-4ae22123d56e', 1076, 'gap_fill', 'B2', 'business_phrasal_verbs', 'The CEO _______ her experience in emerging markets when pitching to the investors.', 'drew on', NULL, NULL, NULL, NULL, NULL, 'To draw on something means to use it as a resource — experience, skills, knowledge, or connections.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dab7f0ad-9e3f-4a27-bb06-d4456880eb16', 662, 'sentence_building', 'C1', 'inversion', '', 'not only did she pass the exam but she also got the highest mark', '["not", "only", "did", "she", "pass", "the", "exam", "but", "she", "also", "got", "the", "highest", "mark", "passed", "get", "to"]', NULL, NULL, NULL, NULL, 'Not only... but also: emphatic structure with inversion after Not only.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d464d6e8-e1a6-441f-be29-c5291b167f77', 420, 'gap_fill', 'C1', 'inversion', 'Only after reading the report ___ I understand the situation.', 'did', NULL, NULL, NULL, NULL, NULL, 'Only after + noun/gerund, + auxiliary + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('348c8061-7c2d-4c1b-8167-05f322b37870', 422, 'gap_fill', 'C2', 'inversion', 'So impressive ___ the performance that the audience gave a standing ovation.', 'was', NULL, NULL, NULL, NULL, NULL, 'So + adjective + auxiliary + subject + that clause. For dramatic emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('003cd481-c9d3-49d2-b247-02834a709f26', 421, 'gap_fill', 'C1', 'inversion', 'Seldom ___ we had the opportunity to work with such talented people.', 'have', NULL, NULL, NULL, NULL, NULL, 'Seldom + auxiliary + subject + verb. For emphasis on rarity.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ed6b5ea8-d6c0-479b-b48b-55abc233b2ef', 721, 'error_correction', 'C1', 'inversion', 'Rarely have I saw such a beautiful sunset.', 'Rarely have I seen such a beautiful sunset.', '[]', NULL, NULL, NULL, NULL, 'After "rarely" at the start of a sentence, we need inversion: "have I seen" using the past participle not the past simple.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a9d45b3d-4d91-4c99-b6e5-36ffe713fbe3', 707, 'error_correction', 'C1', 'inversion', 'Not only did she passed the exam, but she got the highest mark.', 'Not only did she pass the exam, but she got the highest mark.', '[]', NULL, NULL, NULL, NULL, 'After "Not only" at the start of a sentence, we need inversion, and after the auxiliary did the infinitive: "did she pass".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61885334-0741-43d8-bb9f-d2c27883e5e4', 694, 'error_correction', 'C2', 'inversion', 'Scarcely had the meeting begun than the fire alarm went off.', 'Scarcely had the meeting begun when the fire alarm went off.', '[]', NULL, NULL, NULL, NULL, '"Scarcely...when" is the correct pattern, not "scarcely...than". Compare: "No sooner...than".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2ef1201d-f9be-4ff6-9f65-3455a2b4008d', 414, 'gap_fill', 'C1', 'inversion', 'Rarely ___ I seen such a beautiful sunset.', 'have', NULL, NULL, NULL, NULL, NULL, 'Inversion after Rarely: Rarely + auxiliary + subject + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('55221332-bc3c-4d2c-8dce-9e91bc3ee0aa', 971, 'multiple_choice', 'A1', 'hotel_vocabulary', 'Would you like your _______  to be sent to your room?', 'luggage', '["luggage", "package", "equipment", "belongings"]', NULL, NULL, NULL, NULL, 'Luggage (uncountable) refers to the bags and suitcases you travel with. It has no plural form — you cannot say luggages.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f631f4eb-e2d6-491d-8ab5-0794ddeabf80', 725, 'odd_one_out', 'C1', 'inversion', 'Which does NOT use inversion?', 'I always go', '["Never have I", "Seldom does she", "I always go", "Not only did he"]', NULL, NULL, NULL, NULL, '"I always go" uses normal word order. The others use inversion after negative adverbials.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d9268d95-1aff-4725-ae0a-8f41dba46d71', 85, 'gap_fill', 'B2', 'would_rather', 'I''d rather ___ (stay) at home tonight than go out.', 'stay', NULL, NULL, NULL, NULL, 'Would rather + infinitive without ''to''', 'Would rather is followed by the infinitive without ''to''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0176ccf6-f287-497a-8c57-0e03c2e1a342', 86, 'gap_fill', 'B2', 'would_rather', 'She''d rather you ___ (not / smoke) in the house.', 'didn''t smoke', NULL, NULL, NULL, NULL, 'Would rather + subject + past simple', 'When talking about what you want someone else to do, use would rather + subject + past simple.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5393dc89-5bb1-4158-813e-65285e901e0b', 92, 'gap_fill', 'B1', 'must_vs_have_to', 'You ___ (must not / don''t have to) bring anything to the party. Everything is ready!', 'don''t have to', NULL, '["needn''t"]', NULL, NULL, 'No obligation', 'Don''t have to means there is no obligation (it''s not necessary).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('73c9ec88-d384-4632-b6c0-f6eb34a4d212', 271, 'gap_fill', 'A1', 'can_and_cant', 'She ___ (can / swim) very well.', 'can swim', NULL, NULL, NULL, NULL, NULL, 'Can + base verb for ability. No -s for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b5351ad1-b89e-4f2c-9e19-a1ce93022440', 272, 'gap_fill', 'A1', 'can_and_cant', 'I ___ (not can / drive).', 'can''t drive', NULL, NULL, NULL, NULL, NULL, 'Can''t / cannot + base verb for inability.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1cff20da-e4a8-43e7-8391-b2b31a7cbd6f', 8, 'gap_fill', 'B2', 'modal_deduction_past', 'The lights are off. They ___ (must / go) out already.', 'must have gone', NULL, NULL, NULL, NULL, 'Must have + past participle for logical deductions about the past', 'Must have + past participle expresses a logical conclusion about something in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('946b56d1-ec0a-4020-8ad3-64f86df55664', 17, 'gap_fill', 'B1', 'modals_ability', 'When I was younger, I ___ (can / run) really fast.', 'could run', NULL, NULL, NULL, NULL, 'Past ability uses ''could''', 'Could + infinitive expresses past ability.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('404b46d6-24d2-41b0-ab46-9087d15215fb', 18, 'gap_fill', 'B1', 'modals_permission', '___ (I / can / borrow) your pen for a moment?', 'can I borrow', NULL, NULL, NULL, NULL, 'Asking for permission', 'Can, could, or may are used to ask for permission.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48a7a006-8481-4c32-b8a8-df1543dd60fb', 20, 'gap_fill', 'B2', 'modals_prohibition', 'You ___ (must not / _ _ _ _) here. It''s a bus stop.', 'must not park', NULL, NULL, NULL, NULL, 'Strong prohibition', 'Must not expresses prohibition.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f044539c-edee-4f5c-b545-d358e9f25cf6', 103, 'multiple_choice', 'B1', 'modals_obligation', 'You ___ wear a seatbelt in the car. It''s the law.', 'must', '["may", "could", "must", "might"]', NULL, NULL, NULL, NULL, 'Must for strong obligation or rules/laws.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('328e53bf-99bc-46bf-baec-1b605f1c88c2', 123, 'multiple_choice', 'B1', 'modals_ability', 'When I was younger, I ___ run very fast.', 'could', '["can", "could", "was able", "managed"]', NULL, NULL, NULL, NULL, 'Could for general past ability.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ecfec3e3-e53a-497d-84a4-3a95345f45eb', 129, 'multiple_choice', 'B2', 'modals_no_obligation', 'You ___ come to the party if you don''t want to.', 'don''t have to', '["mustn''t", "don''t have to", "can''t", "have to"]', NULL, NULL, NULL, NULL, 'Don''t have to means no obligation.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d5b550e6-a04b-42d3-a9e8-5f4b196c11cd', 149, 'multiple_choice', 'B2', 'modals_deduction_past', 'They''re not here. They ___ forgotten about the meeting.', 'must have', '["must", "must have", "should", "should have"]', NULL, NULL, NULL, NULL, 'Must have + past participle for logical deductions about the past.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1a205282-6429-4ea1-a3b0-8eb55af68171', 665, 'sentence_building', 'C1', 'inversion', 'De haberlo sabido, habria actuado de otra manera.', 'had I known I would have acted differently', '["had", "I", "known", "I", "would", "have", "acted", "differently", "did", "knowing", "been", "other"]', NULL, NULL, NULL, NULL, 'Inverted third conditional: Had + subject + past participle, would have + past participle.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c921161-be71-4775-be8b-a92841ebc019', 666, 'sentence_building', 'C2', 'inversion', '', 'seldom have I encountered such a thoroughly convincing argument', '["seldom", "have", "I", "encountered", "such", "a", "thoroughly", "convincing", "argument", "hardly", "an", "has", "encounter"]', NULL, NULL, NULL, NULL, 'Negative adverb inversion: Seldom + auxiliary + subject. Very formal and emphatic.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ad6c863-55e5-4124-ab96-19e3b48131e6', 1067, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The finance team will _______ the numbers and let us know if the project is viable.', 'run through', '["run through", "run up", "run across", "run down"]', NULL, NULL, NULL, NULL, 'To run through the numbers means to go over them quickly and systematically. Compare: run up = to accumulate costs or debt; run down = to gradually reduce, or to speak badly of someone.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3739ea1a-dcbe-4b7a-90cc-d8198e6337fb', 453, 'gap_fill', 'C1', 'collocations', 'She ___ a key role in the success of the project.', 'played', NULL, NULL, NULL, NULL, NULL, 'Play a role in = contribute to, be involved in.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('18b7b3f3-399b-466f-a84a-dd90a2d4b725', 454, 'gap_fill', 'C1', 'collocations', 'The incident ___ serious concerns about safety standards.', 'raised', NULL, NULL, NULL, NULL, NULL, 'Raise concerns = cause people to worry about something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('50476f73-dd0f-4893-a87d-0e44cc6e2a15', 455, 'gap_fill', 'C2', 'collocations', 'The project was carried ___ despite significant opposition.', 'out', NULL, NULL, NULL, NULL, NULL, 'Carry out = complete, execute. A project, a plan, research, an investigation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Collocation}');
