INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6460ffa0-4ca9-4c4c-82e7-66071870d521', 135, 'multiple_choice', 'B1', 'modals_advice', 'You look tired. You ___ go to bed earlier.', 'should', '["can", " don''t have to", "ought", "should"]', NULL, NULL, NULL, NULL, 'Should for giving advice.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0b6719be-66df-42a1-8197-21dd48077731', 152, 'multiple_choice', 'B1', 'can_could_permission', '___ I borrow your pen for a moment?', 'Can', '["Need", "Can", "Must", "Should"]', NULL, NULL, NULL, NULL, 'Can/Could for asking permission.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('09bd9a4a-3d23-4480-b271-7acb423d045a', 196, 'multiple_choice', 'B2', 'had_better', 'You ___ leave now or you''ll be late.', 'had better', '["should better", "would better", "had better", "have better"]', NULL, NULL, NULL, NULL, 'Had better for strong advice (something bad might happen if you don''t).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e17943fa-f86e-4f5d-abf6-03ef82608ac9', 111, 'multiple_choice', 'B2', 'modals_deduction', 'She''s not answering her phone. She ___ be in a meeting.', 'must', '["can''t", "ought to", "must", "should"]', NULL, NULL, NULL, NULL, 'Must for logical deductions (high certainty).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
