INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('768667f5-f6e1-4595-b0e5-78807b2d24c9', 427, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (needn''t / buy) so much food. Half of it was wasted.', 'needn''t have bought', NULL, NULL, NULL, NULL, NULL, 'Needn''t have + past participle: it wasn''t necessary, but she did it anyway.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('69efdf7d-4f88-444b-85cd-030df9c0e4d4', 429, 'gap_fill', 'C2', 'modal_perfects', 'He ___ (may / misunderstand) the instructions.', 'may have misunderstood', NULL, NULL, NULL, NULL, NULL, 'May have + past participle for possibility in the past (slightly more formal than might).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
