INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('020fcd36-f984-4c33-af71-1dc27f9ddf1e', 433, 'gap_fill', 'C2', 'modal_perfects', 'The letter ___ (ought to / arrive) by now.', 'ought to have arrived', NULL, NULL, NULL, NULL, NULL, 'Ought to have + past participle: expected but possibly didn''t happen.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('65931d19-cc9d-4efd-9975-f85dd407c070', 434, 'gap_fill', 'C1', 'modal_perfects', 'I ___ (not / should / eat) so much at dinner. I feel terrible.', 'shouldn''t have eaten', NULL, NULL, NULL, NULL, NULL, 'Shouldn''t have + past participle for regret about a past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa9747fd-39e4-4ddf-bbd8-c86e9a7a4607', 423, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (must / forget) about the meeting. She''s not here.', 'must have forgotten', NULL, '["must''ve forgotten"]', NULL, NULL, NULL, 'Must have + past participle for logical deduction about the past (very probable).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8935954b-67cd-4005-8078-ac836b48af33', 425, 'gap_fill', 'C1', 'modal_perfects', 'You ___ (should / tell) me earlier. Now it''s too late.', 'should have told', NULL, '["should''ve told"]', NULL, NULL, NULL, 'Should have + past participle for criticism or regret about the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('000f0061-0907-4781-aa1e-0c29ed499bb4', 428, 'gap_fill', 'C1', 'modal_perfects', 'You ___ (could / warn) us about the traffic.', 'could have warned', NULL, '["could''ve warned"]', NULL, NULL, NULL, 'Could have + past participle: you had the ability/opportunity but didn''t do it.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('21148bd5-f00b-4566-8585-0bc97cbb76fc', 430, 'gap_fill', 'C1', 'modal_perfects', 'She ___ (would / love) to see the show, but she was working.', 'would have loved', NULL, '["would''ve loved"]', NULL, NULL, NULL, 'Would have + past participle for imagined/wished situations in the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('032c0418-6fa2-4637-9f50-fc381d6089c3', 432, 'gap_fill', 'C1', 'modal_perfects', 'He looks exhausted. He ___ (must / work) all night.', 'must have been working', NULL, '["must''ve worked", "must''ve been working"]', NULL, NULL, NULL, 'Must have been + verb-ing for deductions about continuous past actions.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('865578e5-a12b-4c98-8867-d50fec1812ea', 699, 'error_correction', 'C1', 'modal_perfects', 'The project should have being completed by last month.', 'The project should have been completed by last month.', '[]', NULL, NULL, NULL, NULL, 'In passive modal perfect, we need the past participle: "been", not "being".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('151b731d-3fc1-4055-a86f-7a209288915b', 4, 'gap_fill', 'B1', 'modals_advice', 'You ___ (should / verb) a doctor about that cough. It sounds serious.', 'should see', NULL, NULL, NULL, '[{"answer": "should be seeing", "feedback": "This isn''t wrong, but ''should see'' is more natural for giving advice about a single action."}]', 'Use should + infinitive for giving advice', 'Should + infinitive is used to give advice or recommendations.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6901d99e-c9f0-4594-9a1c-bb4d4cd21838', 276, 'gap_fill', 'A2', 'can_and_cant', '___ I ___ (can / use) your phone?', 'Can...use', NULL, NULL, NULL, NULL, NULL, 'Can I...? for asking permission politely.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8804dafc-b158-4ec9-a422-53d040823e4c', 91, 'gap_fill', 'B1', 'must_vs_have_to', 'I ___ (must / have to) get up early tomorrow for my flight.', 'must', NULL, NULL, NULL, NULL, 'Both express obligation', 'Both must and have to express obligation, though must is more formal or personal. Native speakers often use both interchangeably.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d6aa1e96-1a0f-4eff-a888-1990e1d251de', 19, 'gap_fill', 'B2', 'modals_obligation', 'You ___ (not have to / come) to the meeting if you''re too busy.', 'don''t have to come', NULL, '["don''t need to come", "needn''t come"]', NULL, NULL, 'No obligation or necessity', 'Don''t have to means there is no obligation.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('72626f90-24f5-4aa2-84bd-fdf7dfd245c8', 426, 'gap_fill', 'C1', 'modal_perfects', 'They ___ (might / get) lost. Let me call them.', 'might have got', NULL, '["might''ve got", "might''ve gotten"]', NULL, NULL, NULL, 'Might have + past participle for possibility about the past (not certain). Gotten more American than the English got, but both are ok. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('962f83c3-51e6-4c22-a835-a407ab2aa2cc', 1182, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO describe el tiempo atmosférico?', 'hambriento', '["soleado", "nublado", "hambriento", "lluvioso"]', NULL, NULL, NULL, NULL, '"Hambriento" significa que tienes ganas de comer — describe un estado físico, no el tiempo atmosférico. Soleado, nublado y lluvioso describen condiciones meteorológicas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7344206-0cec-4235-be7e-558d98320410', 653, 'sentence_building', 'B1', 'modal_verbs', '', 'you should have told me about the meeting earlier', '["you", "should", "have", "told", "me", "about", "the", "meeting", "earlier", "must", "tell", "lately"]', NULL, NULL, NULL, NULL, 'Should have + past participle: criticism or regret about the past.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6ad6a074-e7ac-48d4-a675-5a09ef107d7b', 613, 'sentence_building', 'C1', 'modal_perfects', NULL, 'we should have finished the report earlier', '["we", "should", "have", "finished", "the", "report", "earlier", "must", "complete", "later"]', NULL, NULL, NULL, NULL, '"Should have + past participle" expresses regret about a past action.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3459b1bd-c886-49ba-9737-975e627cb443', 1183, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un pronombre personal?', 'mi', '["yo", "tú", "ella", "mi"]', NULL, NULL, NULL, NULL, '"Mi" es un determinante posesivo, no un pronombre personal. Yo, tú y ella son pronombres personales que se usan para referirse a personas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('89938cc5-5dba-4714-9dc9-2a50ac49955f', 1184, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un día de la semana?', 'finde', '["lunes", "miércoles", "finde", "viernes"]', NULL, NULL, NULL, NULL, '"Finde" es una palabra corta usado en vez de ''fin de semana'', no un día de la semana. Lunes, miércoles y viernes son todos días de la semana.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('43e4da7e-d7a4-4744-986b-f1142f21903b', 608, 'sentence_building', 'C1', 'modal_perfects', 'El proyecto debería haberse terminado el mes pasado.', 'the project should have been completed last month', '["the", "project", "should", "have", "been", "completed", "last", "month", "must", "finish", "next"]', NULL, NULL, NULL, NULL, 'Modal perfect passive: should have been + past participle. Expresses that something was expected but did not happen.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6032d802-444b-4afa-a0c9-fac3bf1868e6', 620, 'sentence_building', 'B1', 'modal_verbs', NULL, 'you should always check your emails before leaving the office', '["you", "should", "always", "check", "your", "emails", "before", "leaving", "the", "office", "never", "soon", "arrive"]', NULL, NULL, NULL, NULL, '"Should" for advice. "Before + gerund" (before leaving). Adverb "always" goes between modal and main verb.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a9e5300b-3f60-41b0-a9b0-5de2f915db9a', 795, 'multiple_choice', 'C1', 'vocabulary', '"She ___ accepted the award on behalf of the entire research team."', 'graciously', '["graciously", "gracefully", "gratefully", "graciously"]', NULL, NULL, NULL, NULL, '"Graciously" means in a pleasantly polite and generous way. "Gracefully" refers to elegant physical movement. "Gratefully" means with thanks. Accepting an award with kind words = graciously.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b0bee205-fa3e-4ebf-aa84-30d9ca6b5c5b', 709, 'error_correction', 'A1', 'modal_verbs', 'He can speaks English very well.', 'He can speak English very well.', '[]', NULL, NULL, NULL, NULL, 'After modal verbs (can, could, should), we use the base form without "s".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('94ecbccf-11fe-4779-88cd-63582bd47886', 424, 'gap_fill', 'C1', 'modal_perfects', 'He ___ (can''t / be) at the party. He was in hospital.', 'can''t have been', NULL, NULL, NULL, NULL, NULL, 'Can''t have + past participle for something you believe is impossible in the past. Using could instead of can here is also acceptable. ', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('24bc44ae-7e66-486e-ba0f-714cee8ee833', 678, 'odd_one_out', 'C1', 'word_formation', 'Which is NOT a word with a negative prefix?', 'important', '["unlikely", "disappear", "important", "irregular"]', NULL, NULL, NULL, NULL, '"Important" has no negative prefix. Un-, dis-, and ir- are all negative prefixes.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Word formation"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0935-0935-0935-000000000935', 935, 'matching', 'C1', 'pronunciation', 'Listen and match each sound to the word and its meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20weapon.mp3"}, "right": {"type": "text", "content": "bow — a weapon for shooting arrows"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20verb.mp3"}, "right": {"type": "text", "content": "row — to propel a boat using oars"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20cry.mp3"}, "right": {"type": "text", "content": "tear — a drop of water from your eye"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20weather.mp3"}, "right": {"type": "text", "content": "wind — moving air; a weather condition"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "live — to exist; to be alive"}}]', NULL, NULL, NULL, NULL, 'Each of these five words has a second pronunciation with a completely different meaning. You''ll hear them next!', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 1, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a7e4e608-b910-4511-b05e-2714c6256499', 349, 'multiple_choice', 'A1', 'daily_routines', 'We ___ breakfast at 8 am.', 'have', '["do", "go", "have", "take"]', NULL, NULL, NULL, NULL, 'Have breakfast = eat your morning meal.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0936-0936-0936-000000000936', 936, 'matching', 'C1', 'pronunciation', 'The same words — but now with their second pronunciation. Listen and match.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20verb.mp3"}, "right": {"type": "text", "content": "bow — to bend forward as a sign of respect"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20argue.mp3"}, "right": {"type": "text", "content": "row — a noisy argument"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20rip.mp3"}, "right": {"type": "text", "content": "tear — to rip something apart"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "wind — to coil or wrap something around an object"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20adjective.mp3"}, "right": {"type": "text", "content": "live — happening now; in front of an audience"}}]', NULL, NULL, NULL, NULL, 'Same spelling, completely different sound and meaning. These are called heteronyms. bow /boʊ/ vs /baʊ/ · row /roʊ/ vs /raʊ/ · tear /tɪər/ vs /tɛr/ · wind /wɪnd/ vs /waɪnd/ · live /lɪv/ vs /laɪv/', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 2, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0938-0938-0938-000000000938', 938, 'matching', 'C1', 'pronunciation', 'Listen and match each pronunciation to the sentence that uses it correctly.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20verb.mp3"}, "right": {"type": "text", "content": "The actors came out to bow at the end of the show."}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20verb.mp3"}, "right": {"type": "text", "content": "She learned to row a boat on the lake."}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20rip.mp3"}, "right": {"type": "text", "content": "Be careful not to tear the paper when you open it."}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "Wind the cable around the reel before you store it."}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20adjective.mp3"}, "right": {"type": "text", "content": "The concert was broadcast live to millions of viewers."}}]', NULL, NULL, NULL, NULL, 'bow /baʊ/ (bend) · row /roʊ/ (boat) · tear /tɛr/ (rip) · wind /waɪnd/ (coil) · live /laɪv/ (adjective)', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 4, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8c00e8cd-51bb-45bf-b41b-dddb01852875', 209, 'gap_fill', 'A1', 'present_simple', 'I ___ (have) two brothers.', 'have', NULL, NULL, NULL, NULL, NULL, 'Have with I/you/we/they: use have (not has).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4c5218bd-b544-4cd3-bfd4-f7391bde2a59', 106, 'multiple_choice', 'B2', 'passive_voice', 'The letter ___ yesterday morning.', 'was sent', '["sent", "is sent", "has been sent", "was sent"]', NULL, NULL, NULL, NULL, 'Past passive: was/were + past participle.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Passive voice"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0937-0937-0937-000000000937', 937, 'matching', 'C1', 'pronunciation', 'Listen and match each sound to its definition. No word is shown this time.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Bow%20-%20weapon.mp3"}, "right": {"type": "text", "content": "a curved piece of wood used to shoot arrows"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Row%20-%20argue.mp3"}, "right": {"type": "text", "content": "a loud and angry dispute"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Tear%20-%20cry.mp3"}, "right": {"type": "text", "content": "the salty liquid that falls from your eye when you cry"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Wind%20-%20verb.mp3"}, "right": {"type": "text", "content": "to twist or wrap something carefully around an object"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "to have life; to exist and breathe"}}]', NULL, NULL, NULL, NULL, 'Mixed pronunciations — you need to identify both the sound AND the meaning. bow /boʊ/ · row /raʊ/ · tear /tɪər/ · wind /waɪnd/ · live /lɪv/', '2026-03-04 08:58:34.770181+00', 'heteronyms_1', 3, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0931-0931-0931-000000000931', 931, 'matching', 'A2', 'pronunciation', 'Listen and match each sound to the correct word.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/ship.mp3"}, "right": {"type": "text", "content": "ship"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "bit"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sit.mp3"}, "right": {"type": "text", "content": "sit"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "live"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "fill"}}]', NULL, NULL, NULL, NULL, 'All five words use the short /ɪ/ sound — like the i in "it". Listen for the clipped, quick vowel.', '2026-03-04 08:58:34.770181+00', 'short_long_i', 1, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0932-0932-0932-000000000932', 932, 'matching', 'A2', 'pronunciation', 'Listen again — now match these sounds to the correct word.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sheep.mp3"}, "right": {"type": "text", "content": "sheep"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/beat.mp3"}, "right": {"type": "text", "content": "beat"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/seat.mp3"}, "right": {"type": "text", "content": "seat"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/leave.mp3"}, "right": {"type": "text", "content": "leave"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/feel.mp3"}, "right": {"type": "text", "content": "feel"}}]', NULL, NULL, NULL, NULL, 'All five words use the long /iː/ sound — like the ee in "see". Notice how the vowel is stretched and sustained.', '2026-03-04 08:58:34.770181+00', 'short_long_i', 2, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0933-0933-0933-000000000933', 933, 'matching', 'A2', 'pronunciation', 'Listen and match each sound to its definition. No word is shown this time.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sheep.mp3"}, "right": {"type": "text", "content": "a farm animal with thick wool"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "a small amount of something"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/seat.mp3"}, "right": {"type": "text", "content": "a place where you can sit"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/leave.mp3"}, "right": {"type": "text", "content": "to go away from a place"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "to put something into a container until it is full"}}]', NULL, NULL, NULL, NULL, 'A mix of /ɪ/ and /iː/ words — you need to recognise the sound AND know the meaning. sheep /iː/ · bit /ɪ/ · seat /iː/ · leave /iː/ · fill /ɪ/', '2026-03-04 08:58:34.770181+00', 'short_long_i', 3, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('95c31603-c07c-4347-8384-079411000f03', 621, 'sentence_building', 'A2', 'question_forms', '¿Puedes ayudarme?', 'can you help me', '["can", "you", "help", "me", "do", "are"]', NULL, NULL, NULL, NULL, 'We use ''can'' + subject + verb to make polite questions. ''Can you help me?'' is a common way to ask for help.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ca47c50f-4009-46e4-ac1e-ad49a7d75d52', 1466, 'multiple_choice', 'B2', 'phrasal_verbs', 'She felt badly _____ when her best friend forgot her birthday.', 'let down', '["let down", "let off", "let out", "let up"]', NULL, NULL, NULL, NULL, 'Let down means to disappoint someone, especially by failing to do what was expected. The noun letdown describes the feeling of disappointment.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1b1f41a5-3bba-4ea9-b53b-9181836810ae', 1467, 'multiple_choice', 'B2', 'phrasal_verbs', 'The smaller company was gradually _____ by a larger competitor.', 'taken over', '["taken over", "taken up", "taken on", "taken off"]', NULL, NULL, NULL, NULL, 'Take over means to gain control of something, such as a company, country, or role.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f6536e1e-6448-4b57-bbd6-afdf47b55a2f', 153, 'multiple_choice', 'B2', 'would_rather', 'I''d rather ___ at home tonight.', 'stay', '["staying", "to stay", "stayed", "stay"]', NULL, NULL, NULL, NULL, 'Would rather + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0934-0934-0934-000000000934', 934, 'matching', 'A2', 'pronunciation', 'Listen and match each word to its minimal pair — the word that sounds almost the same but different.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Sound 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/ship.mp3"}, "right": {"type": "text", "content": "sheep"}}, {"left": {"type": "audio", "label": "Sound 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/bit.mp3"}, "right": {"type": "text", "content": "beat"}}, {"left": {"type": "audio", "label": "Sound 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/sit.mp3"}, "right": {"type": "text", "content": "seat"}}, {"left": {"type": "audio", "label": "Sound 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/Live%20-%20verb.mp3"}, "right": {"type": "text", "content": "leave"}}, {"left": {"type": "audio", "label": "Sound 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/fill.mp3"}, "right": {"type": "text", "content": "feel"}}]', NULL, NULL, NULL, NULL, 'Minimal pairs: ship /ɪ/ ↔ sheep /iː/ · bit /ɪ/ ↔ beat /iː/ · sit /ɪ/ ↔ seat /iː/ · live /ɪ/ ↔ leave /iː/ · fill /ɪ/ ↔ feel /iː/', '2026-03-04 08:58:34.770181+00', 'short_long_i', 4, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7aca6b17-a11e-4d45-bed2-f361a3c2d5be', 729, 'matching', 'B1', 'pronunciation', 'Listen to each word and match it to the word on the left.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "though"}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "through"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "tough"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "trough"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "thought"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', 'ough_words', 1, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('abcc34b6-09c9-4b27-a266-081a144ca908', 732, 'matching', 'B1', 'pronunciation', 'Listen to each word and match it to its spelling and meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "though — conjunction, like \"but\""}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "through — in one side and out of the other"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "tough — difficult or hard"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "trough — where animals eat and drink"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "thought — past tense of \"think\""}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 13:09:12.002627+00', 'ough_words', 2, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('942122fc-42ed-4c70-82d3-9359efe4aeca', 202, 'gap_fill', 'A1', 'present_simple', 'I ___ (not like) coffee.', 'don''t like', NULL, NULL, NULL, NULL, NULL, 'Negative present simple: don''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b0e31c5b-8012-40e5-aa2f-618b2f8a734b', 301, 'multiple_choice', 'A1', 'present_simple', 'My sister ___ in a bank.', 'works', '["work", "works", "working", "is work"]', NULL, NULL, NULL, NULL, 'Third person singular (she/he/it): add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('973aebb7-e59b-4ae2-987e-273c75f06fef', 203, 'gap_fill', 'A1', 'present_simple', 'They ___ (work) in a hospital.', 'work', NULL, NULL, NULL, NULL, NULL, 'Present simple with they: use the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa110f1a-c1f8-4f89-8669-29f8a9902a65', 510, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'She managed to ___ her nerves before the presentation.', 'get over', '["get by", "get through", "get over", "get along"]', NULL, NULL, NULL, NULL, 'Get over = overcome, recover from something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ed9a4ba0-94f5-4f1a-9984-fe83bd839c1e', 733, 'matching', 'B2', 'pronunciation', 'Each word on the left RHYMES with a word on the right (they sound the same at the end). Listen and match them.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "go"}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "blue"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "stuff"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "off"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "port"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 13:09:46.323315+00', 'ough_words', 4, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('60d9879a-6445-44c3-8b8f-b0d90479072e', 730, 'matching', 'B1', 'pronunciation', 'Listen and match each word to its meaning.', 'match_all_pairs', '[{"left": {"type": "audio", "label": "Word 1", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/though.mp3"}, "right": {"type": "text", "content": "conjunction: like \"but\""}}, {"left": {"type": "audio", "label": "Word 2", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/through.mp3"}, "right": {"type": "text", "content": "adverb: in one side and out of the other"}}, {"left": {"type": "audio", "label": "Word 3", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/tough.mp3"}, "right": {"type": "text", "content": "adjective: difficult or hard"}}, {"left": {"type": "audio", "label": "Word 4", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/trough.mp3"}, "right": {"type": "text", "content": "noun: where animals eat"}}, {"left": {"type": "audio", "label": "Word 5", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/thought.mp3"}, "right": {"type": "text", "content": "verb: past tense of \"think\""}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:16:31.110712+00', 'ough_words', 3, 'en', '{Pronunciation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e226b6a-e601-445d-b7ab-a07000be558f', 497, 'gap_fill', 'C2', 'subjunctive', 'Were she ___ (ask) me, I would gladly help.', 'to ask', NULL, NULL, NULL, NULL, NULL, 'Formal: Were + subject + to infinitive = If she were to ask me.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8cbec145-d72a-41e4-8f71-4f6171f9d323', 495, 'gap_fill', 'C2', 'subjunctive', 'The board recommended that the CEO ___ (resign).', 'resign', NULL, NULL, NULL, NULL, NULL, 'Subjunctive after recommend/suggest/propose: base verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c838825f-132d-4a74-b99f-5a3c7f4e619c', 496, 'gap_fill', 'C2', 'subjunctive', 'It is vital that this information ___ (remain) confidential.', 'remain', NULL, NULL, NULL, NULL, NULL, 'Subjunctive: remain (not remains). Formal English structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6a9cb045-5785-474d-8ca9-54c5f38a15bf', 696, 'error_correction', 'C1', 'subjunctive', 'She demanded that he leaves immediately.', 'She demanded that he leave immediately.', '[]', NULL, NULL, NULL, NULL, 'After "demand/insist/suggest that", we use the subjunctive (infinitive): "he leave".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5f1d7845-79bf-44c9-90e5-85a6a4547891', 494, 'gap_fill', 'C2', 'subjunctive', 'It is essential that every employee ___ (attend) the safety briefing.', 'attend', NULL, NULL, NULL, NULL, NULL, 'Subjunctive after essential/important/vital: base verb (no -s), even with he/she.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1ca8845b-d23e-4470-829f-0bd5746f6d7b', 676, 'odd_one_out', 'C2', 'subjunctive', 'Which is NOT a subjunctive structure?', 'She has been working', '["I suggest he leave", "If I were you", "It is vital that she attend", "She has been working"]', NULL, NULL, NULL, NULL, '"She has been working" is present perfect continuous, not subjunctive.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Subjunctive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d2178647-e561-4bf5-91c8-f7394ad102ee', 480, 'gap_fill', 'C1', 'wish_and_regret', 'If only we ___ (have) more time. The deadline is tomorrow.', 'had', NULL, NULL, NULL, NULL, NULL, 'If only + past simple for wishes about the present situation.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2dfdc30a-9edc-413c-ba12-b7a8b99dbc9f', 117, 'multiple_choice', 'B2', 'wish', 'I wish I ___ more time to study for the exam.', 'had', '["have", "had", "would have", "will have"]', NULL, NULL, NULL, NULL, 'Wish + past simple for present wishes.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('91231573-94a3-441c-970d-b21ca104d84c', 144, 'multiple_choice', 'B2', 'wish_regret', 'I wish I ___ harder when I was at school.', 'had studied', '["study", "studying", "had studied", "would study"]', NULL, NULL, NULL, NULL, 'Wish + past perfect for past regrets.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c10a361c-e21e-46c2-9f87-c8e203c53855', 59, 'gap_fill', 'B2', 'wish', 'I wish I ___ (can / speak) French fluently.', 'could speak', NULL, NULL, NULL, NULL, 'Wish + past simple for present wishes', 'Use past simple after ''wish'' when talking about present situations you want to be different.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c2b6989-3fd8-4d26-9e1a-a8b469756d84', 60, 'gap_fill', 'B2', 'wish', 'I wish I ___ (study) harder when I was at school.', 'had studied', NULL, NULL, NULL, NULL, 'Wish + past perfect for past regrets', 'Use past perfect after ''wish'' for regrets about the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('abc11f05-bcc2-420d-a088-e2620c92d48a', 479, 'gap_fill', 'C1', 'wish_and_regret', 'I wish I ___ (not say) that. She looked really hurt.', 'hadn''t said', NULL, NULL, NULL, NULL, NULL, 'Wish + past perfect for regrets about the past.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70c09c80-09a5-43c0-ba42-d0d170f74f24', 484, 'gap_fill', 'C2', 'wish_and_regret', 'I wish it ___ (not rain) every single day. I''m so tired of it.', 'wouldn''t rain', NULL, NULL, NULL, NULL, NULL, 'Wish + wouldn''t or didn''t for dissatisfaction with current situations.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('143e17b0-bdab-41d0-a23e-4844a9f7fb06', 482, 'gap_fill', 'C1', 'wish_and_regret', 'He wishes he ___ (can / afford) a bigger house.', 'could afford', NULL, '["''d afford"]', NULL, NULL, NULL, 'Wish + could for desires about present abilities: wish + past simple of can.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c014016b-e707-4823-8984-f7be5d937416', 508, 'multiple_choice', 'C1', 'advanced_phrasal_verbs', 'We need to ___ a solution before the deadline.', 'come up with', '["come down to", "come up with", "come across", "come round to"]', NULL, NULL, NULL, NULL, 'Come up with = think of, produce an idea or solution.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82790de7-05ad-4f31-84a7-ea3d565a4850', 483, 'gap_fill', 'C1', 'wish_and_regret', 'If only I ___ (listen) to my parents'' advice.', 'had listened', NULL, '["''d listened"]', NULL, NULL, NULL, 'If only + past perfect for strong regret about a past action.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('736a917b-ac81-4637-bd70-a6e56d679e3c', 485, 'gap_fill', 'C1', 'wish_and_regret', 'She wishes she ___ (take) that job offer when she had the chance.', 'had taken', NULL, '["''d taken"]', NULL, NULL, NULL, 'Wish + past perfect: regret about a missed opportunity.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b3f81547-2b5b-4172-8412-af0170a00903', 481, 'gap_fill', 'C1', 'wish_and_regret', 'I wish she ___ (stop) interrupting me.', 'would stop', NULL, '["''d stop"]', NULL, NULL, NULL, 'Wish + would for complaints about annoying habits or situations.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c4f98fe6-af0e-4032-a8b2-9e545a051814', 94, 'gap_fill', 'B2', 'participle_clauses', 'The man ___ (talk) to my boss is the new manager.', 'talking', NULL, NULL, NULL, NULL, 'Present participle as adjective', 'Present participles can be used like adjectives to describe nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61be1c7e-a544-419e-9ea4-dba96a1821da', 456, 'gap_fill', 'C1', 'participle_clauses', '___ (realise) his mistake, he immediately apologised.', 'Realising', NULL, NULL, NULL, NULL, NULL, 'Present participle clause: -ing form replaces because/when + subject + verb.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07ae1c0a-c85b-4ad9-8afe-b77d78ece825', 457, 'gap_fill', 'C1', 'participle_clauses', '___ (write) in the 19th century, the novel still feels relevant today.', 'Written', NULL, NULL, NULL, NULL, NULL, 'Past participle clause (passive meaning): Written = Because it was written.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('160d61a8-e2ba-4663-b91f-65478515f2f2', 163, 'multiple_choice', 'B2', 'participle_clauses', '___ tired, I decided to go to bed early.', 'Feeling', '["Feel", "Felt", "Feeling", "To feel"]', NULL, NULL, NULL, NULL, 'Participle clause showing reason.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('45387375-e12f-425c-9bcc-0784b65c580d', 757, 'multiple_choice', 'A2', 'travel', '"___ is the weather like in Spain in summer?"', 'What', '["How", "What", "Where", "Which"]', NULL, NULL, NULL, NULL, '"What is the weather like?" is the correct fixed phrase for asking about weather. "How is the weather?" is also possible, but "What is it like?" is more natural.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db22b010-56c9-4e3f-bdf0-0f0898bc217c', 1195, 'sentence_building', 'B1', 'routines', 'Tiendo a perder la noción del tiempo por las mañanas.', 'I tend to lose track of time in the morning.', '["I", "tend", "to", "lose", "track", "of", "time", "in", "the", "morning", "miss", "keep", "often"]', NULL, NULL, NULL, NULL, 'Tend to + infinitive describes a habitual behaviour. Lose track of time means to stop noticing how much time is passing.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a53e7d5c-f2f4-4437-8adc-7d52de455923', 458, 'gap_fill', 'C1', 'participle_clauses', '___ (complete) the project, the team celebrated with dinner.', 'Having completed', NULL, NULL, NULL, NULL, NULL, 'Perfect participle: Having + past participle for a completed action before the main clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e5e52e0-fd79-434a-933b-732a3be117c6', 459, 'gap_fill', 'C2', 'participle_clauses', 'The road ___ (block) by a fallen tree, we had to find an alternative route.', 'being blocked', NULL, NULL, NULL, NULL, NULL, 'Absolute participle clause: independent subject + participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3683f9c5-9b6a-4184-9dc8-df6f0ff1fb7f', 460, 'gap_fill', 'C1', 'participle_clauses', '___ (not know) what to say, she remained silent.', 'Not knowing', NULL, NULL, NULL, NULL, NULL, 'Negative participle clause: Not + -ing form.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d1bdf403-ac13-410d-96a7-61a3ededc292', 461, 'gap_fill', 'C1', 'participle_clauses', 'The children, ___ (exhaust) after the long walk, fell asleep immediately.', 'exhausted', NULL, NULL, NULL, NULL, NULL, 'Reduced relative clause: who were exhausted → exhausted.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61a48267-16cb-4114-8e7d-1b3a1af6ec3c', 462, 'gap_fill', 'C2', 'participle_clauses', '___ (not / invite) to the meeting, I can''t tell you what was discussed.', 'Not having been invited', NULL, NULL, NULL, NULL, NULL, 'Perfect passive participle (negative): Not having been + past participle.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9ebb7687-34b9-4345-8eb8-cfbf75dba8c3', 463, 'gap_fill', 'C1', 'participle_clauses', 'The city, ___ (found) in the 12th century, has a rich history.', 'founded', NULL, NULL, NULL, NULL, NULL, 'Past participle = which was founded. Reduced relative clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7976039d-12b0-45c2-bbe9-2387ed9a0395', 93, 'gap_fill', 'B2', 'participle_clauses', '___ (Feel) tired, I decided to go to bed early.', 'feeling', NULL, '["As I felt", "Because I felt", "as I felt", "because I felt"]', NULL, NULL, 'Participle clause showing reason', 'Participle clauses can show the reason for an action.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Participle clause"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b22b2488-cb2d-482f-99c0-6af11f27e0f4', 98, 'gap_fill', 'B2', 'cleft_sentences', '___ (_ _ _ _) I need is a good night''s sleep.', 'what', NULL, NULL, NULL, NULL, 'What-cleft sentence for emphasis', 'What-cleft sentences (What + clause + is/was) add emphasis.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06155271-238f-4c53-95fb-e492944318d4', 97, 'gap_fill', 'B2', 'emphatic_do', 'I ___ (_ _) understand what you mean, but I disagree. Completely.', 'do', NULL, NULL, NULL, NULL, 'Do for emphasis', 'Do/does/did can be used for emphasis in affirmative sentences.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('455f5dca-e7b2-43b1-83f9-5a093aa24332', 561, 'multiple_choice', 'C1', 'cleft_sentences', '___ I really need is a good night''s sleep.', 'What', '["That", "What", "Which", "It"]', NULL, NULL, NULL, NULL, 'What-cleft for emphasis: What I need is... = The thing I need is...', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('78d26378-998c-4890-be4e-8d5feb49b7d5', 151, 'multiple_choice', 'B2', 'cleft_sentences', '___ I really need is a holiday.', 'What', '["That", "What", "Which", "It"]', NULL, NULL, NULL, NULL, 'What-cleft sentences for emphasis.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8279dd16-011c-42be-81f1-9dbd6bf53205', 205, 'gap_fill', 'A1', 'present_simple', 'He ___ (not eat) meat.', 'doesn''t eat', NULL, NULL, NULL, NULL, NULL, 'Third person negative: doesn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c9a4f31-45a6-46a1-ad2a-9f0accbde7bd', 593, 'multiple_choice', 'C1', 'nuance', 'She has a ___ for languages and picks them up quickly.', 'flair', '["flare", "fare", "fair", "flair"]', NULL, NULL, NULL, NULL, 'A flair for = a natural talent or ability for something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('11309884-66ba-4d2f-b0a0-4227ee7542b6', 594, 'multiple_choice', 'C1', 'nuance', 'The manager ___ full responsibility for the error.', 'took', '["gave", "made", "took", "had"]', NULL, NULL, NULL, NULL, 'Take responsibility = accept that you are accountable.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a928f1f5-6833-49cb-911c-8b4f7b1d31e8', 595, 'multiple_choice', 'C2', 'nuance', 'The policy is ___ with controversy.', 'fraught', '["filled", "packed", "loaded", "fraught"]', NULL, NULL, NULL, NULL, 'Fraught with = full of (problems, danger, controversy). Formal register.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('84b2746c-d490-462b-87fc-9b6e622074bb', 172, 'multiple_choice', 'B2', 'emphatic_structures', 'It ___ John who told me the news.', 'was', '["is", "was", "has", "does"]', NULL, NULL, NULL, NULL, 'It-cleft sentence for emphasis (It was... who).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82d2bb17-2885-4f63-b1b2-9e61de021f69', 562, 'multiple_choice', 'C1', 'cleft_sentences', 'It ___ John who suggested the idea.', 'was', '["is", "had", "was", "has"]', NULL, NULL, NULL, NULL, 'It-cleft for emphasis on the person: It was John who...', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Cleft sentence"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('da580e24-3ee4-484e-ae5d-15c0ce45dfa6', 75, 'gap_fill', 'B1', 'linking_words', 'I wanted to go out, ___ (but / so / because) it was raining.', 'but', NULL, NULL, NULL, NULL, 'Contrasting two ideas', 'But is used to show contrast between two ideas.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('57ef7350-f7d5-4f46-b772-0a32c236f73f', 76, 'gap_fill', 'B1', 'linking_words', 'I was tired, ___ (but / so / because) I went to bed early.', 'so', NULL, NULL, NULL, NULL, 'Showing result or consequence', 'So is used to show a result or consequence.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0633aa13-1cfe-48a3-bcb9-c4e5e8a9d123', 77, 'gap_fill', 'B2', 'linking_words', '___ (Although / Despite) it was cold, we went to the beach.', 'although', NULL, NULL, NULL, NULL, 'Although is followed by a clause', 'Although is followed by a subject and verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a743beb2-0710-4ed6-ac7a-60d015315cd9', 78, 'gap_fill', 'B2', 'linking_words', '___ (Although / Despite) the rain, we went to the beach.', 'despite', NULL, NULL, NULL, NULL, 'Despite is followed by a noun', 'Despite is followed by a noun or -ing form.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ac0855f3-92fa-4f10-a7e4-dfafde158f13', 796, 'multiple_choice', 'C2', 'linking language', '"The bill was passed ___ fierce opposition from several powerful lobby groups."', 'All three are correct', '["notwithstanding", "regardless of", "despite", "All three are correct"]', NULL, NULL, NULL, NULL, '"Notwithstanding", "despite", and "regardless of" all express contrast (something happened in spite of something else). All three work here — useful synonyms for formal writing.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('59ce3fa3-2620-40fe-a017-564ca263c02c', 95, 'gap_fill', 'B1', 'as_like', 'He works ___ (as / like) a teacher.', 'as', NULL, NULL, NULL, NULL, 'As + profession/role', 'As is used before a profession or role.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2019871e-d936-447f-a5b3-4ace5a18058f', 96, 'gap_fill', 'B1', 'as_like', 'She sings ___ (as / like) an angel.', 'like', NULL, NULL, NULL, NULL, 'Like + noun for comparisons', 'Like is used for comparisons and means similar to.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('15ee328d-7db3-42da-b067-ef82dca760ac', 166, 'multiple_choice', 'B1', 'as_like', 'He works ___ a doctor in the local hospital.', 'as', '["like", "for", "such as", "as"]', NULL, NULL, NULL, NULL, 'As + profession/role.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a92f9d51-230b-44e0-9031-a7d4c45bb3ba', 132, 'multiple_choice', 'B1', 'linking_words', 'I was tired, ___ I went to bed early.', 'so', '["but", "so", "because", "although"]', NULL, NULL, NULL, NULL, 'So shows result or consequence.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b08ae085-3245-424e-b8a4-bd4ff0bc1ce5', 142, 'multiple_choice', 'B2', 'so_such', 'It was ___ a difficult test that nobody passed.', 'such', '["so", "such", "very", "too"]', NULL, NULL, NULL, NULL, 'Such + a/an + adjective + noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6d01513b-8c56-48df-b041-adbe220938fa', 146, 'multiple_choice', 'B2', 'despite_although', '___ the rain, we enjoyed our walk.', 'Despite', '["Although", "Despite", "However", "Because"]', NULL, NULL, NULL, NULL, 'Despite + noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('952cc111-7aa8-4188-a634-da7dbc755e83', 179, 'multiple_choice', 'B1', 'linking_but', 'I wanted to go out, ___ it was raining.', 'but', '["so", "but", "because", "and"]', NULL, NULL, NULL, NULL, 'But for contrast.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('743f6953-0480-4e1b-bcb2-cde39c7586f1', 397, 'multiple_choice', 'A2', 'conjunctions', 'I want to go out ___ it''s raining.', 'but', '["then", "but", "because", "so"]', NULL, NULL, NULL, NULL, 'But shows contrast: I want to go out (positive) but it''s raining (problem).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dc43a8e5-e731-4b88-9aa0-e83441b0bfa7', 398, 'multiple_choice', 'A2', 'conjunctions', 'She''s tired ___ she went to bed early.', 'so', '["than", "but", "because", "so"]', NULL, NULL, NULL, NULL, 'So shows result: She''s tired → result: she went to bed early.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('647da761-0050-420d-9592-21d95afa614a', 198, 'multiple_choice', 'B2', 'linking_however', 'The weather was terrible. ___, we had a great time.', 'However', '["In spite of", "However", "Although", "Despite"]', NULL, NULL, NULL, NULL, 'However for formal contrast (usually after a full stop).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('68b5b756-7464-4c60-9565-8e518dfad8c3', 65, 'gap_fill', 'B2', 'so_such', 'It was ___ (so / such) a boring film that I fell asleep.', 'such', NULL, NULL, NULL, NULL, 'Such + a/an + adjective + noun', 'Such is used with a/an + adjective + noun.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8cb3ff61-b292-40da-8375-a2787e3020ee', 66, 'gap_fill', 'B2', 'so_such', 'The test was ___ (so / such) difficult that nobody passed.', 'so', NULL, NULL, NULL, NULL, 'So + adjective/adverb', 'So is used directly with adjectives or adverbs.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c699cb89-7206-4777-8030-0dc687d98e4f', 714, 'error_correction', 'B2', 'linking_words', 'Despite of rain, we went for a walk.', 'Despite the rain, we went for a walk.', '[]', NULL, NULL, NULL, NULL, '"Despite" is never followed by "of". Use "In spite of" if you want the "of" form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e27003ac-8dbf-4b63-941b-87069efd7dac', 670, 'sentence_building', 'C2', 'complex_sentences', 'A pesar de que le ofrecieron el puesto, lo rechazó sin pensárselo dos veces.', 'despite having been offered the position she turned it down without thinking twice', '["despite", "having", "been", "offered", "the", "position", "she", "turned", "it", "down", "without", "thinking", "twice", "offering", "thought", "a"]', NULL, NULL, NULL, NULL, 'Despite + having been + past participle (passive perfect gerund) + phrasal verb (turn down).
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('356dc805-2148-4abb-a249-03f65eaa1b86', 684, 'odd_one_out', 'B2', 'linking_words', 'Which is NOT a linking word showing contrast?', 'moreover', '["however", "moreover", "although", "nevertheless"]', NULL, NULL, NULL, NULL, '"Moreover" adds information (addition). The others show contrast.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Linking word"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4dd5f312-7deb-4669-9524-d0b677d9a522', 156, 'multiple_choice', 'B1', 'comparatives', 'This exercise is ___ difficult than the last one.', 'less', '["most", "less", "least", "lease"]', NULL, NULL, NULL, NULL, 'Less for comparatives (opposite of more).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('414ced3b-5c8f-4619-899f-64edd5b2b156', 134, 'multiple_choice', 'B1', 'comparatives_as_as', 'My sister is ___ tall as me.', 'as', '["so", "as", "more", "too"]', NULL, NULL, NULL, NULL, 'As...as for equal comparisons.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5a89ad85-e499-49fc-9904-ba370b0db05b', 21, 'gap_fill', 'B1', 'comparatives', 'This exercise is ___ (difficult) than the last one.', 'more difficult', NULL, NULL, NULL, NULL, 'Comparative form for long adjectives', 'For adjectives with two or more syllables, use more + adjective.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('68964c26-8151-4626-9f11-00000d6b5c2b', 22, 'gap_fill', 'B1', 'comparatives', 'My brother is ___ (tall) than me.', 'taller', NULL, NULL, NULL, NULL, 'Comparative form for short adjectives', 'For short adjectives, add -er to form the comparative.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('948d438d-f556-4a7c-adda-73a7fa4fe628', 107, 'multiple_choice', 'B1', 'comparatives', 'This restaurant is ___ than the one we went to last week.', 'more expensive', '["the more expensive", "more expensive", "most expensive", "expensiver"]', NULL, NULL, NULL, NULL, 'Comparative form for long adjectives: more + adjective.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ac8f794f-aae4-43f8-9120-ee8e3c39d116', 170, 'multiple_choice', 'B2', 'double_comparatives', 'The ___ you practice, the ___ you''ll become.', 'more / better', '["most / better", "more / best", "more / better", "most / best"]', NULL, NULL, NULL, NULL, 'The + comparative... the + comparative (for correlation).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eb45416d-5631-4fc7-8559-48dfcb8ce365', 286, 'gap_fill', 'A2', 'comparatives', 'My house is ___ (big) than your house.', 'bigger', NULL, NULL, NULL, NULL, NULL, 'Short adjectives: add -er. Double the consonant after a short vowel: big → bigger.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d56aa96a-9e22-46e5-9374-55f0ef7da072', 288, 'gap_fill', 'A2', 'comparatives', 'This restaurant is ___ (expensive) than that one.', 'more expensive', NULL, NULL, NULL, NULL, NULL, 'Long adjectives (3+ syllables): more + adjective.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fbdf46e2-4ec8-4c8c-ae97-f9381fa496c4', 289, 'gap_fill', 'A2', 'comparatives', 'She is ___ (good) at maths than me.', 'better', NULL, NULL, NULL, NULL, NULL, 'Good is irregular: good → better → best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('865adacc-2de4-4302-bca6-640c080ec288', 290, 'gap_fill', 'A2', 'comparatives', 'Today is ___ (bad) than yesterday.', 'worse', NULL, NULL, NULL, NULL, NULL, 'Bad is irregular: bad → worse → worst.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f695996a-4213-4b0d-947b-80332e851896', 294, 'gap_fill', 'A2', 'comparatives', 'He runs ___ (fast) than his brother.', 'faster', NULL, NULL, NULL, NULL, NULL, 'Short adjectives/adverbs: add -er for comparatives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eff42f92-f50d-451f-8682-0fc861e3eabf', 287, 'gap_fill', 'A2', 'comparatives', 'English is ___ (easy) than Japanese!', 'easier', NULL, NULL, NULL, NULL, NULL, 'Adjectives ending in -y: change to -ier. Easy → easier.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c8649b09-f96a-4362-a19f-af3328ced48c', 715, 'error_correction', 'A2', 'comparatives', 'She is tallest than her sister.', 'She is taller than her sister.', '[]', NULL, NULL, NULL, NULL, 'One-syllable adjectives use -er (taller), not "tallest". That''s the superlative form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7fcc806d-6a68-47fe-9f4d-f2f1fc0b15a6', 23, 'gap_fill', 'B1', 'superlatives', 'That was ___ (good) meal I''ve ever had!', 'the best', NULL, NULL, NULL, NULL, 'Superlative of ''good''', 'Best is the irregular superlative form of good.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('36f3ce4a-7aed-4664-9630-1f041658c309', 24, 'gap_fill', 'B2', 'superlatives', 'She''s ___ (intelligent) person in our class.', 'the most intelligent', NULL, NULL, NULL, NULL, 'Superlative form for long adjectives', 'For long adjectives, use the most + adjective.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('377e0576-e97c-4f80-b37e-f4a59120f786', 121, 'multiple_choice', 'B1', 'superlatives', 'That was ___ film I''ve ever seen!', 'the best', '["the better", "the best", "the good", "better"]', NULL, NULL, NULL, NULL, 'Best is the irregular superlative of good.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3e5cf8f5-aaf7-450a-b7f9-8e34ccd19458', 187, 'multiple_choice', 'B1', 'superlatives_place', 'This is ___ expensive restaurant in town.', 'the most', '["more", "most", "the more", "the most"]', NULL, NULL, NULL, NULL, 'The + superlative.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fd2df5d0-0e18-4c26-8a6c-12b72b9ffc3c', 291, 'gap_fill', 'A2', 'superlatives', 'This is the ___ (tall) building in the city.', 'tallest', NULL, NULL, NULL, NULL, NULL, 'Superlative: the + adjective-est for short adjectives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('58bdbcaa-a5ac-405c-b04d-2f77e7599117', 292, 'gap_fill', 'A2', 'superlatives', 'She is the ___ (intelligent) student in the class.', 'most intelligent', NULL, NULL, NULL, NULL, NULL, 'Superlative with long adjectives: the most + adjective.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('df636f39-ebb5-4b3d-9d6c-6a276b896672', 293, 'gap_fill', 'A2', 'superlatives', 'What is the ___ (good) restaurant in town?', 'best', NULL, NULL, NULL, NULL, NULL, 'Good is irregular: good → better → best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7938474c-24af-4b1f-82ff-7defc21d5921', 295, 'gap_fill', 'A2', 'superlatives', 'It was the ___ (happy) day of my life.', 'happiest', NULL, NULL, NULL, NULL, NULL, 'Adjectives ending in -y: change to -iest. Happy → happiest.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Superlative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6fed53fe-3698-4807-b8cc-475a5abf3f02', 697, 'error_correction', 'B2', 'verb_patterns', 'She suggested me apply for the job.', 'She suggested I apply for the job.', '[]', NULL, NULL, NULL, NULL, '"Suggest" doesn''t take an object + infinitive. Use "suggest + (that) + subject + infinitive".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0d174ce5-447f-4d77-b49b-e56a08c397c8', 33, 'gap_fill', 'B1', 'gerunds_infinitives', 'I enjoy ___ (read) in my free time.', 'reading', NULL, NULL, NULL, NULL, 'Enjoy is followed by -ing', 'Enjoy is followed by a gerund (-ing form).', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a8fbaf00-152e-4844-bf4e-23685cdd668e', 34, 'gap_fill', 'B1', 'gerunds_infinitives', 'I decided ___ (study) medicine at university.', 'to study', NULL, NULL, NULL, NULL, 'Decide is followed by to + infinitive', 'Decide is followed by the infinitive.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7d3180d2-b7fb-487b-b493-bf18f2314e4f', 35, 'gap_fill', 'B2', 'gerunds_infinitives', 'She stopped ___ (smoke) five years ago.', 'smoking', NULL, NULL, NULL, NULL, 'Stop + -ing means to quit doing something', 'Stop + gerund means to quit an activity.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('320271a1-75f5-4025-b996-677ac41e197d', 116, 'multiple_choice', 'B1', 'gerunds_infinitives', 'I enjoy ___ to music in my free time.', 'listening', '["listen", "to listen", "listening", "listened"]', NULL, NULL, NULL, NULL, 'Enjoy is followed by gerund (-ing form).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('837b0e9f-78bd-4e70-b0d8-8e68bf2b8945', 136, 'multiple_choice', 'B2', 'gerunds_infinitives', 'I stopped ___ cigarettes five years ago.', 'smoking', '["smoke", "to smoke", "smoking", "smoked"]', NULL, NULL, NULL, NULL, 'Stop + gerund means to quit doing something.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('23babafa-9812-4d6e-a5bd-a62c27eee6ce', 738, 'multiple_choice', 'A1', 'grammar', 'Which word completes the sentence? "I ___ hungry. Can we eat soon?"', 'am', '["am", "is", "are", "be"]', NULL, NULL, NULL, NULL, 'Use "am" with "I". Remember: I am, you are, he/she/it is. Easy once you know it!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('95b4b256-88b7-40da-b3ed-e6ea078e96ab', 186, 'multiple_choice', 'B2', 'verb_patterns_allow', 'My parents don''t allow me ___ out late.', 'to stay', '["stay", "to stay", "staying", "stayed"]', NULL, NULL, NULL, NULL, 'Allow + object + to + infinitive.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c323f6e8-31d7-44c5-8ae3-d590a1856f29', 200, 'multiple_choice', 'B2', 'verb_patterns_manage', 'I finally managed ___ the problem.', 'to solve', '["solve", "to solve", "solving", "solved"]', NULL, NULL, NULL, NULL, 'Manage + to + infinitive (succeed in doing something difficult).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('944bd84d-9218-4542-a9c3-1b969aa64244', 704, 'error_correction', 'B2', 'gerunds_and_infinitives', 'I look forward to hear from you.', 'I look forward to hearing from you.', '[]', NULL, NULL, NULL, NULL, '"Look forward to" is followed by the gerund (-ing), not the base form.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a7ccfce0-fe46-40c5-a3a7-608e3e45fced', 626, 'sentence_building', 'A2', 'comparatives', 'Ella es más alta que su hermano.', 'she is taller than her brother', '["she", "is", "taller", "than", "her", "brother", "more", "the"]', NULL, NULL, NULL, NULL, 'Short adjectives use -er + than for comparisons. ''Taller than'' not ''more tall than''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{Comparative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c602f188-2136-4494-8570-1ce85606fa82', 1243, 'gap_fill', 'B2', 'business_phrasal_verbs', 'We need to _____ the deadline — there''s no way we can finish by Friday.', 'push back', '[]', NULL, NULL, NULL, NULL, 'Push back means to move a deadline to a later date. Compare: bring forward (move to an earlier date).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bc606e85-3a26-415a-ad1a-e3e5e7d4104d', 1246, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The consultants were brought in to _____ the inefficiencies in the supply chain.', 'iron out', '[]', NULL, NULL, NULL, NULL, 'Iron out means to resolve problems or difficulties, especially small but persistent ones. Compare: smooth out, work out.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8a10cda3-b0a5-413a-9fe0-934b52af0c34', 1247, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The board voted to _____ the proposal, citing insufficient evidence of commercial viability.', 'throw out', '[]', NULL, NULL, NULL, NULL, 'Throw out means to reject a proposal or idea formally. Compare: dismiss, turn down, vote down.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b27bfee6-532f-4b46-ba43-33c624f7f246', 1244, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The new regulations will  _____  how we operate significantly.', 'impact on', '[]', NULL, NULL, NULL, NULL, 'Impact on means to have an effect on something. In business English, impact is frequently used as a verb: the changes impacted on our workflow.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('86b4b261-c6df-43d3-9d0e-1efd940b59bc', 1245, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The acquisition _____ at the last minute due to regulatory concerns.', 'fell through', '[]', NULL, NULL, NULL, NULL, 'Fall through means a deal or plan fails to happen. It is particularly common in business contexts involving mergers and acquisitions.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('774e02f2-3fa9-4233-9570-c6c7e2ddcd7f', 625, 'sentence_building', 'A2', 'infinitives', 'Necesito comprar algo de comida.', 'I need to buy some food', '["I", "need", "to", "foods", "buy", "some", "food", "want", "the"]', NULL, NULL, NULL, NULL, '''Need to'' is followed by the infinitive verb. We use ''some'' with uncountable nouns in positive sentences.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ee7a60a2-dbc7-4b78-9c7f-2909b2446f8f', 648, 'sentence_building', 'A2', 'past_simple', 'Ayer fui al supermercado con mi madre.', 'yesterday I went to the supermarket with my mother', '["yesterday", "I", "went", "to", "the", "supermarket", "with", "my", "mother", "go", "a", "father"]', '["I went to the supermarket with my mother yesterday."]', NULL, NULL, NULL, 'Past simple irregular: go -> went. "Al" = to the.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7ad4a7ba-d748-4e68-ba1a-462aed46b8a2', 647, 'sentence_building', 'A2', 'past_continuous', '', 'he was watching TV when the phone rang', '["he", "was", "watching", "TV", "when", "the", "phone", "rang", "watched", "rings", "ringing", "is"]', '["the phone rang when he was watching TV. ", ["when he was watching TV the phone rang"]]', NULL, NULL, NULL, 'Past continuous interrupted by past simple: was + -ing when + past simple.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0b842d55-99f7-4bd2-bfc4-d5647a46efe7', 656, 'sentence_building', 'B2', 'past_perfect', '', 'by the time we arrived the film had already started', '["by", "the", "time", "we", "arrived", "the", "film", "had", "already", "started", "has", "will", "starting"]', NULL, NULL, NULL, NULL, 'Past perfect: had + past participle. One past action completed before another.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3765ce23-53f8-402f-bc22-47186e9d8dad', 251, 'gap_fill', 'A1', 'prepositions_of_time', 'I wake up ___ 7 o''clock.', 'at', NULL, NULL, NULL, NULL, NULL, 'Use at with specific times: at 7 o''clock, at midnight.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f46adf44-e6d9-4c6f-bb90-ad4add58abdf', 252, 'gap_fill', 'A1', 'prepositions_of_time', 'My birthday is ___ March.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in with months: in March, in June.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b9199fac-5434-4bd7-965e-523a9d422dff', 253, 'gap_fill', 'A1', 'prepositions_of_time', 'I don''t work ___ Sundays.', 'on', NULL, NULL, NULL, NULL, NULL, 'Use on with days: on Sunday, on Monday.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7113bacc-dffb-4252-9c4f-71e9430d1497', 254, 'gap_fill', 'A2', 'prepositions_of_time', 'She was born ___ 1995.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in with years: in 1995, in 2020.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('60b45b33-6df4-4365-af1d-58b00cb9bc05', 693, 'error_correction', 'A2', 'verb_patterns', 'I''m agree with you.', 'I agree with you.', '[]', NULL, NULL, NULL, NULL, '"Agree" is a verb, not an adjective — we don''t use "am" before it. It''s a typical mistake Spanish speakers make. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Gerund & infinitive"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('35434388-935b-4ab1-aca6-9dc8a674ef58', 141, 'multiple_choice', 'B1', 'question_tags', 'You''re coming to the party, ___?', 'aren''t you', '["isn''t it", "aren''t you", "won''t you", "don''t you"]', NULL, NULL, NULL, NULL, 'Negative question tag after positive statement.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82efd48f-cd8d-4c78-bd98-df00b342cecf', 29, 'gap_fill', 'B1', 'questions', '___ (how _ _ _ _ ) have you been learning English?', 'how long', NULL, NULL, NULL, NULL, 'Question word for duration', 'How long asks about the duration of time.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6519b842-ba8a-4a65-9e40-7b8d73163376', 30, 'gap_fill', 'B1', 'questions', '___ (what _ _ _ _ ) does the train leave?', 'what time', NULL, NULL, NULL, NULL, 'Question phrase for asking about time', 'What time is used to ask about specific times.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f8e7d6ee-f37b-4fe8-9da0-f305eee2be9c', 197, 'multiple_choice', 'B1', 'much_many_questions', 'How ___ people are coming to dinner?', 'many', '["much", "many", "lot", "lots"]', NULL, NULL, NULL, NULL, 'How many with countable nouns.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6256d4e9-d994-4793-ad2a-9856b971674d', 361, 'multiple_choice', 'A1', 'basic_questions', '___ is your name?', 'What', '["Who", "What", "Where", "When"]', NULL, NULL, NULL, NULL, 'What for asking about things: What is your name?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5ccf2951-5956-4e24-a106-150c04d0271c', 362, 'multiple_choice', 'A1', 'basic_questions', '___ are you from?', 'Where', '["What", "Who", "Where", "When"]', NULL, NULL, NULL, NULL, 'Where for asking about places: Where are you from?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3717367d-0274-4b14-8965-7acc9d4da875', 363, 'multiple_choice', 'A1', 'basic_questions', '___ old are you?', 'How', '["What", "How", "Where", "Who"]', NULL, NULL, NULL, NULL, 'How old...? for asking about age.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7996f98-4bb3-4354-a2aa-868fb57196bd', 364, 'multiple_choice', 'A1', 'basic_questions', '___ do you live?', 'Where', '["What", "Who", "Where", "How"]', NULL, NULL, NULL, NULL, 'Where for location: Where do you live?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8c4758ac-b9cb-4025-a2b3-8ac5031f077a', 365, 'multiple_choice', 'A2', 'basic_questions', '___ does the class start?', 'What time', '["What", "How", "Which", "What time"]', NULL, NULL, NULL, NULL, 'What time for asking about specific times.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6251c9f9-c0c4-4559-83d3-7958de3512a7', 366, 'multiple_choice', 'A1', 'basic_questions', '___ is your favourite colour?', 'What', '["Who", "What", "Where", "How"]', NULL, NULL, NULL, NULL, 'What for asking about preferences.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8b1ee55f-94eb-414b-be26-2be010fb8aed', 368, 'multiple_choice', 'A2', 'basic_questions', '___ does it take to get to work?', 'How long', '["How often", "How many", "How much", "How long"]', NULL, NULL, NULL, NULL, 'How long for duration: How long does it take?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dea1d3fb-91e8-469a-8580-f65cf4491396', 660, 'sentence_building', 'B2', 'used_to', 'No estoy acostumbrado a levantarme tan temprano.', 'I am not used to getting up so early', '["I", "am", "not", "used", "to", "getting", "up", "so", "early", "get", "usually", "very"]', NULL, NULL, NULL, NULL, 'Be used to + -ing: describes what you are or aren''t accustomed to.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a5ae48e9-0c65-49b1-b09d-c0be05647d19', 627, 'sentence_building', 'A2', 'past_simple', 'Ayer fuimos al parque.', 'yesterday we went to the park', '["yesterday", "go", "we", "went", "to", "the", "park", "go", "a"]', NULL, NULL, NULL, NULL, '''Go'' becomes ''went'' in the past simple. Time expressions like ''yesterday'' often go at the start of the sentence.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c3726d95-d797-48a0-937f-3e021acc1dbb', 1205, 'sentence_building', 'C1', 'routines', 'He adquirido el hábito de revisar mis objetivos cada lunes por la mañana.', 'I have got into the habit of reviewing my goals every Monday morning.', '["I", "have", "got", "into", "the", "habit", "of", "reviewing", "my", "goals", "every", "Monday", "morning", "review", "acquired", "weekly"]', NULL, NULL, NULL, NULL, 'Get into the habit of + gerund describes the establishment of a regular behaviour. The present perfect shows this is a recently acquired habit.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8a29560a-e70c-4a6d-a02f-75e7e60d0da8', 939, 'multiple_choice', 'A1', 'phrasal_verbs', 'She _______ smoking two years ago and feels much healthier now.', 'gave up', '["gave up", "gave in", "gave out", "gave away"]', NULL, NULL, NULL, NULL, 'To give up means to stop doing something, especially a habit. Compare: give in = to surrender or admit defeat; give out = to distribute, or to stop working.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('93d6090f-6350-4b48-8f6e-9bee45eb813b', 940, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _______ the lights? It''s getting dark in here.', 'turn on', '["turn on", "turn up", "turn over", "turn out"]', NULL, NULL, NULL, NULL, 'To turn on means to switch something on. Compare: turn up = to increase volume or heat; turn out = to produce a result, or to switch off a light.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d1382c39-7305-41d6-935a-b4892f97043b', 941, 'multiple_choice', 'A1', 'phrasal_verbs', 'We _______ of petrol on the motorway and had to call for help.', 'ran out', '["ran out", "ran off", "ran away", "ran through"]', NULL, NULL, NULL, NULL, 'To run out of something means to have none left. The preposition of is essential — don''t omit it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48a00f51-ec62-498c-98e9-2bf46dfc4837', 942, 'multiple_choice', 'A1', 'phrasal_verbs', 'Please _______ the form and sign at the bottom.', 'fill in', '["fill in", "fill up", "fill over", "fill past"]', NULL, NULL, '["fill out"]', NULL, 'To fill in (or fill out) a form means to complete it. Fill in is more common in British English; fill out in American English.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('69e56f9d-dfb0-4f0b-baf6-0968c59c0795', 943, 'multiple_choice', 'A2', 'phrasal_verbs', 'I need to _______ this word — I don''t know what it means.', 'look up', '["look up", "look for", "look after", "look out"]', NULL, NULL, NULL, NULL, 'To look up a word means to search for its meaning — in a dictionary or online. Compare: look after = to take care of someone; look out = to be careful.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5fabea9-0231-4158-962d-44101c159331', 944, 'multiple_choice', 'A2', 'phrasal_verbs', 'The meeting was _______ until next Thursday.', 'put off', '["put off", "put on", "put up", "put away"]', NULL, NULL, NULL, NULL, 'To put off means to postpone something to a later date. Compare: put on = to add or start something; put away = to tidy something into its usual place.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fd7ebd78-93c9-460e-aa1d-280c79354222', 945, 'multiple_choice', 'A2', 'phrasal_verbs', 'He _______ his jacket because it was so hot in the office.', 'took off', '["took off", "put off", "got off", "came off"]', NULL, NULL, NULL, NULL, 'To take off clothing means to remove it. Take off also means to leave the ground (a plane), or to become suddenly successful.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e654ba4-2a26-4e65-94e5-1ddc2555a5be', 946, 'multiple_choice', 'A2', 'phrasal_verbs', 'Can you _______ the music a bit? I''m trying to concentrate.', 'turn down', '["turn down", "turn off", "turn up", "turn over"]', NULL, NULL, NULL, NULL, 'To turn down the music means to reduce the volume. Compare: turn off = to stop completely; turn up = to increase the volume.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7e3d0dc7-d47e-4489-a12b-1ab6559e6063', 947, 'multiple_choice', 'A2', 'phrasal_verbs', 'I _______ an old school friend on the street yesterday — what a surprise!', 'ran into', '["ran into", "ran after", "ran out of", "ran away from"]', NULL, NULL, NULL, NULL, 'To run into someone means to meet them unexpectedly. Compare: run after = to chase; run out of = to have none left.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c7bcb27f-7ad9-4aee-bc80-e7ec3decd610', 948, 'multiple_choice', 'A2', 'phrasal_verbs', 'She _______ a new flat-share app on her phone to find a room.', 'set up', '["set up", "set out", "set off", "set in"]', NULL, NULL, NULL, NULL, 'To set up an app or account means to install and configure it for first use. Set up also means to establish a business or organisation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8a111f4a-7d91-4156-b381-9a8dafe965d3', 949, 'multiple_choice', 'B1', 'phrasal_verbs', 'The company _______ three new branches across Spain last year.', 'set up', '["set up", "set out", "set off", "set back"]', NULL, NULL, NULL, NULL, 'To set up a branch or office means to establish it. Compare: set out = to begin a journey or explain something; set off = to start a journey or trigger something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5fb80f5f-3b72-457d-be90-29f61622e86b', 950, 'multiple_choice', 'B1', 'phrasal_verbs', 'I can''t _______ my new neighbours — they play loud music every night.', 'put up with', '["put up with", "put down with", "put off with", "keep up with"]', NULL, NULL, NULL, NULL, 'To put up with something means to tolerate it, even though it is unpleasant. It is three words — the with is essential.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f8082df7-319c-46f8-bbbb-f6d1e077f4b5', 951, 'multiple_choice', 'B1', 'phrasal_verbs', 'She _______ some fascinating information while researching her project.', 'came across', '["came across", "came up with", "came around to", "came out with"]', NULL, NULL, NULL, NULL, 'To come across something means to find or encounter it by chance, without looking for it. Compare: come up with = to think of an idea or solution.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('889c04cf-844e-4c88-9463-1ae1c9d2073d', 952, 'multiple_choice', 'B2', 'phrasal_verbs', 'The outdoor concert was _______ due to the storm.', 'called off', '["called off", "called up", "called out", "called back"]', NULL, NULL, NULL, NULL, 'To call off an event means to cancel it. Compare: call up = to telephone someone; call out = to shout, or to challenge someone.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7b1cb899-8570-4d04-be68-18f62f82a572', 953, 'multiple_choice', 'B2', 'phrasal_verbs', 'After months of negotiation, the two companies finally _______ a deal.', 'came up with', '["came up with", "came across", "came around", "came out with"]', NULL, NULL, NULL, NULL, 'To come up with something means to think of or produce an idea, plan, or solution. It implies effort or creativity.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7f800de7-9be5-455c-9d02-2039cf555b70', 954, 'gap_fill', 'B1', 'phrasal_verbs', 'The new product really _______ in the market — sales tripled in a month.', 'took off', NULL, NULL, NULL, NULL, NULL, 'To take off means to become suddenly successful — sales, a career, or a trend. The same phrasal verb is used for planes leaving the ground.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e1e60e3-2d97-40fe-a2a8-343c767ba552', 955, 'gap_fill', 'B1', 'phrasal_verbs', 'Don''t worry about the house while you''re away — I''ll _______ it.', 'look after', NULL, NULL, NULL, NULL, NULL, 'To look after someone or something means to take care of it — making sure it is safe, clean, or well-maintained.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a7ab8712-91ad-415f-88a0-b2143aa590ab', 956, 'gap_fill', 'B2', 'phrasal_verbs', 'He asked for a pay rise twice, but his manager turned him _______ both times.', 'down', NULL, NULL, NULL, NULL, NULL, 'To turn someone down means to reject their request. Note that down comes after the object (him), not after the verb.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('728b094c-5038-40e3-b515-23945d47aee8', 957, 'gap_fill', 'B2', 'phrasal_verbs', 'The deal _______ at the last minute because of a legal disagreement.', 'fell through', NULL, NULL, NULL, NULL, NULL, 'If a deal or plan falls through, it fails to happen — usually at a late stage, after seeming likely to succeed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('40f6e26e-29a6-4d27-b1d9-bb4ca1d5773d', 958, 'gap_fill', 'B2', 'phrasal_verbs', 'Unfortunately, the project was _______ due to a lack of funding.', 'called off', NULL, NULL, NULL, NULL, NULL, 'To call something off means to cancel it, usually an event or plan that had already been arranged.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('850d2639-45bd-4a34-8b67-97c4b80c1554', 959, 'gap_fill', 'C1', 'phrasal_verbs', 'He managed to _______ any serious consequences despite breaking the rules.', 'get away with', NULL, NULL, NULL, NULL, NULL, 'To get away with something means to do something wrong without being caught or punished.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e301a649-f54d-430e-97eb-aeba72cf440a', 960, 'gap_fill', 'C1', 'phrasal_verbs', 'It took years, but she finally _______ her parents'' high expectations.', 'lived up to', NULL, NULL, NULL, NULL, NULL, 'To live up to expectations means to be as good as people hoped or expected. If you fail to meet those standards, you don''t live up to them.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c18ed2e1-a2f8-409d-8a1c-7de58b81751c', 961, 'gap_fill', 'C1', 'phrasal_verbs', 'The CEO attempted to _______ the financial irregularities, but the auditors found everything.', 'cover up', NULL, NULL, NULL, NULL, NULL, 'To cover up means to hide or conceal something — usually wrongdoing or a mistake. The noun form is a cover-up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e3932d6b-c1c9-47af-8507-92a3108559fe', 962, 'gap_fill', 'C1', 'phrasal_verbs', 'The experienced detective _______ the suspect''s false alibi immediately.', 'saw through', NULL, NULL, NULL, NULL, NULL, 'To see through something means to recognise that it is false or deceptive, despite an attempt to hide the truth.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('31b9398c-cdcc-4422-812c-0fa2971ecced', 963, 'gap_fill', 'C1', 'phrasal_verbs', 'After initially agreeing to the merger, the smaller company decided to _______.', 'back out', NULL, NULL, NULL, '["pull out"]', NULL, 'To back out of a commitment or agreement means to withdraw from it, especially after initially agreeing. Pull out has the same meaning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('869a7333-3673-4fd4-8706-0ccca10e5c50', 964, 'gap_fill', 'C1', 'phrasal_verbs', 'He talked his colleague _______ taking on the most difficult part of the project.', 'into', NULL, NULL, NULL, NULL, NULL, 'To talk someone into doing something means to persuade them to do it. The preposition into is essential — compare: talk someone out of = to persuade them not to do it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c9476603-3c12-49e2-94f7-010031f1502b', 965, 'gap_fill', 'C2', 'phrasal_verbs', 'The company''s soaring reputation has been gradually _______ by a series of product failures.', 'worn away', NULL, NULL, NULL, '["eroded away", "eaten away", "chipped away"]', NULL, 'To wear away means to gradually damage or reduce something through continuous pressure or use. Similar: erode away, eat away, chip away.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fcb6b1fc-559c-4c15-b543-f17146de11b8', 966, 'gap_fill', 'C2', 'phrasal_verbs', 'Don''t let her relaxed manner _______ you off — she is an exceptionally tough negotiator.', 'throw', NULL, NULL, NULL, '["put"]', NULL, 'To throw someone off means to confuse or mislead them. Put off has a similar meaning — both suggest causing someone to lose focus or misjudge a situation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6661749c-170f-4fc8-8447-7c6d8b5604db', 967, 'gap_fill', 'C2', 'phrasal_verbs', 'Her genuine enthusiasm for the subject _______ in every lecture she gave.', 'shone through', NULL, NULL, NULL, '["came through"]', NULL, 'To shine through means to be clearly visible or evident, even when something might be expected to hide it. Come through has a similar meaning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('11cbf5f5-370c-4d5b-8e94-bea71b726b26', 968, 'gap_fill', 'C2', 'phrasal_verbs', 'The new director promised to _______ the outdated practices that had held the company back.', 'do away with', NULL, NULL, NULL, '["get rid of", "phase out"]', NULL, 'To do away with something means to abolish or eliminate it completely. Stronger than phase out, which implies a gradual process.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('130caf91-cf1f-483e-9838-66be88cf57ae', 969, 'multiple_choice', 'A1', 'hotel_vocabulary', 'You need to _______ at reception when you arrive at the hotel.', 'check in', '["check in", "sign in", "log in", "book in"]', NULL, NULL, NULL, NULL, 'To check in means to register your arrival at a hotel, airport, or event. The opposite is to check out — to leave and settle your bill.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e3a5ab52-d597-4710-b92d-744fb3094dda', 972, 'multiple_choice', 'A1', 'hotel_vocabulary', 'You can order food to your room using _______ service.', 'room', '["room", "hotel", "floor", "door"]', NULL, NULL, NULL, NULL, 'Room service means ordering food or drinks to be delivered directly to your hotel room, usually at any hour.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('25f1a8df-388a-4344-9419-d554f3e625f1', 973, 'multiple_choice', 'A1', 'hotel_vocabulary', 'The receptionist gave us a _______ to get into our room.', 'key card', '["key card", "password", "code card", "chip"]', NULL, NULL, NULL, NULL, 'A key card is the plastic card used to open hotel room doors electronically. It replaced the traditional metal key in most modern hotels.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ba004cc2-5985-4885-b994-01a24914a342', 974, 'multiple_choice', 'A2', 'hotel_vocabulary', 'We made a _______ at the hotel three months before our holiday.', 'reservation', '["reservation", "plan", "contract", "decision"]', NULL, NULL, NULL, NULL, 'A reservation is a formal arrangement to have something kept for you — a room, table, or seat. Book and reserve are common synonyms as verbs.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90217b21-39db-465d-b853-98ccad25f8c8', 975, 'multiple_choice', 'A2', 'hotel_vocabulary', 'Breakfast is _______ with your room — you don''t need to pay for it separately.', 'included', '["included", "optional", "extra", "available"]', NULL, NULL, NULL, NULL, 'If something is included, it is part of the price — you do not pay extra. The opposite is that it is optional or available at an extra charge.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('66dfe840-3a40-48a0-8fdb-6feedc7e70d2', 976, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The sign on the door said ''No _______'' — the hotel was completely full.', 'vacancy', '["vacancy", "space", "availability", "entry"]', NULL, NULL, NULL, NULL, 'A vacancy is an available room. No vacancy means the hotel is full. The same word is used in recruitment — a job vacancy means a position that needs to be filled.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e6d95cb9-4939-4af5-b891-7a231dff8de1', 977, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The hotel offered _______ champagne on arrival — a free glass for every guest.', 'complimentary', '["complimentary", "traditional", "homemade", "special"]', NULL, NULL, NULL, NULL, 'Complimentary means provided free of charge, as a gesture of hospitality. It is a more formal and professional word than free.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dfa0d297-b09d-4c45-b8b4-8206abb66c4c', 978, 'multiple_choice', 'A2', 'hotel_vocabulary', 'The pool and gym are just two of the hotel''s excellent _______.', 'facilities', '["facilities", "decorations", "attractions", "activities"]', NULL, NULL, NULL, NULL, 'Facilities refers to the physical amenities and services a hotel offers — pool, gym, spa, business centre, etc. It is always plural in this context.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1aa3678c-87ac-4f88-a12f-5b460a13c419', 979, 'multiple_choice', 'B1', 'hotel_vocabulary', 'The hotel was _______ — they had accepted more bookings than they had rooms available.', 'overbooked', '["overbooked", "overcrowded", "overwhelmed", "overrun"]', NULL, NULL, NULL, NULL, 'Overbooked means more reservations have been accepted than there are rooms available. Hotels sometimes offer compensation — an upgrade or alternative accommodation — in this situation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2437b54d-913a-43ca-9416-31ed07d94ac9', 980, 'multiple_choice', 'B1', 'hotel_vocabulary', 'We asked for _______ rooms — two rooms with a connecting door between them.', 'adjoining', '["adjoining", "adjacent", "attached", "additional"]', NULL, NULL, NULL, NULL, 'Adjoining rooms share a connecting internal door. Adjacent rooms are next to each other but do not have a connecting door — an important distinction when booking for families.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ddb8b9d2-883f-4132-9db8-c6c84421c995', 981, 'multiple_choice', 'B1', 'hotel_vocabulary', 'The _______ will arrange restaurant bookings, theatre tickets and airport transfers for guests.', 'concierge', '["concierge", "receptionist", "manager", "valet"]', NULL, NULL, NULL, NULL, 'A concierge is a senior hotel staff member whose role is to assist guests with arrangements — bookings, transport, recommendations, and personal requests.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('37aec3c8-08b5-4f97-9b07-d0e5ebeb5ef5', 982, 'multiple_choice', 'B2', 'hotel_vocabulary', '_______ board means breakfast and dinner are both included in the room price.', 'Half', '["Half", "Full", "Part", "Board"]', NULL, NULL, NULL, NULL, 'Half board includes breakfast and dinner. Full board includes all three meals. Bed and breakfast (B&B) includes only breakfast. All-inclusive covers meals, drinks, and sometimes activities.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5824a6d3-2e95-4503-9581-dbd0d77575ae', 983, 'multiple_choice', 'B2', 'hotel_vocabulary', 'The hotel offers a _______ rate for employees of large companies — a significant discount on standard prices.', 'corporate', '["corporate", "business", "commercial", "preferred"]', NULL, NULL, NULL, NULL, 'A corporate rate is a discounted room price negotiated for employees of a specific company. Hotels offer these to attract regular business travellers.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('99d2b08e-788c-4184-867a-c3f85aa147f7', 984, 'gap_fill', 'B1', 'hotel_vocabulary', 'When I checked in, I had to leave my credit card details to cover any _______ — extra charges for minibar use or room damage.', 'incidentals', NULL, NULL, NULL, NULL, NULL, 'Incidentals are additional charges beyond the room rate — minibar use, phone calls, laundry, or damage. Hotels hold a pre-authorisation on your card to cover these.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('89befc44-c0e9-4f50-bc5c-1e1c4a9c8423', 985, 'gap_fill', 'B1', 'hotel_vocabulary', 'We arrived two hours before the official _______ time, but the hotel let us in straight away.', 'check-in', NULL, NULL, NULL, '["check in"]', NULL, 'Check-in time is the earliest you can access your room. Check-out time is the latest you must leave. Early check-in or late check-out can often be arranged, sometimes for a fee.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('202e85ae-51aa-4a59-8187-9645cbfd31e7', 986, 'gap_fill', 'B2', 'hotel_vocabulary', 'Because we were returning guests, the hotel gave us a free room _______ — we moved from a standard double to a junior suite.', 'upgrade', NULL, NULL, NULL, NULL, NULL, 'An upgrade means moving to a better room — larger, higher floor, or a suite — at no extra cost. Hotels offer these as a gesture of goodwill, especially to loyal guests.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('825c9681-5e1b-4c10-8ae1-e2d79bf1c8c9', 987, 'gap_fill', 'B2', 'hotel_vocabulary', 'The hotel operates a strict _______ policy — if you cancel less than 48 hours before arrival, you are charged in full.', 'cancellation', NULL, NULL, NULL, NULL, NULL, 'A cancellation policy sets out the terms for cancelling a booking. Many hotels charge a full or partial fee if you cancel within a specified window before arrival.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('58bf113f-112f-49b8-9ebd-1b6987bb5083', 988, 'gap_fill', 'B2', 'hotel_vocabulary', 'The maid performed _______ service in the evening — she turned down the beds and left chocolates on the pillow.', 'turn-down', NULL, NULL, NULL, '["turndown"]', NULL, 'Turn-down service is an evening housekeeping visit — the maid folds back the bedcovers, dims the lights, and often leaves a small treat such as chocolates.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('862ad02a-8822-4812-aa36-a0fb58e1204c', 734, 'multiple_choice', 'A1', 'grammar', 'Which sentence is correct?', 'She has a dog.', '["She have a dog.", "She has a dog.", "She haves a dog.", "She is have a dog."]', NULL, NULL, NULL, NULL, 'With he/she/it, the verb "have" becomes "has" in present simple.', '2026-02-26 08:30:21.753626+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4b7aff66-4e48-4dee-a92d-98c1993aeee3', 989, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel''s _______ rate last August reached 97% — nearly every room was occupied.', 'occupancy', NULL, NULL, NULL, NULL, NULL, 'Occupancy rate is the percentage of rooms that are occupied at any given time. A 97% occupancy rate means almost every room is filled — an excellent result for the hotel.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5531d38-0858-4934-821d-b547978e857c', 570, 'multiple_choice', 'C1', 'advanced_grammar', 'I''d rather you ___ mention this to anyone.', 'didn''t', '["won''t", "don''t", "wouldn''t", "didn''t"]', NULL, NULL, NULL, NULL, 'I''d rather + subject + past simple for preferences about others'' actions.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('153d76ff-90de-4210-8d25-74234b97d190', 990, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel uses _______ pricing — room rates change automatically according to demand and availability.', 'dynamic', NULL, NULL, NULL, NULL, NULL, 'Dynamic pricing means rates change automatically based on demand, season, and availability. When the hotel is nearly full, prices rise; when it is quiet, they fall.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4eb55bc4-da25-480a-a640-ba0e69af8ef7', 991, 'gap_fill', 'C1', 'hotel_vocabulary', 'A partial _______ was authorised after several guests complained about construction noise throughout their stay.', 'refund', NULL, NULL, NULL, NULL, NULL, 'A refund is money returned to a guest, usually as compensation for a problem during their stay. Partial refund means only part of the cost is returned.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('522844d8-3c84-4946-b916-da17cf9fabec', 992, 'gap_fill', 'C1', 'hotel_vocabulary', 'The hotel chain is investing heavily in the _______ of its oldest property in the city centre.', 'refurbishment', NULL, NULL, NULL, '["renovation", "restoration"]', NULL, 'A refurbishment is a significant programme of renovation and updating — new furniture, fittings, and décor. Renovation and restoration are close synonyms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7df8f58b-8bc2-44c9-81c2-6f79e6985767', 993, 'gap_fill', 'C1', 'hotel_vocabulary', 'Staff training focused on managing the entire guest _______ — from the first online search to the post-stay review.', 'journey', NULL, NULL, NULL, '["experience"]', NULL, 'The guest journey (or guest experience) covers every stage of a hotel stay — from the first search online, through check-in, the stay itself, check-out, and the post-stay review.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fcbf2492-ab9d-42f0-9e6f-d2efebd97a6f', 994, 'gap_fill', 'C2', 'hotel_vocabulary', 'The new general manager introduced _______ service protocols to ensure consistency across all 14 properties in the group.', 'standardised', NULL, NULL, NULL, '["standardized", "consistent", "unified"]', NULL, 'Standardised protocols ensure every property in a group delivers the same level of service, regardless of location. Consistency is a key goal in hotel chain management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90398186-c85a-4823-a941-25cb0bcf9950', 995, 'gap_fill', 'C2', 'hotel_vocabulary', 'The hotel''s reputation for _______ service — anticipating guests'' needs before they are expressed — sets it apart from its competitors.', 'proactive', NULL, NULL, NULL, '["anticipatory", "personalised", "attentive"]', NULL, 'Proactive service means anticipating guests'' needs before they have to ask — for example, offering an umbrella when rain is forecast. It is considered the hallmark of luxury hospitality.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('49c9a646-62eb-4307-9130-5940b2fee305', 996, 'gap_fill', 'C2', 'hotel_vocabulary', 'When a guest''s room is not yet ready on early arrival, good front desk staff will offer _______ storage and direct them to the hotel''s facilities.', 'luggage', NULL, NULL, NULL, '["baggage"]', NULL, 'Luggage storage means keeping guests'' bags securely while their room is not yet ready, or after check-out. A well-run front desk always offers this as a matter of course.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Hotel vocabulary","Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('95aa6e6b-7bdb-46d8-ba6b-f96e13a0bf19', 997, 'multiple_choice', 'A1', 'vocabulary', 'Can you _______ me your pen for a minute? I''ll give it back straight away.', 'lend', '["lend", "borrow", "rent", "take"]', NULL, NULL, NULL, NULL, 'Lend means to give something temporarily — you lend to someone. Borrow means to receive something temporarily — you borrow from someone. These are commonly confused.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('50a227cd-f521-4b73-b2e9-f7eba8ba53f9', 998, 'multiple_choice', 'A1', 'vocabulary', 'I need to _______ a reservation at the restaurant for Friday night.', 'make', '["make", "do", "have", "take"]', NULL, NULL, NULL, NULL, 'Make a reservation is a fixed collocation. You make a reservation, a booking, an appointment, and a decision. You do not do these things.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d5cb0d70-8fda-4319-848c-1ec6d63b2f4b', 999, 'multiple_choice', 'A1', 'vocabulary', 'My teacher gave me some useful _______ on how to improve my writing.', 'advice', '["advice", "advices", "advise", "advising"]', NULL, NULL, NULL, NULL, 'Advice is an uncountable noun — it has no plural form. You cannot say advices. One piece of advice; some advice; a lot of advice.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c9205651-6e26-47f2-8a08-4e33e8eb5288', 1000, 'multiple_choice', 'A1', 'vocabulary', 'All of our _______ was lost at the airport — including our passports.', 'luggage', '["luggage", "luggages", "bags", "baggages"]', NULL, NULL, NULL, NULL, 'Luggage is uncountable — no plural form. The same applies to baggage. You say a piece of luggage, not a luggage or luggages.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Uncountable noun"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0dff1681-468c-4b28-930e-24877444f9b5', 1001, 'multiple_choice', 'A2', 'vocabulary', 'The teacher spoke quickly and I couldn''t _______ everything she said.', 'follow', '["follow", "listen", "hear", "catch"]', NULL, NULL, NULL, NULL, 'To follow means to understand the logic or sequence of something. Catch has a similar meaning in informal English — I didn''t catch what she said.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e7baaabf-4b05-43dc-9ec6-86eaa362a276', 1002, 'multiple_choice', 'A2', 'vocabulary', 'She was _______ when she found out she''d passed — she jumped up and screamed!', 'delighted', '["delighted", "disappointed", "confused", "shocked"]', NULL, NULL, NULL, NULL, 'Delighted means very pleased. It is stronger than happy and is the natural choice when the good news is significant, like passing an exam.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8f8fd5d0-8d75-45be-9e03-621be6c52703', 1003, 'multiple_choice', 'A2', 'vocabulary', 'I _______ my umbrella on the bus and had to walk home in the rain.', 'left', '["left", "forgot", "lost", "dropped"]', NULL, NULL, NULL, NULL, 'Left is used when you deliberately or accidentally put something somewhere and did not take it with you. Forgot implies you did not remember to bring it. Lose implies you do not know where it is.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e972298-600d-44f8-80ff-d9d6ea3b8185', 1004, 'multiple_choice', 'A2', 'vocabulary', 'My boss is very _______ — she always says thank you and treats everyone with respect.', 'polite', '["polite", "punctual", "ambitious", "creative"]', NULL, NULL, NULL, NULL, 'Polite describes someone who is respectful and considerate in manner and speech. Compare: punctual = always on time; ambitious = strongly motivated to succeed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c7e715c7-c195-4d7d-a04d-1efd514716d6', 1005, 'multiple_choice', 'A2', 'vocabulary', 'The documentary was really _______ — I learned so much I didn''t know before.', 'informative', '["informative", "entertaining", "enjoyable", "exciting"]', NULL, NULL, NULL, NULL, 'Informative means providing useful knowledge or facts. Compare: entertaining = enjoyable to watch or read; educational = teaching something, but with a stronger sense of formal learning.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90316c47-e964-489a-b785-a38370b284a4', 1006, 'multiple_choice', 'A2', 'vocabulary', 'He was very _______ — he arrived ten minutes early for every single meeting.', 'punctual', '["punctual", "polite", "organised", "professional"]', NULL, NULL, NULL, NULL, 'Punctual means consistently on time. It is a valued professional quality, especially in cultures where time-keeping is taken seriously.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9a91008a-7fbd-40ae-9c85-dd8c7c40f841', 1007, 'multiple_choice', 'B1', 'vocabulary', 'She''s very _______ — if she says she''ll do something, she always does it.', 'reliable', '["reliable", "flexible", "ambitious", "determined"]', NULL, NULL, NULL, NULL, 'Reliable describes someone who can be trusted to do what they say. Compare: flexible = willing to adapt; determined = strongly committed to achieving something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('37cf0df0-67d6-4491-b433-f3a930e35171', 1008, 'multiple_choice', 'B1', 'vocabulary', 'The audit was extremely _______ — the team checked every single transaction.', 'thorough', '["thorough", "brief", "efficient", "routine"]', NULL, NULL, NULL, NULL, 'Thorough means extremely careful and complete. A thorough audit leaves nothing unchecked. Compare: efficient = achieving results without wasting time or resources.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('57456f01-2dd2-4377-82af-c1c0a14a265c', 1009, 'multiple_choice', 'B2', 'vocabulary', 'The new office has a very _______ atmosphere — everyone is on first-name terms and wears casual clothes.', 'informal', '["informal", "formal", "tense", "competitive"]', NULL, NULL, NULL, NULL, 'Informal describes a relaxed environment without strict rules or formality. Common signs: first names, casual clothes, open-plan offices. The opposite is formal.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('68afbc41-8927-4f9a-beee-b749b84082b8', 1010, 'multiple_choice', 'B2', 'vocabulary', 'There was a _______ between the figures in the report and the actual bank statements.', 'discrepancy', '["discrepancy", "mistake", "problem", "difference"]', NULL, NULL, NULL, NULL, 'A discrepancy is a difference between two figures or accounts that should match. In finance, a discrepancy between records and actual balances is a serious concern.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('91ee463e-bdf2-4f29-a406-633219239a67', 1011, 'multiple_choice', 'B2', 'vocabulary', 'Her speech was _______ — every single person in the room was completely engaged.', 'compelling', '["compelling", "informative", "prepared", "professional"]', NULL, NULL, NULL, NULL, 'Compelling means so interesting or persuasive that it holds your complete attention. A compelling argument is one that is very difficult to disagree with.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c023959-a056-462d-bee4-7493aa4dfbfd', 1012, 'gap_fill', 'B1', 'vocabulary', 'The project was finished three weeks _______ of schedule — the team was delighted.', 'ahead', NULL, NULL, NULL, NULL, NULL, 'Ahead of schedule means finishing or progressing earlier than planned. The opposite is behind schedule. Both are essential phrases in project management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f04c8c79-1659-412c-be67-31e7f54e34ce', 1013, 'gap_fill', 'B1', 'vocabulary', 'I have a real _______ for languages — I find it easy to pick up new words and grammar.', 'flair', NULL, NULL, NULL, '["gift", "talent", "knack"]', NULL, 'A flair for something means a natural talent or instinct for it. Similar: a gift for, a talent for, a knack for — though flair carries a slightly more stylish connotation.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation,"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6f1a6a00-3d52-4645-8ecf-f49b7c6c6ede', 1014, 'gap_fill', 'B2', 'vocabulary', 'His first attempt at the business failed, but his second one was a _______ success.', 'resounding', NULL, NULL, NULL, '["huge", "massive", "tremendous", "great"]', NULL, 'A resounding success means a very great and unmistakeable success. Resounding is a strong intensifier — more emphatic than huge or great.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6ffba1a8-4b06-4e73-9398-1ee9b7bdddb6', 1015, 'gap_fill', 'B2', 'vocabulary', 'She was _______ with praise after her presentation — her manager called it the best he''d seen in years.', 'showered', NULL, NULL, NULL, NULL, NULL, 'To be showered with praise means to receive a great deal of it all at once. The image is of praise falling like water — sudden and abundant.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07527c6f-efa0-423c-8a85-c8c6b7393e09', 1016, 'gap_fill', 'B2', 'vocabulary', 'The company has _______ its profits by 40% this year through cost-cutting and new markets.', 'boosted', NULL, NULL, NULL, '["increased", "grown", "raised"]', NULL, 'To boost profits means to increase them, often significantly and deliberately. Boost implies both the action taken and a strong positive result.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('844d2664-5c20-4acb-8a59-415f15c47527', 1017, 'gap_fill', 'C1', 'vocabulary', 'The findings of the new study are largely _______ with earlier research on the same topic.', 'consistent', NULL, NULL, NULL, NULL, NULL, 'Consistent with means in agreement or harmony with. If new findings are consistent with earlier research, the two support each other.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7b0631da-6c2f-42a0-bf1d-5971a4f0c465', 1018, 'gap_fill', 'C1', 'vocabulary', 'Her argument was completely _______ — every point supported the next, with no logical gaps.', 'coherent', NULL, NULL, NULL, '["watertight", "airtight", "logical"]', NULL, 'Coherent means logically structured and easy to follow — every part connects clearly to the next. Compare: watertight = having no flaws or gaps, especially in an argument or contract.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7fe099e2-0907-49f3-8576-12ab7bc9ad00', 1019, 'gap_fill', 'C1', 'vocabulary', 'The proposal was _______ on the grounds that it was too expensive and too risky.', 'rejected', NULL, NULL, NULL, '["dismissed", "turned down"]', NULL, 'To reject a proposal means to refuse or dismiss it officially. Rejected on the grounds that means refused for a specific stated reason.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a20a9499-2bf8-4ae3-b9f5-1e3f9b6c42cc', 1020, 'gap_fill', 'C1', 'vocabulary', 'The data was carefully _______ before any conclusions were drawn.', 'scrutinised', NULL, NULL, NULL, '["scrutinized", "analysed", "examined", "reviewed"]', NULL, 'To scrutinise means to examine very carefully and critically. It implies more intensity than simply review or check — often used in formal, legal, or financial contexts.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db4b7dd6-9657-450b-8bf2-39da1ba3fc36', 1021, 'gap_fill', 'C1', 'vocabulary', 'She has a _______ understanding of the political complexities involved in the negotiation.', 'nuanced', NULL, NULL, NULL, '["sophisticated", "thorough", "deep"]', NULL, 'A nuanced understanding is one that recognises complexity, subtlety, and different shades of meaning — rather than seeing things in simple black and white.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7b60baf-d962-44bc-b704-2a67ea70a467', 1022, 'gap_fill', 'C2', 'vocabulary', 'The two theories are mutually _______ — accepting one means rejecting the other entirely.', 'exclusive', NULL, NULL, NULL, NULL, NULL, 'Mutually exclusive means two things that cannot both be true or accepted at the same time. If you accept one, you must reject the other.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4b1f57d0-b01d-4460-a745-85361c161bc5', 1023, 'gap_fill', 'C2', 'vocabulary', 'The new CEO has worked hard to _______ the company''s public image following last year''s scandal.', 'rehabilitate', NULL, NULL, NULL, '["restore", "rebuild", "repair"]', NULL, 'To rehabilitate an image means to restore it after damage — to make it credible and respected again. Rebuild and restore are close synonyms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0073a9be-7266-4efd-b949-118d6af7cc7f', 1024, 'gap_fill', 'C2', 'vocabulary', 'The report identified a number of serious _______ in the organisation''s financial reporting.', 'shortcomings', NULL, NULL, NULL, '["irregularities", "deficiencies", "weaknesses"]', NULL, 'Shortcomings are weaknesses or failures to meet a required standard. In formal reports, shortcomings is more precise than problems or mistakes.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('28bd7821-4f70-4f91-bdca-2a5d73bcfac8', 1025, 'gap_fill', 'C2', 'vocabulary', 'His initial reluctance to accept the terms of the deal was eventually _______ by a revised offer.', 'overcome', NULL, NULL, NULL, '["addressed", "resolved"]', NULL, 'To overcome reluctance means to succeed despite it — the obstacle is conquered rather than avoided. Compare: address = to deal with something directly; resolve = to find a solution.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('33add3bd-2cb4-4c05-ae96-a1be83b6a6f1', 1026, 'gap_fill', 'C2', 'vocabulary', 'The legislation was criticised for being _______ — it failed to address the root causes of the problem.', 'superficial', NULL, NULL, NULL, '["inadequate", "piecemeal", "insufficient"]', NULL, 'Superficial means dealing only with the surface of a problem — lacking depth or substance. Legislation can be criticised as superficial if it fails to tackle root causes.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eae7ed9f-9950-402b-8905-6afe1b0f842c', 1027, 'multiple_choice', 'A1', 'prepositions', 'I usually wake up _______ seven o''clock in the morning.', 'at', '["at", "in", "on", "by"]', NULL, NULL, NULL, NULL, 'Use at with specific times: at seven o''clock, at noon, at midnight, at 3pm. Use in with parts of the day: in the morning, in the evening. Use on with days and dates.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1bc161ba-7a1d-451b-a350-1853faac8a08', 1029, 'multiple_choice', 'A1', 'prepositions', 'My birthday is _______ the 14th of March.', 'on', '["on", "at", "in", "by"]', NULL, NULL, NULL, NULL, 'Use on with specific dates and named days: on the 14th of March, on Monday, on Christmas Day. Use in with months, years, and seasons: in March, in 2024, in summer.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of time"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('85e05c38-6b22-4d4e-a1ea-51c91010cc7d', 1030, 'multiple_choice', 'A1', 'prepositions', 'She lives _______ a small flat in the centre of the city.', 'in', '["in", "at", "on", "inside"]', NULL, NULL, NULL, NULL, 'Use in with enclosed spaces — rooms, buildings, cities, countries: in a flat, in London, in Spain. Use at for specific locations or points: at the door, at the station.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9c466ebd-1f03-445c-bbfc-22c689465b7c', 1031, 'multiple_choice', 'A1', 'prepositions', 'The keys are _______ the table in the kitchen.', 'on', '["on", "in", "at", "above"]', NULL, NULL, NULL, NULL, 'Use on for surfaces — things resting on top of something: on the table, on the floor, on the wall. Use in for things inside a container or enclosed space.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c062d7e1-3f22-44d6-815d-9daa007d0824', 1037, 'multiple_choice', 'B1', 'prepositions', 'I''m really interested _______ learning how to cook Thai food.', 'in', '["in", "for", "with", "at"]', NULL, NULL, NULL, NULL, 'Interested in is a fixed collocation — the preposition is always in. Compare: keen on, enthusiastic about, passionate about — each adjective has its own fixed preposition.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d6b89237-32c6-4948-ba45-1f04a866cddf', 1038, 'multiple_choice', 'B1', 'prepositions', 'She''s very good _______ dealing with difficult clients — she always stays calm.', 'at', '["at", "in", "for", "with"]', NULL, NULL, NULL, NULL, 'Good at is a fixed collocation — the preposition is always at. Compare: skilled in, experienced in, capable of — different adjectives require different prepositions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0768b195-d1d9-45a6-aa13-80064ffc61e2', 1039, 'multiple_choice', 'B1', 'prepositions', 'He apologised _______ being late and explained what had happened.', 'for', '["for", "on", "of", "to"]', NULL, NULL, NULL, NULL, 'Apologise for is the correct collocation — the preposition is always for. You apologise for an action: for being late, for the delay, for the mistake.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82da67e5-759d-4cbb-be37-f930f1968176', 1040, 'multiple_choice', 'B2', 'prepositions', 'The report was criticised _______ a lack of evidence and poor methodology.', 'for', '["for", "by", "about", "with"]', NULL, NULL, NULL, NULL, 'Criticised for means the reason for criticism is introduced with for. Compare: criticised by = identifies who is doing the criticising.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('47158ccd-0ade-4e2e-b689-e6b867fc7d95', 1041, 'multiple_choice', 'B2', 'prepositions', 'The decision to expand was made _______ consultation with the board.', 'in', '["in", "for", "to", "by"]', NULL, NULL, NULL, NULL, 'In consultation with is a fixed phrase meaning after discussing with. The decision was made in consultation with the board = the board was involved in the process.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a0a43e8e-8054-4707-9218-7d1124a693ca', 1042, 'gap_fill', 'B1', 'prepositions', 'She''s very keen _______ joining the project — she asked me about it again this morning.', 'on', NULL, NULL, NULL, NULL, NULL, 'Keen on is a fixed collocation. Other similar expressions: interested in, enthusiastic about, passionate about. Each adjective takes a specific preposition.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e3b6b5f8-dde1-4adb-a383-16a4e55796b0', 1043, 'gap_fill', 'B1', 'prepositions', 'I''m not very good _______ remembering names, but I never forget a face.', 'at', NULL, NULL, NULL, NULL, NULL, 'Good at is fixed. The preposition at is used with skills and abilities: good at maths, bad at cooking, terrible at remembering names.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('119cc318-be1b-42df-9348-10375087420f', 1044, 'gap_fill', 'B2', 'prepositions', 'The new policy came _______ force on the first of January.', 'into', NULL, NULL, NULL, NULL, NULL, 'Come into force is a fixed legal and formal phrase meaning to officially start taking effect. A law or policy comes into force on a specific date.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8d15b2b5-abc3-462c-8c18-bc3073fd06a3', 1045, 'gap_fill', 'B2', 'prepositions', 'He resigned _______ protest after the board rejected his proposal for the third time.', 'in', NULL, NULL, NULL, NULL, NULL, 'Resign in protest is a fixed phrase — the preposition is in. In protest means as a formal expression of disagreement or objection.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ed0904e8-5850-46d2-99fa-d5af1e4eeb72', 1046, 'gap_fill', 'B2', 'prepositions', 'The deal was agreed _______ principle, but the details still need to be finalised.', 'in', NULL, NULL, NULL, NULL, NULL, 'Agreed in principle means the main idea has been accepted, but the specific details still need to be worked out and confirmed.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('60f563e1-6b72-4668-875e-c20fc6ec9713', 1047, 'gap_fill', 'C1', 'prepositions', 'The two parties reached an agreement _______ the basis of mutual compromise.', 'on', NULL, NULL, NULL, NULL, NULL, 'On the basis of is a fixed formal phrase meaning using something as the foundation or reason for a decision or agreement.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e44fc4e-70ae-41e6-ae41-147a59ecd012', 1048, 'gap_fill', 'C1', 'prepositions', 'Her success is testament _______ years of dedicated preparation.', 'to', NULL, NULL, NULL, NULL, NULL, 'Testament to is a fixed phrase meaning clear evidence or proof of something: Her success is testament to years of hard work.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('111805ce-2657-4ae4-9ee1-557764e4ddab', 1049, 'gap_fill', 'C1', 'prepositions', 'The government was accused _______ acting in bad faith during the negotiations.', 'of', NULL, NULL, NULL, NULL, NULL, 'Accused of is fixed — the preposition is always of. You accuse someone of a specific act: accused of fraud, accused of acting in bad faith.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Dependent preposition"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f68ab317-9aac-4b17-9762-03167695acd8', 1050, 'gap_fill', 'C1', 'prepositions', 'The merger fell _______ at the final hurdle due to regulatory concerns.', 'through', NULL, NULL, NULL, NULL, NULL, 'Fall through means to fail or collapse — particularly a deal, plan, or negotiation. The at the final hurdle phrase means it failed at the very last stage.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Phrasal verb","Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3eccf293-2f22-46f3-a6ac-74e8c1b7f8a4', 1051, 'gap_fill', 'C1', 'prepositions', 'He was _______ the verge of resigning when the company offered him a promotion.', 'on', NULL, NULL, NULL, NULL, NULL, 'On the verge of means on the point of — very close to doing something, usually significant: on the verge of resigning, on the verge of bankruptcy.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0f7cce3f-9f9b-49fc-ae6e-40a0813ba115', 1052, 'gap_fill', 'C2', 'prepositions', 'The new law applies _______ retrospect — it affects decisions made before it was passed.', 'in', NULL, NULL, NULL, NULL, NULL, 'In retrospect is a fixed phrase meaning when looking back at past events with the knowledge you have now. Retroactively and retrospectively are related adverbs.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cc9392cd-0144-484d-8b7d-ad1474faf06c', 1053, 'gap_fill', 'C2', 'prepositions', 'The committee concluded that the organisation had acted in accordance _______ all relevant guidelines.', 'with', NULL, NULL, NULL, NULL, NULL, 'In accordance with is a fixed formal phrase meaning in compliance with, or following the rules of. Common in legal and official language.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aae376ec-cc16-4f87-b124-067efd09743f', 1054, 'gap_fill', 'C2', 'prepositions', 'She spoke on behalf _______ all the employees when she raised the concerns.', 'of', NULL, NULL, NULL, NULL, NULL, 'On behalf of is a fixed phrase meaning representing or acting for someone else: She spoke on behalf of all the employees.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b887b0e1-a9d3-49b5-bff5-898079218dad', 1055, 'gap_fill', 'C2', 'prepositions', 'The latest figures stand in stark contrast _______ the optimistic forecasts made last year.', 'to', NULL, NULL, NULL, NULL, NULL, 'In stark contrast to is a fixed phrase meaning showing a very clear and strong difference. The preposition after contrast is always to or with.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('99cf345e-7417-4115-834d-49f6ab43df76', 1056, 'gap_fill', 'C2', 'prepositions', 'The proposal is in line _______ the company''s long-term sustainability goals.', 'with', NULL, NULL, NULL, NULL, NULL, 'In line with is a fixed phrase meaning consistent with, or following the same direction as. Common in business and policy language.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Fixed expression","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5a2a87cd-4022-484a-b3d7-d21177771c00', 1058, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _______ new staff before the busy season starts.', 'take on', '["take on", "take off", "take up", "take over"]', NULL, NULL, NULL, NULL, 'To take on staff means to hire or employ new people. Take on can also mean to accept a responsibility or challenge.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","HR vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f4505806-6d48-4902-9f7d-d6f5391c9f07', 1059, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'Please _______ the form completely before you submit your application.', 'fill in', '["fill in", "fill up", "fill through", "fill over"]', NULL, NULL, '["fill out"]', NULL, 'To fill in (or fill out) a form means to complete it by writing all the required information. Both are correct — fill out is more common in American English.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1fece76a-b4f7-42eb-8bff-798bed150c41', 262, 'gap_fill', 'A1', 'prepositions_of_place', 'She lives ___ Barcelona.', 'in', NULL, NULL, NULL, NULL, NULL, 'Use in with cities, countries, and continents.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Preposition of place"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('23750d54-ea09-4904-9639-c2edde8a2034', 1060, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The CEO has decided to _______ early — he''ll leave the company next year.', 'step down', '["step down", "step back", "step out", "step up"]', NULL, NULL, NULL, NULL, 'To step down means to resign from a senior position, usually voluntarily. The opposite — moving to a more senior role — is to step up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","HR vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ca09327f-2ab7-4323-b2b6-b7b8ab4c2683', 1061, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _______ the main points from today''s meeting and send them to the team.', 'write up', '["write up", "write out", "write down", "write off"]', NULL, NULL, NULL, NULL, 'To write up means to produce a formal written record of something. Compare: write down = to make a quick note; write off = to dismiss something as a loss.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ca953330-8f27-4482-9ae8-a3e5a31cedbd', 1062, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The new product launch really _______ — sales exceeded all our targets.', 'took off', '["took off", "took on", "took over", "took up"]', NULL, NULL, NULL, NULL, 'To take off means to become suddenly successful or popular. It also means to remove clothing, or for a plane to leave the ground.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5600f283-3df8-4103-b810-13bb3c673083', 1063, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Could you _______ the sales figures for last month? I need them for the report.', 'look up', '["look up", "look into", "look after", "look over"]', NULL, NULL, NULL, NULL, 'To look up means to search for specific information — in a database, reference book, or online. Compare: look into = to investigate a problem more deeply.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d65ab7d-82fa-4f60-bb35-7c0a451c4a5c', 1064, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The smaller company was _______ by a large international corporation last year.', 'taken over', '["taken over", "taken on", "taken off", "taken up"]', NULL, NULL, NULL, NULL, 'A takeover happens when one company buys a controlling interest in another. To take over means to assume control of something.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3438f673-48a0-4b7f-96b6-1bf84c0e7189', 1065, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Please _______ the contract carefully before you sign it.', 'go over', '["go over", "go back", "go on", "go ahead"]', NULL, NULL, '["go through"]', NULL, 'To go over (or go through) a document means to examine it carefully, checking each part. Both are correct here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('33e5eca5-98c0-47f1-a2d0-96cf56b4c615', 1066, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The manager asked everyone to _______ their ideas before the next meeting.', 'think over', '["think over", "think up", "think about", "think through"]', NULL, NULL, NULL, NULL, 'To think over means to consider something carefully before deciding. Compare: think up = to invent or come up with an idea.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0003cd08-9211-4b28-a5e3-b8a674422d5e', 1068, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'It took six months to _______ a contract that worked for both companies.', 'draw up', '["draw up", "draw on", "draw out", "draw back"]', NULL, NULL, NULL, NULL, 'To draw up a contract or plan means to prepare a formal written version of it.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0d228670-dab7-457b-bf0f-b9e437792aa1', 1069, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'After unexpected delays, the project went significantly _______ budget.', 'over', '["over", "above", "past", "beyond"]', NULL, NULL, NULL, NULL, 'To go over budget means to spend more than planned. This is a fixed expression — above, past, and beyond don''t work here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Fixed expression","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cd9526ef-f8ee-44ae-a17c-3687ab3a1989', 1070, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'After months of planning, the directors finally _______ a workable restructuring plan.', 'came up with', '["came up with", "came across", "came around", "came out with"]', NULL, NULL, NULL, NULL, 'To come up with something means to produce or think of an idea, plan, or solution. It implies creativity or effort.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8706fac5-61f2-48fb-b5e2-b15a41f71744', 1071, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'The aggressive expansion plan _______ the company''s cash reserves very quickly.', 'ate into', '["ate into", "ate up", "ate away", "ate all"]', NULL, NULL, NULL, NULL, 'To eat into something means to gradually reduce or deplete it — typically money, time, or resources. Very common in financial contexts.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('78ef6fd4-e657-4462-9d05-5a170d280bc9', 1073, 'gap_fill', 'B1', 'business_phrasal_verbs', 'We need to _______ our operating costs if we want to stay competitive.', 'cut down on', NULL, NULL, NULL, '["cut back on", "reduce", "bring down"]', NULL, 'To cut down on (or cut back on) costs means to reduce spending. Both are equally correct here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d8f5965b-66b5-4471-a701-67d27b2d9336', 1077, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The audit revealed that the management team had been _______ significant financial irregularities for years.', 'covering up', NULL, NULL, NULL, NULL, NULL, 'To cover up means to deliberately conceal wrongdoing or mistakes. The noun is a cover-up.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c5637bb9-1b5c-4e4c-b633-0993fefea11a', 1078, 'gap_fill', 'C1', 'business_phrasal_verbs', 'After intense pressure from shareholders, the company agreed to _______ its controversial data-sharing practices.', 'phase out', NULL, NULL, NULL, '["do away with"]', NULL, 'To phase out a practice or product means to withdraw it gradually and systematically, rather than stopping all at once.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b7d20097-3dba-4095-a89f-8ebe97b5c67d', 1079, 'gap_fill', 'C1', 'business_phrasal_verbs', 'She managed to _______ the hostile board members and get them to support the new strategy.', 'win over', NULL, NULL, NULL, '["bring around", "talk round", "bring round"]', NULL, 'To win someone over means to persuade them to change their position or gain their support, often after initial resistance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('24f1db93-a953-4053-9d21-817beddea32d', 1080, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The legal dispute between the two firms has been _______ for nearly three years with no resolution in sight.', 'dragging on', NULL, NULL, NULL, NULL, NULL, 'If something drags on, it continues for much longer than expected or desired. Commonly used for disputes, negotiations, and meetings.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8add974c-108a-4b67-8fb0-a6393cf2a9ad', 369, 'multiple_choice', 'A1', 'basic_questions', '___ is this? It''s my phone.', 'What', '["Who", "What", "Where", "How"]', NULL, NULL, NULL, NULL, 'What for identifying objects: What is this?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3d85a895-cfbc-4130-bab4-bebcc986e730', 1081, 'gap_fill', 'C1', 'business_phrasal_verbs', 'Demand for the product has _______ significantly since the negative press coverage.', 'tailed off', NULL, NULL, NULL, '["dropped off", "fallen off", "died down"]', NULL, 'To tail off means to gradually decrease or decline. Compare: fall off, drop off. Note: died down suggests noise or excitement fading, not quantity declining.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cfea1474-77fd-4264-95a2-b51301645354', 1082, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The new CEO immediately set about _______ the bloated management structure that had developed under her predecessor.', 'cutting back on', NULL, NULL, NULL, '["doing away with", "streamlining", "slimming down"]', NULL, 'To cut back on means to significantly reduce. To do away with is stronger — it means to eliminate completely.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9e925ecb-345b-42fd-98ff-f52ad08fe501', 1083, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The smaller firm was worried the partnership would allow the larger company to _______ their intellectual property.', 'get hold of', NULL, NULL, NULL, '["walk away with", "take over"]', NULL, 'To get hold of something means to obtain or acquire it, often implying some difficulty or effort involved.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('47bbf07a-804b-4703-ac81-700806008f16', 1084, 'gap_fill', 'C2', 'business_phrasal_verbs', 'Both parties eventually _______ their entrenched positions and reached a compromise.', 'backed away from', NULL, NULL, NULL, '["moved away from", "stepped back from"]', NULL, 'To back away from a position means to withdraw from it, often under pressure. Similar to step back from or move away from.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4be02d5c-f0ac-402e-8028-051e26e6cba3', 1085, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The company''s aggressive pricing strategy is designed to _______ less well-funded competitors.', 'squeeze out', NULL, NULL, NULL, '["drive out", "force out", "push out"]', NULL, 'To squeeze out competitors means to force them out of the market — typically through price pressure, superior resources, or aggressive tactics.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb","Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('749b63e9-74d9-494f-bda1-3cda39c27ef1', 1086, 'gap_fill', 'C2', 'business_phrasal_verbs', 'After the scandal, the PR team worked overtime to _______ the reputational damage as quickly as possible.', 'contain', NULL, NULL, NULL, '["limit", "minimise", "minimise the impact of"]', NULL, 'To contain damage means to limit it and prevent it from spreading further. Damage containment is a standard term in PR and crisis management.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53129746-68d3-4873-9d3f-545afd91aade', 1093, 'multiple_choice', 'A2', 'business_vocabulary', 'A _______ is an amount of extra money paid to an employee for doing very well.', 'bonus', '["bonus", "salary", "commission", "benefit"]', NULL, NULL, NULL, NULL, 'A bonus is a one-off additional payment for good performance. Compare: commission = a percentage of sales earned by a salesperson; benefit = a non-cash perk such as a company car or health insurance.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Financial vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fcddf7f4-8812-4ecb-a557-e4401567c1ec', 1094, 'multiple_choice', 'A2', 'business_vocabulary', 'To _______ someone means to officially end their employment.', 'dismiss', '["dismiss", "resign", "retire", "suspend"]', NULL, NULL, NULL, NULL, 'To dismiss someone means to end their employment, usually for misconduct or poor performance. Compare: resign = to leave voluntarily; retire = to stop working, usually at an older age; make redundant = to eliminate a role due to business reasons.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bd469c87-4f87-4761-8d1c-9b188ff404c0', 1095, 'multiple_choice', 'A2', 'business_vocabulary', 'When two companies join together to form one new company, it is called a _______.', 'merger', '["merger", "takeover", "acquisition", "partnership"]', NULL, NULL, NULL, NULL, 'A merger is when two companies combine to form one new company. A takeover (or acquisition) is when one company buys another — the bought company loses its independence.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d50f2e9c-bf3f-4dc7-bc00-3d29a2a4f55a', 1096, 'multiple_choice', 'A2', 'business_vocabulary', 'A formal request for a job is called a job _______.', 'application', '["application", "interview", "contract", "proposal"]', NULL, NULL, NULL, NULL, 'A job application is the formal process of applying for a position — usually a written form plus a CV. Compare: interview = the next stage; contract = the agreement signed if you are offered the job.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","HR vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('52e19c11-16a0-4fd3-a3bd-c04a6e89f461', 1097, 'multiple_choice', 'B1', 'business_vocabulary', 'The company decided to focus on its most profitable products and _______ its operations.', 'streamline', '["streamline", "downsize", "restructure", "outsource"]', NULL, NULL, NULL, NULL, 'To streamline operations means to simplify and make more efficient — removing unnecessary steps or roles. Compare: downsize = to reduce the size of the workforce; restructure = to reorganise departments or reporting lines.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5da467b7-dc49-4437-a7dd-530bdab2c3d0', 1098, 'multiple_choice', 'B1', 'business_vocabulary', 'The company has decided to _______ its IT support to an external company in Eastern Europe.', 'outsource', '["outsource", "delegate", "transfer", "subcontract"]', NULL, NULL, NULL, NULL, 'To outsource means to pay an external company to do work that could be done in-house. Companies outsource to reduce costs or access specialist skills. Compare: delegate = to assign tasks to someone within the company.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fa634673-153a-45ab-8516-9280c5597613', 1099, 'multiple_choice', 'B2', 'business_vocabulary', 'The sudden resignation of the CEO had a significant _______ effect on the company''s share price.', 'knock-on', '["knock-on", "follow-on", "carry-on", "spin-off"]', NULL, NULL, NULL, NULL, 'A knock-on effect is a secondary consequence — one event causes another, which then causes another. Very common in business and economics.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d14b3ba2-8f0a-4e17-be4c-b379547093c7', 1100, 'multiple_choice', 'B2', 'business_vocabulary', 'After three consecutive years of losses, the company was declared _______.', 'insolvent', '["insolvent", "bankrupt", "illiquid", "indebted"]', NULL, NULL, '["bankrupt"]', NULL, 'Insolvent means unable to pay debts as they fall due. Bankrupt is the legal status that follows — when a court formally declares insolvency. Both are acceptable answers here.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9615bbc3-e834-4394-b01b-c603adc8d423', 506, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'It later ___ that he had been lying all along.', 'came out', '["came up", "came round", "came out", "came off"]', NULL, NULL, NULL, NULL, 'Come out = become known, be revealed publicly.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('434fc45d-33d3-4c76-ab9e-410247f163a4', 1146, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a colour of the rainbow?', 'pink', '["red", "green", "pink", "blue"]', NULL, NULL, NULL, NULL, 'Pink is not a colour of the rainbow. The colours are red, orange, yellow, green, blue, indigo, and violet.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c2cf1f1f-a2f5-4b49-b76c-6a5314ce912f', 1101, 'multiple_choice', 'B2', 'business_vocabulary', 'A product that generates a large profit relative to its cost is said to have a high profit _______.', 'margin', '["margin", "rate", "percentage", "ratio"]', NULL, NULL, NULL, NULL, 'Profit margin is the percentage of revenue that becomes profit after costs. A high margin means the product is very profitable relative to its price.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('297421df-faf8-48d2-a6b0-307b47362e0d', 1103, 'gap_fill', 'B1', 'business_vocabulary', 'A summary of a company''s financial position — what it owns and what it owes — is called a _______ sheet.', 'balance', NULL, NULL, NULL, NULL, NULL, 'A balance sheet is a financial statement showing what a company owns (assets) and what it owes (liabilities) at a specific point in time. Assets minus liabilities = equity.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aecb5cb6-f575-4e81-8502-997c303df5c5', 48, 'gap_fill', 'B1', 'adjectives_order', 'She bought a ___ (beautiful / red / Italian) dress.', 'beautiful red Italian', NULL, NULL, NULL, NULL, 'Opinion, size, age, shape, color, origin, material', 'Adjective order: opinion → color → origin.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adjective}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ec635975-47a2-4d11-a7dc-1376e1e5b3e1', 1150, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a form of transport?', 'ladder', '["bus", "train", "bicycle", "ladder"]', NULL, NULL, NULL, NULL, 'A ladder is a piece of equipment used for climbing, not a form of transport. The others — bus, train, and bicycle — are all used to travel from place to place.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('388b9e98-f72f-47a4-939f-04489813e160', 1155, 'odd_one_out', 'B1', 'vocabulary', 'Which of these is NOT a planet in our solar system?', 'Pluto', '["Mercury", "Venus", "Pluto", "Mars"]', NULL, NULL, NULL, NULL, 'Pluto was reclassified as a dwarf planet by the International Astronomical Union in 2006. Mercury, Venus, and Mars are all recognised planets in our solar system.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f48b3ae4-5ddf-4eb4-ba26-73b71cf66399', 1157, 'odd_one_out', 'B1', 'grammar', 'Which of these words does NOT introduce a contrast?', 'therefore', '["however", "although", "therefore", "whereas"]', NULL, NULL, NULL, NULL, '"Therefore" introduces a result or conclusion, not a contrast. However, although, and whereas are all used to show contrast between two ideas.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('225e9d37-342e-4747-bd0b-2e7c8c24e20d', 1158, 'odd_one_out', 'B2', 'vocabulary', 'Which of these words does NOT mean to think carefully about something?', 'demand', '["consider", "reflect", "ponder", "demand"]', NULL, NULL, NULL, NULL, '"Demand" means to ask for something forcefully. Consider, reflect, and ponder all mean to think carefully or deeply about something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('845e4f00-bb26-4dc9-a9fa-3608838ad675', 1159, 'odd_one_out', 'B1', 'idioms', 'Which of these idioms does NOT mean to avoid or delay something?', 'face the music', '["beat around the bush", "drag your feet", "sit on the fence", "face the music"]', NULL, NULL, NULL, NULL, '"Face the music" means to accept the consequences of your actions. The others — beat around the bush, drag your feet, and sit on the fence — all suggest avoiding or delaying something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70ea8ce3-51c0-4fd4-9a88-bae43925cb29', 1160, 'odd_one_out', 'B2', 'vocabulary', 'Which of these phrasal verbs does NOT mean to cancel something?', 'bring up', '["call off", "back out of", "fall through", "bring up"]', NULL, NULL, NULL, NULL, '"Bring up" means to mention or raise a topic in conversation. Call off, back out of, and fall through all relate to cancelling or not going ahead with something.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5107c6bc-dbdd-4e1b-8360-734a872836d4', 1161, 'odd_one_out', 'B1', 'vocabulary', 'Which of these words is NOT connected to travel?', 'invoice', '["itinerary", "departure", "invoice", "destination"]', NULL, NULL, NULL, NULL, 'An invoice is a financial document, not connected to travel. Itinerary, departure, and destination are all words commonly used when talking about travel.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b4081e41-5eb6-4a8f-ab2c-ac14f7662183', 1162, 'odd_one_out', 'B2', 'grammar', 'Which of these words is NOT used to introduce a relative clause?', 'although', '["who", "which", "whose", "although"]', NULL, NULL, NULL, NULL, '"Although" is a subordinating conjunction used to introduce contrast, not a relative pronoun. Who, which, and whose are all relative pronouns used to introduce relative clauses.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('93cac49e-4433-4e29-b407-529882d9a7ee', 1148, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT a day of the week?', 'January', '["Monday", "Wednesday", "weekend", "Sunday"]', NULL, NULL, NULL, NULL, 'The weekend is a little group, not a day of the week. The seven individual days are Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, and Sunday.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b4af6227-3dfc-4ed8-b59f-e5fa884b9fca', 1149, 'odd_one_out', 'A2', 'idioms', 'Which of these expressions does NOT mean something is easy?', 'hit the sack', '["a piece of cake", "a walk in the park", "hit the sack", "plain sailing"]', NULL, NULL, NULL, NULL, '"Hit the sack" means to go to bed. The other expressions all describe something easy: "a piece of cake", "a walk in the park", and "plain sailing".', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('664caedf-0e3b-4190-bb42-a2ff199422f3', 1151, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT part of the face?', 'knee', '["nose", "eye", "neck", "mouth"]', NULL, NULL, NULL, NULL, 'The neck is what joins the head to the body, not part of the face. The nose, eye, and mouth are all parts of the face.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eb73ab87-1a6c-409f-beca-b94aebcc53c7', 1152, 'odd_one_out', 'A2', 'grammar', 'Which of these verb forms is NOT in the past simple?', 'running', '["walked", "played", "run", "stopped"]', NULL, NULL, NULL, NULL, '"Run" is the present and past participle (third column), not the past simple. Walked, played, and stopped are all past simple forms.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('039867ee-5806-4f35-965f-26025d2782cf', 1154, 'odd_one_out', 'A2', 'grammar', 'Which of these words does NOT show where something is?', 'because', '["under", "behind", "despite", "next to"]', NULL, NULL, NULL, NULL, '"Despite" shows relationship, not location. Under, behind, and next to are all prepositions of place that tell you where something is.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('840cd94e-84c4-4a82-9439-49d1d33d34f4', 1156, 'odd_one_out', 'B1', 'vocabulary', 'Which of these words does NOT mean happy?', 'nervous', '["cheerful", "content", "elated", "nervous"]', NULL, NULL, NULL, NULL, '"Nervous" means worried or anxious — the opposite of happy. Cheerful, content, and elated all describe positive emotional states.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fa5c91a4-f6ed-4d5c-b1e6-c6500cc2fd7b', 1163, 'odd_one_out', 'B2', 'vocabulary', 'Which of these is NOT a play by Shakespeare?', 'Sherlock Holmes', '["Hamlet", "Macbeth", "Othello", "Oliver Twist"]', NULL, NULL, NULL, NULL, 'Oliver Twist is a famous novel by Charles Dickens, not Shakespeare. Hamlet, Macbeth, and Othello are all plays written by William Shakespeare.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d2503dc-83a3-47d3-aff7-511207ba22e1', 1164, 'odd_one_out', 'B1', 'vocabulary', 'Which of these adjectives does NOT describe a positive personality trait?', 'grumpy', '["generous", "patient", "grumpy", "reliable"]', NULL, NULL, NULL, NULL, '"Grumpy" describes someone who is always unhappy and vocal about it,  generally considered a negative trait. Generous, patient, and reliable are all positive personality characteristics.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('27da9be5-d179-4f79-8d6a-88abb6ecf007', 125, 'multiple_choice', 'B1', 'too_enough', 'This coffee is ___ hot. I can''t drink it yet.', 'too', '["so", "enough", "very", "too"]', NULL, NULL, NULL, NULL, 'Too means more than necessary or wanted.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Too & enough"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c9de56a-5d18-4a83-a9c5-73be5fee7db4', 1165, 'odd_one_out', 'C1', 'vocabulary', 'Which of these is NOT a logical fallacy?', 'Occam''s razor', '["ad hominem", "straw man", "Occam''s razor", "false dichotomy"]', NULL, NULL, NULL, NULL, 'Occam''s razor is a philosophical principle stating that the simplest explanation is usually correct — not a logical fallacy. Ad hominem, straw man, and false dichotomy are all recognised logical fallacies.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e6a27f68-f146-4b5c-ab3f-72913e049a69', 1166, 'odd_one_out', 'C1', 'vocabulary', 'Which of these words does NOT describe a gradual decline?', 'escalate', '["deteriorate", "erode", "wane", "escalate"]', NULL, NULL, NULL, NULL, '"Escalate" means to increase or intensify, the opposite of decline. Deteriorate, erode, and wane all describe a gradual weakening or reduction.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a26dc4c3-e4d6-4b77-a9df-a7d0c94cb0aa', 1167, 'odd_one_out', 'C1', 'vocabulary', 'Which of these adjectives does NOT suggest ambiguity or uncertainty?', 'categorical', '["ambivalent", "equivocal", "tentative", "categorical"]', NULL, NULL, NULL, NULL, '"Categorical" means absolute and unconditional — leaving no room for doubt. Ambivalent, equivocal, and tentative all suggest uncertainty or a lack of clear commitment.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('815fd8c4-8460-4699-9c32-4edeec73d026', 512, 'multiple_choice', 'C2', 'advanced_phrasal_verbs', 'Don''t ___ the importance of regular exercise.', 'play down', '["play up", "play down", "play out", "play off"]', NULL, NULL, NULL, NULL, 'Play down = minimise the importance of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f080553b-55e8-4f60-8e74-82fbb4d640c4', 1169, 'odd_one_out', 'C1', 'idioms', 'Which of these expressions does NOT suggest that someone is being evasive?', 'an open book', '["beating around the bush", "economising with the truth", "an open book", "sitting on the fence"]', NULL, NULL, NULL, NULL, '"An open book" describes someone who is transparent and easy to understand — not evasive. Beating around the bush, economising with the truth, and sitting on the fence all suggest a reluctance to be direct.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c69761d-179d-4321-a358-0eb0228882b1', 1170, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT relate to contradiction or opposition?', 'axiom', '["paradox", "oxymoron", "dichotomy", "axiom"]', NULL, NULL, NULL, NULL, 'An axiom is a self-evident truth or established principle — not a contradiction. Paradox, oxymoron, and dichotomy all involve some form of contradiction or opposition.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f576bfc9-6d3d-4c8b-9206-5c3d9005bb37', 1171, 'odd_one_out', 'C1', 'vocabulary', 'Which of these verbs does NOT mean to make something worse?', 'mitigate', '["exacerbate", "aggravate", "mitigate", "compound"]', NULL, NULL, NULL, NULL, '"Mitigate" means to reduce or lessen the severity of something. Exacerbate, aggravate, and compound all mean to make a situation worse.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('796b97b7-e5a2-421a-9c1f-6b774a2e807c', 1173, 'odd_one_out', 'C1', 'vocabulary', 'Which of these words does NOT describe someone who talks too much?', 'taciturn', '["garrulous", "loquacious", "taciturn", "verbose"]', NULL, NULL, NULL, NULL, '"Taciturn" describes someone who is habitually quiet and says very little. Garrulous, loquacious, and verbose all describe someone who talks a great deal.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f8c73fa2-b423-46ad-838a-f7402dc64c7f', 1174, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT describe a feeling of unease?', 'equanimity', '["disquiet", "trepidation", "malaise", "equanimity"]', NULL, NULL, NULL, NULL, '"Equanimity" means calm composure and acceptance, especially in difficult situations. Disquiet, trepidation, and malaise all describe feelings of unease, anxiety, or general discomfort.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ee2f70b-6e8b-4030-97a3-4fc4aaa16292', 1175, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un insecto?', 'araña', '["hormiga", "mariposa", "araña", "abeja"]', NULL, NULL, NULL, NULL, 'La araña es un arácnido, no un insecto. Los insectos tienen seis patas y tres partes en el cuerpo. Las arañas tienen ocho patas y dos partes.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b17515b9-2650-4b31-b6b0-0b7baf0486a7', 1176, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es una fruta?', 'zanahoria', '["manzana", "plátano", "zanahoria", "mango"]', NULL, NULL, NULL, NULL, 'La zanahoria es una verdura, no una fruta. Las frutas se desarrollan a partir de la flor de una planta y contienen semillas. La zanahoria es una raíz.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db583fc1-c74d-423e-8e2c-fd687698cfc8', 1177, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas palabras NO es un verbo?', 'rápido', '["hablar", "correr", "rápido", "comer"]', NULL, NULL, NULL, NULL, '"Rápido" es un adjetivo, no un verbo. Hablar, correr y comer son todos verbos en infinitivo.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ad654977-3a0e-45b8-83a3-73a6aa3a4433', 1178, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estos NO es un color primario en pintura?', 'verde', '["rojo", "azul", "verde", "amarillo"]', NULL, NULL, NULL, NULL, 'El verde no es un color primario en pintura. Los colores primarios en el modelo tradicional de pintura son el rojo, el azul y el amarillo. El verde se forma mezclando azul y amarillo.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('840ae3ac-7574-4273-a2db-83f85e26d5d1', 1179, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas expresiones NO significa tener buena suerte?', 'tener mala pata', '["estar en racha", "caer de pie", "tener mala pata", "tocar la lotería"]', NULL, NULL, NULL, NULL, '"Tener mala pata" significa tener mala suerte, lo contrario de las demás expresiones. Estar en racha, caer de pie y tocar la lotería significan tener buena suerte o fortuna.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa13526d-b6b5-4445-b8a2-f1d503c427ae', 1180, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estos NO es un animal doméstico?', 'tigre', '["perro", "gato", "conejo", "tigre"]', NULL, NULL, NULL, NULL, 'El tigre es un animal salvaje, no doméstico. El perro, el gato y el conejo son animales que viven habitualmente con personas en casa.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06c28cef-8038-4368-b6a0-86f8f7c040f5', 1181, 'odd_one_out', 'A2', 'spanish', '¿Cuál de estas ciudades NO es la capital de un país hispanohablante?', 'Barcelona', '["Buenos Aires", "Lima", "Barcelona", "Bogotá"]', NULL, NULL, NULL, NULL, 'Barcelona no es la capital de ningún país hispanohablante — es la segunda ciudad más grande de España, cuya capital es Madrid. Buenos Aires, Lima y Bogotá son todas capitales nacionales.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cf793052-5f8d-4cc9-af3e-0cdcd5bee8c9', 1168, 'odd_one_out', 'C2', 'vocabulary', 'Which of these words does NOT mean to criticise someone strongly?', 'extol', '["lambast", "castigate", "censure", "extol"]', NULL, NULL, NULL, NULL, '"Extol" means to praise someone enthusiastically. Lambast, castigate, and censure all mean to criticise or condemn someone strongly.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d99f9a3e-956d-49fc-9fa3-47bb831a4bb6', 1172, 'odd_one_out', 'C2', 'vocabulary', 'Which of these authors did NOT win the Nobel Prize in Literature?', 'Stephen King', '["Gabriel García Márquez", "Toni Morrison", "Stephen King", "Albert Camus"]', NULL, NULL, NULL, NULL, 'Stephen King has not won the Nobel Prize in Literature. Gabriel García Márquez (1982), Toni Morrison (1993), and Albert Camus (1957) are all Nobel laureates.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e0d551f1-4dfc-4343-8a2d-6d68236920ef', 1208, 'sentence_building', 'C1', 'routines', 'Establecer un horario de sueño constante tiene beneficios a largo plazo para la salud mental.', 'Establishing a consistent sleep schedule has long-term benefits for mental health.', '["establishing", "a", "consistent", "sleep", "schedule", "has", "long-term", "benefits", "for", "mental", "health", "establish", "regular", "improve", "physical"]', NULL, NULL, NULL, NULL, 'A gerund (Establishing) functions as the subject of this sentence. Long-term benefits are those that persist into the future.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90261efb-87aa-47f5-b9c3-677a4ed61a9f', 159, 'multiple_choice', 'B2', 'causative_make', 'My boss made me ___ late yesterday.', 'work', '["to work", "working", "worked", "work"]', NULL, NULL, NULL, NULL, 'Make + object + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e218ccea-1c09-4fd6-b938-902ec13adcef', 143, 'multiple_choice', 'B1', 'adverbs_manner', 'She speaks English very ___.', 'well', '["good", "well", "nice", "better"]', NULL, NULL, NULL, NULL, 'Well is the adverb form of good.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('43c63d6b-a9fe-42f9-95d6-2f8b347fac44', 160, 'multiple_choice', 'B1', 'frequency_adverbs', 'I ___ eat breakfast. I''m never hungry in the morning.', 'hardly ever', '["always", "usually", "sometimes", "hardly ever"]', NULL, NULL, NULL, NULL, 'Hardly ever means almost never.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1ac1c8e5-8cfd-42ac-895f-4112b2fb18af', 1266, 'error_correction', 'A1', 'grammar', 'My sister have a cat.', 'My sister has a cat.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (he/she/it) uses has, not have, in the present simple.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9c452bf4-93d2-46a9-911d-d6788b970a85', 1268, 'error_correction', 'A1', 'grammar', 'There is twenty students in the class.', 'There are twenty students in the class.', '[]', NULL, NULL, NULL, NULL, 'Use there are with plural nouns. Twenty students is plural, so are is required.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7dfac322-16ea-4ab5-88e2-3a56a511bd37', 565, 'multiple_choice', 'C2', 'advanced_grammar', '___ should you attempt to repair this equipment yourself.', 'Under no circumstances', '["No wonder", "Under no circumstances", "By no means only", "In no time"]', NULL, NULL, NULL, NULL, 'Under no circumstances + inversion = you must never do this.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f6a8e8fa-9ce4-43ca-977d-babf3865538f', 1270, 'error_correction', 'A1', 'grammar', 'I am boring in this lesson.', 'I am bored in this lesson.', '[]', NULL, NULL, NULL, NULL, 'Bored describes how a person feels. Boring describes what causes the feeling. The student is bored, not boring.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('43348126-85c9-438b-a7e9-99b66513b9cb', 1271, 'error_correction', 'A2', 'routines', 'We go to the gym in Saturdays.', 'We go to the gym on Saturdays.', '[]', NULL, NULL, NULL, NULL, 'Use on with days of the week: on Monday, on Saturdays. In is used for months, seasons, and parts of the day.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5ef42ef-a1bd-4338-befb-6d85bae86d22', 1272, 'error_correction', 'A1', 'grammar', 'She have got two brothers.', 'She has got two brothers.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (she) requires has got, not have got.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0d1270aa-eb3f-4db0-9fde-1ec73440cbb5', 1274, 'error_correction', 'A1', 'grammar', 'He don''t understand the question.', 'He doesn''t understand the question.', '[]', NULL, NULL, NULL, NULL, 'In the third person singular (he/she/it), the negative form is doesn''t, not don''t.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3fbec3b2-eb3c-4631-8eb7-55a80daa15e0', 566, 'multiple_choice', 'C1', 'advanced_grammar', 'Strange ___ it may seem, he actually enjoys public speaking.', 'as', '["so", "that", "if", "as"]', NULL, NULL, NULL, NULL, 'Strange as it may seem = although it seems strange. Concessive clause.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d8d042d9-7b01-48c6-87dc-919a9f49cf86', 1275, 'error_correction', 'B1', 'routines', 'I am used to get up early for my job.', 'I am used to getting up early for my job.', '[]', NULL, NULL, NULL, NULL, 'Be used to expresses familiarity and is followed by a gerund (-ing). The to here is a preposition, not part of an infinitive marker.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e092893-b549-41a5-85c1-4d570547c1ed', 1277, 'error_correction', 'B1', 'routines', 'I have been following this routine since three months.', 'I have been following this routine for three months.', '[]', NULL, NULL, NULL, NULL, 'Use for with a period of time (for three months) and since with a specific point in time (since January).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bfe3c7c1-f4d6-4584-8d48-094c8497896d', 568, 'multiple_choice', 'C2', 'advanced_grammar', 'Little ___ she know what was about to happen.', 'did', '["had", "did", "would", "was"]', NULL, NULL, NULL, NULL, 'Little did + subject + know: inversion for emphasis on lack of knowledge.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b7e7f4f2-ae0e-4151-a562-b22ae1b5cfa3', 548, 'multiple_choice', 'C1', 'confusing_words', 'The ___ of the new policy remains to be seen.', 'effect', '["affect", "effective", "effect", "affection"]', NULL, NULL, NULL, NULL, 'Effect (noun) = result, impact. Affect (verb) = influence.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c7579a0e-88b6-4af7-b0b5-ad4f486bad3c', 1280, 'error_correction', 'B2', 'grammar', 'The news are very concerning today.', 'The news is very concerning today.', '[]', NULL, NULL, NULL, NULL, 'News is an uncountable noun and always takes a singular verb, even though it ends in -s.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('919a83f9-1622-4023-b27b-55d97d7fa16c', 1273, 'error_correction', 'A2', 'routines', 'He rarely eats breakfast he just goes at work.', 'He rarely eats breakfast he just goes to work.', '[]', NULL, NULL, NULL, NULL, 'The correct expression is go to work. At work means you are already there; to work indicates movement towards it.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cd46e1a5-fbbb-4b40-8b71-49c3386225b8', 1265, 'error_correction', 'A1', 'routines', 'I usually going to bed at ten o''clock.', 'I usually go to bed at ten o''clock.', '[]', NULL, NULL, NULL, NULL, 'Present simple for routines, wit hwords like usually and never etc. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c94019d4-8597-4bd3-9a05-785c97ae5529', 1269, 'error_correction', 'A2', 'routines', 'I always have lunch on the same time.', 'I always have lunch at the same time.', '[]', NULL, NULL, NULL, NULL, 'We use at with the same time, we can say ''on time'' meaning when we are supoosed to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1063a24b-f09c-4e22-b535-1f872a78c4b1', 1267, 'error_correction', 'A2', 'routines', 'She wake up early every day for work.', 'She wakes up early every day for work.', '[]', NULL, NULL, NULL, NULL, 'The present simple, not the present continuous, is used for regular habits and routines. Remember the third person S!', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6e9e407a-fe25-4e97-922b-3d8a3a6c51a5', 1276, 'error_correction', 'B2', 'grammar', 'He suggested taking one different route.', 'He suggested taking a different route.', '[]', NULL, NULL, NULL, NULL, 'It''s more natural to use ''a'' than ''one'' in most contexts for native speakers.
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b4ea8a90-2711-49db-a32d-8bb3a600a210', 1279, 'error_correction', 'B1', 'routines', 'I wish I would fall asleep more easily at night.', 'I wish I could fall asleep more easily at night.', '[]', NULL, NULL, NULL, NULL, 'After I wish, use the past simple for a present wish. In thois case of the verb ''can''. Would in wish clauses is only used to express a desire about someone else''s behaviour.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('138c9da4-240d-43c5-bba0-cd287e2b6553', 1281, 'error_correction', 'B1', 'routines', 'It is worth plan your week in advance.', 'It is worth planning your week in advance.', '[]', NULL, NULL, NULL, NULL, 'Worth is followed by a gerund (-ing), never the infinitive. Other examples: worth trying, worth considering, worth remembering.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5097ef53-542d-445c-a9f9-f6c307645491', 1282, 'error_correction', 'B2', 'grammar', 'He is the taller player on the team.', 'He is the tallest player on the team.', '[]', NULL, NULL, NULL, NULL, 'One-syllable adjectives form the superlative with the -est, not with most. The here indicates a superlative form, not a comparative.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c5ab2cc7-69bf-4d21-8cfd-68183748ba89', 1278, 'error_correction', 'B2', 'grammar', 'Despite the bad whether, we enjoyed the trip.', 'Despite the bad weather, we enjoyed the trip.', '[]', NULL, NULL, NULL, NULL, 'Weather and whether sound the same, but at this level we need to know which is which. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dcebfc63-a0f7-4451-9a10-4cc7b91b46b4', 571, 'multiple_choice', 'C2', 'advanced_grammar', 'Not only ___ the film win Best Picture, but it also swept every other category.', 'did', '["was", "has", "did", "had"]', NULL, NULL, NULL, NULL, 'Not only + auxiliary + subject + verb: inversion for emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a4a2df8e-9b9c-4447-aa65-2e6b18fd4a6a', 178, 'multiple_choice', 'B2', 'causative_get', 'I must get my bike ___.', 'repaired', '["repair", "repaired", "repairing", "to repair"]', NULL, NULL, NULL, NULL, 'Get + object + past participle (causative).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('15caf229-2a35-4b61-82b3-c563bead638d', 576, 'multiple_choice', 'C1', 'advanced_grammar', 'Barely ___ she sat down when the phone rang.', 'had', '["was", "did", "has", "had"]', NULL, NULL, NULL, NULL, 'Barely had + subject + past participle + when: inversion showing two quick events.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1bb879c1-ced4-4c6f-9539-41eb85548032', 195, 'multiple_choice', 'B1', 'too_adjective', 'I''m ___ tired to go out tonight.', 'too', '["a lot of", "too", "so", "enough"]', NULL, NULL, NULL, NULL, 'Too + adjective + to (more than wanted/needed).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Too & enough"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('17ca038d-b73c-4771-ac19-c2f0a117e0d7', 199, 'multiple_choice', 'B1', 'possessive_s', 'That''s ___ car.', 'John''s', '["John", "Johns", "John''s", "Johns''"]', NULL, NULL, NULL, NULL, 'Apostrophe + s for possession.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Possessive}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('12e65558-37e8-4e20-b9c5-963481e8efd3', 171, 'multiple_choice', 'B1', 'time_expressions', 'I haven''t seen her ___ last week.', 'since', '["for", "since", "ago", "from"]', NULL, NULL, NULL, NULL, 'Since with a point in time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Time expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ba90a2ff-3e2a-44f5-8623-4071483ff49c', 181, 'multiple_choice', 'B1', 'prepositions_by', 'The report must be finished ___ Friday.', 'by', '["until", "by", "on", "at"]', NULL, NULL, NULL, NULL, 'By for deadlines (not later than).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Preposition}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d049c0c-7947-40e6-880f-29a306251e0a', 1285, 'error_correction', 'C1', 'routines', 'She has accustomed herself to wake up without an alarm.', 'She has accustomed herself to waking up without an alarm.', '[]', NULL, NULL, NULL, NULL, 'Accustom oneself to is followed by a gerund. The to is a preposition here, as in be used to, look forward to, and object to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3d0148c4-dc35-47cd-aab3-838ba4bebde7', 1286, 'error_correction', 'C2', 'grammar', 'He took great pride of his punctuality.', 'He took great pride in his punctuality.', '[]', NULL, NULL, NULL, NULL, 'The correct collocation is take pride in. Compare: pride in one''s work, take pride in doing something well.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b2fd085e-dcbe-477b-987b-8aea8f6d44a2', 1287, 'error_correction', 'C1', 'routines', 'Not having a routine can result to feeling disoriented.', 'Not having a routine can result in feeling disoriented.', '[]', NULL, NULL, NULL, NULL, 'Result in is the correct collocation. Result to does not exist. Compare: result in confusion, result in failure.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a6231c15-6b81-4362-8a6f-21fc2e8f13a1', 1290, 'error_correction', 'C2', 'grammar', 'The report had a profound affect on government policy.', 'The report had a profound effect on government policy.', '[]', NULL, NULL, NULL, NULL, 'Effect is the noun meaning result or impact. Affect is typically a verb. The correct collocation is have an effect on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fea2de56-fa18-4a61-bf73-0273548f974f', 1292, 'error_correction', 'C2', 'grammar', 'She is widely known of her expertise in the field.', 'She is widely known for her expertise in the field.', '[]', NULL, NULL, NULL, NULL, 'Known for is the correct collocation. Compare: famous for, celebrated for, recognised for. Known of means you have heard of someone but don''t know them well.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b630060f-5001-40f5-804d-a8614dbe2452', 1293, 'error_correction', 'C1', 'routines', 'The key to maintain good habits is starting small and being consistent.', 'The key to maintaining good habits is starting small and being consistent.', '[]', NULL, NULL, NULL, NULL, 'When to functions as a preposition (not an infinitive marker), it is followed by a gerund. Compare: be used to, look forward to, the secret to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2a4cbe5d-d118-4fb5-bfc7-85d9cc297173', 1294, 'error_correction', 'C2', 'grammar', 'He spoke to the audience with great eloquency.', 'He spoke to the audience with great eloquence.', '[]', NULL, NULL, NULL, NULL, 'The correct noun form is eloquence. The suffix -ency is not used here — compare: eloquence, resilience, patience.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e526e381-f3e7-495d-b0cb-7d99350458b0', 1283, 'error_correction', 'B1', 'routines', 'I keep forgetting to taking my vitamins every morning.', 'I keep forgetting to take my vitamins every morning.', '[]', NULL, NULL, NULL, NULL, 'Forget + to + infinitive. Forget to do something means to fail to remember to do it. Forget doing something refers to not remembering a past event — a completely different meaning.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3dd78060-f577-4ea0-ab4a-29cafe26db8a', 1284, 'error_correction', 'B2', 'grammar', 'If I known the answer, I would tell you.', 'If I knew the answer, I would tell you.', '[]', NULL, NULL, NULL, NULL, 'In second conditional sentences, the if clause uses the past simple, not the past participle. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5156a5a2-8c73-4126-a00c-d75a366f0ac2', 582, 'multiple_choice', 'C1', 'nuance', 'The proposal was ___ rejected by the committee.', 'unanimously', '["anonymously", "spontaneously", "simultaneously", "unanimously"]', NULL, NULL, NULL, NULL, 'Unanimously = with complete agreement from everyone.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{"Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b52d5ac4-8a2b-4f11-8bc6-5a3430b54f9f', 1288, 'error_correction', 'C2', 'grammar', 'She refrained for commenting on the allegations.', 'She refrained from commenting on the allegations.', '[]', NULL, NULL, NULL, NULL, 'Refrain from is the correct collocation, followed by a gerund. Compare: abstain from, desist from, shy away from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dae1a16d-992a-4676-b181-710dc775b743', 1289, 'error_correction', 'C1', 'routines', 'The extent at which daily habits shape our behaviour is often overlooked.', 'The extent to which daily habits shape our behaviour is often overlooked.', '[]', NULL, NULL, NULL, NULL, 'The correct phrase is the extent to which. This is a fixed relative clause structure — to which, not at which.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b8bd6f3b-ec57-4b41-bb58-8bbb8db9d581', 1291, 'error_correction', 'C1', 'routines', 'Blocking off time in your diary for rest is rarely a waste of it.', 'Blocking out time in your diary for rest is rarely a waste of it.', '[]', NULL, NULL, NULL, NULL, 'Block out time is the correct phrasal verb, meaning to deliberately reserve a period in your schedule. Block time  off is not a standard expression.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2cc058e5-fab3-430f-ada5-8db0c62ec69b', 1295, 'error_correction', 'A2', 'spanish', 'Me gusta levantarme pronto para las mañanas.', 'Me gusta levantarme pronto por las mañanas.', '[]', NULL, NULL, NULL, NULL, 'La expresión correcta es "por las mañanas". Por se usa con partes del día: por la mañana, por la tarde, por la noche.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f3745ee4-98ad-46b9-98c8-93e84ad954d6', 341, 'multiple_choice', 'A1', 'daily_routines', 'I ___ up at 7 o''clock every morning.', 'get', '["back", "get", "stand", "go"]', NULL, NULL, NULL, NULL, 'Get up = leave your bed in the morning. Also: wake up.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4707e90b-474a-4967-a04f-754a6ba5f8ec', 342, 'multiple_choice', 'A1', 'daily_routines', 'I ___ a shower before breakfast.', 'have', '["make", "do", "have", "go"]', NULL, NULL, NULL, NULL, 'Have a shower / have a bath. British English usage.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ad027481-c1fa-4010-a779-cad280252782', 343, 'multiple_choice', 'A1', 'daily_routines', 'She ___ to work by train.', 'goes', '["has", "goes", "go", "does"]', NULL, NULL, NULL, NULL, 'Go to work = travel to your workplace.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ab2400f0-90b4-45e5-8bbd-0524dfed2246', 344, 'multiple_choice', 'A1', 'daily_routines', 'I ___ lunch at 1 pm.', 'have', '["do", "go", "have", "take"]', NULL, NULL, NULL, NULL, 'Have lunch / have dinner / have breakfast.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d7e20a9a-2094-4322-ae3a-e35993b42d24', 345, 'multiple_choice', 'A2', 'daily_routines', 'He ___ the housework at the weekend.', 'does', '["makes", "does", "has", "goes"]', NULL, NULL, NULL, NULL, 'Do the housework / do the washing / do the ironing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c24bce20-99bf-4d4a-ba37-553317236958', 346, 'multiple_choice', 'A1', 'daily_routines', 'I ___ my teeth twice a day.', 'brush', '["wash", "clean", "brush", "do"]', NULL, NULL, NULL, NULL, 'Brush your teeth = clean with a toothbrush.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2a838220-7418-42a6-b193-dc675c15501f', 347, 'multiple_choice', 'A1', 'daily_routines', 'She ___ dressed and goes to school.', 'gets', '["makes", "puts", "does", "gets"]', NULL, NULL, NULL, NULL, 'Get dressed = put on your clothes.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9b47f0eb-946e-4d2e-948e-588e63927801', 348, 'multiple_choice', 'A2', 'daily_routines', 'I usually ___ to bed at 11 pm.', 'go', '["sleep", "go", "have", "make"]', NULL, NULL, NULL, NULL, 'Go to bed = go to sleep for the night.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ad9ce188-288e-4a4d-84bd-d71b62af9d6f', 350, 'multiple_choice', 'A2', 'daily_routines', 'He ___ his homework after dinner.', 'does', '["makes", "does", "has", "gets"]', NULL, NULL, NULL, NULL, 'Do homework / do exercise / do your best.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d2a4590-126c-4a0c-897e-f012fa0c182d', 351, 'multiple_choice', 'A1', 'food_and_drink', 'Can I have a ___ of water, please?', 'glass', '["cup", "glass", "plate", "dish"]', NULL, NULL, NULL, NULL, 'A glass of water / a glass of wine / a glass of juice.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('732be982-c924-44c0-926d-15e677802575', 352, 'multiple_choice', 'A1', 'food_and_drink', 'I''d like a ___ of coffee.', 'cup', '["glass", "plate", "cup", "bottle"]', NULL, NULL, NULL, NULL, 'A cup of coffee / a cup of tea.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('50cea5dc-52be-4b12-849d-2db50edfd600', 353, 'multiple_choice', 'A1', 'food_and_drink', 'Would you like ___ sugar in your tea?', 'some', '["a", "an", "some", "a lot"]', NULL, NULL, NULL, NULL, 'Some with uncountable nouns in offers: Would you like some...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a4045bf1-71da-4787-88b8-612213e86b2e', 355, 'multiple_choice', 'A1', 'food_and_drink', 'There isn''t ___ milk in the fridge.', 'any', '["some", "any", "a", "many"]', NULL, NULL, NULL, NULL, 'Any in negatives: There isn''t any + uncountable noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cce1b16b-778a-4c2b-b4f3-b27d76293df9', 356, 'multiple_choice', 'A2', 'food_and_drink', 'How ___ eggs do we need?', 'many', '["much", "many", "some", "any"]', NULL, NULL, NULL, NULL, 'How many + countable plural noun (eggs are countable).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ba2882df-f415-4026-946f-36abc7f08b17', 357, 'multiple_choice', 'A2', 'food_and_drink', 'How ___ sugar do you want?', 'much', '["any", "many", "some", "much"]', NULL, NULL, NULL, NULL, 'How much + uncountable noun (sugar is uncountable).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bd04acef-a694-4abe-af40-dddbb328fbcf', 358, 'multiple_choice', 'A1', 'food_and_drink', 'I''m hungry. I want ___ to eat.', 'something', '["anything", "something", "nothing", "everything"]', NULL, NULL, NULL, NULL, 'Something in positive statements: I want something.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c7226fae-5b36-4ea4-bc49-f2e942be4a58', 1296, 'error_correction', 'A2', 'spanish', 'Ella es muy simpático con todo el mundo.', 'Ella es muy simpática con todo el mundo.', '[]', NULL, NULL, NULL, NULL, 'Los adjetivos en español deben concordar en género con el sustantivo. Ella es femenino, así que el adjetivo debe ser simpática, no simpático.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0472d717-82cc-49b9-a66e-b9a30e51e275', 1298, 'error_correction', 'A2', 'spanish', 'Me gustan mucho el café por las mañanas.', 'Me gusta mucho el café por las mañanas.', '[]', NULL, NULL, NULL, NULL, 'Con el verbo gustar, el verbo concuerda con lo que gusta. El café es singular, así que el verbo debe ser gusta, no gustan.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9773949c-01e4-4b11-a2f7-6f23f23a7adf', 1297, 'error_correction', 'A2', 'spanish', 'Siempre desayuno a las ocho de lo mañana.', 'Siempre desayuno a las ocho de la mañana.', '[]', NULL, NULL, NULL, NULL, 'La expresión correcta es "de la mañana". El artículo la es necesario: de la mañana, de la tarde, de la noche.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('513cf21c-cc1d-4b98-893e-69ef8101b23a', 1299, 'error_correction', 'A2', 'spanish', 'Normalmente voy al gimnasio las lunes.', 'Normalmente voy al gimnasio los lunes.', '[]', NULL, NULL, NULL, NULL, 'Para indicar un día de la semana de forma habitual, se usa el artículo los sin preposición: los lunes, los viernes. ', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d4aa8201-5fd6-4f53-abc8-cb015d84c4cd', 1300, 'error_correction', 'A2', 'spanish', 'Soy muy cansado hoy porque no dormí bien.', 'Estoy muy cansado hoy porque no dormí bien.', '[]', NULL, NULL, NULL, NULL, 'Estar se usa para estados temporales como el cansancio. Ser se usa para características permanentes. El cansancio es temporal, así que estoy cansado es correcto.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2c995fd3-e763-4df9-a355-ed00f0765e3b', 1301, 'error_correction', 'A2', 'spanish', 'Me cepillo los dientes antes de ir a duermo.', 'Me cepillo los dientes antes de ir a dormir.', '[]', NULL, NULL, NULL, NULL, 'Ir a + infinitivo es la estructura correcta. Antes de ir a dormir significa before going to sleep. Sin la preposición a, la frase es incorrecta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d83ad210-5bad-4f84-85a8-bc7a46fe4285', 1303, 'error_correction', 'A2', 'spanish', 'Intento acostar temprano los días entre semana.', 'Intento acostarme temprano los días entre semana.', '[]', NULL, NULL, NULL, NULL, 'Acostarse es un verbo reflexivo. Cuando se usa como infinitivo, el pronombre reflexivo debe concordar con el sujeto: me (yo), te (tú), se (él/ella).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ec652c12-cca9-4766-bf08-9428f49bad79', 1302, 'error_correction', 'A2', 'spanish', 'Mi hermana tiene veintycinco años.', 'Mi hermana tiene veinticinco años.', '[]', NULL, NULL, NULL, NULL, 'Los números del 21 al 29 se escriben en una sola palabra en español usando i: veintiuno, veintidós, veintitrés... veinticinco. No se separan. Desde 30 en adelante lo normal es escribirlos en varias palabras: treinta y uno, cincuenta y siete.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2fdb1a60-2ed1-408e-a172-50cd61913478', 1304, 'error_correction', 'A2', 'spanish', 'Ayer fuimos al restaurante y comemos pizza y pasta.', 'Ayer fuimos al restaurante y comimos pizza y pasta.', '[]', NULL, NULL, NULL, NULL, 'Ayer indica pasado, así que el verbo debe estar en pretérito indefinido (comimos), no en presente (comemos). Todos los verbos en la oración deben concordar en tiempo.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('379519a5-e739-4d7a-af95-4be9d55fd780', 1209, 'sentence_building', 'C2', 'routines', 'Sin darnos cuenta, desarrollamos rituales que nos anclan a una sensación de normalidad.', 'Without realising it, we develop rituals that anchor us to a sense of normality.', '["without", "realising", "it", "we", "develop", "rituals", "that", "anchor", "us", "to", "a", "sense", "of", "normality", "routine", "stability", "knowing"]', NULL, NULL, NULL, NULL, 'Without realising it is a participial phrase describing an unconscious process. Note British spelling: realising, not realizing.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aff4ea8f-c0f7-48e3-94d8-2ee4182034f2', 381, 'multiple_choice', 'A1', 'plurals', 'I have two ___.', 'children', '["child", "childs", "children", "childrens"]', NULL, NULL, NULL, NULL, 'Child → children (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('390fbb0c-549d-48a5-87c5-671a650a2d29', 384, 'multiple_choice', 'A2', 'plurals', 'There are a lot of ___ in this city.', 'people', '["person", "persons", "people", "peoples"]', NULL, NULL, NULL, NULL, 'Person → people (the most common plural form).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6386a847-9b17-440d-9d1a-7594e6d7c094', 385, 'multiple_choice', 'A1', 'plurals', 'Two ___ of wine, please.', 'glasses', '["glass", "glasses", "glasss", "cups"]', NULL, NULL, NULL, NULL, 'Nouns ending in -ss: add -es. Glass → glasses.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b8ceade6-1b40-4967-9b69-ed258b35dd1d', 390, 'multiple_choice', 'A1', 'plurals', 'There are lots of ___ in the park.', 'women', '["woman", "womans", "women", "womens"]', NULL, NULL, NULL, NULL, 'Woman → women (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('93f54376-761a-4100-9fcc-b4f8147d7d5f', 395, 'multiple_choice', 'A2', 'adverbs_of_frequency', 'She ___ goes to the gym. She goes every day.', 'always', '["never", "sometimes", "always", "rarely"]', NULL, NULL, NULL, NULL, 'Always = 100% of the time. She goes every day = always.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82c5d2c5-73d7-4b56-b7f7-845d30a3aca8', 396, 'multiple_choice', 'A2', 'adverbs_of_frequency', 'I ___ eat fish. I don''t like it.', 'never', '["always", "usually", "sometimes", "never"]', NULL, NULL, NULL, NULL, 'Never = 0% of the time. I don''t like it = I never eat it.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9c3a459e-b683-44fc-afe9-ae26ff096417', 392, 'multiple_choice', 'A2', 'like_and_would_like', 'I ___ a coffee, please.', 'would like', '["like", "would like", "am liking", "liked"]', NULL, NULL, NULL, NULL, 'Would like = polite way to say want. For ordering/requesting.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('981bfd38-277c-4dcb-86b4-e98e1d7160d8', 393, 'multiple_choice', 'A1', 'to_be', 'They ___ at school today.', 'are', '["is", "am", "are", "be"]', NULL, NULL, NULL, NULL, 'To be: I am, you/we/they are, he/she/it is.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"To be"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e9327070-4701-408e-bfbe-a8eedefb5c80', 394, 'multiple_choice', 'A1', 'to_be', 'I ___ 25 years old.', 'am', '["have", "am", "has", "is"]', NULL, NULL, NULL, NULL, 'In English we say: I am 25 (not I have 25).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"To be"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ccf2d918-2d06-49c5-b995-47f6dfedcc00', 359, 'multiple_choice', 'A2', 'food_and_drink', 'There are ___ oranges in the bowl.', 'a few', '["a", "any", "much", "a few"]', NULL, NULL, NULL, NULL, 'A few + countable plural = a small number (positive meaning).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5122f5c8-c89a-4c08-9c6b-6f2cde047368', 360, 'multiple_choice', 'A1', 'food_and_drink', 'She doesn''t eat ___ meat.', 'any', '["some", "any", "a", "many"]', NULL, NULL, NULL, NULL, 'Any in negative sentences: She doesn''t eat any meat.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8dc575c9-9a4b-4c80-abc9-ee6a1cc47191', 1305, 'sentence_auction', 'A1', 'routines', 'Daily routines', 'auction', '[{"correct": true, "sentence": "I wake up at seven o''clock every morning.", "explanation": "Correct. Present simple is used for regular daily habits."}, {"correct": false, "sentence": "She is going to the gym every Monday.", "explanation": "Incorrect. The present continuous is not used for regular habits. It should be: she goes to the gym every Monday."}, {"correct": true, "sentence": "We have dinner at nine o''clock every evening.", "explanation": "Correct. Have dinner in the present simple is the right form for a daily routine."}, {"correct": false, "sentence": "He don''t drink coffee in the morning.", "explanation": "Incorrect. Third person singular requires doesn''t, not don''t."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('afb7cac0-af75-40c9-a92f-45a5435429a4', 1306, 'sentence_auction', 'A1', 'grammar', 'Present simple', 'auction', '[{"correct": true, "sentence": "There are twenty students in my class.", "explanation": "Correct. There are is used with plural nouns."}, {"correct": false, "sentence": "She have got a new job.", "explanation": "Incorrect. Third person singular requires has got, not have got."}, {"correct": true, "sentence": "I like swimming in the sea.", "explanation": "Correct. Like + gerund (-ing) is a standard structure."}, {"correct": false, "sentence": "The children is playing in the garden.", "explanation": "Incorrect. Children is plural and requires are, not is."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b2753753-2966-409a-b7bb-9b379769f6fb', 1307, 'sentence_auction', 'A2', 'routines', 'Frequency adverbs', 'auction', '[{"correct": true, "sentence": "I usually go for a walk after lunch.", "explanation": "Correct. Usually goes before the main verb."}, {"correct": false, "sentence": "She always is late for work on Mondays.", "explanation": "Incorrect. Frequency adverbs go after the verb to be, not before it. It should be: she is always late."}, {"correct": true, "sentence": "They go to bed early on weekdays.", "explanation": "Correct. On weekdays is the right preposition expression for regular days."}, {"correct": false, "sentence": "I am brushing my teeth twice a day.", "explanation": "Incorrect. Regular habits use the present simple, not the present continuous."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('59bf5a17-f5c7-4832-9f65-b1acd26604fd', 575, 'multiple_choice', 'C1', 'advanced_grammar', 'She insisted that he ___ present at the meeting.', 'be', '["is", "being", "was", "be"]', NULL, NULL, NULL, NULL, 'Subjunctive after insist: base form of verb (no -s, no past tense).', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('63454b0a-7201-4235-a284-114f994889b4', 140, 'multiple_choice', 'B2', 'have_something_done', 'I need to ___ my hair ___.', 'have / cut', '["have / to cut", "make / cut", "cut / have", "have / cut"]', NULL, NULL, NULL, NULL, 'Have + object + past participle (causative structure).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('14b4f106-4bf8-41ed-a15e-dfc459db4d46', 383, 'multiple_choice', 'A1', 'plurals', 'I brush my ___ twice a day.', 'teeth', '["tooth", "tooths", "teeth", "teeths"]', NULL, NULL, NULL, NULL, 'Tooth → teeth (irregular plural).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('43b94bb8-8831-40f9-941d-1cc94ef0d871', 391, 'multiple_choice', 'A2', 'like_and_would_like', 'I ___ pizza. It''s my favourite food.', 'like', '["liked", "would like", "am liking", "like"]', NULL, NULL, NULL, NULL, 'Like = enjoy in general (permanent). Would like = want now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Modal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5c41ac84-3654-4f6e-a91b-91538bd5eb6b', 169, 'multiple_choice', 'B1', 'suggestions_lets', 'Let''s ___ to the cinema tonight.', 'go', '["going", "went", "go", "to go"]', NULL, NULL, NULL, NULL, 'Let''s + infinitive without ''to''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Making suggestions"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ecde8e3d-cb69-458e-a24a-1b1bcc5e0b55', 399, 'multiple_choice', 'A1', 'basic_vocabulary', 'The opposite of "hot" is ___.', 'cold', '["warm", "cool", "cold", "big"]', NULL, NULL, NULL, NULL, 'Hot ↔ cold. These are basic opposite adjectives.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d61fca9b-e94d-473c-82c4-22199c900349', 400, 'multiple_choice', 'A1', 'basic_vocabulary', 'The opposite of "cheap" is ___.', 'expensive', '["small", "expensive", "free", "old"]', NULL, NULL, NULL, NULL, 'Cheap ↔ expensive. About the price of things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8c03979e-5642-4257-9402-c0c44993a30b', 354, 'multiple_choice', 'A2', 'food_and_drink', 'We need to buy a ___ of bread.', 'loaf', '["bag", "bottle", "loaf", "cup"]', NULL, NULL, NULL, NULL, 'A loaf of bread = the whole bread from the bakery.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('83a66d89-3c24-401d-8a7b-46f459db7f73', 1308, 'sentence_auction', 'A2', 'grammar', 'Common grammar', 'auction', '[{"correct": true, "sentence": "The news was very surprising yesterday.", "explanation": "Correct. News is uncountable and takes a singular verb."}, {"correct": true, "sentence": "I met a lot of interesting people at the party.", "explanation": "Correct. People is already plural — no -s needed."}, {"correct": false, "sentence": "She is more taller than her brother.", "explanation": "Incorrect. Never use more with a comparative adjective ending in -er. It should be: she is taller."}, {"correct": true, "sentence": "He told me about his new job last week.", "explanation": "Correct. Told is the past simple of tell, used correctly here."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f0e2eaac-f851-4b50-8b87-b7e68b233d70', 1309, 'sentence_auction', 'A1', 'routines', 'Home routines', 'auction', '[{"correct": true, "sentence": "My mother cooks dinner every evening.", "explanation": "Correct. Third person singular adds -s: cooks, not cook."}, {"correct": true, "sentence": "I always drink a glass of water when I wake up.", "explanation": "Correct. When I wake up is a correct time clause using the present simple."}, {"correct": false, "sentence": "He go to work by the bus every day.", "explanation": "Incorrect. Two errors: go should be goes (third person), and by the bus should be by bus — no article after by with transport."}, {"correct": false, "sentence": "We don''t never eat fast food during the week.", "explanation": "Incorrect. Double negatives are not used in standard English. Use either don''t or never, not both."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6cdc8f5b-275b-43bf-9bc7-efd3e33f5cbf', 1310, 'sentence_auction', 'A2', 'grammar', 'Articles and nouns', 'auction', '[{"correct": true, "sentence": "I need some advice about my new job.", "explanation": "Correct. Advice is uncountable and cannot be made plural."}, {"correct": false, "sentence": "She gave me an useful tip about the exercise.", "explanation": "Incorrect. Use a, not an, before words starting with a consonant sound. Useful starts with a /j/ sound, so it takes a."}, {"correct": true, "sentence": "There is a lot of traffic on the road this morning.", "explanation": "Correct. Traffic is uncountable and uses a lot of correctly."}, {"correct": false, "sentence": "Can you give me an information about the schedule?", "explanation": "Incorrect. Information is uncountable. You cannot say an information — use some information or a piece of information."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('44e11fa1-3977-4814-9bd5-b92ef0842580', 1311, 'sentence_auction', 'B1', 'routines', 'Habits and routines', 'auction', '[{"correct": true, "sentence": "She has been following the same morning routine for years.", "explanation": "Correct. The present perfect continuous describes an ongoing habit that started in the past."}, {"correct": false, "sentence": "I am used to wake up early since I started this job.", "explanation": "Incorrect. Be used to is followed by a gerund (-ing), not the infinitive. It should be: used to waking up."}, {"correct": true, "sentence": "Getting enough sleep has made a huge difference to my energy levels.", "explanation": "Correct. A gerund (Getting) as subject is grammatically correct, and the collocation is make a difference to."}, {"correct": false, "sentence": "It''s worth to establish a consistent bedtime.", "explanation": "Incorrect. Worth is followed by a gerund, not the infinitive. It should be: worth establishing."}, {"correct": true, "sentence": "Most people find it hard to change their daily habits.", "explanation": "Correct. Find it + adjective + to-infinitive is a standard structure."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d640a9c9-7209-4046-af1a-99d5b0320417', 638, 'sentence_building', 'A2', 'past_simple', '', 'I was born in Spain', '["I", "was", "born", "in", "spain", "am", "the"]', NULL, NULL, NULL, NULL, '''Was born'' is a fixed expression for talking about your birth. ''I was born in'' + place.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06cab03b-d1d4-40b5-bb76-b1146653522d', 650, 'sentence_building', 'A2', 'going_to_future', 'Qué vas a hacer este fin de semana?', 'what are you going to do this weekend', '["what", "are", "you", "going", "to", "do", "this", "weekend", "did", "last", "is"]', NULL, NULL, NULL, NULL, 'Going to future question: What + are + subject + going to + verb?', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'both', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1f391c23-e7a8-4e7a-b740-52b535a77826', 615, 'sentence_building', 'B1', 'future_plans', NULL, 'they are planning to launch a new product next month', '["they", "are", "planning", "to", "launch", "a", "new", "product", "next", "month", "old", "sell", "last"]', NULL, NULL, NULL, NULL, 'Present continuous for future arrangements. "Launch a product" is a standard business collocation.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('374a0a4c-955f-4bce-a241-f09d34d98cbf', 617, 'sentence_building', 'C1', 'future_perfect', NULL, 'the contract will have been signed by the end of the week', '["the", "contract", "will", "have", "been", "signed", "by", "the", "end", "of", "the", "week", "until", "signing", "after"]', NULL, NULL, NULL, NULL, 'Future perfect passive: will have been + past participle. "By the end of" marks the deadline.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a43725a9-f942-4b3b-9711-3a7aada0557b', 1248, 'gap_fill', 'C2', 'business_phrasal_verbs', 'After the restructuring, several middle management positions were _____ entirely.', 'phased out', '[]', NULL, NULL, NULL, NULL, 'Phase out means to gradually eliminate something over time. Compare: wind down, discontinue.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8b0d1e39-4a5e-427c-a44e-dea3c4548fd1', 1312, 'sentence_auction', 'B2', 'grammar', 'Verb patterns', 'auction', '[{"correct": true, "sentence": "He suggested going to a different restaurant.", "explanation": "Correct. Suggest is followed by a gerund (-ing)."}, {"correct": false, "sentence": "She denied to take the money.", "explanation": "Incorrect. Deny is followed by a gerund (-ing), not the infinitive. It should be: denied taking the money."}, {"correct": true, "sentence": "They managed to finish the project on time.", "explanation": "Correct. Manage is followed by the infinitive (to finish)."}, {"correct": true, "sentence": "I regret to inform you that your application was unsuccessful.", "explanation": "Correct. Regret + to-infinitive is used in formal contexts to introduce bad news."}, {"correct": false, "sentence": "He avoided to make eye contact during the interview.", "explanation": "Incorrect. Avoid is followed by a gerund (-ing). It should be: avoided making eye contact."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6813f0e7-16cb-4f43-8313-e7019b48fcc9', 1313, 'sentence_auction', 'B1', 'routines', 'Sleep and wellbeing', 'auction', '[{"correct": true, "sentence": "I tend to feel more focused after a good night''s sleep.", "explanation": "Correct. Tend to + infinitive describes a general tendency or habit."}, {"correct": false, "sentence": "Despite to have a regular bedtime, she often feels tired.", "explanation": "Incorrect. Despite is a preposition followed by a noun or gerund (-ing). It should be: despite having."}, {"correct": true, "sentence": "I wish I could fall asleep more easily at night.", "explanation": "Correct. Wish + could is used to express a desire about the present."}, {"correct": true, "sentence": "It has been shown that sleep deprivation affects both mood and performance.", "explanation": "Correct. The present perfect passive (has been shown) is appropriate for established research findings."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f04ee0c6-f599-4b36-883c-9e5b26650a39', 1314, 'sentence_auction', 'B2', 'grammar', 'Conditionals and wishes', 'auction', '[{"correct": true, "sentence": "If I had more free time, I would exercise more regularly.", "explanation": "Correct second conditional: past simple in the if clause, would + infinitive in the result clause."}, {"correct": false, "sentence": "If I would have known earlier, I would have prepared better.", "explanation": "Incorrect. In third conditional sentences, the if clause uses had + past participle, not would have. It should be: if I had known."}, {"correct": true, "sentence": "I wish I had taken better care of my health when I was younger.", "explanation": "Correct. Wish + past perfect is used to express regret about a past event."}, {"correct": false, "sentence": "Unless you will rest properly, your performance will suffer.", "explanation": "Incorrect. Unless introduces a conditional clause and uses the present simple, not will. It should be: unless you rest."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c8914ebc-1b08-477d-91e6-3f8703549a95', 1315, 'sentence_auction', 'B1', 'routines', 'Present perfect and habits', 'auction', '[{"correct": true, "sentence": "I have gradually cut down on the amount of coffee I drink.", "explanation": "Correct. The present perfect shows a recent change, and cut down on is the correct collocation."}, {"correct": false, "sentence": "She has been doing yoga since two years.", "explanation": "Incorrect. Use for with a period of time: for two years. Since is used with a specific point in time."}, {"correct": true, "sentence": "Lately I have been trying to go to bed before midnight.", "explanation": "Correct. Lately refers to a recent ongoing period, so the present perfect continuous is required."}, {"correct": true, "sentence": "He has recently started to follow a healthier routine.", "explanation": "Correct. Recently with the present perfect is natural and standard."}, {"correct": true, "sentence": "She used to take the bus but now she cycles to work.", "explanation": "Correct. Used to describes a past habit that no longer happens."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('81944569-3813-4fb3-a1e1-14dbd4437d48', 1316, 'sentence_auction', 'C1', 'routines', 'Routine and discipline', 'auction', '[{"correct": true, "sentence": "Establishing a consistent sleep schedule has long-term benefits for mental health.", "explanation": "Correct. A gerund (Establishing) as subject is grammatically correct and natural."}, {"correct": true, "sentence": "She has made mindfulness a non-negotiable part of her daily routine.", "explanation": "Correct. Make + object + noun phrase (SVOC) correctly expresses transformation."}, {"correct": false, "sentence": "Such is the extent of his self-discipline that he rarely deviates of his schedule.", "explanation": "Incorrect. The correct collocation is deviate from, not deviate of. Compare: depart from, differ from."}, {"correct": true, "sentence": "The key to maintaining a healthy routine lies in making gradual adjustments.", "explanation": "Correct. The key to + gerund is the standard structure. Lies in is the correct collocation."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e9d1a76a-ba53-411e-9739-edb7001cf2b4', 1317, 'sentence_auction', 'C2', 'grammar', 'Advanced grammar', 'auction', '[{"correct": true, "sentence": "Were it not for her meticulous planning, the project would have failed.", "explanation": "Correct. Were it not for is a formal inversion structure used in place of if it were not for."}, {"correct": true, "sentence": "Hardly had she sat down when the phone rang.", "explanation": "Correct. Hardly had + subject + past participle is a standard inversion structure with when."}, {"correct": false, "sentence": "Not only he failed the exam, but he also missed the deadline.", "explanation": "Incorrect. After negative adverbials like not only, subject-verb inversion is required: Not only did he fail the exam."}, {"correct": true, "sentence": "The extent to which habits shape identity is often underestimated.", "explanation": "Correct. The extent to which is a sophisticated structure introducing a degree or measure."}, {"correct": true, "sentence": "Seldom does she deviate from her morning routine, regardless of circumstance.", "explanation": "Correct. Seldom triggers inversion (does she), which is correct formal usage."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9fd599cf-3074-409f-b4c2-dbe56f46bee3', 1318, 'sentence_auction', 'C1', 'routines', 'Wellbeing and habits', 'auction', '[{"correct": true, "sentence": "Research suggests that structured routines are linked to higher levels of wellbeing.", "explanation": "Correct. Research as a general concept takes a singular verb, and linked to describes correlation correctly."}, {"correct": true, "sentence": "Procrastination is often a symptom of deeper anxiety rather than laziness.", "explanation": "Correct. Rather than is used to contrast two ideas, suggesting the first is more accurate."}, {"correct": true, "sentence": "Without realising it, we often develop rituals that anchor us to a sense of normality.", "explanation": "Correct. Without realising it is a participial phrase. Note British spelling: realising."}, {"correct": false, "sentence": "Daily exercise has a proven affect on both mood and concentration.", "explanation": "Incorrect. Effect is the noun meaning result or impact. Affect is typically a verb. The collocation is have an effect on."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('96d61db5-a4b5-49b2-90f2-6a90eafda183', 1249, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The two rival firms decided to _____ and form a joint venture.', 'team up', '[]', NULL, NULL, NULL, NULL, 'Team up means to join together with another person or organisation for a shared purpose. Compare: partner with, collaborate with.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7488dc08-60e5-46fd-a385-d4cef0a63a40', 1319, 'sentence_auction', 'C2', 'grammar', 'Precision and register', 'auction', '[{"correct": true, "sentence": "He is widely regarded as one of the most innovative thinkers of his generation.", "explanation": "Correct. Regarded as is the correct collocation in formal English."}, {"correct": false, "sentence": "The findings are consistent to previous research in this area.", "explanation": "Incorrect. The correct collocation is consistent with, not consistent to."}, {"correct": true, "sentence": "Her tenacity in the face of adversity is truly commendable.", "explanation": "Correct. In the face of is a fixed prepositional phrase meaning despite. Tenacity and commendable are used at the appropriate register."}, {"correct": true, "sentence": "The committee reached a consensus on the proposed changes.", "explanation": "Correct. Reach a consensus is the standard collocation. On introduces what the consensus is about."}, {"correct": false, "sentence": "She is renowned of her ability to remain calm under pressure.", "explanation": "Incorrect. Renowned for is the correct collocation. Compare: famous for, known for, celebrated for."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be64af7c-6737-4b5a-9c47-4c9b0ea2deac', 1320, 'sentence_auction', 'C1', 'routines', 'Habits and psychology', 'auction', '[{"correct": true, "sentence": "Habits formed early in childhood are often remarkably resistant to change.", "explanation": "Correct. Formed is a past participle acting as a reduced relative clause. Resistant to is the correct collocation."}, {"correct": true, "sentence": "She has been making a conscious effort to wind down before bed.", "explanation": "Correct. The present perfect continuous describes an ongoing intentional effort. Wind down means to relax gradually."}, {"correct": true, "sentence": "Getting into a good routine is particularly important for those who tend to procrastinate.", "explanation": "Correct. Get into the habit/routine of is a natural expression. Tend to describes a habitual characteristic."}, {"correct": false, "sentence": "The more you practice a habit, the most automatic it becomes.", "explanation": "Incorrect. In the the more... the more structure, both parts use comparative forms. It should be: the more automatic it becomes."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f48e8094-4930-4a21-b6d4-48e8cca20e8c', 1321, 'sentence_auction', 'A2', 'spanish', 'Rutinas diarias', 'auction', '[{"correct": true, "sentence": "Me levanto a las siete de la mañana todos los días.", "explanation": "Correcto. El presente de indicativo se usa para expresar hábitos y rutinas."}, {"correct": false, "sentence": "Estoy desayunando siempre antes de ir al trabajo.", "explanation": "Incorrecto. El presente continuo no se usa para hábitos regulares en español. Lo correcto es: siempre desayuno antes de ir al trabajo."}, {"correct": true, "sentence": "Normalmente me ducho por la mañana y me visto rápidamente.", "explanation": "Correcto. Por la mañana es la expresión correcta para indicar el momento del día."}, {"correct": true, "sentence": "Ella siempre llega tarde al trabajo porque no le gusta madrugar.", "explanation": "Correcto. El adverbio siempre va antes del verbo principal en español."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('45608e64-3f36-4bfa-94c3-9cc3faa9b9fe', 1322, 'sentence_auction', 'A2', 'spanish', 'Descripciones', 'auction', '[{"correct": true, "sentence": "Mi hermano es muy trabajador y siempre llega puntual a sus citas.", "explanation": "Correcto. Trabajador y puntual son adjetivos masculinos que concuerdan con mi hermano."}, {"correct": true, "sentence": "Esta mañana estoy muy cansada porque dormí mal.", "explanation": "Correcto. Estar se usa para estados temporales como el cansancio."}, {"correct": false, "sentence": "Soy muy nervioso hoy porque tengo una entrevista de trabajo.", "explanation": "Incorrecto. El nerviosismo de hoy es temporal, así que se usa estoy nervioso, no soy nervioso."}, {"correct": true, "sentence": "Me gustan mucho las películas de terror pero mis amigos no las soportan.", "explanation": "Correcto. El verbo gustar concuerda con las películas (plural), y no las soportan es correcto."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a81eb46c-1412-4645-ac31-0b29d3d92d86', 1323, 'sentence_auction', 'A2', 'spanish', 'Tiempo libre y ocio', 'auction', '[{"correct": true, "sentence": "Los fines de semana me gusta salir a caminar por el parque.", "explanation": "Correcto. Me gusta + infinitivo es la estructura estándar para expresar gustos."}, {"correct": true, "sentence": "¿A qué hora quedamos mañana para tomar algo?", "explanation": "Correcto. Quedar con alguien es la expresión española para to meet up."}, {"correct": false, "sentence": "Ayer fuimos al cine y nos divertamos mucho.", "explanation": "Incorrecto. El pretérito indefinido de divertirse es nos divertimos, no nos divertamos."}, {"correct": true, "sentence": "Normalmente paso los domingos con mi familia en casa.", "explanation": "Correcto. Pasar el tiempo con alguien es la expresión correcta."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('88cdf5d4-3a7a-4410-a3d0-780e6c890015', 1324, 'sentence_auction', 'A2', 'spanish', 'El trabajo y los estudios', 'auction', '[{"correct": true, "sentence": "Llevo tres años trabajando en la misma empresa.", "explanation": "Correcto. Llevar + gerundio es la estructura española para expresar una acción que empezó en el pasado y continúa."}, {"correct": false, "sentence": "Estudio español desde dos años.", "explanation": "Incorrecto. Con llevar o hace + que, se usa la estructura correcta. También se puede decir: llevo dos años estudiando español."}, {"correct": true, "sentence": "Trabajo de lunes a viernes y los sábados descanso.", "explanation": "Correcto. De lunes a viernes es la expresión estándar para indicar días laborables."}, {"correct": true, "sentence": "Ayer tuve una reunión muy importante con mis clientes.", "explanation": "Correcto. Tuve es el pretérito indefinido de tener, usado correctamente para hablar del pasado."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53d12e02-7f57-43e7-b736-44efdeea5f42', 567, 'multiple_choice', 'C1', 'advanced_grammar', 'The more you practise, the ___ you''ll become.', 'better', '["best", "better", "good", "well"]', NULL, NULL, NULL, NULL, 'The more...the more/better: double comparative structure.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9856c627-8a97-483b-a2a0-a2d62e057c01', 569, 'multiple_choice', 'C1', 'advanced_grammar', 'She acted as ___ nothing had happened.', 'if', '["when", "though", "while", "if"]', NULL, NULL, NULL, NULL, 'As if / as though + past perfect for unreal past comparisons.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('32788bab-2546-4f32-9b3f-18b3db6be4ba', 572, 'multiple_choice', 'C1', 'advanced_grammar', 'It''s high time we ___ about our future.', 'thought', '["thinking", "think", "to think", "thought"]', NULL, NULL, NULL, NULL, 'It''s high time + past simple: it should have happened already.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a6397f3c-3dab-4192-ac8b-a4803dbc0a65', 578, 'multiple_choice', 'C1', 'advanced_grammar', 'On no ___ should this door be left unlocked.', 'account', '["occasion", "terms", "account", "condition"]', NULL, NULL, NULL, NULL, 'On no account = under no circumstances. Emphatic negative.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f9b2d1e5-e159-4bd7-94c3-85980de522fe', 579, 'multiple_choice', 'C2', 'advanced_grammar', 'So ___ was the damage that the building had to be demolished.', 'extensive', '["extent", "extending", "extensive", "extended"]', NULL, NULL, NULL, NULL, 'So + adjective + was + subject + that: inverted structure for emphasis.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b7756bf6-1abd-499f-a5c7-5455bdb110b1', 580, 'multiple_choice', 'C1', 'advanced_grammar', 'He left without so much ___ saying goodbye.', 'as', '["than", "as", "like", "that"]', NULL, NULL, NULL, NULL, 'Without so much as + gerund = without even doing something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5d5b2c1a-c554-439f-b26f-02ec788cdb6a', 55, 'gap_fill', 'B1', 'adverbs_frequency', 'I ___ (_ _ _ _ _ _) drink coffee in the morning.', 'always', NULL, NULL, NULL, NULL, 'Adverbs of frequency come before the main verb', 'Adverbs of frequency are placed before the main verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('84fd2792-de82-4c97-a666-dd0df921bbef', 56, 'gap_fill', 'B1', 'adverbs_frequency', 'She is ___ (_ _ _ _ _) late for class.', 'never', NULL, NULL, NULL, NULL, 'Adverbs of frequency come after ''be''', 'With the verb ''be'', adverbs of frequency come after it.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Adverb}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('939a2c72-4e3b-42a2-82a0-1826846935e3', 1325, 'sentence_auction', 'A2', 'spanish', 'Hábitos y salud', 'auction', '[{"correct": true, "sentence": "Intento comer sano y hacer ejercicio al menos tres veces a la semana.", "explanation": "Correcto. Intentar + infinitivo y al menos son expresiones estándar."}, {"correct": false, "sentence": "Me acuesto muy tarde los noches del fin de semana.", "explanation": "Incorrecto. Noches es femenino plural, así que el artículo debe ser las noches, no los noches."}, {"correct": true, "sentence": "Bebo mucha agua durante el día porque sé que es importante para la salud.", "explanation": "Correcto. Durante el día es la expresión correcta para throughout the day."}, {"correct": true, "sentence": "Antes de acostarme siempre leo un poco para relajarme.", "explanation": "Correcto. Antes de + infinitivo es la estructura correcta. Los verbos reflexivos están bien conjugados."}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c8d8dde5-d57b-4694-8cac-fae29cd2ac96', 1326, 'matching', 'A1', 'routines', 'Match each action to the time of day when it usually happens.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "wake up"}, "right": {"type": "text", "label": "", "content": "in the morning"}}, {"left": {"type": "text", "label": "", "content": "have lunch"}, "right": {"type": "text", "label": "", "content": "at midday"}}, {"left": {"type": "text", "label": "", "content": "watch TV"}, "right": {"type": "text", "label": "", "content": "in the evening"}}, {"left": {"type": "text", "label": "", "content": "go to bed"}, "right": {"type": "text", "label": "", "content": "at night"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aecde125-d14d-45cc-88b7-8523e45e6788', 1327, 'matching', 'A2', 'vocabulary', 'Match each verb to its opposite.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "wake up"}, "right": {"type": "text", "label": "", "content": "fall asleep"}}, {"left": {"type": "text", "label": "", "content": "arrive"}, "right": {"type": "text", "label": "", "content": "leave"}}, {"left": {"type": "text", "label": "", "content": "start"}, "right": {"type": "text", "label": "", "content": "finish"}}, {"left": {"type": "text", "label": "", "content": "remember"}, "right": {"type": "text", "label": "", "content": "forget"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d229d26-e388-4369-bb8c-c4272939d2d6', 1328, 'matching', 'A1', 'vocabulary', 'Match each adjective to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "tired"}, "right": {"type": "text", "label": "", "content": "needing rest or sleep"}}, {"left": {"type": "text", "label": "", "content": "hungry"}, "right": {"type": "text", "label": "", "content": "wanting food"}}, {"left": {"type": "text", "label": "", "content": "bored"}, "right": {"type": "text", "label": "", "content": "not interested or entertained"}}, {"left": {"type": "text", "label": "", "content": "busy"}, "right": {"type": "text", "label": "", "content": "having a lot to do"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c858d933-05f3-4410-9ea9-efaa23c8a2fc', 1329, 'matching', 'A2', 'routines', 'Match each expression to its meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "on weekdays"}, "right": {"type": "text", "label": "", "content": "Monday to Friday"}}, {"left": {"type": "text", "label": "", "content": "at the weekend"}, "right": {"type": "text", "label": "", "content": "Saturday and Sunday"}}, {"left": {"type": "text", "label": "", "content": "once a week"}, "right": {"type": "text", "label": "", "content": "one time every seven days"}}, {"left": {"type": "text", "label": "", "content": "every other day"}, "right": {"type": "text", "label": "", "content": "on alternate days"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ebc361fa-446b-4376-b26e-ca61ae10757a', 1330, 'matching', 'A2', 'vocabulary', 'Match each verb with the noun it most commonly goes with.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "make"}, "right": {"type": "text", "label": "", "content": "a mistake"}}, {"left": {"type": "text", "label": "", "content": "do"}, "right": {"type": "text", "label": "", "content": "the housework"}}, {"left": {"type": "text", "label": "", "content": "have"}, "right": {"type": "text", "label": "", "content": "a shower"}}, {"left": {"type": "text", "label": "", "content": "take"}, "right": {"type": "text", "label": "", "content": "a photo"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('983227c4-0e68-4f88-9014-cc8a264f16de', 1210, 'sentence_building', 'C1', 'routines', 'La procrastinación suele ser un síntoma de una ansiedad más profunda que de pereza.', 'Procrastination is often a symptom of deeper anxiety rather than laziness.', '["procrastination", "is", "often", "a", "symptom", "of", "deeper", "anxiety", "rather", "than", "laziness", "usually", "instead", "sign", "profound"]', NULL, NULL, NULL, NULL, 'Rather than contrasts two ideas, suggesting the first is more accurate or likely. A symptom of implies a deeper underlying cause.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d175094c-3ee6-490d-8ee2-c6e912070a61', 1104, 'gap_fill', 'B2', 'business_vocabulary', 'The company''s strategy is built around cost _______ — making the same product at a lower cost than any competitor.', 'leadership', NULL, NULL, NULL, NULL, NULL, 'Cost leadership is a competitive strategy based on being the lowest-cost producer in the market. The company can then undercut competitors on price while maintaining profitability.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f19e204-2b25-4beb-839c-3930ba22571c', 1218, 'sentence_building', 'A2', 'spanish', 'He never eats breakfast at home.', 'él nunca desayuna en casa.', '["él", "nunca", "desayuna", "en", "casa", "come", "siempre", "trabajo", "fuera"]', NULL, NULL, NULL, NULL, 'Nunca means never. En casa means at home — no article is needed in this fixed expression.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fcc8437f-b7b4-4e6c-a4a1-ffa91d12d114', 1105, 'gap_fill', 'B2', 'business_vocabulary', 'In tough economic conditions, customer _______ is far cheaper than acquiring new ones.', 'retention', NULL, NULL, NULL, NULL, NULL, 'Customer retention means keeping existing customers and encouraging them to return. Acquiring a new customer typically costs five to seven times more than retaining an existing one.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fb2c39ae-e955-49b5-844f-7cc2b4adff8c', 1106, 'gap_fill', 'B2', 'business_vocabulary', 'A _______ analysis is a detailed calculation of whether a project will earn more money than it costs.', 'cost-benefit', NULL, NULL, NULL, '["cost benefit"]', NULL, 'A cost-benefit analysis calculates whether the financial benefits of a project outweigh its costs. It is a standard tool for evaluating investment decisions.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('331abdd0-7510-4ca8-83ef-d6c419be97ac', 279, 'gap_fill', 'A1', 'there_is_there_are', '___ a supermarket near my house.', 'There is', NULL, NULL, NULL, NULL, NULL, 'There is + singular noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"There is/are"}');
