INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('739f0e03-9bcc-4448-972a-427f2690b782', 297, 'gap_fill', 'A1', 'have_got', 'She ___ (h... got) blue eyes.', 'has got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, NULL, 'He/she/it has got for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e25b911d-8433-4341-973b-15e3f82c0e31', 299, 'gap_fill', 'A1', 'have_got', 'He ___ (not h... got) a car.', 'hasn''t got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, NULL, 'Negative: hasn''t got / haven''t got.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('93538c69-1cb4-4043-825b-c2c84272b86e', 300, 'gap_fill', 'A1', 'have_got', 'We ___ (not h... got) any homework today.', 'haven''t got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, NULL, 'Haven''t got = don''t have.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}');
