INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4787aff6-d8d3-48ca-a15b-c209811fa5f6', 1341, 'matching', 'B2', 'routines', 'Match each gerund phrase to what it describes.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "pulling an all-nighter"}, "right": {"type": "text", "label": "", "content": "staying awake all night to work or study"}}, {"left": {"type": "text", "label": "", "content": "hitting snooze"}, "right": {"type": "text", "label": "", "content": "delaying waking up by dismissing an alarm"}}, {"left": {"type": "text", "label": "", "content": "meal prepping"}, "right": {"type": "text", "label": "", "content": "preparing food in advance for the week"}}, {"left": {"type": "text", "label": "", "content": "power napping"}, "right": {"type": "text", "label": "", "content": "sleeping briefly during the day to restore energy"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b40c1812-f588-4965-b730-8ac87bb2670e', 1211, 'sentence_building', 'C2', 'routines', 'Las investigaciones sugieren que las rutinas estructuradas están relacionadas con mayores niveles de bienestar.', 'Research suggests that structured routines are linked to higher levels of wellbeing.', '["research", "suggests", "that", "structured", "routines", "are", "linked", "to", "higher", "levels", "of", "wellbeing", "shows", "regular", "connected", "happiness"]', NULL, NULL, NULL, NULL, 'Linked to describes a correlation without implying direct causation. Research as a general concept takes a singular verb.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7f600ab-5e75-4f17-9499-8a6fddb74a3b', 1212, 'sentence_building', 'C1', 'routines', 'Reservar tiempo en tu agenda para el descanso y el ocio rara vez es una pérdida.', 'Blocking out time in your diary for rest and leisure is rarely a waste.', '["blocking", "out", "time", "in", "your", "diary", "for", "rest", "and", "leisure", "is", "rarely", "a", "waste", "schedule", "never", "valuable"]', NULL, NULL, NULL, NULL, 'Block out time means to deliberately reserve a period in your schedule. The gerund Blocking acts as the subject of the sentence.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('52d00ce8-ee78-438a-b163-40340cf14f24', 758, 'multiple_choice', 'B2', 'grammar', '"By the time she arrived at the station, the train ___."', 'had left', '["left", "has left", "had left", "was leaving"]', NULL, NULL, NULL, NULL, 'When one past action happens before another, the earlier action uses the past perfect (had + past participle). The train left first, then she arrived.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
