INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e90a7b12-8012-440e-854f-d8e8d88238da', 1360, 'matching', 'A2', 'spanish', 'Match each Spanish phrase to its English equivalent.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "tener sueño"}, "right": {"type": "text", "label": "", "content": "to be sleepy"}}, {"left": {"type": "text", "label": "", "content": "tener hambre"}, "right": {"type": "text", "label": "", "content": "to be hungry"}}, {"left": {"type": "text", "label": "", "content": "tener prisa"}, "right": {"type": "text", "label": "", "content": "to be in a hurry"}}, {"left": {"type": "text", "label": "", "content": "tener ganas de"}, "right": {"type": "text", "label": "", "content": "to feel like doing something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('280ae9cc-b8fa-4cb0-8517-456baca918c9', 1361, 'matching', 'A2', 'spanish', 'Match each Spanish word to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "el despertador"}, "right": {"type": "text", "label": "", "content": "alarm clock"}}, {"left": {"type": "text", "label": "", "content": "el horario"}, "right": {"type": "text", "label": "", "content": "schedule / timetable"}}, {"left": {"type": "text", "label": "", "content": "la costumbre"}, "right": {"type": "text", "label": "", "content": "habit / custom"}}, {"left": {"type": "text", "label": "", "content": "el rutina"}, "right": {"type": "text", "label": "", "content": "routine"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('369bff08-fe0b-47db-b7b1-343d85df01ad', 1362, 'matching', 'A2', 'spanish', 'Match the Spanish expression to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "quedarse dormido"}, "right": {"type": "text", "label": "", "content": "to fall asleep"}}, {"left": {"type": "text", "label": "", "content": "dar una cabezada"}, "right": {"type": "text", "label": "", "content": "to take a nap"}}, {"left": {"type": "text", "label": "", "content": "pegar ojo"}, "right": {"type": "text", "label": "", "content": "to sleep (often in negative: no pegar ojo)"}}, {"left": {"type": "text", "label": "", "content": "levantarse con el pie izquierdo"}, "right": {"type": "text", "label": "", "content": "to get out of bed on the wrong side"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('12202ff5-bdb1-42a0-bdea-3f3acebf8e3f', 1363, 'matching', 'A2', 'spanish', 'Match each Spanish verb to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "desayunar"}, "right": {"type": "text", "label": "", "content": "to have breakfast"}}, {"left": {"type": "text", "label": "", "content": "almorzar"}, "right": {"type": "text", "label": "", "content": "to have lunch"}}, {"left": {"type": "text", "label": "", "content": "merendar"}, "right": {"type": "text", "label": "", "content": "to have an afternoon snack"}}, {"left": {"type": "text", "label": "", "content": "cenar"}, "right": {"type": "text", "label": "", "content": "to have dinner"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('009fe9ab-ffb6-4f7d-af1b-7d558adb1bd6', 464, 'gap_fill', 'C1', 'advanced_vocabulary', 'The negotiations reached a ___ when neither side would compromise.', 'deadlock', NULL, NULL, NULL, NULL, NULL, 'Deadlock/stalemate/impasse = a situation where no progress can be made.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('32c91b37-f6c2-4ff7-a638-d4716a579688', 465, 'gap_fill', 'C1', 'advanced_vocabulary', 'Her speech was so ___ that everyone in the audience was moved.', 'compelling', NULL, NULL, NULL, NULL, NULL, 'Compelling/eloquent = powerfully persuasive or expressive.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('556f174f-d46d-4557-b895-9b244e1807d8', 466, 'gap_fill', 'C2', 'advanced_vocabulary', 'The report ___ the need for immediate action on climate change.', 'underscores', NULL, NULL, NULL, NULL, NULL, 'Underscore/underline/highlight = emphasise the importance of something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('acb7120a-99c6-4157-9c30-77606f2daabb', 467, 'gap_fill', 'C1', 'advanced_vocabulary', 'There has been a ___ increase in the cost of living.', 'substantial', NULL, NULL, NULL, NULL, NULL, 'Substantial/significant/considerable = large and important.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82a30b16-5a79-4200-a380-b8390b14e4f1', 1225, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The meeting has been _____ until next week.', 'put off', '["put off", "put on", "put in", "put up"]', NULL, NULL, NULL, NULL, 'Put off means to postpone or delay something. Compare: the meeting has been put off / rescheduled.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7325eba7-d865-47ed-ab39-b077506c4f76', 470, 'gap_fill', 'C1', 'advanced_vocabulary', 'They reached a ___ agreement after months of negotiations.', 'tentative', NULL, NULL, NULL, NULL, NULL, 'Tentative/preliminary = not final, subject to change.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('101ab3b8-dcd2-4858-b914-01ba1b994c0b', 472, 'gap_fill', 'C2', 'advanced_vocabulary', 'The author''s latest novel has received ___ critical acclaim.', 'widespread', NULL, NULL, NULL, NULL, NULL, 'Widespread/universal acclaim = praise from many critics.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a15a1c2b-7cd6-4485-92b7-3077bc4cc3c7', 473, 'gap_fill', 'C1', 'advanced_vocabulary', 'There is a growing ___ that the current system is unsustainable.', 'consensus', NULL, NULL, NULL, NULL, NULL, 'Consensus = general agreement among a group of people.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f1da8dce-1337-4ad9-be38-43635fa745f3', 474, 'gap_fill', 'C1', 'advanced_vocabulary', 'The policy has had far-___ consequences for the economy.', 'reaching', NULL, NULL, NULL, NULL, NULL, 'Far-reaching = having a wide and significant effect.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d8f5778-3c6f-440b-9435-1a0e5db549c4', 475, 'gap_fill', 'C2', 'advanced_vocabulary', 'The two accounts of the event are completely at ___ with each other.', 'odds', NULL, NULL, NULL, NULL, NULL, 'At odds with = in conflict or disagreement with.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cf84e4df-ac1b-45e0-bde3-85e0c15a120d', 476, 'gap_fill', 'C1', 'advanced_vocabulary', 'The findings ___ light on a previously unknown aspect of the disease.', 'shed', NULL, NULL, NULL, NULL, NULL, 'Shed/throw/cast light on = reveal new information about something.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f8a4cbea-0a91-4b0d-af94-306160983eea', 477, 'gap_fill', 'C1', 'advanced_vocabulary', 'The situation calls ___ immediate intervention.', 'for', NULL, NULL, NULL, NULL, NULL, 'Call for = require, demand. A formal expression.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dcb34959-45d7-4cf3-a731-f82cfc88bf42', 478, 'gap_fill', 'C2', 'advanced_vocabulary', 'She was ___ to the idea at first but eventually came round.', 'averse', NULL, NULL, NULL, NULL, NULL, 'Averse/opposed/resistant to = against something initially.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('12ab37a6-4895-4800-8650-3deab0389219', 471, 'gap_fill', 'C1', 'advanced_vocabulary', 'The government has pledged to ___ the root causes of poverty.', 'tackle', NULL, '["investigate"]', NULL, NULL, NULL, 'Tackle/address = deal with a problem seriously.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4948c3cf-9713-4963-99b6-cae9bd63a1c3', 688, 'error_correction', 'A2', 'adjectives', 'I am interesting in learning English.', 'I am interested in learning English.', '[]', NULL, NULL, NULL, NULL, 'We use "interested" (how you feel) not "interesting" (what something is like).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Adjective}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('df1b39c5-1de2-4bf6-b84e-234bfbfe44d2', 761, 'multiple_choice', 'B1', 'grammar', '"The new hospital ___ by the end of next year."', 'will be built', '["will build", "will be built", "is building", "builds"]', NULL, NULL, NULL, NULL, 'The hospital doesn''t build itself — it is built by someone. We need the passive: will be built.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d17a58b5-aca8-400b-afad-280637fcdff7', 762, 'multiple_choice', 'B1', 'grammar', '"Despite ___ for the interview, he didn''t get the job."', 'preparing', '["to prepare", "prepare", "prepared", "preparing"]', NULL, NULL, NULL, NULL, '"Despite" is always followed by a noun or gerund (-ing form). "Despite preparing" / "Despite his preparation" — never "despite to prepare".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d702b99c-e229-45ac-805c-0de668b47ef3', 770, 'multiple_choice', 'B1', 'academic writing', 'Which linking word shows contrast?', 'nevertheless', '["therefore", "consequently", "nevertheless", "furthermore"]', NULL, NULL, NULL, NULL, '"Nevertheless" means "despite this" or "even so" — it shows contrast. "Therefore" and "consequently" show result. "Furthermore" adds information.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fe998f6d-ab96-42bd-9c14-6881fd4362e2', 1369, 'multiple_choice', 'A1', 'prepositions', 'Your phone is _____ the bedside chest.', 'on', '["at", "in", "on", "under"]', NULL, NULL, NULL, NULL, 'On is used for surfaces. The phone is placed on the bedside chest.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3b9a1e2e-b189-45d2-8d21-af473f1529a3', 764, 'multiple_choice', 'B2', 'vocabulary', '"She is ___ to get the promotion — she seems far more qualified the other candidates."', 'bound', '["bound", "supposed", "probably", "due"]', NULL, NULL, NULL, NULL, '"Bound to" expresses strong certainty about the future — almost certain to happen. "Due to" suggests imminent timing, not certainty.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5322b9e5-f532-4e95-bd9b-f327f0391626', 1364, 'matching', 'A2', 'spanish', 'Match each Spanish time expression to its English equivalent.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "entre semana"}, "right": {"type": "text", "label": "", "content": "on weekdays"}}, {"left": {"type": "text", "label": "", "content": "el fin de semana"}, "right": {"type": "text", "label": "", "content": "at the weekend"}}, {"left": {"type": "text", "label": "", "content": "cada dos días"}, "right": {"type": "text", "label": "", "content": "every other day"}}, {"left": {"type": "text", "label": "", "content": "a diario"}, "right": {"type": "text", "label": "", "content": "every day / on a daily basis"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('80f9ab87-e406-4669-927b-eac4c50984c2', 1365, 'matching', 'A2', 'spanish', 'Match each Spanish adverb to its English meaning.', '["match_all_pairs"]', '[{"left": {"type": "text", "label": "", "content": "normalmente"}, "right": {"type": "text", "label": "", "content": "normally / usually"}}, {"left": {"type": "text", "label": "", "content": "a menudo"}, "right": {"type": "text", "label": "", "content": "often"}}, {"left": {"type": "text", "label": "", "content": "de vez en cuando"}, "right": {"type": "text", "label": "", "content": "from time to time"}}, {"left": {"type": "text", "label": "", "content": "casi nunca"}, "right": {"type": "text", "label": "", "content": "hardly ever"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8f07d5a4-df18-4ae0-b35f-cfeab493d047', 1366, 'multiple_choice', 'A1', 'prepositions', 'She wakes up _____ seven o''clock every morning.', 'at', '["at", "in", "on", "by"]', NULL, NULL, NULL, NULL, 'Use at with clock times: at seven o''clock, at midnight, at noon.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b3d68b06-2ff8-44e6-8358-f40987e5d108', 1367, 'multiple_choice', 'A1', 'prepositions', 'We always go to the beach _____ summer.', 'in', '["at", "in", "on", "during"]', NULL, NULL, NULL, NULL, 'Use in with seasons: in summer, in winter, in spring.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('64494c34-4c62-45af-b46a-ccaea48f870b', 1368, 'multiple_choice', 'A2', 'prepositions', 'I usually go to the gym _____ Mondays.', 'on', '["at", "in", "on", "by"]', NULL, NULL, NULL, NULL, 'Use on with specific days of the week: on Monday, on Fridays, on weekends.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8cad6ac2-5c72-46ff-8b60-52c51f6b47ba', 765, 'multiple_choice', 'B1', 'grammar', 'Which reported speech sentence is correct? He said: "I will call you tomorrow."', 'He said he would call me the next day.', '["He said he will call me tomorrow.", "He said he would call me the next day.", "He said he calls me the next day.", "He said he had called me tomorrow."]', NULL, NULL, NULL, NULL, 'In reported speech: "will" becomes "would", and "tomorrow" becomes "the next day" (since time shifts when we report later).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1d5530dc-18d2-4b52-b5d6-7967f665c535', 766, 'multiple_choice', 'B1', 'vocabulary', '"He spoke so quietly that I could ___ hear him."', 'barely', '["barely", "nearly", "slightly", "mostly"]', NULL, NULL, NULL, NULL, '"Barely" means almost not at all. "I could barely hear him" = I could hear him, but only just. Don''t confuse it with "nearly" (almost).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('da817ce9-85a4-41dc-bc3a-fcec490372b6', 767, 'multiple_choice', 'B1', 'grammar', '"If I ___ you, I would apologise immediately."', 'were', '["am", "was", "were", "had been"]', NULL, NULL, NULL, NULL, 'In the second conditional, we use "were" for all persons in formal English: "If I were you...", "If he were here...". Some speakers use "was" informally, but "were" is correct.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('149215e3-93b0-42cd-925e-26e1b0180ac7', 1370, 'multiple_choice', 'A2', 'prepositions', 'I''ll see you _____ Monday morning.', 'on', '["at", "in", "on", "by"]', NULL, NULL, NULL, NULL, 'Use on with specific days or parts of specific days: on Monday morning, on Friday afternoon.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c94e112-fdae-4e9c-afba-70309248abed', 771, 'multiple_choice', 'B2', 'grammar', '"You ___ told me earlier — I could have helped you!"', 'should have', '["should have", "must have", "would", "could"]', NULL, NULL, NULL, NULL, '"Should have + past participle" expresses criticism or regret about a past action. You had the opportunity to tell me, but you didn''t — and you should have.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('16a76d82-b869-49b6-b7bd-49a9611955ea', 772, 'multiple_choice', 'B2', 'grammar', '"The higher the temperature, ___ the bacteria grow."', 'the faster', '["the faster", "faster", "the fast", "more faster"]', NULL, NULL, NULL, NULL, '"The + comparative, the + comparative" is a fixed structure showing that two things increase or change together. The hotter it gets, the more you sweat!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('66df07b6-da3a-4726-8c62-ee57ad43377b', 773, 'multiple_choice', 'B1', 'vocabulary', 'Which word is a synonym for "reluctant"?', 'unwilling', '["unwilling", "unable", "unaware", "unusual"]', NULL, NULL, NULL, NULL, '"Reluctant" means not wanting to do something. A synonym is "unwilling". "Unable" means lacking the ability, not the desire.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f81b2532-d755-4d5c-87fa-1cc185689118', 775, 'multiple_choice', 'B2', 'money', 'Which word means "the money left after all costs have been paid"?', 'profit', '["profit", "revenue", "turnover", "budget"]', NULL, NULL, NULL, NULL, '"Profit" = income minus costs. "Revenue" = total income before costs. "Turnover" = total sales (similar to revenue). "Budget" = a plan for spending money.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6290d5f2-0f05-4cf3-91e0-2c844fd11928', 1371, 'multiple_choice', 'A2', 'prepositions', 'She lives _____ a small flat _____ the city centre.', 'in / in', '["in / in", "at / in", "on / at", "in / at"]', NULL, NULL, NULL, NULL, 'Live in is used for towns, cities, countries, and enclosed spaces like flats. City centre also uses in.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ab3d2aa7-c662-4845-ba17-897e945c1d66', 1372, 'multiple_choice', 'A1', 'prepositions', 'I go to work _____ bus every day.', 'by', '["by", "in", "on", "with"]', NULL, NULL, NULL, NULL, 'Use by with forms of transport when talking about how you travel: by bus, by train, by car.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61f900f2-5431-4b0a-b49d-c7c9d981e641', 779, 'multiple_choice', 'C1', 'grammar', '"It is high time the government ___ decisive action on housing costs."', 'took', '["takes", "take", "took", "has taken"]', NULL, NULL, NULL, NULL, '"It is high time + past simple subjunctive" expresses that something should already have happened. The past form does not refer to the past — it refers to the present urgency.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8aeac0cc-ca01-457e-98fe-c9de88072531', 728, 'matching', 'B2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "concise"}, "right": {"type": "text", "content": "Short and clear, using few words"}}, {"left": {"type": "text", "content": "ambiguous"}, "right": {"type": "text", "content": "Having more than one possible meaning"}}, {"left": {"type": "text", "content": "redundant"}, "right": {"type": "text", "content": "No longer needed or useful"}}, {"left": {"type": "text", "content": "coherent"}, "right": {"type": "text", "content": "Logical and easy to understand"}}, {"left": {"type": "text", "content": "eloquent"}, "right": {"type": "text", "content": "Fluent and persuasive in speaking"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2535de10-7b03-4e7e-8cea-d57696f981a3', 731, 'matching', 'A1', 'vocabulary', 'Match the picture to the correct word.', 'match_all_pairs', '[{"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/apple.png"}, "right": {"type": "text", "content": "apple"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/chair.png"}, "right": {"type": "text", "content": "chair"}}, {"left": {"type": "image", "content": "https://dyxmgicedabvmsbuvxny.supabase.co/storage/v1/object/public/audio/matching/window.png"}, "right": {"type": "text", "content": "window"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:43:15.182597+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('195c3746-e39c-41cd-9f2e-e7626dccdea1', 1374, 'multiple_choice', 'A2', 'prepositions', 'We met _____ the cafe _____ the corner.', 'at / on', '["at / on", "in / at", "on / in", "at / in"]', NULL, NULL, NULL, NULL, 'Meet at a place (at the cafe). On the corner is a fixed expression for location.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2aebb3e6-3622-428f-a69c-ac4a0b0f467d', 780, 'multiple_choice', 'C2', 'grammar', '"Hardly ___ sat down when the phone rang."', 'had I', '["I had", "had I", "I have", "have I"]', NULL, NULL, NULL, NULL, 'When "hardly" begins a sentence, subject and auxiliary invert: "Hardly had I sat down..." This inversion gives the sentence a formal, literary feel.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9187593a-95e4-4e0c-9ab8-e81a3c7f07e9', 1375, 'multiple_choice', 'A1', 'prepositions', 'I study English _____ the evenings.', 'in', '["at", "in", "on", "by"]', NULL, NULL, NULL, NULL, 'Use in with parts of the day: in the morning, in the afternoon, in the evening. Exception: at night.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('86896e00-4468-4e42-993e-6d7c20deeef2', 1376, 'gap_fill', 'B1', 'prepositions', 'She is very good _____ managing her time.', 'at', '[]', NULL, NULL, NULL, NULL, 'Good at is the correct collocation. Compare: bad at, brilliant at, hopeless at.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ec89affb-1769-49aa-b13c-a5c569bd2917', 1377, 'gap_fill', 'B2', 'prepositions', 'The new policy will have a significant impact _____ daily routines.', 'on', '[]', NULL, NULL, NULL, NULL, 'The collocation is have an impact on. Compare: have an effect on, have an influence on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7b7a2a27-7afa-4bbf-8b63-78b415af5d0f', 1378, 'gap_fill', 'B1', 'prepositions', 'I''m not used _____ getting up before six o''clock.', 'to', '[]', NULL, NULL, NULL, NULL, 'Be used to is a fixed expression meaning to be accustomed to. The to here is a preposition followed by a gerund.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48a22533-3241-4c31-8c57-9bc22e9c8e2f', 1379, 'gap_fill', 'B2', 'prepositions', 'She tends to arrive _____ time, regardless of the circumstances.', 'on', '[]', NULL, NULL, NULL, NULL, 'On time means punctual (at the right time). In time means early enough. Arrive on time is the standard collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('43bca0cc-c986-4707-8f47-ce6eb3c41eb8', 1380, 'gap_fill', 'B1', 'prepositions', 'He cut down _____ caffeine after his doctor''s advice.', 'on', '[]', NULL, NULL, NULL, NULL, 'Cut down on means to reduce the amount of something. The preposition on is part of the phrasal verb and cannot be omitted.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8e0d0d1b-0b30-43d6-b0b9-b540e39396a7', 1381, 'gap_fill', 'B2', 'prepositions', 'The key _____ maintaining a good routine lies in being consistent.', 'to', '[]', NULL, NULL, NULL, NULL, 'The key to (doing) something is a fixed expression. The to is a preposition followed by a gerund (maintaining).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6a48f545-9771-4302-8672-d271df89c1e4', 1382, 'gap_fill', 'B1', 'prepositions', 'She''s been working _____ the same company _____ over five years.', 'for / for', '[]', NULL, NULL, NULL, NULL, 'Work for a company (not at in this context). For five years expresses duration — use for, not since, with a period of time.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0d692de7-774a-4647-815d-9c4e5de80654', 1383, 'gap_fill', 'B2', 'prepositions', 'It''s hard to concentrate _____ work when you''re sleep-deprived.', 'on', '[]', NULL, NULL, NULL, NULL, 'Concentrate on is the correct collocation. Compare: focus on, work on, reflect on.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6a27c3b2-0b60-48ad-8fee-59a0f5cbe034', 1384, 'gap_fill', 'B1', 'prepositions', 'I''m looking forward _____ having a proper break next week.', 'to', '[]', NULL, NULL, NULL, NULL, 'Look forward to is a fixed phrasal verb. The to is a preposition followed by a gerund (-ing), not the infinitive.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1aa3147e-0385-487e-94a7-77b9615111f5', 1373, 'multiple_choice', 'A2', 'prepositions', 'The post office is _____ the station and the pub.', 'between', '["between", "among", "beside", "through"]', NULL, NULL, NULL, NULL, 'Between is used when something is in the middle of two specific things. Among is used with groups of three or more.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('887f40bf-12b2-4821-ac6a-413ebbba9ccd', 788, 'multiple_choice', 'C2', 'academic language', '"The notion that growth and sustainability are mutually exclusive is a ___."', 'false dichotomy', '["false dichotomy", "false economy", "red herring", "straw man"]', NULL, NULL, NULL, NULL, 'A "false dichotomy" presents two options as if they are the only possibilities, when in reality there are more. A "straw man" misrepresents an argument. A "red herring" distracts from the real issue.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('67c7aece-5fd5-4a36-a1ad-281cc58420d6', 1385, 'gap_fill', 'B2', 'prepositions', 'She suffers _____ insomnia and rarely sleeps more than five hours.', 'from', '[]', NULL, NULL, NULL, NULL, 'Suffer from is the correct collocation for medical or ongoing conditions. Compare: recover from, benefit from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('849b1a14-8ac0-448e-96e0-f2b413b7f7d9', 782, 'multiple_choice', 'C2', 'grammar', '"Not until the final results were published ___ the true extent of the crisis."', 'did we realise', '["we realised", "did we realise", "we did realise", "had we realised"]', NULL, NULL, NULL, NULL, 'When a negative adverbial (Not until, Never, Rarely) starts a sentence, auxiliary and subject must invert: "Not until X did we realise..." This is a key C2 feature.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fa217eb8-8abb-41cd-a142-ec4939e028eb', 1386, 'gap_fill', 'C1', 'prepositions', 'His success is attributed _____ years of disciplined practice.', 'to', '[]', NULL, NULL, NULL, NULL, 'Attribute to is the correct collocation. Compare: put down to, ascribe to. All mean to identify the cause of something.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0f9e7075-e47e-420e-a39d-ab1c6adffe93', 783, 'multiple_choice', 'C2', 'grammar', '"___ it not for the team''s resilience, the project would have collapsed entirely."', 'Were', '["Were", "Had", "Should", "Did"]', NULL, NULL, NULL, NULL, '"Were it not for..." is an inverted conditional equivalent to "If it were not for...". It is formal and commonly found in written English.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c6d27f2b-eb43-4d03-acef-396fcdde7343', 784, 'multiple_choice', 'C1', 'vocabulary', '"The CEO ___ in her speech that redundancies were likely, without ever using the word."', 'implied', '["implied", "inferred", "suggested", "insinuated"]', NULL, NULL, NULL, NULL, '"Imply" = to suggest something without saying it directly (speakers imply). "Infer" = to draw a conclusion from evidence (listeners infer). A classic mix-up — even at C2!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ae270178-a7be-45f1-8b56-02890d66bdbd', 785, 'multiple_choice', 'C2', 'vocabulary', '"The author''s later work is characterised by a ___ economy of line and colour."', 'studied', '["studied", "deliberate", "careful", "conscious"]', NULL, NULL, NULL, NULL, '"Studied" as an adjective means "deliberately considered and refined" — a sophisticated collocation used in art and literary criticism.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e72e74bc-18f9-42eb-8445-0cc9d031519a', 786, 'multiple_choice', 'C1', 'vocabulary', '"The report ___ to several systemic failures that had been ignored for years."', 'alluded', '["alluded", "referred", "pointed", "indicated"]', NULL, NULL, NULL, NULL, '"Allude to" means to refer to something indirectly. "Refer to" is direct and explicit. The distinction matters: the report suggested the failures without stating them plainly.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('30670cf4-26fb-41c4-b5cb-8f35e1599823', 1387, 'gap_fill', 'C2', 'prepositions', 'She is renowned _____ her ability to remain calm under pressure.', 'for', '[]', NULL, NULL, NULL, NULL, 'Renowned for is the correct collocation. Compare: famous for, celebrated for, known for.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('381c08e9-cbd5-4599-82f8-ac48131051fa', 1388, 'gap_fill', 'C1', 'prepositions', 'The extent _____ which habits shape identity is rarely considered.', 'to', '[]', NULL, NULL, NULL, NULL, 'The extent to which is a fixed relative clause structure. It introduces a degree or measure and cannot be replaced by at which or in which.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5b870957-5adf-4996-8a75-728ddfd87389', 1389, 'gap_fill', 'C2', 'prepositions', 'She refrained _____ commenting on the matter until the report was published.', 'from', '[]', NULL, NULL, NULL, NULL, 'Refrain from is the correct collocation, followed by a gerund. Compare: abstain from, desist from, shy away from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('acddb5f4-4e0c-4f30-8303-3ead3e43120e', 1390, 'gap_fill', 'C1', 'prepositions', 'He took great pride _____ the consistency of his morning routine.', 'in', '[]', NULL, NULL, NULL, NULL, 'Take pride in is the correct collocation. Compare: pride yourself on, derive satisfaction from.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0a52a663-4353-4458-ac80-32e4cecb119a', 1391, 'gap_fill', 'C2', 'prepositions', 'The habit is deeply ingrained _____ her daily behaviour.', 'in', '[]', NULL, NULL, NULL, NULL, 'Ingrained in is the correct collocation. Ingrained means deeply embedded or established.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('96baeb73-5791-4877-ae02-e0a5599b667d', 1392, 'gap_fill', 'C1', 'prepositions', 'Research suggests that regular exercise is conducive _____ improved sleep.', 'to', '[]', NULL, NULL, NULL, NULL, 'Conducive to is the correct collocation, meaning tending to produce a particular result. Compare: beneficial to, detrimental to.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('de07cad2-39db-4ddc-b52e-6f228b37d2ec', 1393, 'gap_fill', 'C2', 'prepositions', 'She is consistent _____ applying the same standards to herself as to others.', 'in', '[]', NULL, NULL, NULL, NULL, 'Consistent in (doing something) means doing something regularly and without variation. Compare: consistent with (meaning in agreement with).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('129c3e1d-a854-42f1-b222-0355b60f2dcf', 1394, 'gap_fill', 'C1', 'prepositions', 'Resilience is a quality that can be cultivated _____ deliberate practice.', 'through', '[]', NULL, NULL, NULL, NULL, 'Through means by means of when describing a method or process. Compare: through hard work, through repetition, through experience.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e4c85f58-ec0e-491d-9e55-cc703f825144', 1395, 'gap_fill', 'C2', 'prepositions', 'Her output is by no means _____ proportion to the effort she puts in.', 'in', '[]', NULL, NULL, NULL, NULL, 'In proportion to is the correct prepositional phrase meaning corresponding to or relative to. By no means in proportion to means the result does not match the effort.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9b688ca9-62b1-4fdf-9c15-62b87c4c29bc', 1396, 'multiple_choice', 'A1', 'vocabulary', 'Which word means the opposite of "remember"?', 'forget', '["forget", "recall", "think", "know"]', NULL, NULL, NULL, NULL, 'Forget means to fail to remember something. Recall and remember are synonyms.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db04808e-2334-4995-bdbe-6d6a93b4d89e', 1397, 'multiple_choice', 'A2', 'vocabulary', 'Which word describes someone who always arrives on time?', 'punctual', '["punctual", "lazy", "tidy", "careful"]', NULL, NULL, NULL, NULL, 'Punctual means arriving exactly on time, without being late. It comes from the Latin punctum, meaning point (of time).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d8c670ec-fb61-49b0-bbac-df74a978a684', 1398, 'multiple_choice', 'A1', 'vocabulary', 'What do you call the meal you eat in the morning?', 'breakfast', '["breakfast", "lunch", "supper", "snack"]', NULL, NULL, NULL, NULL, 'Breakfast is the first meal of the day. The word literally means breaking the fast from the night before.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48d26b28-f2f0-47a5-b239-bbb66e97feba', 1399, 'multiple_choice', 'A2', 'vocabulary', 'Which word means to feel very tired?', 'exhausted', '["exhausted", "anxious", "bored", "confused"]', NULL, NULL, NULL, NULL, 'Exhausted means extremely tired, with no energy left. It is stronger than simply tired.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('65e1d9a7-2695-437f-9810-940d4f365a4c', 1400, 'multiple_choice', 'A1', 'vocabulary', 'Which of these is something you set before going to sleep?', 'an alarm', '["an alarm", "a schedule", "a habit", "a routine"]', NULL, NULL, NULL, NULL, 'An alarm (clock) is a device or setting that wakes you up at a chosen time.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ced81b20-b519-48ba-9289-0a121b1d0953', 716, 'error_correction', 'A2', 'there_is_there_are', 'There is lots of people in the park.', 'There are lots of people in the park.', '[]', NULL, NULL, NULL, NULL, '"People" is plural, so we need "are", not "is".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"There is/are"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('deda3674-3649-4a16-8ea6-b06077d2be1a', 718, 'error_correction', 'A2', 'time_expressions', 'I went to the cinema this night.', 'I went to the cinema last night.', '[]', NULL, NULL, NULL, NULL, 'We say "last night" in the past, or "tonight" if it is the same day.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Time expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c1647b3-d870-4991-b209-6cd55376a39d', 1401, 'multiple_choice', 'A2', 'vocabulary', 'Which word means to do something regularly without thinking about it?', 'automatically', '["automatically", "carefully", "quickly", "rarely"]', NULL, NULL, NULL, NULL, 'Automatically means without conscious thought or effort. It is the adverb form of automatic.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('03624e79-820e-47e2-8362-6cd652b24ef0', 1402, 'multiple_choice', 'A2', 'vocabulary', 'If you feel _____, you need to eat something.', 'hungry', '["hungry", "sleepy", "thirsty", "tired"]', NULL, NULL, NULL, NULL, 'Hungry means wanting or needing food. Thirsty is the equivalent feeling for wanting water.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('069bbead-fca8-470e-8ad0-0efbed01f682', 1403, 'multiple_choice', 'A1', 'vocabulary', 'What do you call the things you do every day at the same time?', 'a routine', '["a routine", "a hobby", "a task", "an event"]', NULL, NULL, NULL, NULL, 'A routine is a sequence of actions regularly followed. It implies regularity and repetition.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('09cec244-dafe-48d8-8c3e-4fbef48068ea', 1404, 'multiple_choice', 'A2', 'vocabulary', 'Which word describes someone who finds it hard to wake up early?', 'a night owl', '["a night owl", "an early bird", "a workaholic", "a homebody"]', NULL, NULL, NULL, NULL, 'A night owl is a person who prefers to be awake and active at night. An early bird is the opposite — someone who wakes up early.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('62a0c6a4-e587-43da-b092-c66eeb94a813', 1405, 'multiple_choice', 'A2', 'vocabulary', 'Which of these means to sleep for a short time during the day?', 'to nap', '["to nap", "to doze off", "to rest", "to oversleep"]', NULL, NULL, NULL, NULL, 'To nap means a short, intentional sleep during the day. Doze off means to fall asleep unintentionally.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('39f6fde8-5740-4763-ba5d-09c3a52e518d', 1406, 'gap_fill', 'B1', 'vocabulary', 'She has a very _____ approach to her work — she does the same tasks in the same order every day.', 'methodical', '[]', NULL, NULL, NULL, NULL, 'Methodical means done in a careful, systematic way. It describes someone who follows a clear, consistent method.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c6b2783-713f-4029-95bd-8b6c5ccab1e5', 789, 'multiple_choice', 'C2', 'vocabulary', '"The government''s economic measures were ___ by critics as short-sighted and damaging."', 'lambasted', '["lambasted", "criticised", "condemned", "denounced"]', NULL, NULL, NULL, NULL, '"Lambasted" is a more vivid and forceful word than "criticised". It implies harsh, vigorous public attack. While the others work grammatically, "lambasted" is the most precise and expressive choice here.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('15579c71-cc18-4dff-92d9-4ce3a3e4e6cd', 790, 'multiple_choice', 'C1', 'vocabulary', '"She ___ accepted responsibility, admitting fault only under sustained pressure."', 'grudgingly', '["grudgingly", "openly", "willingly", "frankly"]', NULL, NULL, NULL, NULL, '"Grudgingly" means reluctantly, with resistance. The clause "only under sustained pressure" confirms she didn''t want to accept responsibility.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7ae36c4-00ac-4ac8-a0c8-97ba39cb1e9a', 835, 'error_correction', 'A2', 'grammar', 'They didn''t went to the concert.', 'They didn''t go to the concert.', '[]', NULL, NULL, NULL, NULL, 'After "didn''t" (did not), we use the infinitive. "They didn''t go" — not "didn''t went".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f81ba816-2d4c-427b-93d5-8a75e60c8129', 1407, 'gap_fill', 'B2', 'vocabulary', 'I find it difficult to _____ between rest and productivity — I feel guilty when I''m not doing something.', 'strike a balance', '[]', NULL, NULL, NULL, NULL, 'Strike a balance means to find a satisfactory middle point between two things. It is a common collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('10e3601f-2776-4886-b4d0-ee063df3d5cc', 1408, 'gap_fill', 'B1', 'vocabulary', 'He tends to _____ important tasks until the last minute, even though he knows it causes stress.', 'procrastinate', '[]', NULL, NULL, NULL, NULL, 'Procrastinate means to delay doing something, especially something important. The noun form is procrastination.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c1e7fe06-6270-4abe-b56a-02f7252dc7f7', 1409, 'gap_fill', 'B2', 'vocabulary', 'After years of working from home, she has found it difficult to maintain clear _____ between work and personal life.', 'boundaries', '[]', NULL, NULL, NULL, NULL, 'Boundaries in this context means the limits that separate two areas of life. Maintain boundaries is the standard collocation.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b0121906-9a8d-4c3c-acd5-f0b4ccab01b8', 1410, 'gap_fill', 'B1', 'vocabulary', 'A good morning routine can help you feel more _____ and ready for the day ahead.', 'focused', '[]', NULL, NULL, NULL, NULL, 'Focused means giving full attention to something. It is a common adjective when discussing productivity and concentration.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('31a55eca-bfa3-4827-9319-88ca340faade', 1411, 'gap_fill', 'B2', 'vocabulary', 'Regular exercise is known to _____ the effects of stress on the body and mind.', 'mitigate', '[]', NULL, NULL, NULL, NULL, 'Mitigate means to reduce the severity or impact of something. It is a formal verb used in academic and professional English.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07ace117-8908-402d-b9f6-8e5e3d93cfff', 1412, 'gap_fill', 'B1', 'vocabulary', 'It''s important to _____ realistic goals when trying to build a new habit — starting too ambitiously often leads to failure.', 'set', '[]', NULL, NULL, NULL, NULL, 'Set goals / set targets is the standard collocation. Set means to establish or fix something.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ab2d207e-8ee0-4fb2-af25-6c493abab0ba', 643, 'sentence_building', 'A1', 'there_is_there_are', '', 'there is a dog in the garden', '["there", "any", "a", "cats", "in", "the", "garden", "is", "dog"]', '["in the garden there is a dog."]', 'There is a dog in the garden is more natural ', NULL, NULL, 'There is + singular noun + place. Use "is" for singular.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"There is/are"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4828bcb1-c82b-4a69-907b-751e67807207', 631, 'sentence_building', 'A2', 'adjectives', '', 'the weather is very cold today', '["the", "weather", "is", "very", "cold", "today", "were", "it"]', NULL, NULL, NULL, NULL, 'We use ''the weather is'' + adjective to describe current weather. ''Very'' goes before the adjective to make it stronger.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{Adjective}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c07fc9a-6c95-4d8a-9202-adf845ae43ce', 791, 'multiple_choice', 'C1', 'grammar', '"Which sentence correctly uses a cleft construction?"', 'It was the marketing team that identified the problem.', '["It was the marketing team that identified the problem.", "It was the marketing team who has identified the problem.", "It is the marketing team that have identified the problem.", "It was the marketing team which identified the problem."]', NULL, NULL, NULL, NULL, 'A cleft sentence splits information for emphasis: "It was X that/who did Y." For groups and things, "that" is preferred. "Which" is used for non-defining relative clauses, not cleft structures.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cfb10f89-ea2b-4226-a39b-ffa6f2106efb', 792, 'multiple_choice', 'C1', 'vocabulary', '"The witness''s account ___ that of the defendant in several crucial respects."', 'contradicted', '["contradicted", "conflicted", "clashed", "disputed"]', NULL, NULL, NULL, NULL, '"Contradict" means to state the opposite of something — one account said X, the other said not-X. "Conflict" and "clash" imply tension but not necessarily direct opposition. "Dispute" means to challenge, often actively.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c3dca8a-ad54-4c6d-a625-7ee8840536c3', 793, 'multiple_choice', 'C2', 'vocabulary', '"The philosopher''s ___ style — dense with allusion — rewards patient, careful reading."', 'allusive', '["allusive", "elusive", "illusive", "inclusive"]', NULL, NULL, NULL, NULL, '"Allusive" means full of allusions (indirect references). "Elusive" means hard to catch or define. "Illusive" means based on illusion (less common). Easy to confuse, but very different!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3697e2e2-f7f8-455d-a66e-378b94cf762c', 836, 'error_correction', 'A2', 'grammar', 'I buyed a new phone last week.', 'I bought a new phone last week.', '[]', NULL, NULL, NULL, NULL, '"Buy" is an irregular verb. Its past simple form is "bought". Unfortunately, you have to study irregular verbs, but there are patterns you can learn!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0913-0913-0913-000000000913', 913, 'matching', 'A2', 'vocabulary', 'Match each adjective to its opposite.', 'match_all_pairs', '[{"left": {"type": "text", "content": "cheap"}, "right": {"type": "text", "content": "expensive"}}, {"left": {"type": "text", "content": "easy"}, "right": {"type": "text", "content": "difficult"}}, {"left": {"type": "text", "content": "noisy"}, "right": {"type": "text", "content": "quiet"}}, {"left": {"type": "text", "content": "fast"}, "right": {"type": "text", "content": "slow"}}, {"left": {"type": "text", "content": "hot"}, "right": {"type": "text", "content": "cold"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0914-0914-0914-000000000914', 914, 'matching', 'A2', 'vocabulary', 'Match each travel word to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "depart"}, "right": {"type": "text", "content": "to leave a place"}}, {"left": {"type": "text", "content": "arrive"}, "right": {"type": "text", "content": "to reach a place"}}, {"left": {"type": "text", "content": "book"}, "right": {"type": "text", "content": "to reserve something in advance"}}, {"left": {"type": "text", "content": "cancel"}, "right": {"type": "text", "content": "to decide something will not happen"}}, {"left": {"type": "text", "content": "check in"}, "right": {"type": "text", "content": "to register on arrival at a hotel or airport"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e1cac905-f465-48a6-90ff-8f37602c84dd', 1413, 'gap_fill', 'B2', 'vocabulary', 'The _____ of her routine was remarkable — she barely deviated from it even during holidays.', 'consistency', '[]', NULL, NULL, NULL, NULL, 'Consistency means the quality of always behaving or performing in the same way. It is closely related to reliability and predictability.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a71f013c-df03-4b70-b293-547de712e02e', 1414, 'gap_fill', 'B1', 'vocabulary', 'She decided to _____ her screen time after realising it was affecting her sleep.', 'cut down on', '[]', NULL, NULL, NULL, NULL, 'Cut down on means to reduce the amount or frequency of something. It is a phrasal verb commonly used for habits.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f26c90e0-2fd8-4074-ad89-832d91968bc8', 1415, 'gap_fill', 'B2', 'vocabulary', 'The study found that people with structured morning routines reported higher levels of _____ throughout the day.', 'wellbeing', '[]', NULL, NULL, NULL, NULL, 'Wellbeing refers to a person''s general health, happiness, and comfort. It is commonly used in psychology and health contexts.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ce3c400e-733e-497a-962a-ac82f7ac88f2', 1416, 'gap_fill', 'C1', 'vocabulary', 'The speaker''s _____ delivery made the presentation difficult to follow — she moved between topics without warning.', 'erratic', '[]', NULL, NULL, NULL, NULL, 'Erratic means unpredictable and inconsistent. It is the opposite of steady or methodical.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('642c3bea-3292-4ec8-88e7-952326b1b355', 1417, 'gap_fill', 'C2', 'vocabulary', 'His _____ in completing tasks — always finishing what he starts — is one of his greatest professional assets.', 'tenacity', '[]', NULL, NULL, NULL, NULL, 'Tenacity means persistent determination. It implies the refusal to give up despite difficulties.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1f3e6af3-5dce-4880-b3ef-ff4e35606f08', 1418, 'gap_fill', 'C1', 'vocabulary', 'She approached the challenge with remarkable _____, never showing signs of panic or frustration.', 'equanimity', '[]', NULL, NULL, NULL, NULL, 'Equanimity means mental calmness, especially in difficult situations. It implies composure and balance.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0915-0915-0915-000000000915', 915, 'matching', 'A2', 'vocabulary', 'Match each word to the correct category.', 'match_all_pairs', '[{"left": {"type": "text", "content": "apple"}, "right": {"type": "text", "content": "fruit"}}, {"left": {"type": "text", "content": "carrot"}, "right": {"type": "text", "content": "vegetable"}}, {"left": {"type": "text", "content": "salmon"}, "right": {"type": "text", "content": "fish"}}, {"left": {"type": "text", "content": "chicken"}, "right": {"type": "text", "content": "meat"}}, {"left": {"type": "text", "content": "cheddar"}, "right": {"type": "text", "content": "cheese"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('75d2e0e5-9aa5-4588-a7ae-907df58e67cf', 1419, 'gap_fill', 'C2', 'vocabulary', 'The _____ of good habits is not about willpower — it is about designing an environment that makes good choices easier.', 'cultivation', '[]', NULL, NULL, NULL, NULL, 'Cultivation means the development or improvement of something over time. It is used metaphorically here, as in cultivating habits.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('81543106-7bc2-4b10-b36c-7e7a4692d3f4', 1420, 'gap_fill', 'C1', 'vocabulary', 'Many high achievers are _____ about protecting their morning routine from interruptions.', 'fastidious', '[]', NULL, NULL, NULL, NULL, 'Fastidious means very attentive to detail and careful about maintaining standards. It can also imply being difficult to please.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('59517f15-d2d0-48ad-a2f0-9736ad8278a6', 633, 'sentence_building', 'A2', 'there_is_there_are', '', 'there are two cats in the garden', '["there", "are", "two", "cats", "in", "the", "garden", "is", "a"]', NULL, NULL, '["in the garden there are two cats ."]', NULL, 'We use ''there are'' for plural nouns and ''there is'' for singular. Two cats = plural, so ''there are''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"There is/are"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('27baeea2-7b3a-49e1-9938-f980dc4fc269', 296, 'gap_fill', 'A1', 'have_got', 'I ___ (h... got) a dog.', 'have got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, NULL, 'Have got = have (possession). I/you/we/they have got.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('34edf13c-9871-465f-b791-fa29348c368d', 801, 'odd_one_out', 'A1', 'grammar', 'Three of these are verbs (action words). Which is the odd one out?', 'fast', '["run", "jump", "fast", "swim"]', NULL, NULL, NULL, NULL, 'Run, jump, and swim are all verbs — things you do. "Fast" is an adjective (or adverb) meaning quick. You can run fast, but "fast" itself is not a verb.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('94dddddf-9358-45e1-a591-5fc1b6323887', 298, 'gap_fill', 'A1', 'have_got', '___ you ___ (h... got) any brothers?', 'Have...got', NULL, NULL, 'British English uses have/has got, where Americans use have/has.', NULL, NULL, 'Questions: Have + subject + got...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Have got"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c04696b4-7c1c-4eba-993f-1e9826ea5a20', 798, 'odd_one_out', 'A1', 'home', 'Three of these are rooms in a house. Which is the odd one out?', 'garden', '["kitchen", "bedroom", "garden", "bathroom"]', NULL, NULL, NULL, NULL, 'The kitchen, bedroom, and bathroom are all indoor rooms. A garden is outside — which is lovely in summer, but it''s not a room!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1116bab8-2aa7-417f-9ac4-eb2eebb88444', 799, 'odd_one_out', 'A1', 'weather', 'Three of these describe the weather. Which is the odd one out?', 'hungry', '["sunny", "rainy", "cloudy", "hungry"]', NULL, NULL, NULL, NULL, 'Sunny, rainy, and cloudy all describe the weather. Hungry describes how you feel when you need food — nothing to do with the forecast!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06f8c23f-09da-479a-ab9a-f6fdb81b983e', 800, 'odd_one_out', 'A1', 'body', 'Three of these are parts of the face. Which is the odd one out?', 'knee', '["eye", "nose", "knee", "mouth"]', NULL, NULL, NULL, NULL, 'Eyes, noses, and mouths are all on your face. A knee is on your leg. Thankfully — imagine a knee on your face!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9be3f513-ab80-45a5-b184-f0a2fe90d715', 802, 'odd_one_out', 'A1', 'animals', 'Three of these are animals you would find on a farm. Which is the odd one out?', 'shark', '["cow", "pig", "shark", "chicken"]', NULL, NULL, NULL, NULL, 'Cows, pigs, and chickens are all common farm animals. A shark lives in the ocean — and if it were on your farm, you would have much bigger problems than collecting eggs.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3c708a8d-084c-45d7-bb30-6f1e6592e504', 794, 'multiple_choice', 'C1', 'academic vocabulary', '"The study''s findings were ___; they neither confirmed nor refuted the original hypothesis."', 'inconclusive', '["inconclusive", "ambiguous", "indeterminate", "uncertain"]', NULL, NULL, NULL, NULL, '"Inconclusive" specifically means a study or investigation did not produce a clear result. It is the precise academic term. "Ambiguous" means unclear in meaning. "Uncertain" is too general.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('77bf793f-bb41-40d8-b2a7-25eca3bc642f', 797, 'multiple_choice', 'C2', 'academic vocabulary', '"The sociological concept of ___ describes the tendency to view one''s own culture as superior."', 'ethnocentrism', '["ethnocentrism", "nationalism", "xenophobia", "parochialism"]', NULL, NULL, NULL, NULL, '"Ethnocentrism" is the specific academic term for judging other cultures by the standards of your own. "Xenophobia" is fear of foreigners. "Nationalism" is attachment to one''s nation. "Parochialism" is narrow-mindedness.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6414ab4a-4245-4da8-b461-7975ae51ec5c', 1421, 'gap_fill', 'C2', 'vocabulary', 'Research has shown that sleep deprivation has a markedly _____ effect on decision-making and emotional regulation.', 'deleterious', '[]', NULL, NULL, NULL, NULL, 'Deleterious means causing harm or damage. It is a formal synonym for harmful or detrimental.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e38ef627-375d-4adf-8e1a-ccfe63b48ee5', 1422, 'gap_fill', 'C1', 'vocabulary', 'She was able to maintain her _____ under pressure, finishing the project ahead of schedule despite the setbacks.', 'composure', '[]', NULL, NULL, NULL, NULL, 'Composure means the state of being calm and in control of your feelings. Compare: equanimity, poise, self-possession.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0df28f30-d24d-40cd-a146-bb6e9b701c10', 1423, 'gap_fill', 'C2', 'vocabulary', 'The _____ nature of his schedule — never the same two days in a row — made it difficult to establish lasting habits.', 'mercurial', '[]', NULL, NULL, NULL, NULL, 'Mercurial means subject to sudden unpredictable changes. It derives from Mercury, the Roman god of speed, associated with rapid movement.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fbf89265-ba5c-456f-a11b-909b1ca948c0', 1424, 'gap_fill', 'C1', 'vocabulary', 'The report identified sleep deprivation as a major _____ to productivity in modern workplaces.', 'impediment', '[]', NULL, NULL, NULL, NULL, 'Impediment means something that prevents or slows progress. Synonyms include obstacle, barrier, hindrance.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f31a7553-260c-4354-8727-c12835c3f022', 74, 'gap_fill', 'B2', 'have_something_done', 'She''s ___ (have / her hair / cut) tomorrow.', 'having her hair cut', NULL, '["having a hair cut", "getting a hair cut"]', NULL, NULL, 'Have + object + past participle', 'Have/get something done structure.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Causative}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3131cbea-e02e-4422-9329-ea6a8c433789', 63, 'gap_fill', 'B1', 'too_enough', 'This coffee is ___ (_ _ _) hot to drink right now.', 'too', NULL, NULL, NULL, NULL, 'Too means more than necessary', 'Too means more than is wanted or needed.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Too & enough"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48b71834-cc0f-42f6-92e2-58d88a5bd975', 67, 'gap_fill', 'B1', 'making_suggestions', 'Why don''t we ___ (_ _) to the cinema tonight?', 'go', NULL, NULL, NULL, NULL, 'Why don''t we + infinitive without ''to''', 'Why don''t we is followed by the infinitive without ''to'' when making suggestions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Making suggestions"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0911-0911-0911-000000000911', 911, 'matching', 'A2', 'vocabulary', 'Match each verb with the correct collocation.', 'match_all_pairs', '[{"left": {"type": "text", "content": "make"}, "right": {"type": "text", "content": "a decision"}}, {"left": {"type": "text", "content": "do"}, "right": {"type": "text", "content": "homework"}}, {"left": {"type": "text", "content": "have"}, "right": {"type": "text", "content": "a shower"}}, {"left": {"type": "text", "content": "take"}, "right": {"type": "text", "content": "a photo"}}, {"left": {"type": "text", "content": "go"}, "right": {"type": "text", "content": "shopping"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('59f2ecb0-5ad3-4c70-adb9-425c57574213', 1425, 'gap_fill', 'C2', 'vocabulary', 'There is a growing body of evidence to suggest that micro-habits — tiny _____ changes — are more effective than dramatic lifestyle overhauls.', 'incremental', '[]', NULL, NULL, NULL, NULL, 'Incremental means increasing or developing gradually in small steps. Compare: gradual, progressive, cumulative.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53836d01-ffc9-408f-81f1-0a15afe72950', 1426, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el significado de "madrugar"?', 'levantarse muy temprano', '["levantarse muy temprano", "quedarse dormido", "acostarse tarde", "descansar"]', NULL, NULL, NULL, NULL, 'Madrugar significa levantarse muy temprano por la mañana. Una persona que madruga se llama madrugador/a.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('07756731-2b03-435d-b743-3339ed761c76', 1427, 'multiple_choice', 'A2', 'spanish', '¿Qué significa "tener sueño"?', 'tener ganas de dormir', '["tener ganas de dormir", "tener un sueño bonito", "dormir bien", "estar descansado"]', NULL, NULL, NULL, NULL, 'Tener sueño significa sentir la necesidad de dormir. Es diferente de "tener un sueño", que significa to have a dream.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f167cb6c-991b-433c-9672-e12f88a656fd', 1428, 'multiple_choice', 'A2', 'spanish', '¿Cuál de estas palabras describe a alguien que trabaja mucho?', 'trabajador', '["trabajador", "perezoso", "tranquilo", "aburrido"]', NULL, NULL, NULL, NULL, 'Trabajador/a describe a alguien que trabaja mucho y con esfuerzo. Su opuesto es perezoso/a (lazy).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dac5a8f5-3334-41f9-8146-039b6f2e40d2', 468, 'gap_fill', 'C1', 'advanced_vocabulary', 'She has a ___ knowledge of international law.', 'thorough', NULL, NULL, NULL, NULL, NULL, 'Thorough/comprehensive = very complete and detailed.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3b500666-d6d2-4f88-810b-4c0e3803bd29', 1429, 'gap_fill', 'A2', 'spanish', 'Cada mañana me _____ a las siete, me ducho y desayuno antes de salir de casa.', 'levanto', '[]', NULL, NULL, NULL, NULL, 'Levantarse es un verbo reflexivo. En primera persona singular (yo), la forma es me levanto.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f30aa32c-8912-40f0-8bc6-aa281879df68', 1430, 'gap_fill', 'A2', 'spanish', 'Intento acostarme antes de las once _____ semana para no llegar cansado al trabajo.', 'entre', '[]', NULL, NULL, NULL, NULL, 'Entre semana es la expresión española para on weekdays (de lunes a viernes). Es una expresión fija.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bf303c0a-e234-4089-8b98-8a56814723a4', 1431, 'multiple_choice', 'A2', 'spanish', '¿Cómo se dice "alarm clock" en español?', 'el despertador', '["el despertador", "el reloj de pared", "el temporizador", "el cronómetro"]', NULL, NULL, NULL, NULL, 'El despertador es el reloj que te despierta por la mañana. El verbo relacionado es despertar/despertarse (to wake up).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('740cf589-0e7d-4ad0-8311-9ccb3eafbd29', 1432, 'gap_fill', 'A2', 'spanish', 'Los fines de semana me gusta _____ una siesta después de comer.', 'echar', '[]', NULL, NULL, NULL, NULL, 'Echar una siesta es la expresión española para to take a nap. Siesta es una palabra que existe también en inglés.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('42a0e6cd-b665-4a9f-97dc-ff8179b57656', 1433, 'multiple_choice', 'A2', 'spanish', '¿Qué significa "trasnochar"?', 'quedarse despierto hasta muy tarde', '["quedarse despierto hasta muy tarde", "dormir demasiado", "levantarse muy temprano", "tomar una siesta"]', NULL, NULL, NULL, NULL, 'Trasnochar significa quedarse despierto hasta muy tarde o durante toda la noche. Su opuesto es madrugar.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5e671b31-46fc-43cf-8322-8a66c401787f', 1434, 'gap_fill', 'A2', 'spanish', 'Siempre me cepillo los dientes _____ de acostarme.', 'antes', '[]', NULL, NULL, NULL, NULL, 'Antes de + infinitivo significa before doing something. La estructura es la misma que en inglés: before going to bed / antes de acostarse.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('02cef32c-8112-40ad-ac4c-c36c60630713', 1435, 'multiple_choice', 'A2', 'spanish', '¿Cuál es el verbo correcto? "Llevo tres años _____ en esta empresa."', 'trabajando', '["trabajando", "trabaje", "trabajo", "trabajar"]', NULL, NULL, NULL, NULL, 'Con llevar + tiempo, se usa el gerundio: llevo tres años trabajando. Esta estructura equivale a "I have been working here for three years."', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1beae735-a255-45ec-9d47-661cacef9a82', 1436, 'gap_fill', 'A2', 'spanish', 'Cuando llegué a la fiesta, todo el mundo _____ bailando.', 'estaba', '[]', NULL, NULL, NULL, NULL, 'El imperfecto continuo (estaba + gerundio) se usa para describir una acción que estaba en progreso en un momento concreto del pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d2ddc666-83fa-45d9-8b72-909d85aa89df', 1437, 'gap_fill', 'A2', 'spanish', 'Ayer _____ al supermercado después del trabajo.', 'fui', '[]', NULL, NULL, NULL, NULL, 'Fui es el pretérito indefinido de ir. Se usa para acciones completadas en el pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c9208292-52b5-496f-a5c0-7ef2fa444a20', 1438, 'gap_fill', 'A2', 'spanish', 'Mi hermana es más alta _____ yo.', 'que', '[]', NULL, NULL, NULL, NULL, 'En los comparativos en español se usa que (no de) para comparar dos cosas: más alto que, más rápido que.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3cc389ec-6795-4681-b4ef-74ee592062aa', 1439, 'gap_fill', 'A2', 'spanish', 'Me encanta esta ciudad _____ hay muchísimas cosas que hacer.', 'porque', '[]', NULL, NULL, NULL, NULL, 'Porque significa because y se escribe en una sola palabra. No confundir con por qué (why — en preguntas).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('75f54af8-24a9-4ee3-a8a4-15e32b9dcf5e', 1440, 'gap_fill', 'A2', 'spanish', 'Habla muy bien el español _____ nunca ha vivido en un país hispanohablante.', 'aunque', '[]', NULL, NULL, NULL, NULL, 'Aunque significa although o even though. Introduce una concesión — algo sorprendente dado lo que se ha dicho antes.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d028f7bd-4ecf-42a5-bc7e-c0cff6e708a4', 469, 'gap_fill', 'C2', 'advanced_vocabulary', 'The new evidence ___ the original theory.', 'contradicts', NULL, '["supports", "confirms"]', 'Supports/confirms = strengthen a previous position.', NULL, NULL, 'Contradict/undermine = go against or weaken a previous position.', '2026-02-11 19:06:02.933261+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0912-0912-0912-000000000912', 912, 'matching', 'A2', 'vocabulary', 'Match each job to the correct workplace.', 'match_all_pairs', '[{"left": {"type": "text", "content": "doctor"}, "right": {"type": "text", "content": "hospital"}}, {"left": {"type": "text", "content": "chef"}, "right": {"type": "text", "content": "restaurant"}}, {"left": {"type": "text", "content": "teacher"}, "right": {"type": "text", "content": "school"}}, {"left": {"type": "text", "content": "mechanic"}, "right": {"type": "text", "content": "garage"}}, {"left": {"type": "text", "content": "pilot"}, "right": {"type": "text", "content": "airport"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 15:58:50.696706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('844aafb8-7ce5-42db-a892-8a830abf6971', 804, 'odd_one_out', 'A2', 'time', 'Three of these are months of the year. Which is the odd one out?', 'Friday', '["January", "Friday", "March", "October"]', NULL, NULL, NULL, NULL, 'January, March, and October are months of the year. Friday is a day of the week. Both useful for making plans — but not the same category!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Time expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b8a14ad0-2d53-42a4-bdb0-b05f52826f5d', 803, 'odd_one_out', 'A1', 'food', 'Three of these are drinks. Which is the odd one out?', 'bread', '["water", "juice", "coffee", "bread"]', NULL, NULL, NULL, NULL, 'Water, juice, and coffee are all things you drink. Bread is a food — you eat it, not drink it (unless you are very, very hungry).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1b4c52da-5c97-4b5d-a320-d43a680afc3c', 805, 'odd_one_out', 'A2', 'money', 'Three of these are ways to pay in a shop. Which is the odd one out?', 'receipt', '["cash", "credit card", "contactless", "receipt"]', NULL, NULL, NULL, NULL, 'Cash, credit card, and contactless are all payment methods. A receipt is what you receive after you pay — it''s proof of purchase, not a way to pay.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1f6bcaac-8c9e-4caf-8c0f-8f4d17d25499', 806, 'odd_one_out', 'A2', 'feelings', 'Three of these describe how someone feels. Which is the odd one out?', 'tall', '["nervous", "excited", "angry", "tall"]', NULL, NULL, NULL, NULL, 'Nervous, excited, and angry are all emotions — how a person feels. Tall describes physical height, not a feeling. (Though some tall people feel very confident about it!)', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d30fd080-dea5-4dfd-8a1a-598bd81fc094', 808, 'odd_one_out', 'B1', 'vocabulary', 'Three of these are synonyms for "tired". Which is the odd one out?', 'energetic', '["exhausted", "drained", "weary", "energetic"]', NULL, NULL, NULL, NULL, 'Exhausted, drained, and weary all mean very tired. "Energetic" means full of energy — the complete opposite. Don''t mix them up in your CV!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d226bba4-6719-4ec5-b6f6-4d4979d91db0', 809, 'odd_one_out', 'B1', 'vocabulary', 'Three of these describe a confident person. Which is the odd one out?', 'timid', '["assertive", "self-assured", "bold", "timid"]', NULL, NULL, NULL, NULL, 'Assertive, self-assured, and bold all describe someone with confidence. Timid means shy and lacking confidence — the opposite quality.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('08bb3a22-00ca-45d8-b299-fffe01d13988', 807, 'odd_one_out', 'A2', 'travel', 'Three of these are types of transport. Which is the odd one out?', 'motorway', '["train", "bus", "ferry", "motorway"]', NULL, NULL, NULL, NULL, 'Trains, buses, and ferries are all vehicles — things you travel in. A motorway is a type of road — it is where you travel, not what you travel in.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('880fc37f-50d0-4c12-8eac-8e6f6d86fba8', 813, 'odd_one_out', 'B2', 'environment', 'Three of these words are connected with the environment. Which is the odd one out?', 'dividend', '["deforestation", "pollution", "flooding", "dividend"]', NULL, NULL, NULL, NULL, 'Deforestation, pollution, and flooding are all environmental issues. A dividend is a payment made to shareholders from a company''s profits — firmly in finance, not ecology.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('271a17e2-b426-4f01-abe4-a267ee875a15', 680, 'odd_one_out', 'A2', 'house_and_home', 'Which one is NOT a room in a house?', 'garden', '["kitchen", "bedroom", "garden", "bathroom"]', NULL, NULL, NULL, NULL, '"Garden" is outside the house, not a room inside it.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be54ceed-1e63-409b-a3a7-34cb69437390', 1441, 'gap_fill', 'A2', 'spanish', 'Llevo tres años _____ español.', 'estudiando', '[]', NULL, NULL, NULL, NULL, 'Con llevar + tiempo, se usa el gerundio para indicar una acción que empezó en el pasado y continúa: llevo tres años estudiando.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f008920-e57a-489d-a6dd-f1ac81533f44', 1442, 'gap_fill', 'A2', 'spanish', 'Quedamos en el bar a las ocho, pero él _____ tarde.', 'llegó', '[]', NULL, NULL, NULL, NULL, 'Llegó es el pretérito indefinido de llegar en tercera persona singular. Se usa para una acción completada en el pasado.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('78751307-cdbf-4813-af7c-27a9bad8d5b5', 1443, 'gap_fill', 'A2', 'spanish', 'La película era muy larga; _____, nos gustó mucho.', 'sin embargo', '[]', NULL, NULL, NULL, NULL, 'Sin embargo significa however o nevertheless. Introduce un contraste con lo dicho anteriormente.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0916-0916-0916-000000000916', 916, 'matching', 'B1', 'vocabulary', 'Match each phrasal verb to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "put off"}, "right": {"type": "text", "content": "to postpone"}}, {"left": {"type": "text", "content": "take on"}, "right": {"type": "text", "content": "to accept responsibility for"}}, {"left": {"type": "text", "content": "bring up"}, "right": {"type": "text", "content": "to mention a topic"}}, {"left": {"type": "text", "content": "look into"}, "right": {"type": "text", "content": "to investigate"}}, {"left": {"type": "text", "content": "carry out"}, "right": {"type": "text", "content": "to perform or complete a task"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0917-0917-0917-000000000917', 917, 'matching', 'B1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "persuade"}, "right": {"type": "text", "content": "to convince someone to do something"}}, {"left": {"type": "text", "content": "negotiate"}, "right": {"type": "text", "content": "to discuss in order to reach an agreement"}}, {"left": {"type": "text", "content": "recommend"}, "right": {"type": "text", "content": "to suggest something as a good choice"}}, {"left": {"type": "text", "content": "complain"}, "right": {"type": "text", "content": "to express dissatisfaction"}}, {"left": {"type": "text", "content": "confirm"}, "right": {"type": "text", "content": "to state that something is definitely true or agreed"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0918-0918-0918-000000000918', 918, 'matching', 'B2', 'vocabulary', 'Match each adjective to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "reluctant"}, "right": {"type": "text", "content": "unwilling to do something"}}, {"left": {"type": "text", "content": "assertive"}, "right": {"type": "text", "content": "confident in stating your views"}}, {"left": {"type": "text", "content": "impartial"}, "right": {"type": "text", "content": "not favouring one side over another"}}, {"left": {"type": "text", "content": "tentative"}, "right": {"type": "text", "content": "not certain or definite"}}, {"left": {"type": "text", "content": "forthcoming"}, "right": {"type": "text", "content": "willing to give information"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0919-0919-0919-000000000919', 919, 'matching', 'B2', 'grammar', 'Match each linking word to its function.', 'match_all_pairs', '[{"left": {"type": "text", "content": "although"}, "right": {"type": "text", "content": "to show contrast"}}, {"left": {"type": "text", "content": "therefore"}, "right": {"type": "text", "content": "to show result"}}, {"left": {"type": "text", "content": "provided that"}, "right": {"type": "text", "content": "to show condition"}}, {"left": {"type": "text", "content": "in addition"}, "right": {"type": "text", "content": "to add information"}}, {"left": {"type": "text", "content": "in other words"}, "right": {"type": "text", "content": "to clarify or restate"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0920-0920-0920-000000000920', 920, 'matching', 'B2', 'vocabulary', 'Match each idiom to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "hit the nail on the head"}, "right": {"type": "text", "content": "to describe something exactly right"}}, {"left": {"type": "text", "content": "sit on the fence"}, "right": {"type": "text", "content": "to avoid taking sides"}}, {"left": {"type": "text", "content": "get the ball rolling"}, "right": {"type": "text", "content": "to start a process"}}, {"left": {"type": "text", "content": "bite the bullet"}, "right": {"type": "text", "content": "to endure a difficult situation"}}, {"left": {"type": "text", "content": "burn bridges"}, "right": {"type": "text", "content": "to permanently damage a relationship"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0921-0921-0921-000000000921', 921, 'matching', 'C1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "exacerbate"}, "right": {"type": "text", "content": "to make a problem worse"}}, {"left": {"type": "text", "content": "mitigate"}, "right": {"type": "text", "content": "to reduce the severity of something"}}, {"left": {"type": "text", "content": "undermine"}, "right": {"type": "text", "content": "to weaken or damage gradually"}}, {"left": {"type": "text", "content": "corroborate"}, "right": {"type": "text", "content": "to confirm or support with evidence"}}, {"left": {"type": "text", "content": "circumvent"}, "right": {"type": "text", "content": "to find a way around a rule or obstacle"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d45e91f1-88bc-4981-b953-9c8f4239add2', 1444, 'gap_fill', 'A2', 'spanish', 'Necesito practicar más _____ mejorar mi español.', 'para', '[]', NULL, NULL, NULL, NULL, 'Para + infinitivo expresa finalidad (in order to): para mejorar = in order to improve.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0922-0922-0922-000000000922', 922, 'matching', 'C1', 'vocabulary', 'Match each formal verb to its neutral equivalent.', 'match_all_pairs', '[{"left": {"type": "text", "content": "commence"}, "right": {"type": "text", "content": "begin"}}, {"left": {"type": "text", "content": "endeavour"}, "right": {"type": "text", "content": "try"}}, {"left": {"type": "text", "content": "terminate"}, "right": {"type": "text", "content": "end"}}, {"left": {"type": "text", "content": "ascertain"}, "right": {"type": "text", "content": "find out"}}, {"left": {"type": "text", "content": "remunerate"}, "right": {"type": "text", "content": "pay"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bf4800dc-cef2-4cb8-8a38-3fbacd60df02', 1445, 'gap_fill', 'A2', 'spanish', 'Llegaron tarde _____ el tráfico.', 'por', '[]', NULL, NULL, NULL, NULL, 'Por se usa para expresar causa o razón: llegaron tarde por el tráfico (they arrived late because of the traffic).', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bf680403-7b11-4c02-b92f-fb9407fc5771', 1446, 'gap_fill', 'A2', 'spanish', 'Todas las mañanas me _____ antes de desayunar.', 'ducho', '[]', NULL, NULL, NULL, NULL, 'Ducharse es un verbo reflexivo. Primera persona singular del presente: me ducho.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82973cab-609a-4bf4-a617-f6fe8507422e', 1447, 'gap_fill', 'A2', 'spanish', 'Normalmente _____ a las ocho de la mañana.', 'desayuno', '[]', NULL, NULL, NULL, NULL, 'Desayunar significa to have breakfast. Primera persona singular del presente: desayuno.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('79662f1b-cd2a-421f-9e71-eb9581f59411', 1448, 'gap_fill', 'A2', 'spanish', 'Mi padre _____ muy temprano porque empieza a trabajar a las seis.', 'se levanta', '[]', NULL, NULL, NULL, NULL, 'Levantarse es un verbo reflexivo. Tercera persona singular del presente: se levanta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('949def93-9def-4163-aa26-4fff15179126', 1450, 'gap_fill', 'A2', 'spanish', 'Mi hermana _____ veinte minutos en arreglarse cada mañana.', 'tarda', '[]', NULL, NULL, NULL, NULL, 'Tardar significa to take (time). Tercera persona singular: tarda. Por ejemplo: tarde veinte minutos = I take twenty minutes.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0923-0923-0923-000000000923', 923, 'matching', 'C1', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "pragmatic"}, "right": {"type": "text", "content": "focused on practical results rather than theory"}}, {"left": {"type": "text", "content": "ambivalent"}, "right": {"type": "text", "content": "having mixed or contradictory feelings"}}, {"left": {"type": "text", "content": "tenuous"}, "right": {"type": "text", "content": "weak or unconvincing"}}, {"left": {"type": "text", "content": "nuanced"}, "right": {"type": "text", "content": "having subtle distinctions"}}, {"left": {"type": "text", "content": "pervasive"}, "right": {"type": "text", "content": "spreading widely through something"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0924-0924-0924-000000000924', 924, 'matching', 'C2', 'vocabulary', 'Match each word to its definition.', 'match_all_pairs', '[{"left": {"type": "text", "content": "obfuscate"}, "right": {"type": "text", "content": "to make something unclear or confusing"}}, {"left": {"type": "text", "content": "vacillate"}, "right": {"type": "text", "content": "to waver between different opinions"}}, {"left": {"type": "text", "content": "inveterate"}, "right": {"type": "text", "content": "having a habit too firmly established to change"}}, {"left": {"type": "text", "content": "perfidious"}, "right": {"type": "text", "content": "deceitful and untrustworthy"}}, {"left": {"type": "text", "content": "pellucid"}, "right": {"type": "text", "content": "transparently clear and easy to understand"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1b2c3d4-0925-0925-0925-000000000925', 925, 'matching', 'C2', 'vocabulary', 'Match each expression to its meaning.', 'match_all_pairs', '[{"left": {"type": "text", "content": "a foregone conclusion"}, "right": {"type": "text", "content": "a result that seems certain before it happens"}}, {"left": {"type": "text", "content": "to split hairs"}, "right": {"type": "text", "content": "to focus on trivial distinctions"}}, {"left": {"type": "text", "content": "to beg the question"}, "right": {"type": "text", "content": "to assume the truth of what you are trying to prove"}}, {"left": {"type": "text", "content": "a double-edged sword"}, "right": {"type": "text", "content": "something with both advantages and disadvantages"}}, {"left": {"type": "text", "content": "to take something at face value"}, "right": {"type": "text", "content": "to accept something without questioning it further"}}]', NULL, NULL, NULL, NULL, NULL, '2026-03-03 19:46:49.927263+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e588dfe5-460b-4119-ab93-0b1aef975411', 735, 'sentence_auction', 'B1', 'grammar', 'Theme: Present Perfect vs Past Simple', 'auction', '[{"correct": false, "sentence": "I have seen that film last week.", "explanation": "Wrong — use Past Simple with a finished time reference. It should be: \"I saw that film last week.\""}, {"correct": true, "sentence": "She has never been to New York.", "explanation": "Correct! Present Perfect used with \"never\" to describe a life experience — no specific time given."}, {"correct": false, "sentence": "We have finished the report yesterday.", "explanation": "Wrong — \"yesterday\" is a finished time reference, so Past Simple is needed: \"We finished the report yesterday.\""}, {"correct": true, "sentence": "Have you ever tried sushi?", "explanation": "Correct! Present Perfect with \"ever\" asking about a life experience."}, {"correct": false, "sentence": "He worked here since 2019.", "explanation": "Wrong — \"since\" requires Present Perfect: \"He has worked here since 2019.\""}, {"correct": true, "sentence": "They left the office an hour ago.", "explanation": "Correct! Past Simple with \"ago\" — a finished, specific time reference."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:02.6411+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f0e53da4-2b8d-44e1-a216-b87e11c87f03', 812, 'odd_one_out', 'B2', 'register', 'Three of these are words typical of formal or academic writing. Which is the odd one out?', 'gonna', '["hereby", "notwithstanding", "furthermore", "gonna"]', NULL, NULL, NULL, NULL, '"Hereby", "notwithstanding", and "furthermore" are all formal connectors and phrases. "Gonna" is very informal spoken English — it would raise a few eyebrows in a legal document.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('82263a7e-fd49-4c1e-b07e-7b5f55ab1a1b', 810, 'odd_one_out', 'B2', 'business', 'Three of these are types of employment contract. Which is the odd one out?', 'invoice', '["permanent", "temporary", "freelance", "invoice"]', NULL, NULL, NULL, NULL, 'Permanent, temporary, and freelance are all types of work arrangement. An invoice is a document requesting payment — important in business, but it is not a type of contract.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('afa303e5-35ab-4647-ac84-8a2c8a9d9df6', 1451, 'gap_fill', 'A2', 'spanish', 'Después de comer, mi abuelo siempre _____ una siesta corta.', 'echa', '[]', NULL, NULL, NULL, NULL, 'Echar una siesta es una expresión fija que significa to take a nap. Tercera persona singular de echar: echa.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7e2801c5-5790-4ea8-92c7-03bfab7f44bb', 1452, 'gap_fill', 'A2', 'spanish', 'Antes de acostarme, _____ mis cosas para el día siguiente.', 'preparo', '[]', NULL, NULL, NULL, NULL, 'Preparar es un verbo regular -ar. Primera persona singular del presente: preparo.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('58b610db-ef42-4070-bc89-a9b92c37f5fd', 1453, 'gap_fill', 'A2', 'spanish', 'Mi hermana _____ sin despertador todas las mañanas a la misma hora.', 'se despierta', '[]', NULL, NULL, NULL, NULL, 'Despertarse es reflexivo y cambia la raíz (e→ie): me despierto, te despiertas, se despierta.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7f2fccb9-f3c5-4289-b737-1cd38d565733', 736, 'sentence_auction', 'B2', 'grammar', 'Theme: Prepositions', 'auction', '[{"correct": false, "sentence": "She is very good in mathematics.", "explanation": "Wrong — the correct preposition is \"at\": \"She is very good at mathematics.\""}, {"correct": true, "sentence": "He depends on his parents for money.", "explanation": "Correct! \"Depend on\" is the right collocation."}, {"correct": false, "sentence": "I am not interested about your opinion.", "explanation": "Wrong — it should be \"interested in\": \"I am not interested in your opinion.\""}, {"correct": true, "sentence": "We need to concentrate on the main issues.", "explanation": "Correct! \"Concentrate on\" is the right collocation."}, {"correct": false, "sentence": "She is married with a doctor.", "explanation": "Wrong — it should be \"married to\": \"She is married to a doctor.\""}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:15.162556+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9bdfcb8d-ccb7-4372-9c0b-38869c69fe0e', 1454, 'gap_fill', 'A2', 'spanish', 'En casa, _____ sobre las nueve de la noche, lo cual es bastante normal en España.', 'cenamos', '[]', NULL, NULL, NULL, NULL, 'Cenar significa to have dinner. Primera persona plural del presente: cenamos.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cc6653cf-bad0-40d6-852c-5e23f936113b', 1455, 'gap_fill', 'A2', 'spanish', 'Por la mañana prefiero _____ un café antes de salir de casa.', 'tomar', '[]', NULL, NULL, NULL, NULL, 'Después de preferir + infinitivo, el infinitivo no cambia. Tomar un café significa to have a coffee en español.', '2026-03-17 09:30:11.660865+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('099d6261-6c66-4c4a-8dc1-d801b551911f', 1213, 'sentence_building', 'C2', 'routines', 'Los hábitos formados en la infancia temprana suelen ser extraordinariamente resistentes al cambio.', 'Habits formed early in childhood are often remarkably resistant to change.', '["habits", "formed", "early", "in", "childhood", "are", "often", "remarkably", "resistant", "to", "change", "made", "very", "difficult", "overcome", "adulthood"]', NULL, NULL, NULL, NULL, 'Formed is a past participle acting as a reduced relative clause (= habits that are formed). Resistant to is the correct collocation.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('44ab9fed-2126-48b9-9c75-88b23176782c', 815, 'odd_one_out', 'B2', 'phrasal verbs', 'Three of these phrasal verbs mean to "postpone". Which is the odd one out?', 'call off', '["put off", "push back", "hold off", "call off"]', NULL, NULL, NULL, NULL, '"Put off", "push back", and "hold off" can all mean to delay something. "Call off" means to cancel entirely — a stronger and different action. Don''t postpone — cancel!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Phrasal verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('54cf7faa-974f-40b5-9d4f-637da94cb83a', 814, 'odd_one_out', 'B2', 'academic writing', 'Three of these are reporting verbs. Which is the odd one out?', 'wonder', '["claim", "state", "argue", "wonder"]', NULL, NULL, NULL, NULL, '"Claim", "state", and "argue" are all reporting verbs used to introduce someone else''s words or ideas. "Wonder" expresses a personal thought or question — it does not report what someone said.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e9453fac-dadb-4c53-a5a2-0d8ec7f40b2c', 816, 'odd_one_out', 'B2', 'vocabulary', 'Three of these words describe something uncertain or unclear. Which is the odd one out?', 'categorical', '["vague", "ambiguous", "obscure", "categorical"]', NULL, NULL, NULL, NULL, '"Vague", "ambiguous", and "obscure" all mean unclear or difficult to understand. "Categorical" means clear, definite, and absolute — the complete opposite.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ccabca27-b3bf-42e3-8bb4-e9b449f026a0', 838, 'error_correction', 'B2', 'grammar', 'She is used to work late on Fridays.', 'She is used to working late on Fridays.', '[]', NULL, NULL, NULL, NULL, '"Be used to" is always followed by the -ing form: "She is used to working late." Compare with "used to + infinitive" for past habits: "She used to work there." Very different meanings from small differences in grammar.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aed19c47-2760-4be0-9885-66e949c813d4', 737, 'sentence_auction', 'C1', 'grammar', 'Theme: Articles (a / an / the / zero article)', 'auction', '[{"correct": false, "sentence": "The life is full of surprises.", "explanation": "Wrong — no article needed with abstract nouns used in a general sense: \"Life is full of surprises.\""}, {"correct": true, "sentence": "She plays the piano beautifully.", "explanation": "Correct! We use \"the\" with musical instruments."}, {"correct": false, "sentence": "He was sent to the prison for fraud.", "explanation": "Wrong — \"prison\" used institutionally takes zero article: \"He was sent to prison for fraud.\""}, {"correct": true, "sentence": "I had a most enjoyable evening.", "explanation": "Correct! \"A\" can be used before superlatives in exclamatory expressions."}, {"correct": false, "sentence": "The unemployment is rising in many countries.", "explanation": "Wrong — abstract nouns used generally take zero article: \"Unemployment is rising in many countries.\""}, {"correct": true, "sentence": "He arrived home late and went straight to bed.", "explanation": "Correct! \"Home\" and \"bed\" in these expressions take zero article."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 20:33:34.312863+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('782dab47-3a4d-4a8d-8928-7f7dc5031ff8', 819, 'odd_one_out', 'C1', 'academic language', 'Three of these are associated with logic and formal reasoning. Which is the odd one out?', 'rhetoric', '["premise", "syllogism", "inference", "rhetoric"]', NULL, NULL, NULL, NULL, 'A premise, syllogism, and inference are all elements of logical argument. Rhetoric is the art of persuasive language — it may use logic, but its primary focus is effect, not strict reasoning.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('eece4035-eff7-493e-8981-ab10c441e6bf', 821, 'odd_one_out', 'C1', 'vocabulary', 'Three of these describe a person who avoids clear commitment. Which is the odd one out?', 'decisive', '["evasive", "noncommittal", "equivocal", "decisive"]', NULL, NULL, NULL, NULL, '"Evasive", "noncommittal", and "equivocal" all describe someone who avoids giving clear answers or making clear choices. "Decisive" means someone who makes clear, confident decisions — the total opposite.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aba57a01-04aa-43ca-8fa8-35f8f515118a', 825, 'odd_one_out', 'C1', 'vocabulary', 'Three of these words suggest something is not quite right or dishonest. Which is the odd one out?', 'categorical', '["dubious", "suspect", "questionable", "categorical"]', NULL, NULL, NULL, NULL, '"Dubious", "suspect", and "questionable" all cast doubt on something''s honesty or validity. "Categorical" means absolute and clear — no doubt at all.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6a95762d-f81f-4f83-84f0-a4975b766cba', 822, 'odd_one_out', 'C2', 'linguistics', 'Three of these are related to linguistics. Which is the odd one out?', 'theorem', '["morpheme", "phoneme", "lexeme", "theorem"]', NULL, NULL, NULL, NULL, 'A morpheme (smallest unit of meaning), phoneme (unit of sound), and lexeme (unit of vocabulary) are all linguistic terms. A theorem is a proven mathematical or logical statement — different field entirely.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c1632c14-7596-41b8-8020-d346618e5bdb', 823, 'odd_one_out', 'C2', 'language/rhetoric', 'Three of these are rhetorical devices. Which is the odd one out?', 'ellipsis', '["hyperbole", "anaphora", "euphemism", "ellipsis"]', NULL, NULL, NULL, NULL, 'Hyperbole (exaggeration), anaphora (repetition at the start of clauses), and euphemism (polite substitution for something unpleasant) are rhetorical/stylistic devices. Ellipsis is primarily a grammatical and punctuation term — the omission of words or the three dots (...).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7196a9f6-a967-480b-85f1-eb2b985b375b', 1145, 'odd_one_out', 'A1', 'vocabulary', 'Which of these is NOT an insect?', 'spider', '["ant", "butterfly", "spider", "bee"]', NULL, NULL, NULL, NULL, 'A spider is an arachnid, not an insect. Insects have six legs and three body parts. Spiders have eight legs and two body parts.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('42210fc1-abb4-4610-b1b2-739993511b72', 1214, 'sentence_building', 'C1', 'routines', 'Ha convertido la atención plena en una parte innegociable de su rutina diaria.', 'She has made mindfulness a non-negotiable part of her daily routine.', '["she", "has", "made", "mindfulness", "a", "non-negotiable", "part", "of", "her", "daily", "routine", "essential", "practice", "fixed", "important", "meditation"]', NULL, NULL, NULL, NULL, 'Make + object + noun phrase (SVOC) expresses transformation: she has turned mindfulness into a fixed part of her routine.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e028634c-56ee-4e11-a4dd-250023f3bc93', 1215, 'sentence_building', 'A2', 'spanish', 'I normally have breakfast at eight in the morning.', 'Normalmente desayuno a las ocho de la mañana.', '["normalmente", "desayuno", "a", "las", "ocho", "de", "la", "mañana", "como", "siete", "tarde"]', NULL, NULL, NULL, NULL, 'Desayunar means to have breakfast. A las ocho means at eight o''clock. De la mañana means in the morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('53323794-0904-45c8-8a7b-c9a124ea9d32', 1216, 'sentence_building', 'A2', 'spanish', 'She always brushes her teeth before going to bed.', 'Ella siempre se cepilla los dientes antes de acostarse.', '["ella", "siempre", "se", "cepilla", "los", "dientes", "antes", "de", "acostarse", "después", "lavarse", "dormir"]', NULL, NULL, NULL, NULL, 'Cepillarse los dientes is a reflexive verb phrase. Antes de + infinitive means before doing something.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('30cd8854-87ba-4350-91cb-5dce239ec102', 1217, 'sentence_building', 'A2', 'spanish', 'We go for a walk every Sunday morning.', 'Damos un paseo todos los domingos por la mañana.', '["damos", "un", "paseo", "todos", "los", "domingos", "por", "la", "mañana", "caminamos", "sábados", "tarde"]', NULL, NULL, NULL, NULL, 'Dar un paseo is the fixed expression for to go for a walk. Por la mañana means in the morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f9b060e-49f5-41a0-9923-a4df59887572', 832, 'error_correction', 'A1', 'grammar', 'She goed to school by bus.', 'She went to school by bus.', '["She goes to school by bus."]', NULL, NULL, NULL, NULL, '"Go" is an irregular verb. Its "goes" in the present 3rd person not "goed", and its past simple form is "went". English irregular verbs are a difficult to remember, but they are worth learning!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1fa32306-0ec6-4dd7-8012-468e3a675b43', 830, 'error_correction', 'A1', 'grammar', 'He have a new car.', 'He has a new car.', '[]', NULL, NULL, NULL, NULL, 'With he, she, or it, we use "has", not "have". He has a new car. ', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cc508ab3-8552-44df-9d67-ac057b52fb4b', 739, 'multiple_choice', 'A1', 'food', 'Which of these is a fruit?', 'mango', '["carrot", "onion", "mango", "potato"]', NULL, NULL, NULL, NULL, 'A mango is a fruit — sweet and delicious. The others are vegetables.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bdd11698-96cc-49a8-b25f-9c9b28244fa1', 827, 'odd_one_out', 'C2', 'academic vocabulary', 'Three of these are economic concepts. Which is the odd one out?', 'jurisprudence', '["stagflation", "quantitative easing", "deflation", "jurisprudence"]', NULL, NULL, NULL, NULL, 'Stagflation (stagnation + inflation), quantitative easing (central bank asset purchasing), and deflation (falling prices) are all economic concepts. Jurisprudence is the theory and philosophy of law — different field.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f7ea256f-ec0c-4035-ba6d-605d5ab00bc9', 1147, 'odd_one_out', 'A2', 'vocabulary', 'Which of these is NOT a fruit?', 'carrot', '["apple", "banana", "parsnip", "mango"]', NULL, NULL, NULL, NULL, 'A carrot is a vegetable, not a fruit. Fruits develop from the flower of a plant and contain seeds. Parsnips are roots.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e4f7eec-2b8d-4206-9133-5616fa549e1e', 1219, 'sentence_building', 'A2', 'spanish', 'I usually read for a while before falling asleep.', 'Normalmente leo un rato antes de quedarme dormido.', '["normalmente", "leo", "un", "rato", "antes", "de", "quedarme", "dormido", "después", "dormir", "siempre"]', NULL, NULL, NULL, NULL, 'Quedarse dormido means to fall asleep. Antes de + infinitive means before doing something. Un rato means a while.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a30bd0bb-1e3a-4f0e-81f5-0388f69134dd', 1220, 'sentence_building', 'A2', 'spanish', 'My mother makes coffee every morning without fail.', 'Mi madre hace café todas las mañanas sin falta.', '["mi", "madre", "hace", "café", "todas", "las", "mañanas", "sin", "falta", "padre", "toma", "noches"]', NULL, NULL, NULL, NULL, 'Sin falta means without fail or without exception. Todas las mañanas means every morning.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a116c346-3eea-4264-ac8b-e825b7051eb2', 1221, 'sentence_building', 'A2', 'spanish', 'They usually have dinner at nine o''clock.', 'Normalmente cenan a las nueve.', '["normalmente", "cenan", "a", "las", "nueve", "comen", "siete", "tarde", "siempre"]', NULL, NULL, NULL, NULL, 'Cenar means to have dinner. The third person plural form is cenan. A las nueve means at nine o''clock.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('51853a7f-8416-480a-bb2b-bc1cb16bb8a4', 1222, 'sentence_building', 'A2', 'spanish', 'I try to go to the gym three times a week.', 'Intento ir al gimnasio tres veces a la semana.', '["intento", "ir", "al", "gimnasio", "tres", "veces", "a", "la", "semana", "voy", "dos", "mes"]', NULL, NULL, NULL, NULL, 'Intentar + infinitive means to try to do something. Al is a contraction of a + el. Tres veces a la semana means three times a week.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6f5c8d4d-361b-4db4-825c-c60a015dd747', 1223, 'sentence_building', 'A2', 'spanish', 'She gets up early even on weekends.', 'Ella se levanta temprano incluso los fines de semana.', '["ella", "se", "levanta", "temprano", "incluso", "los", "fines", "de", "semana", "tarde", "siempre", "días"]', NULL, NULL, NULL, NULL, 'Levantarse is the reflexive verb meaning to get up. Incluso means even. Los fines de semana means at weekends.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c3f6f4e3-a70d-4835-a4c6-6969d6e4d975', 740, 'multiple_choice', 'A1', 'grammar', '"She ___ to school by bus every day."', 'goes', '["go", "goes", "going", "gone"]', NULL, NULL, NULL, NULL, 'With he/she/it in the present simple, we add -s or -es to the verb. She goes.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('35587e4d-44d8-463e-a4fa-f99cb3fc215a', 741, 'multiple_choice', 'A1', 'vocabulary', 'Which word means the opposite of "cheap"?', 'expensive', '["expensive", "small", "new", "fast"]', NULL, NULL, NULL, NULL, 'Cheap means low price. Expensive means high price. The others describe size, age, and speed.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4eb66a4a-0fc7-4519-82d8-d7c9fc14806b', 1224, 'sentence_building', 'A2', 'spanish', 'I check my phone first thing every morning.', 'Miro el móvil nada más levantarme cada mañana.', '["miro", "el", "móvil", "nada", "más", "levantarme", "cada", "mañana", "veo", "despertarme", "tarde", "siempre"]', NULL, NULL, NULL, NULL, 'Nada más + infinitive means as soon as or right after. Móvil is the Spanish word for mobile phone.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'es', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('58f203b2-e7dc-40fb-aeb2-91d40af8e155', 644, 'sentence_building', 'A1', 'family', 'Tengo un hermano y una hermana.', 'I have a brother and a sister', '["I", "have", "a", "brother", "and", "a", "sister", "the", "has"]', NULL, NULL, NULL, NULL, 'Tener = to have. Use "a" before singular family members.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3acc6fa5-61dc-4911-b14b-441c82727cb5', 210, 'gap_fill', 'A1', 'present_simple', 'She ___ (watch) TV every evening.', 'watches', NULL, NULL, NULL, NULL, NULL, 'Verbs ending in -ch: add -es for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c6a62f3e-3e7d-41e5-aca0-fe205323c1cc', 667, 'sentence_building', 'C2', 'formal_register', '', 'were it not for the generous support of our sponsors this event would never have taken place', '["were", "it", "not", "for", "the", "generous", "support", "of", "our", "sponsors", "this", "event", "would", "never", "have", "taken", "place", "did", "took", "been"]', NULL, NULL, NULL, NULL, 'Were it not for: formal inverted conditional meaning "If it were not for".', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Formal register"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1907ffa-9f00-4748-9393-a8632361748d', 634, 'sentence_building', 'A2', 'question_forms', '', 'what time does the shop open', '["what", "time", "does", "the", "shop", "open", "is", "do"]', NULL, NULL, NULL, NULL, 'For questions about time with he/she/it subjects, use: What time + does + subject + verb.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('843f42e2-c8ce-4229-ab61-5e1db6b4f8de', 641, 'sentence_building', 'A1', 'present_simple', '', 'I go to work every day', '["I", "go", "to", "work", "every", "day", "night", "goes"]', '["every day I go to work."]', 'If you put the time phrase at the end it is more natural.', NULL, NULL, 'Simple present routine: subject + verb + place + time expression.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e2383405-4c2e-4d30-956b-d43bc27753ca', 1153, 'odd_one_out', 'A2', 'vocabulary', 'Which of these is NOT a sport?', 'chess', '["football", "swimming", "chess", "tennis"]', NULL, NULL, NULL, NULL, 'Chess is a board game, not usually considered a sport — though this is debated! (I think it is a sport...) Football, swimming, and tennis all involve physical activity and are universally recognised as sports.', '2026-03-16 08:29:27.085219+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('451c47e3-eea2-48ca-a1f3-06d37979b29c', 604, 'sentence_building', 'B2', 'polite_requests', 'Me gustaría solicitar un día libre la semana que viene.', 'I would like to request a day off next week', '["I", "would", "like", "to", "request", "a", "day", "off", "next", "week", "want", "free", "this"]', NULL, NULL, NULL, NULL, '"Would like to request" is the polite formal structure. "A day off" = un día libre. "Free" is a false friend — we say "day off", not "free day".', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Making suggestions"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4dae8217-d0fc-4a91-a914-73ef5eea7e8e', 602, 'sentence_building', 'B1', 'polite_requests', '¿Podrías enviarme el informe antes del viernes?', 'could you send me the report before Friday', '["could", "you", "send", "me", "the", "report", "before", "friday", "should", "after", "to"]', NULL, NULL, NULL, NULL, '"Could you" is used for polite requests. "Before" = antes de. Both "send me" and "send to me" are correct.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Making suggestions"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1a995a8c-d33a-4f51-8f99-9081f9cd9cf0', 642, 'sentence_building', 'A1', 'present_simple', '', 'she likes drinking coffee in the morning', '["she", "likes", "drinking", "coffee", "in", "the", "morning", "liking", "at"]', '["in the morning she likes drinking coffee."]', 'If you put the time phrase at the end it is more natural.', NULL, NULL, 'Present simple with gerund: She likes + -ing form.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6e8832f3-53f2-417a-b552-a3c0337eb89b', 635, 'sentence_building', 'A2', 'present_simple', '', 'my sister lives in a small town', '["my", "sister", "lives", "in", "a", "small", "town", "is", "the"]', NULL, NULL, NULL, NULL, 'In present simple, ''she lives'' takes -s. Adjectives go before the noun: ''a small town'' not ''a town small''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aba73cd8-605b-4046-bb73-1d15c3793afc', 629, 'sentence_building', 'A2', 'present_simple', 'Siempre desayuno a las ocho.', 'I always have breakfast at eight', '["I", "always", "have", "breakfast", "at", "eight", "eat", "the"]', NULL, NULL, '["I have breakfast at eight ."]', NULL, 'Adverbs of frequency (always, usually, never) go before the main verb. ''I always have breakfast'' not ''I have always breakfast''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('80e10461-daf9-446f-95bd-e1065f08257b', 639, 'sentence_building', 'A2', 'present_continuous', '', 'she is wearing a red dress', '["she", "is", "wearing", "a", "red", "dress", "wear", "the"]', NULL, NULL, NULL, NULL, 'Use present continuous (is + -ing) to describe what someone is doing or wearing now. ''She is wearing'' not ''she wears'' for right now.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fb8fe35d-9914-4f83-8701-6d831b46bab2', 632, 'sentence_building', 'A2', 'present_continuous', '', 'we are going to the beach', '["we", "are", "going", "to", "the", "beach", "will", "a"]', NULL, NULL, NULL, NULL, '''We are going to'' describes a plan or movement. ''Are going'' is the present continuous of ''go''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('10c093a9-6204-4477-97ae-486fc4478a39', 652, 'sentence_building', 'B1', 'present_perfect', '', 'I have lived here since I was a child', '["I", "have", "lived", "here", "since", "I", "was", "a", "child", "for", "living", "am"]', NULL, NULL, NULL, NULL, 'Present perfect with "since" + point in time. Describes duration from past to now.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c6d7b013-7ddd-4633-a3ff-c6c2b2e04a8a', 645, 'sentence_building', 'A1', 'present_simple', 'Ella no come carne.', 'She does not eat meat', '["she", "does", "not", "eat", "meat", "don''t", "do", "eats", "fish"]', NULL, NULL, NULL, NULL, 'Negative present simple: subject + does not + base verb.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('01b2c34e-1003-4091-b7f6-b45dd1397915', 611, 'sentence_building', 'B1', 'present_perfect_continuous', NULL, 'she has been working here since January', '["she", "has", "been", "working", "here", "since", "january", "is", "from", "at"]', NULL, NULL, NULL, NULL, 'Present perfect continuous (has been working) + "since" for a specific point in time.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('06881467-f7b6-4ef8-becf-d0fc74ff2d5a', 624, 'sentence_building', 'A2', 'present_simple', 'No me gusta el café.', 'I do not like coffee', '["I", "do", "not", "like", "coffee", "am", "the"]', NULL, NULL, NULL, NULL, 'To make a negative sentence in present simple, we use: subject + do/does + not + verb. ''I do not like coffee.''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b21fb022-74be-4477-a968-b37f467b3b56', 637, 'sentence_building', 'A2', 'present_simple', '', 'he usually walks to work', '["he", "usually", "walks", "to", "work", "is", "goes"]', NULL, NULL, '["he walks to work ."]', NULL, 'Adverbs of frequency go before the main verb. ''He usually walks'' — ''walks'' because he/she/it takes -s.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('29c29c3a-0067-4f02-86be-485eaab0ea6a', 618, 'sentence_building', 'B1', 'present_perfect', NULL, 'I have never been to Scotland but I would love to go', '["I", "have", "never", "been", "to", "scotland", "but", "I", "would", "love", "to", "go", "always", "hate", "from"]', NULL, NULL, NULL, NULL, 'Present perfect for life experience (have never been) + "would love to" for desire. "Been to" = visited.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ad6b0e51-2191-45c1-89c2-845d72163fef', 609, 'sentence_building', 'B1', 'present_continuous', 'Mis compañeros están preparando una presentación para el cliente.', 'my colleagues are preparing a presentation for the client', '["my", "colleagues", "are", "preparing", "a", "presentation", "for", "the", "client", "friends", "making", "from"]', NULL, NULL, NULL, NULL, 'Present continuous for current activities. "Preparing a presentation" and "for the client" are standard collocations.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1bda82b9-a6cd-4602-981c-c4e813c25f77', 675, 'odd_one_out', 'B1', 'adjectives', 'Which word does NOT describe personality?', 'enormous', '["generous", "reliable", "enormous", "cheerful"]', NULL, NULL, NULL, NULL, '"Enormous" describes size, not personality.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Adjective}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ee3df3b4-97ae-46d2-bf00-64eab8945260', 722, 'odd_one_out', 'B1', 'irregular_verbs', 'Which is NOT an irregular verb?', 'play', '["go", "eat", "play", "swim"]', NULL, NULL, NULL, NULL, '"Play" is regular (play → played → played). The others are irregular.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Irregular verb"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('89a72a2f-e49b-49d0-8e1e-cb87372fc41c', 700, 'odd_one_out', 'A1', 'days_and_months', 'Which one is NOT a day of the week?', 'tomorrow', '["Monday", "tomorrow", "Friday", "Sunday"]', NULL, NULL, NULL, NULL, '"Tomorrow" is not a day of the week.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Time expression"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fc6040c4-5d44-442e-a1e6-21aba606b9e6', 726, 'odd_one_out', 'A2', 'family', 'Which one is NOT a family member?', 'neighbour', '["uncle", "cousin", "neighbour", "grandmother"]', NULL, NULL, NULL, NULL, '"Neighbour" is someone who lives nearby, not a family member.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a2bcf68e-527d-4017-9118-6788aa4394bb', 706, 'odd_one_out', 'A1', 'food', 'Which one is NOT food?', 'snails', '["bread", "cheese", "snails", "rice"]', NULL, NULL, NULL, NULL, 'A "snail" is a mollusc, not food. Some people disagree, I know...', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('91083ef4-0fba-4711-803b-1fd90af6d227', 702, 'odd_one_out', 'A2', 'jobs', 'Which one is NOT a job?', 'teach', '["builder", "doctor", "teach", "nurse"]', NULL, NULL, NULL, NULL, '"Teach" is a verb, not a job. Teacher is arguably a job, it depends on your teacher... ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bd040507-4420-43c2-b022-a1b65fc4f812', 710, 'odd_one_out', 'A1', 'numbers', 'Which one is NOT a number?', 'many', '["many", "twelve", "seven", "three"]', NULL, NULL, NULL, NULL, '"Many" is a quantifier, not a number.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c49050be-42a2-49fd-8a07-fd7ad273b31d', 713, 'odd_one_out', 'A2', 'weather', 'Which one is NOT weather?', 'soft', '["sunny", "rainy", "soft", "cloudy"]', NULL, NULL, NULL, NULL, '"Soft" describes many things, not the weather generally. We can say ''soft wind'' or ''soft rain'' though. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('47e97981-6a12-4b87-8626-49772f477d9f', 687, 'odd_one_out', 'A2', 'transport', 'Which one is NOT a means of transport?', 'sheep', '["bus", "train", "sheep", "bicycle"]', NULL, NULL, NULL, NULL, 'A "sheep" is an animal, not transport. They do not like it if you try to ride them 😉. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('922a6b47-00cb-4d81-a89a-e23f67b93afe', 703, 'odd_one_out', 'A1', 'animals', 'Which one is NOT an animal?', 'mushroom', '["cat", "dog", "horse", "mushroom"]', NULL, NULL, NULL, NULL, 'A "mushroom" is an fungi not an animal. Nor a vegetable. ', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dffc2de6-41c4-4e69-ac9d-a4bcf05ed647', 719, 'odd_one_out', 'A1', 'colours', 'Which one is NOT a colour?', 'clear', '["red", "blue", "green", "clear"]', NULL, NULL, NULL, NULL, '"Clear" is an adjective describing transparency, or the absence of colour,  it is not a colour.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c3e5135f-7c4e-4d41-86cb-504ccd2c5f50', 712, 'odd_one_out', 'C2', 'euphemisms', 'Which is NOT a euphemism?', 'blunt', '["passed away", "let go", "blunt", "economical with the truth"]', NULL, NULL, NULL, NULL, '"Blunt" is direct, the opposite of euphemistic. The others soften difficult truths.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('38ba09f0-abf6-47d3-a3c3-ea5308108936', 686, 'odd_one_out', 'C2', 'literary_devices', 'Which literary device is NOT about comparison?', 'alliteration', '["simile", "metaphor", "alliteration", "analogy"]', NULL, NULL, NULL, NULL, '"Alliteration" is repetition of initial sounds. The others compare things.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Academic English"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('591e6f0f-cf44-40ac-9dab-548caf501104', 616, 'sentence_building', 'B1', 'reported_speech', NULL, 'he told me that he was leaving the company', '["he", "told", "me", "that", "he", "was", "leaving", "the", "company", "said", "are", "join"]', NULL, NULL, NULL, NULL, 'Reported speech: told + person + that + past tense. "Told me" requires an object; "said" does not.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{"Reported speech"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b2a3c455-c10f-4ac6-b3d7-acd614db2609', 1226, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Can you _____ the new employee on the office rules?', 'fill in', '["fill in", "fill up", "fill out", "fill over"]', NULL, NULL, NULL, NULL, 'Fill someone in means to give them information they are missing. Compare: bring someone up to speed.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('816c0101-8d78-4561-9a04-caafd19b50dc', 1227, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'We need to _____ a new supplier before the end of the month.', 'take on', '["take on", "take off", "take up", "take over"]', NULL, NULL, NULL, NULL, 'Take on means to hire someone or start using a new supplier or partner.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6d187e8d-54c8-4783-81c0-797476d2956f', 1228, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'Please _____ the contract before you sign it.', 'look over', '["look over", "look up", "look after", "look into"]', NULL, NULL, NULL, NULL, 'Look over means to read or check something quickly to see if it is correct.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c896f954-560c-4f10-a112-84cb850fccd1', 1229, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'The deal _____ because the two sides couldn''t agree on the price.', 'fell through', '["fell through", "fell over", "fell out", "fell behind"]', NULL, NULL, NULL, NULL, 'Fall through means a plan or deal fails to happen. Compare: the merger fell through.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('23d6b23f-8243-4824-94a5-aca23d20ccb5', 1230, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'We need to _____ costs if we want to stay profitable this quarter.', 'cut down on', '["cut down on", "cut out", "cut off", "cut up"]', NULL, NULL, NULL, NULL, 'Cut down on means to reduce the amount or level of something. Compare: cut back on spending.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('05465e73-3ebf-4edc-bc76-7d338ed55588', 1231, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'She _____ the sales report to her manager every Friday.', 'sends off', '["sends off", "sends over", "sends up", "sends out"]', NULL, NULL, NULL, NULL, 'Send off means to send something to someone, often formally. Send out is also possible but send off implies dispatching something specific.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c6d9f734-ede8-438b-b88b-394eba3d58e1', 1232, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The new manager wants to _____ some changes in the department.', 'bring in', '["bring in", "bring up", "bring out", "bring over"]', NULL, NULL, NULL, NULL, 'Bring in means to introduce new ideas, rules, or people to an organisation.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('08ef2fca-7500-4151-b07d-663f60d8f92b', 1233, 'multiple_choice', 'A1', 'business_phrasal_verbs', 'I need to _____ the report before the deadline tomorrow.', 'hand in', '["hand in", "hand out", "hand over", "hand back"]', NULL, NULL, NULL, NULL, 'Hand in means to give a piece of work to someone in authority, such as a manager or teacher.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0ca683a7-196d-47f7-928b-56217c4b083f', 1234, 'multiple_choice', 'A2', 'business_phrasal_verbs', 'The project is _____ schedule — we need to work faster.', 'behind', '["behind", "under", "below", "off"]', NULL, NULL, NULL, NULL, 'Behind schedule means later than planned. Compare: ahead of schedule (earlier than planned), on schedule (on time).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e8ea1ccf-6b18-4f6f-b279-2deb434e445d', 1235, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The board decided to _____ the merger after concerns were raised by shareholders.', 'call off', '["call off", "call up", "call out", "call back"]', NULL, NULL, NULL, NULL, 'Call off means to cancel something that was planned. Compare: the strike was called off after negotiations succeeded.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f1ad904e-25a5-4009-86c1-8df4c4cc94f2', 1236, 'multiple_choice', 'B2', 'business_phrasal_verbs', 'We''ve had to _____ several staff members due to the drop in demand.', 'lay off', '["lay off", "lay out", "lay down", "lay up"]', NULL, NULL, NULL, NULL, 'Lay off means to dismiss employees because of a lack of work, not because of poor performance. Compare: make redundant.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('696cefba-f86b-42be-a6b6-2a6905d7ece5', 695, 'error_correction', 'A1', 'singular_plural', 'I have two sister and a brother.', 'I have two sisters and a brother.', '[]', NULL, NULL, NULL, NULL, 'We need the plural form: "two sisters".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{Plural}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('44f4ab6e-60b5-4038-b6b7-f9c469583b7c', 727, 'matching', 'A1', 'vocabulary', 'Match the English words to their Spanish translations.', 'match_all_pairs', '[{"left": {"type": "text", "content": "new"}, "right": {"type": "text", "content": "nuevo"}}, {"left": {"type": "text", "content": "old"}, "right": {"type": "text", "content": "viejo"}}, {"left": {"type": "text", "content": "big"}, "right": {"type": "text", "content": "grande"}}, {"left": {"type": "text", "content": "small"}, "right": {"type": "text", "content": "pequeño"}}, {"left": {"type": "text", "content": "beautiful"}, "right": {"type": "text", "content": "bonito"}}]', NULL, NULL, NULL, NULL, NULL, '2026-02-25 12:16:31.110712+00', NULL, NULL, 'both', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9b0de821-3f61-4484-8a45-583e7b33191f', 742, 'multiple_choice', 'A1', 'social', 'What do you say when you leave someone at the end of the day?', 'Goodbye', '["Good morning", "How are you?", "Goodbye", "Nice to meet you"]', NULL, NULL, NULL, NULL, '"Goodbye" is used when you leave or end a conversation. "Good morning" is a greeting, not a farewell.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{Vocabulary}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a0c68e2d-b29e-4b57-8979-4bbfb124a077', 743, 'multiple_choice', 'A1', 'grammar', '"There ___ a lot of people at the market today."', 'are', '["is", "are", "am", "be"]', NULL, NULL, NULL, NULL, '"People" is a plural noun, so we use "are". There are many people. There is one person.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b7cc2ab4-42cd-4784-8cd4-61b8bd442b55', 745, 'multiple_choice', 'A2', 'grammar', '"We ___ football last Saturday."', 'played', '["play", "plays", "played", "playing"]', NULL, NULL, NULL, NULL, '"Last Saturday" tells us this is in the past, so we use the past simple: played.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e8f7951-bc86-42b1-bc9b-26cf7fd3fec6', 747, 'multiple_choice', 'A2', 'grammar', '"How long ___ you been learning English?"', 'have', '["have", "did", "are", "do"]', NULL, NULL, NULL, NULL, '"How long have you been...?" uses the present perfect continuous. It asks about something that started in the past and continues now.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('150f4c9c-6e3e-4b5d-abb5-a33ee4babf9f', 748, 'multiple_choice', 'A2', 'grammar', 'Which sentence is correct?', 'She is taller than me.', '["She is more tall than me.", "She is taller than me.", "She is tallest than me.", "She is tall than me."]', NULL, NULL, NULL, NULL, 'For short adjectives (one syllable), we add -er to compare two things: taller, shorter, cheaper.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('854422b4-d4c2-41fe-85f0-dd4f1c5d16f6', 749, 'multiple_choice', 'A2', 'grammar', '"I ___ watch TV when I was young, but now I prefer reading."', 'used to', '["used to", "use to", "was used to", "would use to"]', NULL, NULL, NULL, NULL, '"Used to + infinitive" describes habits or states in the past that are no longer true. "I used to watch TV" means I don''t watch much anymore.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e15d4a02-63fa-4831-a3de-1e7b31f00339', 750, 'multiple_choice', 'A2', 'vocabulary', 'Which word completes the sentence? "Can you ___ me how to get to the station?"', 'tell', '["say", "tell", "speak", "talk"]', NULL, NULL, NULL, NULL, 'We "tell someone something". We "say something". So: "Can you tell me...?" not "Can you say me...?"', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f102d248-786a-4935-992c-fb03a43538a8', 751, 'multiple_choice', 'A2', 'grammar', '"She hasn''t phoned me ___ three weeks."', 'for', '["since", "for", "ago", "during"]', NULL, NULL, NULL, NULL, 'Use "for" with a period of time (for three weeks, for an hour). Use "since" with a point in time (since Monday, since 2020).', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ff9768bd-47c4-4a58-b950-0413925e40f9', 753, 'multiple_choice', 'A2', 'grammar', '"The film ___ two hours ago."', 'started', '["starts", "has started", "started", "is starting"]', NULL, NULL, NULL, NULL, '"Two hours ago" is a finished time in the past, so we use the past simple: started.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e878f55-bd11-4601-8038-a1dd73e49e66', 755, 'multiple_choice', 'A2', 'grammar', '"You ___ take an umbrella — it might rain later."', 'should', '["should", "must", "can", "will"]', NULL, NULL, NULL, NULL, '"Should" gives friendly advice. "Must" is stronger (a rule or obligation). Here we are just suggesting — take an umbrella!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5ebbe87d-ea16-4a69-aa07-2daec478f4c5', 858, 'sentence_auction', 'A1', 'grammar', 'Theme: He, She, It — does or doesn''t?', 'auction', '[{"correct": true, "sentence": "She doesn''t like spicy food.", "explanation": "Correct! We use doesn''t with he/she/it in negative present simple."}, {"correct": false, "sentence": "He go to work by bus every day.", "explanation": "Wrong — he/she/it needs an -s: ''He goes to work by bus every day.''"}, {"correct": false, "sentence": "My brother play football on Sundays.", "explanation": "Wrong — third person singular needs -s: ''My brother plays football on Sundays.''"}, {"correct": true, "sentence": "The cat sleeps on the sofa.", "explanation": "Correct! The cat = third person singular, so sleeps is right."}, {"correct": true, "sentence": "Does your sister speak English?", "explanation": "Correct! Does + infinitive (no -s) for questions with he/she/it."}, {"correct": false, "sentence": "He doesn''t speaks French.", "explanation": "Wrong — after doesn''t, use the infinitive: ''He doesn''t speak French.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('30ab2d2d-4e69-442f-b1ee-838f48877a4a', 655, 'sentence_building', 'B1', 'second_conditional', 'Si tuviera mas tiempo, aprendería a tocar la guitarra.', 'if I had more time I would learn to play the guitar', '["if", "I", "had", "more", "time", "I", "would", "learn", "to", "play", "the", "guitar", "will", "have", "played"]', '["I would learn to play the guitar if I had more time.", "I would learn to play the guitar if I had more time ."]', NULL, NULL, NULL, 'Second conditional: If + past simple, would + infinitive. Used for unreal or unlikely situations.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e3094ad4-822f-4822-9501-24979fc8d271', 651, 'sentence_building', 'B1', 'first_conditional', '', 'if it rains tomorrow we will stay at home', '["if", "it", "rains", "tomorrow", "we", "will", "stay", "at", "home", "would", "stayed", "rained"]', NULL, NULL, NULL, NULL, 'First conditional: If + present simple, will + infinitive. Used for real future possibilities. Either clause can go first in the sentence.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Conditional}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('90ec15b8-4fb4-4b8a-a598-de29a4bab397', 668, 'sentence_building', 'C2', 'inversion', 'Bajo ningun concepto deberia haberse tomado esa decision sin consultarnos.', 'under no circumstances should that decision have been made without consulting us', '["under", "no", "circumstances", "should", "that", "decision", "have", "been", "made", "without", "consulting", "us", "hardly", "making", "the", "consult"]', NULL, NULL, NULL, NULL, 'Under no circumstances + inverted auxiliary: emphatic prohibition. Passive perfect infinitive.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be380d41-47f0-4c14-9d0e-c9bbb2e569ae', 619, 'sentence_building', 'C1', 'inversion', NULL, 'not only did she pass the exam but she also got the highest mark', '["not", "only", "did", "she", "pass", "the", "exam", "but", "she", "also", "got", "the", "highest", "mark", "failed", "lowest", "however"]', NULL, NULL, NULL, NULL, 'Inversion with "not only...but also": not only + auxiliary + subject + verb. Emphasises both achievements.', '2026-02-12 14:34:46.611844+00', NULL, NULL, 'en', '{Inversion}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('771d75bc-dbce-4a9d-b1be-4c6696751112', 603, 'sentence_building', 'B2', 'present_perfect', 'La empresa ha decidido ampliar su equipo de ventas.', 'the company has decided to expand its sales team', '["the", "company", "has", "decided", "to", "expand", "its", "sales", "team", "their", "reduce", "group"]', NULL, NULL, NULL, NULL, '"Its" (not "their") is correct for a singular company. "Expand" = ampliar. "Sales team" is the standard business term.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2088af5c-3dcb-40eb-899c-8d6e807826cb', 840, 'error_correction', 'B1', 'grammar', 'She is the most talented of the two candidates.', 'She is the more talented of the two candidates.', '[]', NULL, NULL, NULL, NULL, 'When comparing exactly two people or things, use the comparative (-er / more). Use the superlative (-est / most) for three or more. She is the more talented of the two.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('628c3414-9075-458a-b695-1394a32c9540', 859, 'sentence_auction', 'A1', 'grammar', 'Theme: Present Continuous — what is happening right now?', 'auction', '[{"correct": true, "sentence": "They are watching a film at the moment.", "explanation": "Correct! Are + watching — perfect present continuous."}, {"correct": false, "sentence": "She is study for her exam right now.", "explanation": "Wrong — you need the -ing form: ''She is studying for her exam.''"}, {"correct": false, "sentence": "I am not understand this question.", "explanation": "Wrong — ''understand'' is a state verb. We don''t use it in continuous: ''I don''t understand this question.''"}, {"correct": true, "sentence": "He is wearing a red jacket today.", "explanation": "Correct! Is + wearing — describing something happening now."}, {"correct": true, "sentence": "Are you listening to me?", "explanation": "Correct! Are + listening — perfect question form."}, {"correct": false, "sentence": "We is having a great time!", "explanation": "Wrong — with ''we'', use are: ''We are having a great time!''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('16d9a762-88dd-491e-9209-af843f953172', 860, 'sentence_auction', 'A2', 'grammar', 'Theme: Question word order — do the words go in the right order?', 'auction', '[{"correct": true, "sentence": "Where does she live?", "explanation": "Correct! Question word + does + subject + infinitive — perfect."}, {"correct": false, "sentence": "What time you wake up?", "explanation": "Wrong — you need the auxiliary: ''What time do you wake up?''"}, {"correct": true, "sentence": "How old is your brother?", "explanation": "Correct! With the verb ''to be'', we invert: How old + is + subject."}, {"correct": false, "sentence": "Why he is angry?", "explanation": "Wrong — invert the subject and auxiliary: ''Why is he angry?''"}, {"correct": true, "sentence": "Who is your favourite teacher?", "explanation": "Correct! When ''who'' is the subject, no auxiliary needed."}, {"correct": true, "sentence": "What does ''curious'' mean?", "explanation": "Correct! Does + subject + infinitive — the word order is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c1f8311a-0688-44c3-8ec3-26a0d8bd4813', 861, 'sentence_auction', 'A1', 'grammar', 'Theme: There is / There are — singular or plural?', 'auction', '[{"correct": true, "sentence": "There are three windows in this room.", "explanation": "Correct! Three windows = plural, so we use ''there are''."}, {"correct": false, "sentence": "There is a lot of people in the street.", "explanation": "Wrong — ''people'' is plural: ''There are a lot of people in the street.''"}, {"correct": true, "sentence": "Is there any milk in the fridge?", "explanation": "Correct! ''Milk'' is uncountable — ''is there'' is right."}, {"correct": false, "sentence": "There are a good restaurant near here.", "explanation": "Wrong — one restaurant = singular: ''There is a good restaurant near here.''"}, {"correct": true, "sentence": "There isn''t any bread left.", "explanation": "Correct! ''Bread'' is uncountable — ''there isn''t'' is perfect."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('81df3985-f19b-43fa-9f28-e49ed8488b96', 862, 'sentence_auction', 'A1', 'grammar', 'Theme: Can and can''t — ability and possibility', 'auction', '[{"correct": false, "sentence": "She can to swim very well.", "explanation": "Wrong — modal verbs never use ''to'': ''She can swim very well.''"}, {"correct": true, "sentence": "Can you help me, please?", "explanation": "Correct! Can + subject + infinitive — perfect question form."}, {"correct": true, "sentence": "He can''t drive a car.", "explanation": "Correct! Can''t + infinitive — no -s, no ''to''."}, {"correct": true, "sentence": "I can speak three languages.", "explanation": "Correct! Can + infinitive — simple and clean."}, {"correct": false, "sentence": "Can she to play the guitar?", "explanation": "Wrong — no ''to'' after can: ''Can she play the guitar?''"}, {"correct": false, "sentence": "He can''t drives a car.", "explanation": "Wrong — after can/can''t, always use the infinitive: ''He can''t drive.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('21c64191-3530-403c-a621-b75f92e6da35', 863, 'sentence_auction', 'A2', 'grammar', 'Theme: Articles — a, an, or the?', 'auction', '[{"correct": true, "sentence": "She is an engineer.", "explanation": "Correct! ''Engineer'' starts with a vowel sound — so we use ''an''."}, {"correct": true, "sentence": "He is the best student in the class.", "explanation": "Correct! ''The best'' — superlatives always use ''the''."}, {"correct": true, "sentence": "I want to be a doctor.", "explanation": "Correct! Jobs use ''a/an'' — ''a doctor'' is right."}, {"correct": false, "sentence": "She is a honest person.", "explanation": "Wrong — ''honest'' starts with a vowel sound (the h is silent): ''She is an honest person.''"}, {"correct": true, "sentence": "He plays the guitar every evening.", "explanation": "Correct! Musical instruments use ''the'': the guitar, the piano."}, {"correct": false, "sentence": "She plays a piano.", "explanation": "Wrong — musical instruments take ''the'': ''She plays the piano.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('aa134200-7ec9-4b51-9797-bd9c645220cd', 864, 'sentence_auction', 'A1', 'grammar', 'Theme: At, on, in — prepositions of time', 'auction', '[{"correct": true, "sentence": "I was born in 1995.", "explanation": "Correct! We use ''in'' with years, months and seasons."}, {"correct": true, "sentence": "The meeting is on Monday at 9 o''clock.", "explanation": "Correct! ''On'' for days, ''at'' for specific times — both right."}, {"correct": false, "sentence": "The party is in Saturday.", "explanation": "Wrong — use ''on'' with days of the week: ''The party is on Saturday.''"}, {"correct": true, "sentence": "I go to bed at midnight.", "explanation": "Correct! We use ''at'' with clock times and midnight/midday."}, {"correct": false, "sentence": "She was born on July.", "explanation": "Wrong — use ''in'' with months: ''She was born in July.''"}, {"correct": true, "sentence": "He arrived at the airport in the morning.", "explanation": "Correct! ''At'' the airport (place), ''in the morning'' (part of day) — both right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f9a67517-358b-4415-97aa-89f2bc204a26', 865, 'sentence_auction', 'A2', 'grammar', 'Theme: Object pronouns — me, him, her, us, them', 'auction', '[{"correct": true, "sentence": "She gave him a book.", "explanation": "Correct! ''Him'' is the object pronoun for ''he''."}, {"correct": false, "sentence": "Can you help I?", "explanation": "Wrong — ''I'' is a subject pronoun. After a verb, use the object: ''Can you help me?''"}, {"correct": true, "sentence": "I love her very much.", "explanation": "Correct! ''Her'' is the object pronoun for ''she''."}, {"correct": false, "sentence": "He called we yesterday.", "explanation": "Wrong — ''we'' is a subject pronoun. Use the object: ''He called us yesterday.''"}, {"correct": true, "sentence": "They invited her to the party.", "explanation": "Correct! ''Her'' is right — she received the invitation."}, {"correct": true, "sentence": "Give it to me, please.", "explanation": "Correct! Both ''it'' and ''me'' are object pronouns used correctly here."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6015c19c-fd03-451c-918f-8af613edc0f6', 370, 'multiple_choice', 'A2', 'basic_questions', '___ people are in your family?', 'How many', '["How often", "How many", "How much", "How long"]', NULL, NULL, NULL, NULL, 'How many + plural countable noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e24e6aeb-5417-4a12-8b15-0e3ddd6d1bb5', 866, 'sentence_auction', 'A1', 'grammar', 'Theme: Have got / Has got — possession', 'auction', '[{"correct": true, "sentence": "She has got two brothers.", "explanation": "Correct! She = third person singular, so ''has got'' is right."}, {"correct": false, "sentence": "She have got two brothers.", "explanation": "Wrong — with he/she/it, use ''has got'': ''She has got two brothers.''"}, {"correct": true, "sentence": "Have you got a pen?", "explanation": "Correct! ''Have you got'' — the right question form."}, {"correct": false, "sentence": "They has got a dog.", "explanation": "Wrong — ''they'' uses ''have got'': ''They have got a dog.''"}, {"correct": true, "sentence": "Has she got any sisters?", "explanation": "Correct! Has + subject + got — perfect question form for third person."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f4dd393b-ff1e-474f-9dc0-56a7f4d3d2a7', 867, 'sentence_auction', 'A2', 'grammar', 'Theme: Adjectives — where do they go?', 'auction', '[{"correct": true, "sentence": "It''s a beautiful old building.", "explanation": "Correct! Adjectives go before the noun in English."}, {"correct": false, "sentence": "She has a hair long and brown.", "explanation": "Wrong — adjectives go BEFORE the noun in English: ''She has long, brown hair.''"}, {"correct": true, "sentence": "The weather is cold today.", "explanation": "Correct! Adjectives can also go after ''be'': is/are/was + adjective."}, {"correct": true, "sentence": "He is a very tall man.", "explanation": "Correct! Very + adjective + noun — the order is right."}, {"correct": false, "sentence": "That was an idea interesting.", "explanation": "Wrong — the adjective goes before the noun: ''That was an interesting idea.''"}, {"correct": true, "sentence": "She wore a lovely red dress.", "explanation": "Correct! Opinion adjective (lovely) comes before colour (red) — perfect order."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('01105ef8-1375-4cc4-ac67-5cf5e21ccfec', 868, 'sentence_auction', 'B1', 'grammar', 'Theme: Conditionals — first and second', 'auction', '[{"correct": true, "sentence": "If it rains tomorrow, we will stay at home.", "explanation": "Correct! First conditional: if + present simple, will + infinitive."}, {"correct": false, "sentence": "If I would have more money, I would travel more.", "explanation": "Wrong — never use ''would'' in the if-clause: ''If I had more money, I would travel more.''"}, {"correct": true, "sentence": "If I knew the answer, I would tell you.", "explanation": "Correct! Second conditional: if + past simple, would + infinitive."}, {"correct": true, "sentence": "We''ll miss the train if we don''t hurry.", "explanation": "Correct! First conditional — the if-clause is in present simple, main clause uses will."}, {"correct": false, "sentence": "She would be happier if she exercises more.", "explanation": "Wrong — second conditional needs past simple in the if-clause: ''if she exercised more.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('78b65257-6984-4ac4-a4d6-2762cf3434e9', 869, 'sentence_auction', 'B1', 'grammar', 'Theme: Passive voice — is the form correct?', 'auction', '[{"correct": true, "sentence": "This bridge was built in 1890.", "explanation": "Correct! Was + past participle — passive simple past."}, {"correct": false, "sentence": "The report was wrote by the manager.", "explanation": "Wrong — ''wrote'' is simple past, not past participle. Use ''written'': ''The report was written by the manager.''"}, {"correct": true, "sentence": "The meeting has been postponed until Friday.", "explanation": "Correct! Has been + past participle — present perfect passive."}, {"correct": false, "sentence": "English is spoke in many countries.", "explanation": "Wrong — the past participle of ''speak'' is ''spoken'': ''English is spoken in many countries.''"}, {"correct": true, "sentence": "The windows are cleaned every week.", "explanation": "Correct! Are + past participle — present simple passive for repeated actions."}, {"correct": false, "sentence": "The cake was ate by the children.", "explanation": "Wrong — the past participle of ''eat'' is ''eaten'': ''The cake was eaten by the children.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7d114739-1fb9-4926-935c-f49201be425d', 870, 'sentence_auction', 'B2', 'grammar', 'Theme: Reported speech — what changes when we report?', 'auction', '[{"correct": true, "sentence": "She said that she was tired.", "explanation": "Correct! ''Is'' shifts back to ''was'' in reported speech — perfect."}, {"correct": false, "sentence": "He told me he will come tomorrow.", "explanation": "Wrong — ''will'' shifts back to ''would'' in reported speech: ''He told me he would come.''"}, {"correct": true, "sentence": "She asked me where I lived.", "explanation": "Correct! Reported questions use normal word order — no inversion after the question word."}, {"correct": false, "sentence": "She asked me where did I live.", "explanation": "Wrong — no inversion in reported questions: ''She asked me where I lived.''"}, {"correct": true, "sentence": "They said they hadn''t seen the film.", "explanation": "Correct! ''Haven''t'' shifts back to ''hadn''t'' — the backshift is right."}, {"correct": false, "sentence": "He told to me the news.", "explanation": "Wrong — ''tell'' doesn''t use ''to'' before the indirect object: ''He told me the news.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bcde4ce1-76b0-4f63-a82a-31b461498561', 871, 'sentence_auction', 'B1', 'grammar', 'Theme: Modal verbs — should, must, have to, might', 'auction', '[{"correct": true, "sentence": "She must be tired — she worked all night.", "explanation": "Correct! ''Must'' for a logical deduction — we''re almost certain."}, {"correct": false, "sentence": "You should to see a doctor about that cough.", "explanation": "Wrong — modal verbs never use ''to'': ''You should see a doctor.''"}, {"correct": true, "sentence": "You mustn''t park here — it''s illegal.", "explanation": "Correct! ''Mustn''t'' = prohibition. It is not allowed."}, {"correct": false, "sentence": "He don''t have to come if he doesn''t want to.", "explanation": "Wrong — ''have to'' conjugates like a normal verb: ''He doesn''t have to come.''"}, {"correct": true, "sentence": "I might go to the gym later.", "explanation": "Correct! ''Might'' + infinitive — expressing possibility. No ''to'' needed."}, {"correct": true, "sentence": "You don''t have to wear a tie — it''s not obligatory.", "explanation": "Correct! Don''t have to = no obligation. (Different from mustn''t, which is prohibition.)"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5e734748-52ca-4f45-8c2a-36be6b0548d7', 872, 'sentence_auction', 'B1', 'grammar', 'Theme: Gerund or infinitive — which verb form follows?', 'auction', '[{"correct": true, "sentence": "I want to learn a new language.", "explanation": "Correct! ''Want'' is always followed by the infinitive: want to do."}, {"correct": false, "sentence": "She enjoys to swim in the sea.", "explanation": "Wrong — ''enjoy'' is always followed by the gerund: ''She enjoys swimming.''"}, {"correct": true, "sentence": "He decided to change jobs.", "explanation": "Correct! ''Decide'' takes the infinitive: decided to change."}, {"correct": false, "sentence": "They finished to paint the house.", "explanation": "Wrong — ''finish'' is always followed by the gerund: ''They finished painting the house.''"}, {"correct": true, "sentence": "I look forward to seeing you soon.", "explanation": "Correct! ''Look forward to'' is followed by the gerund — the ''to'' here is a preposition, not part of an infinitive."}, {"correct": true, "sentence": "She suggested going to the cinema.", "explanation": "Correct! ''Suggest'' takes the gerund: suggested going."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('be956fa2-6345-44c6-8337-355689019b1c', 239, 'gap_fill', 'A2', 'past_simple', 'He ___ (leave) the office early last Friday.', 'left', NULL, NULL, NULL, NULL, NULL, 'Leave is irregular: leave → left → left.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a64deb62-a6f9-445f-8859-46cdd239ba21', 607, 'sentence_building', 'B2', 'present_perfect_continuous', 'Llevo trabajando aquí desde que terminé la universidad.', 'I have been working here since I finished university', '["I", "have", "been", "working", "here", "since", "I", "finished", "university", "from", "completing", "school"]', NULL, NULL, NULL, NULL, 'Present perfect continuous (have been working) + "since" + past simple. "Since" marks when the action started.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('314039ae-ffab-4c4b-8ca6-b34fdc6f5079', 873, 'sentence_auction', 'B2', 'grammar', 'Theme: Relative clauses — who, which, whose, where', 'auction', '[{"correct": true, "sentence": "The woman who lives next door is a doctor.", "explanation": "Correct! ''Who'' for people — and it''s the subject of the clause."}, {"correct": false, "sentence": "The man which I met was very kind.", "explanation": "Wrong — use ''who'' or ''that'' for people, not ''which'': ''The man who I met was very kind.''"}, {"correct": true, "sentence": "He''s the person whose car was stolen.", "explanation": "Correct! ''Whose'' shows possession — it belongs to him."}, {"correct": true, "sentence": "That''s the shop where I buy my coffee.", "explanation": "Correct! ''Where'' for places — perfect."}, {"correct": false, "sentence": "She''s the teacher who her students love.", "explanation": "Wrong — ''her'' is redundant here. Either: ''the teacher who(m) students love'' or ''the teacher her students love'' (no who)."}, {"correct": true, "sentence": "This is the book that changed my life.", "explanation": "Correct! ''That'' can replace ''which'' for things in defining relative clauses."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9c5cc719-3813-4d47-b81a-a1dd74391fe1', 874, 'sentence_auction', 'B1', 'grammar', 'Theme: Countable and uncountable nouns', 'auction', '[{"correct": true, "sentence": "I need some advice about my career.", "explanation": "Correct! ''Advice'' is uncountable — no plural, no ''a''."}, {"correct": false, "sentence": "Can I have some informations, please?", "explanation": "Wrong — ''information'' is uncountable in English. No plural: ''Can I have some information?''"}, {"correct": true, "sentence": "There isn''t much traffic today.", "explanation": "Correct! ''Traffic'' is uncountable — we use ''much'', not ''many''."}, {"correct": false, "sentence": "She gave me a very useful advice.", "explanation": "Wrong — ''advice'' is uncountable. You can say ''some advice'' or ''a piece of advice''."}, {"correct": true, "sentence": "We need to buy some furniture for the new flat.", "explanation": "Correct! ''Furniture'' is uncountable — no plural form, no ''a''."}, {"correct": true, "sentence": "I don''t have much time right now.", "explanation": "Correct! ''Time'' (in general) is uncountable — ''much time'' is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c08adb5d-99db-43f8-9eea-424612c8f8d7', 875, 'sentence_auction', 'B1', 'grammar', 'Theme: Future forms — will, going to, present continuous', 'auction', '[{"correct": true, "sentence": "Look at those clouds — it''s going to rain.", "explanation": "Correct! Evidence in the present = going to. We can see it coming."}, {"correct": false, "sentence": "I will call you when I will arrive.", "explanation": "Wrong — after time conjunctions (when, after, before, until), use present simple: ''I will call you when I arrive.''"}, {"correct": true, "sentence": "She''s meeting her manager tomorrow at 2pm.", "explanation": "Correct! Present continuous for fixed future arrangements — the meeting is in the diary."}, {"correct": true, "sentence": "I''ll open the window — it''s very hot in here.", "explanation": "Correct! Will for spontaneous decisions made at the moment of speaking."}, {"correct": false, "sentence": "They will to arrive at 6 o''clock.", "explanation": "Wrong — ''will'' is already a modal verb. No ''to'': ''They will arrive at 6.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5e50a40b-c1d7-4fbf-9d5f-c2b028470591', 876, 'sentence_auction', 'B1', 'grammar', 'Theme: Comparatives and superlatives', 'auction', '[{"correct": true, "sentence": "This is the most difficult exam I''ve ever taken.", "explanation": "Correct! Most + adjective for superlatives with longer words."}, {"correct": false, "sentence": "She is more taller than her sister.", "explanation": "Wrong — never use ''more'' with a comparative adjective that already has -er: ''She is taller than her sister.''"}, {"correct": true, "sentence": "He drives more carefully than his brother.", "explanation": "Correct! ''Carefully'' is an adverb — it uses ''more'', not -er."}, {"correct": true, "sentence": "The more you practise, the better you become.", "explanation": "Correct! The + comparative, the + comparative — a great structure for cause and effect."}, {"correct": false, "sentence": "That was the most best film I''ve seen.", "explanation": "Wrong — ''best'' is already a superlative. Drop ''most'': ''That was the best film I''ve seen.''"}, {"correct": false, "sentence": "She works more harder than anyone else in the office.", "explanation": "Wrong — ''harder'' is already a comparative. No need for ''more'': ''She works harder than anyone else.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('72b8b521-5b28-4e47-a9d6-27b530c2732c', 877, 'sentence_auction', 'B1', 'grammar', 'Theme: Past simple vs past continuous — what was happening?', 'auction', '[{"correct": true, "sentence": "I was cooking dinner when the phone rang.", "explanation": "Correct! Longer background action (was cooking) interrupted by shorter event (rang)."}, {"correct": false, "sentence": "While I drove to work, I heard the news.", "explanation": "Wrong — driving is the longer background action: ''While I was driving to work, I heard the news.''"}, {"correct": true, "sentence": "They were watching TV when the power went off.", "explanation": "Correct! Were watching = background. Went off = the interrupting event."}, {"correct": false, "sentence": "He fall asleep while he was watching the film.", "explanation": "Wrong — past simple of ''fall'' is ''fell'': ''He fell asleep while he was watching the film.''"}, {"correct": true, "sentence": "What were you doing when I called?", "explanation": "Correct! Asking about the background action in progress — were you doing is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('13b08976-403a-419c-9fad-7df957d96442', 878, 'sentence_auction', 'C1', 'grammar', 'Theme: Inversion — formal and emphatic structures', 'auction', '[{"correct": true, "sentence": "Hardly had she sat down when the phone rang.", "explanation": "Correct! Hardly + had + subject — inversion required with negative adverbials."}, {"correct": false, "sentence": "Never I have seen such a beautiful sunset.", "explanation": "Wrong — inversion is required: ''Never have I seen such a beautiful sunset.''"}, {"correct": true, "sentence": "Under no circumstances should you open that door.", "explanation": "Correct! Negative adverbial at the front triggers inversion: should + subject."}, {"correct": false, "sentence": "Not only he was late, but he also forgot to call.", "explanation": "Wrong — ''not only'' at the front requires inversion in the first clause: ''Not only was he late, but...''"}, {"correct": true, "sentence": "No sooner had I left the house than it started raining.", "explanation": "Correct! No sooner + had + subject — classic inversion with ''no sooner...than''."}, {"correct": true, "sentence": "Rarely have I enjoyed a meal so much.", "explanation": "Correct! Rarely + have + subject — formal inversion used for emphasis."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('337b3ec5-4752-49c3-87c1-19e5406f1ddf', 367, 'multiple_choice', 'A2', 'basic_questions', '___ do you go to the gym?', 'How often', '["How many", "How often", "How long", "Who"]', NULL, NULL, NULL, NULL, 'How often for frequency: How often do you...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ebe44609-df7b-4096-bbf5-38d60f4bfd33', 829, 'error_correction', 'A1', 'grammar', 'We was at the beach yesterday.', 'We were at the beach yesterday.', '[]', NULL, NULL, NULL, NULL, '"We" is first person plural, the past tense of "to be" is "were", not "was". We were at the beach. I was. You/we/they were.  He/she/it was.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('832846e5-1198-4362-bf21-00b55dbbe9d9', 1237, 'multiple_choice', 'B1', 'business_phrasal_verbs', 'The finance team will _____ the costs and report back next week.', 'look into', '["look into", "look over", "look up", "look after"]', NULL, NULL, NULL, NULL, 'Look into means to investigate or examine something in detail. Compare: the committee is looking into the issue.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2cdce2e1-fe1f-4c29-bf8e-43eab1943581', 879, 'sentence_auction', 'C1', 'grammar', 'Theme: Perfect modals — must have, should have, can''t have', 'auction', '[{"correct": true, "sentence": "She must have forgotten about the meeting.", "explanation": "Correct! Must have + past participle — a logical deduction about the past."}, {"correct": true, "sentence": "He should have told us about the problem sooner.", "explanation": "Correct! Should have + past participle — a criticism or regret about the past."}, {"correct": true, "sentence": "They can''t have known about the changes in advance.", "explanation": "Correct! Can''t have + past participle — expressing near certainty that something didn''t happen."}, {"correct": false, "sentence": "He must had left before we arrived.", "explanation": "Wrong — it''s ''must have'', not ''must had'': ''He must have left before we arrived.''"}, {"correct": false, "sentence": "You should of called me!", "explanation": "Wrong — this is a very common written error. It''s always ''should have'', not ''should of'': ''You should have called me!''"}, {"correct": true, "sentence": "She might have missed the train.", "explanation": "Correct! Might have + past participle — speculating about a past possibility."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b4575afa-5a60-4c87-bed1-f892b96594f1', 880, 'sentence_auction', 'C1', 'grammar', 'Theme: Participle clauses — -ing and -ed at the start', 'auction', '[{"correct": true, "sentence": "Exhausted by the long journey, she went straight to bed.", "explanation": "Correct! Past participle clause — she was exhausted, so she went to bed."}, {"correct": true, "sentence": "Having finished the report, she sent it to her manager.", "explanation": "Correct! Having + past participle for an action completed before the main verb."}, {"correct": false, "sentence": "Opened the door, he walked into the room.", "explanation": "Wrong — the subject is doing the opening, so use the present participle: ''Opening the door, he walked into the room.''"}, {"correct": true, "sentence": "Written in 1945, the novel is still widely read today.", "explanation": "Correct! Past participle clause — the novel was written, so the passive participle is right."}, {"correct": false, "sentence": "Arriving late, his colleagues were unimpressed.", "explanation": "Wrong — dangling participle! It was he who arrived late, not his colleagues. Try: ''Arriving late, he found his colleagues were unimpressed.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6f7904de-1298-4f6c-a3e2-c855bddfeab9', 881, 'sentence_auction', 'C1', 'grammar', 'Theme: Cleft sentences — It was... / What I need is...', 'auction', '[{"correct": true, "sentence": "It was in 2005 that she first visited Japan.", "explanation": "Correct! It was + focus element + that — a classic cleft structure for emphasis."}, {"correct": true, "sentence": "What I need is more time to prepare.", "explanation": "Correct! What-cleft — ''what I need'' is the subject, ''more time'' is the complement."}, {"correct": true, "sentence": "What surprised me most was his reaction.", "explanation": "Correct! What-cleft used to focus on the subject — clean and emphatic."}, {"correct": false, "sentence": "What I told him was the true.", "explanation": "Wrong — ''true'' is an adjective; the noun is ''truth'': ''What I told him was the truth.''"}, {"correct": true, "sentence": "It was her idea that was suggested first.", "explanation": "Correct! It was + noun phrase + relative clause — putting the focus on her idea."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e23a1c2-f96a-49d1-8e85-217d16a64b9b', 882, 'sentence_auction', 'C1', 'grammar', 'Theme: Wish, if only, as if — unreal and hypothetical', 'auction', '[{"correct": true, "sentence": "I wish I knew the answer.", "explanation": "Correct! Wish + past simple for a present wish — I don''t know the answer now."}, {"correct": true, "sentence": "I wish I had studied harder at school.", "explanation": "Correct! Wish + past perfect for a past regret — I can''t change it now."}, {"correct": false, "sentence": "If only I would have more time!", "explanation": "Wrong — never use ''would'' after ''wish'' or ''if only'': ''If only I had more time!''"}, {"correct": true, "sentence": "If only she would listen to me!", "explanation": "Correct! Wish/if only + would + infinitive is used to express irritation about someone else''s behaviour."}, {"correct": true, "sentence": "They acted as though nothing had happened.", "explanation": "Correct! As though + past perfect — describing how they behaved after an event."}, {"correct": true, "sentence": "He speaks to her as if she was a small child.", "explanation": "Correct! Both ''was'' and ''were'' are accepted after ''as if'' in modern English."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9337fdb2-f1d5-4578-8e65-33d40f70a14c', 883, 'sentence_auction', 'C1', 'grammar', 'Theme: Dependent prepositions — the right preposition after adjectives and verbs', 'auction', '[{"correct": true, "sentence": "She has a real talent for languages.", "explanation": "Correct! ''Talent for'' is the right collocation."}, {"correct": false, "sentence": "He is very keen of classical music.", "explanation": "Wrong — it''s ''keen on'': ''He is very keen on classical music.''"}, {"correct": true, "sentence": "I''m not familiar with this software.", "explanation": "Correct! ''Familiar with'' — the right dependent preposition."}, {"correct": true, "sentence": "She takes pride in her work.", "explanation": "Correct! ''Take pride in'' — a fixed collocation."}, {"correct": false, "sentence": "He is responsible of the marketing team.", "explanation": "Wrong — it''s ''responsible for'': ''He is responsible for the marketing team.''"}, {"correct": true, "sentence": "They are committed to improving customer service.", "explanation": "Correct! ''Committed to'' + gerund — ''to'' here is a preposition, not part of an infinitive."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e4e1c8e-fd82-4f58-9130-2e6d0cd6b306', 845, 'error_correction', 'B2', 'grammar', 'He is the kind of person who enjoy talking to new people.', 'He is the kind of person who enjoys talking to new people.', '[]', NULL, NULL, NULL, NULL, 'The relative pronoun "who" refers back to "person" (singular), so the verb must agree: "a person who enjoys". The relative clause takes its number from the noun, not "who".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4b62db4f-940e-46d5-a0e5-7bfaac256de5', 833, 'error_correction', 'A2', 'grammar', 'I have 25 years old.', 'I am 25 years old.', '["I''m 25 years old."]', NULL, NULL, NULL, NULL, 'In English, we use "to be" to talk about age: "I am 25 years old." Spanish speakers often say "I have 25 years" — a direct translation that sounds weird in English!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('039428a4-f420-4852-9b21-72b06737f3ba', 841, 'error_correction', 'B1', 'grammar', 'I wish I would more free time.', 'I wish I had more free time.', '[]', NULL, NULL, NULL, NULL, '"I wish + past simple" expresses a wish about the present: "I wish I had more time." Using "would" after "wish" is a very common mistake — but "I wish I had" is the correct form. But, we often say "I wish you/he/she/etc would..."', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('353d65e3-2287-4b94-b08d-f1dc940082a9', 884, 'sentence_auction', 'C1', 'grammar', 'Theme: Formal writing — professional English', 'auction', '[{"correct": true, "sentence": "The proposal was discussed at length by the board.", "explanation": "Correct! Formal passive — appropriate for professional writing."}, {"correct": false, "sentence": "We would like to apologise for any inconveniences caused.", "explanation": "Wrong — ''inconvenience'' is uncountable in this context: ''...for any inconvenience caused.''"}, {"correct": true, "sentence": "Please do not hesitate to contact us.", "explanation": "Correct! Standard formal phrase — and note, it''s ''contact us'', not ''contact with us''."}, {"correct": false, "sentence": "We are writing with regards to your recent complaint.", "explanation": "Wrong — the formal phrase is ''with regard to'' (no s): ''We are writing with regard to your complaint.''"}, {"correct": true, "sentence": "Further information is available on request.", "explanation": "Correct! Clean, formal construction — passive without an unnecessary agent."}, {"correct": false, "sentence": "Please don''t hesitate to contact with us.", "explanation": "Wrong — ''contact'' is a transitive verb. No preposition needed: ''Please don''t hesitate to contact us.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('45b08b84-9c3f-4064-9f91-76e5a87992a2', 828, 'error_correction', 'A1', 'grammar', 'She don''t like the cold.', 'She doesn''t like the cold.', '[]', NULL, NULL, NULL, NULL, 'With he, she, or it in the present simple, we use "doesn''t" (does not), not "don''t" (do not). She doesn''t like cold.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ab728d23-3512-42ab-a0dc-243f6f37c4a2', 885, 'sentence_auction', 'C2', 'grammar', 'Theme: Discourse markers — connecting ideas accurately', 'auction', '[{"correct": true, "sentence": "Nevertheless, the results were disappointing.", "explanation": "Correct! ''Nevertheless'' = despite this — used to introduce a contrasting point."}, {"correct": false, "sentence": "Despite of the rain, we enjoyed the trip.", "explanation": "Wrong — it''s ''despite'' + noun (no ''of'') or ''in spite of'' + noun: ''Despite the rain, we enjoyed the trip.''"}, {"correct": true, "sentence": "Furthermore, the study reveals a significant correlation.", "explanation": "Correct! ''Furthermore'' adds another point — formal and appropriate here."}, {"correct": false, "sentence": "In spite the challenges, the team succeeded.", "explanation": "Wrong — it''s ''in spite of'', not ''in spite'': ''In spite of the challenges, the team succeeded.''"}, {"correct": true, "sentence": "Consequently, the project was delayed by three weeks.", "explanation": "Correct! ''Consequently'' = as a result — used to signal a cause-effect relationship."}, {"correct": true, "sentence": "However, we must acknowledge the limitations.", "explanation": "Correct! ''However'' introduces a contrasting point — and ''must'' + infinitive is right."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d13b46c6-9cfa-4677-a0fa-2a3d19230889', 886, 'sentence_auction', 'C1', 'grammar', 'Theme: Third and mixed conditionals — past regrets and present consequences', 'auction', '[{"correct": true, "sentence": "If she had studied harder, she would have passed the exam.", "explanation": "Correct! Third conditional — past unreal condition, past unreal result."}, {"correct": true, "sentence": "If he hadn''t moved abroad, he would be living here now.", "explanation": "Correct! Mixed conditional — past condition with a present result."}, {"correct": false, "sentence": "If I would have known, I would have helped.", "explanation": "Wrong — never use ''would'' in the if-clause: ''If I had known, I would have helped.''"}, {"correct": true, "sentence": "She would be a doctor now if she had chosen medicine.", "explanation": "Correct! Mixed conditional — the past choice has a present-day consequence."}, {"correct": false, "sentence": "If it hadn''t rained, we would had a great picnic.", "explanation": "Wrong — the result clause needs ''would have'': ''...we would have had a great picnic.''"}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('95ec8712-aeb9-4c37-b7d6-e7b297653279', 887, 'sentence_auction', 'C1', 'grammar', 'Theme: Collocations — the right verb with the right noun', 'auction', '[{"correct": true, "sentence": "She made a great effort to finish on time.", "explanation": "Correct! ''Make an effort'' is the right collocation."}, {"correct": false, "sentence": "He did a serious mistake during the presentation.", "explanation": "Wrong — we ''make'' a mistake, not ''do'' one: ''He made a serious mistake.''"}, {"correct": true, "sentence": "The company made a significant profit last year.", "explanation": "Correct! ''Make a profit'' is the standard collocation."}, {"correct": true, "sentence": "She made great progress in her studies.", "explanation": "Correct! ''Make progress'' — another fixed collocation."}, {"correct": false, "sentence": "She did progress in her studies.", "explanation": "Wrong — we ''make'' progress, not ''do'' it: ''She made great progress in her studies.''"}, {"correct": true, "sentence": "He took full responsibility for the error.", "explanation": "Correct! ''Take responsibility'' is the right collocation — accept it, own it."}]', NULL, NULL, NULL, NULL, NULL, '2026-02-26 08:26:39.264638+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('04d2f57f-2fa0-4be8-84a7-b7bd899ca8ec', 831, 'error_correction', 'A2', 'vocabulary', 'I am very boring at this party.', 'I am very bored at this party.', '[]', NULL, NULL, NULL, NULL, '"Boring" describes something that causes boredom (the party is boring). "Bored" describes how you feel (I am bored). If you say "I am boring", people might agree — but that is not what you want!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('092b9fd9-cd38-44fe-b0c4-52ac2b777b87', 834, 'error_correction', 'A2', 'grammar', 'He plays tennis very good.', 'He plays tennis very well.', '[]', NULL, NULL, NULL, NULL, '"Good" is an adjective (a good player). "Well" is the adverb (he plays well). Use adverbs to describe how you do something. (I do these exercises very well ''fandandgo''!)', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('892c6372-b5f0-4073-ab67-59a79c376a06', 837, 'error_correction', 'A2', 'vocabulary', 'Can you say me the time, please?', 'Can you tell me the time, please?', '[]', NULL, NULL, NULL, NULL, 'In English, we "tell someone something" but "say something". "Can you tell me the time?" — not "say me". A small but very common mistake!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ca9c5ad4-5a97-4ba0-89eb-c68fd0ff231c', 842, 'error_correction', 'B1', 'grammar', 'The contract must be finish by the end of the month.', 'The contract must be finished by the end of the month.', '[]', NULL, NULL, NULL, NULL, 'In passive constructions with modal verbs, we need "be + past participle, the third column": must be finished, should be completed, will be delivered.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9795b842-8997-4122-8baf-67ed04fcfc7b', 843, 'error_correction', 'B2', 'grammar', 'He admitted to steal the money.', 'He admitted to stealing the money.', '[]', NULL, NULL, NULL, NULL, 'Certain verbs are followed by a gerund (-ing), not an infinitive. "Admit to doing something" is the correct pattern: He admitted to stealing the money. Maybe don''t admit to doing it until they show you proof 😉.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f27e32f8-6641-4d4c-a2f6-202b5c037ca3', 844, 'error_correction', 'B1', 'grammar', 'She has been working here since three years.', 'She has been working here for three years.', '[]', NULL, NULL, NULL, NULL, 'Use "for" with a duration (for three years, for a long time). Use "since" with a specific point in time (since 2020, since Monday). Three years is a duration, not a point in time.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ac5cf53a-bc9a-45e8-a92e-33cea6f8515d', 206, 'gap_fill', 'A1', 'present_simple', 'My mother ___ (teach) at a school.', 'teaches', NULL, NULL, NULL, NULL, NULL, 'Verbs ending in -ch: add -es for third person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1ce4f287-a567-4e92-8083-e8f6fedc1233', 669, 'sentence_building', 'C2', 'inversion', 'Solo cuando perdemos algo nos damos cuenta de su verdadero valor.', 'only when we lose something do we realise its true value', '["only", "when", "we", "lose", "something", "do", "we", "realise", "its", "true", "value", "does", "lost", "it", "really"]', '["we only realise its true value when we lose something"]', 'With this word order there is no need for the auxiliary verb ''do''', NULL, NULL, 'Only when + clause + inverted main clause. Emphatic structure.
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('57a3b995-1a93-4bc7-b416-f5f12877cf05', 846, 'error_correction', 'B2', 'grammar', 'The manager suggested that we would start the meeting earlier.', 'The manager suggested that we should start the meeting earlier.', '[]', NULL, NULL, NULL, NULL, '"Suggest + that + should" is the formal pattern in British English: "suggested that we should start..." Using "would" here is incorrect. Note: the subjunctive (suggest we start) is also acceptable.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d94804b0-80be-40bf-8ca8-1d8a77fc6eb8', 850, 'error_correction', 'C2', 'grammar', 'The bill has laid before parliament for three weeks.', 'The bill has lain before parliament for three weeks.', '[]', NULL, NULL, NULL, NULL, 'The verb "lie" (to be in a horizontal position / to exist somewhere) is intransitive. Past participle: lain. "Lay" is transitive (to place something). "The bill has lain before parliament" = it has been there. It suggests inactivity, in this case on the part of parliament.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f1514f60-ee44-4a12-861a-7f7475e4a01d', 851, 'error_correction', 'C1', 'vocabulary', 'The CEO inferred in her speech that redundancies were likely.', 'The CEO implied in her speech that redundancies were likely.', '[]', NULL, NULL, NULL, NULL, 'Speakers "imply" (hint at something without stating it). Listeners "infer" (draw a conclusion). The CEO was speaking, so she implied — the audience inferred. A very common mix-up, even among native speakers!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c312f99a-2035-4f9e-a3c8-30ec54d2c2b4', 640, 'sentence_building', 'A2', 'question_forms', '', 'do you want to come with us', '["do", "you", "want", "to", "come", "with", "us", "are", "going"]', NULL, NULL, NULL, NULL, 'For present simple questions we use ''do'' + subject + verb. ''Want to'' is followed by the infinitive: ''want to come''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'en', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2969d7a3-ec60-4e90-9c95-117c5b984981', 853, 'error_correction', 'C1', 'vocabulary', 'He made a complement about her presentation skills.', 'He made a compliment about her presentation skills.', '[]', NULL, NULL, NULL, NULL, 'A "compliment" (noun) is a positive remark about someone. A "complement" (noun) is something that completes or enhances something else. Remember: E is for ''extra'' it adds something: good wine complements the meal.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4bdc985c-2468-4109-9a2b-15071dc6d438', 854, 'error_correction', 'C1', 'vocabulary', 'She is adverse to taking any financial risks.', 'She is averse to taking any financial risks.', '[]', NULL, NULL, NULL, NULL, '"Averse to" means reluctant or unwilling. "Adverse" means harmful or unfavourable (adverse conditions, adverse effects). "Risk-averse" is a common business term — not "risk-adverse".', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('578f1a5c-1c54-41ca-90cc-f6e7d448902d', 855, 'error_correction', 'C1', 'vocabulary', 'The principle cause of the project failure was poor communication.', 'The principal cause of the project failure was poor communication.', '[]', NULL, NULL, NULL, NULL, '"Principal" as an adjective means "main" or "most important". "Principle" is a noun meaning a rule or belief. "The principal cause" = the main cause. "A core principle" = a fundamental belief.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a629ca4f-35de-481e-823c-6f8f119edac6', 856, 'error_correction', 'C1', 'vocabulary', 'The new regulation will effect thousands of small businesses.', 'The new regulation will affect thousands of small businesses.', '[]', NULL, NULL, NULL, NULL, '"Affect" is the verb (to have an impact on), usually. "Effect" is usually the noun (the result or impact). "The regulation will affect businesses" — and its "effect" may be significant. A notoriously tricky pair, native speakers make lots of mistakes!', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5ed68428-ec20-4cff-b29c-710afdd75785', 857, 'error_correction', 'C2', 'grammar', 'The report alluded several serious failures in the inspection process.', 'The report identified several serious failures in the inspection process.', '[]', NULL, NULL, NULL, NULL, '"Allude" must be followed by "to": "alluded to several failures." Without "to", the sentence is ungrammatical. If "to" is missing and cannot be added, the verb should change — "identified" works cleanly here, though there are other options too.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c354be3f-958a-4ff2-8f4d-85fcb07f9c23', 1185, 'sentence_building', 'A1', 'routines', 'Me despierto a las siete todos los días.', 'I wake up at seven o''clock every day.', '["I", "wake", "up", "at", "seven", "o''clock", "every", "day", "wakes", "morning", "goes"]', NULL, NULL, NULL, NULL, 'Wake up is a phrasal verb meaning to stop sleeping. Use the present simple for regular daily routines.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c032d188-2dfc-4256-b6d8-c3e02d9797f1', 1186, 'sentence_building', 'A1', 'routines', 'Ella siempre desayuna antes de trabajar.', 'She always has breakfast before work.', '["she", "always", "has", "breakfast", "before", "work", "have", "after", "never", "eat"]', NULL, NULL, NULL, NULL, 'Frequency adverbs like always go before the main verb, not after it.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7f763dc4-d4be-47b9-9f65-8cc25026de92', 628, 'sentence_building', 'A2', 'question_forms', '¿Cuánto cuesta esto?', 'how much does this cost', '["how", "much", "does", "this", "cost", "is", "do"]', '["how much is this"]', 'A different way of translating, less formal.', NULL, NULL, 'We use ''how much'' + does + subject + verb to ask about prices. ''How much does this cost?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5beab43c-be83-47dc-9574-e3e9690bb1b2', 849, 'error_correction', 'C1', 'grammar', 'She was reluctant to accepting the offer without legal advice.', 'She was reluctant to accept the offer without legal advice.', '[]', NULL, NULL, NULL, NULL, '"Reluctant to + infinitive" is the correct structure: "reluctant to accept". "Reluctant in" does not exist as a pattern in English.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6670f943-7958-48d6-9820-1f69852b1dbb', 847, 'error_correction', 'B1', 'past_tenses
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4ade00a8-ae1d-4a2f-90a4-c88efce1a34b', 1187, 'sentence_building', 'A2', 'routines', 'Normalmente vamos al gimnasio los lunes.', 'We usually go to the gym on Mondays.', '["we", "usually", "go", "to", "the", "gym", "on", "Mondays", "going", "at", "sometimes"]', NULL, NULL, NULL, NULL, 'Use the present simple for regular habits and routines. Usually goes before the main verb.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f95c692a-c9cb-4a3d-8b50-f564203c3b4e', 1117, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The material used to fill the gaps between tiles is called _______.', 'grout', '["grout", "sealant", "plaster", "filler"]', NULL, NULL, NULL, NULL, 'Grout is the material that fills the joints between tiles. It is typically cement-based and available in a range of colours. It is applied after the tiles are set.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5b10f5cd-8db3-474d-8b7b-d5778ddfa059', 1118, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat regularly things we stick to a surface are called _______.', 'tiles', '["glue", "sealant", "grout", "tiles"]', NULL, NULL, NULL, NULL, 'Tiles in English include tiles for floors, walls, ceilings and any surface. We don''t use different words for different types, but can combine words: floor tiles, ceiling tiles etc. ', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary","Confusable words"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b9f72d6e-46d9-4347-a5ef-c85669eb2651', 1119, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'Small plastic crosses used to keep equal space between tiles are called tile _______.', 'spacers', '["spacers", "clips", "guides", "holders"]', NULL, NULL, NULL, NULL, 'Tile spacers are small plastic crosses placed between tiles during installation to maintain a consistent joint width before the grout is applied.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7446e6b7-83f1-463f-9b02-2177b8eec4a6', 1107, 'gap_fill', 'C1', 'business_vocabulary', 'The regulator found the company guilty of _______ — fixing prices in secret with a competitor.', 'collusion', NULL, NULL, NULL, NULL, NULL, 'Collusion means secret cooperation between companies to fix prices or manipulate markets — illegal in most jurisdictions and a serious breach of competition law.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4f249c59-5f18-481a-b260-85ec91180dc2', 1108, 'gap_fill', 'C1', 'business_vocabulary', 'A private _______ firm takes controlling stakes in companies, improves them, and sells them for a profit.', 'equity', NULL, NULL, NULL, NULL, NULL, 'Private equity refers to investment funds that take controlling stakes in private (non-listed) companies, restructure them to increase their value, and then sell them for a profit.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db43740e-ad3b-4eb5-92fd-a75ff96bbe93', 1109, 'gap_fill', 'C1', 'business_vocabulary', 'The company''s current ratio fell below 1.0 for the first time, raising serious _______ concerns.', 'liquidity', NULL, NULL, NULL, NULL, NULL, 'Liquidity refers to a company''s ability to meet its short-term financial obligations. A current ratio below 1.0 means current liabilities exceed current assets — a warning sign.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('32d6ad65-3b8a-4b17-99a9-75967d504a35', 1110, 'gap_fill', 'C1', 'business_vocabulary', 'The new product created a genuine competitive _______, protecting the company''s market position for years.', 'advantage', NULL, NULL, NULL, NULL, NULL, 'A competitive advantage is something that allows a company to outperform its rivals — lower costs, a unique product, a strong brand, or proprietary technology.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a1f11ad6-4efa-497d-8df2-3cd2192d333d', 1111, 'gap_fill', 'C1', 'business_vocabulary', 'Companies in highly regulated sectors must ensure full _______ with all applicable laws and industry standards.', 'compliance', NULL, NULL, NULL, NULL, NULL, 'Compliance means acting in accordance with all relevant laws, regulations, and internal policies. Compliance departments exist specifically to manage this in regulated industries.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f06b5a11-dde8-4734-8b3a-d412da328c69', 1112, 'gap_fill', 'C2', 'business_vocabulary', 'A company that holds a dominant market position and abuses it to prevent competition may be accused of being a _______.', 'monopoly', NULL, NULL, NULL, NULL, NULL, 'A monopoly exists when one company dominates a market so completely that competition is effectively eliminated. Regulators can investigate and break up monopolies.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8efbee93-88f2-4560-b57d-e563d2d5db0a', 1113, 'gap_fill', 'C2', 'business_vocabulary', 'The aggressive acquisition strategy resulted in significant _______, making the business complex and difficult to manage.', 'overexpansion', NULL, NULL, NULL, '["overdiversification"]', NULL, 'Overexpansion means growing too quickly or into too many areas — resulting in a business that is complex, inefficient, and difficult to manage profitably.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8f5dd7ee-a97b-48d9-9589-3fff5d8a8ce1', 1114, 'gap_fill', 'C2', 'business_vocabulary', 'The board commissioned an independent _______ review to assess whether each business unit was delivering sufficient shareholder value.', 'strategic', NULL, NULL, NULL, '["portfolio"]', NULL, 'A strategic review (or portfolio review) assesses each part of a business to decide which units to invest in, maintain, or sell off. It is typically commissioned by the board.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a03ce063-abba-41fe-a94e-0f4c846a588e', 1115, 'gap_fill', 'C2', 'business_vocabulary', 'The concept of corporate social _______ holds that a company has obligations not just to shareholders, but to employees, customers, and communities.', 'responsibility', NULL, NULL, NULL, NULL, NULL, 'Corporate social responsibility (CSR) is the idea that companies have obligations beyond profit — to employees, communities, the environment, and society as a whole.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f248c442-f74e-438d-b95d-d627494c4ec6', 1116, 'gap_fill', 'C2', 'business_vocabulary', 'The process of buying back shares from the public market to reduce the number in circulation is called a share _______.', 'buyback', NULL, NULL, NULL, '["repurchase"]', NULL, 'A share buyback means a company repurchases its own shares from the open market, reducing the number in circulation and typically increasing the value of remaining shares.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Business vocabulary","Financial vocabulary",Collocation}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('69b7e7cf-f747-464c-8ee7-8f001aa99270', 1120, 'multiple_choice', 'A1', 'bathroom_vocabulary', 'The flat thing we stand on in a shower which collects water is called a  _______.', 'shower tray', '["shower tray", "shower trail", "shower train", "shower trae"]', NULL, NULL, NULL, NULL, 'A shower tray micht sometimes also be referred to as only a tray once it is established we are talking about bathrooms.', '2026-03-07 21:49:47.936435+00', NULL, NULL, 'en', '{"Bathroom vocabulary"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c59f08b7-bd96-4f4c-861f-b8950dc9eb86', 630, 'sentence_building', 'A2', 'question_forms', '¿Puedo tener un vaso de agua?', 'can I have a glass of water', '["can", "I", "have", "cup", "a", "glass", "of", "water", "do", "the"]', NULL, NULL, NULL, NULL, '''Can I have...?'' is a polite way to ask for something. We say ''a glass of water'' not ''a glass with water''.', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('16ab6170-cd4a-447e-af7a-b76a47c61e52', 623, 'sentence_building', 'A2', 'question_forms', '¿Dónde está la estación de tren?', 'where is the train station', '["where", "trains", "is", "the", "train", "station", "are", "do"]', NULL, NULL, NULL, NULL, 'For questions with ''where'', the word order is: Where + is/are + subject. ''Where is the train station?''', '2026-02-13 08:00:10.850224+00', NULL, NULL, 'both', '{"Question form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('832673cc-4bb4-44a9-9d33-b2a3b0f0f17c', 1188, 'sentence_building', 'A1', 'routines', 'Él nunca toma café por la tarde.', 'He never drinks coffee in the evening.', '["he", "never", "drinks", "coffee", "in", "the", "evening", "morning", "always", "drink"]', NULL, NULL, NULL, NULL, 'Never is a negative frequency adverb — no additional negative verb form is needed.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('725be44b-ef9a-459a-8038-5f188d06243d', 1189, 'sentence_building', 'A2', 'routines', 'Me cepillo los dientes dos veces al día.', 'I brush my teeth twice a day.', '["I", "brush", "my", "teeth", "twice", "a", "day", "once", "clean", "daily"]', NULL, NULL, NULL, NULL, 'Twice a day means two times per day. Use the present simple for personal routines.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('abf9c510-bbb8-4f97-91c8-1668f7b44288', 211, 'gap_fill', 'A2', 'present_simple', 'What time ___ the film ___ (start)?', 'does...start', NULL, NULL, NULL, NULL, NULL, 'Questions about schedules: does + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2164033a-50a1-499b-95d9-ef24efc02e05', 302, 'multiple_choice', 'A1', 'present_simple', '___ they live in Valencia?', 'Do', '["Does", "Do", "Are", "Is"]', NULL, NULL, NULL, NULL, 'Questions with they/we/I/you: Do + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('13cb3f67-5e68-4ffc-ad4f-17ab8ef8539e', 303, 'multiple_choice', 'A1', 'present_simple', 'I ___ coffee every morning.', 'drink', '["drinks", "am drink", "drink", "drinking"]', NULL, NULL, NULL, NULL, 'With I/you/we/they: use the base verb without -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2fb85f67-1f8f-492e-ae3e-8bb0a98dfb2b', 304, 'multiple_choice', 'A1', 'present_simple', 'She ___ to work by bus.', 'goes', '["go", "goes", "going", "is go"]', NULL, NULL, NULL, NULL, 'Third person: go → goes (add -es after -o).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7b7fe222-88b3-45f4-a5c5-751b4429c6d7', 305, 'multiple_choice', 'A2', 'present_simple', 'How often ___ you exercise?', 'do', '["does", "do", "are", "is"]', NULL, NULL, NULL, NULL, 'Frequency questions with you: How often do you...?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d786ef43-4d10-4a6c-aa43-43dd04dc35c4', 212, 'gap_fill', 'A1', 'present_simple', 'My dad ___ (drive) to work every day.', 'drives', NULL, NULL, NULL, NULL, NULL, 'Third person singular: add -s to the verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('76f4dd83-6b61-4293-b7c9-5c24ae303f29', 306, 'multiple_choice', 'A1', 'present_simple', 'He ___ like fish.', 'doesn''t', '["don''t", "doesn''t", "isn''t", "aren''t"]', NULL, NULL, NULL, NULL, 'Third person negative: doesn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7300ab1a-fa78-4a27-951f-24a43b5c9e0f', 307, 'multiple_choice', 'A1', 'present_simple', 'We ___ dinner at 8 pm.', 'have', '["has", "have", "having", "are have"]', NULL, NULL, NULL, NULL, 'With we: use have (not has).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dfcf8bd8-cf5c-4082-8672-657065277978', 308, 'multiple_choice', 'A2', 'present_simple', 'The train ___ at 6:30.', 'leaves', '["leave", "leaves", "leaving", "is leave"]', NULL, NULL, NULL, NULL, 'Present simple for timetables and schedules.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c202815-c33a-4320-8d00-d5c93eada6fa', 309, 'multiple_choice', 'A1', 'present_simple', 'I ___ from Italy.', 'am', '["is", "am", "are", "be"]', NULL, NULL, NULL, NULL, 'To be: I am, you are, he/she is, we/they are.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('505a8134-25e5-4755-b545-07a505a8f665', 310, 'multiple_choice', 'A1', 'present_simple', '___ your father work here?', 'Does', '["Do", "Does", "Is", "Are"]', NULL, NULL, NULL, NULL, 'Third person questions: Does + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f274f195-06e0-4394-b2ca-c1f97d669077', 311, 'multiple_choice', 'A2', 'present_simple', 'My parents ___ in a small village.', 'live', '["lives", "live", "living", "is living"]', NULL, NULL, NULL, NULL, 'With plural subjects (parents): use the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('49040b98-8813-45ab-abb0-9b78887052d5', 312, 'multiple_choice', 'A1', 'present_simple', 'She ___ English and French.', 'speaks', '["speak", "speaks", "speaking", "is speak"]', NULL, NULL, NULL, NULL, 'Third person singular: add -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('351c6a31-5e46-4b10-b899-57d489d16eab', 313, 'multiple_choice', 'A2', 'present_simple', 'What ___ you do at the weekend?', 'do', '["does", "do", "are", "is"]', NULL, NULL, NULL, NULL, 'What do you do? = asking about habits/routines.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3be645b1-741b-4342-a5d1-922753585a8c', 314, 'multiple_choice', 'A1', 'present_simple', 'It ___ a lot in England.', 'rains', '["rain", "rains", "raining", "is rain"]', NULL, NULL, NULL, NULL, 'Third person (it): add -s. For facts and general truths.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b22d95be-9b96-4066-8fd7-77e43fb8a19a', 315, 'multiple_choice', 'A2', 'present_simple', 'She never ___ breakfast.', 'eats', '["eat", "eats", "eating", "is eat"]', NULL, NULL, NULL, NULL, 'After he/she/it + adverb of frequency: verb takes -s.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('98711e11-b18e-4a2b-afc5-297e1471db82', 317, 'multiple_choice', 'A1', 'present_continuous', 'What are you ___?', 'doing', '["do", "does", "doing", "did"]', NULL, NULL, NULL, NULL, 'Present continuous question: What are you doing?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c5111c65-429b-43f1-94c3-8f2db04902ce', 318, 'multiple_choice', 'A2', 'present_continuous', 'They ___ a new house at the moment.', 'are building', '["build", "are building", "builds", "building"]', NULL, NULL, NULL, NULL, 'Present continuous for actions in progress around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2fe2a9f4-2f45-44ed-91ae-94e69e30f18d', 319, 'multiple_choice', 'A1', 'present_continuous', 'She ___ right now. Can I take a message?', 'is working', '["works", "is working", "work", "working"]', NULL, NULL, NULL, NULL, 'Right now = happening at this moment → present continuous.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3105237a-1310-48bd-ab34-a1e388820adc', 320, 'multiple_choice', 'A2', 'present_continuous', 'I ___ a really good book this week.', 'am reading', '["read", "am reading", "reads", "reading"]', NULL, NULL, NULL, NULL, 'Present continuous for temporary situations around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ac587346-a194-49d3-9ff8-1c2b56c130f7', 321, 'multiple_choice', 'A1', 'present_continuous', 'The children ___ in the garden.', 'are playing', '["play", "plays", "are playing", "is playing"]', NULL, NULL, NULL, NULL, 'Plural subject (children) + are + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4ccd6d5c-1b8e-4287-8a9b-b3bc978363ac', 322, 'multiple_choice', 'A2', 'present_continuous', 'He ___ to the gym today. He''s ill.', 'isn''t going', '["doesn''t go", "isn''t going", "don''t go", "not going"]', NULL, NULL, NULL, NULL, 'Negative present continuous: isn''t + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f75ee8fc-eeb6-46ab-8526-15afb802465b', 316, 'multiple_choice', 'A1', 'present_continuous', 'Sshhhhhh, be quiet! The baby ___.', 'is sleeping', '["sleeps", "is sleeping", "sleep", "sleeping"]', NULL, NULL, NULL, NULL, 'Present continuous: is + verb-ing for something happening now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('db4f5b3a-0c5f-4459-a06a-416bd376e407', 213, 'gap_fill', 'A1', 'present_simple', 'I ___ (not understand) this word.', 'don''t understand', NULL, NULL, NULL, NULL, NULL, 'Negative present simple: don''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ba0b141c-aee8-4243-8699-6f5bd98104e5', 215, 'gap_fill', 'A1', 'present_simple', 'The sun ___ (rise) in the east.', 'rises', NULL, NULL, NULL, NULL, NULL, 'Present simple for general truths and facts.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('17f561a3-fc30-4129-b5d1-49cd23c2fa85', 216, 'gap_fill', 'A1', 'present_continuous', 'I ___ (read) a book right now.', 'am reading', NULL, NULL, NULL, NULL, NULL, 'Present continuous: am/is/are + verb-ing. For actions happening now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4abb7d85-7c84-4901-988f-f3fec0093ef0', 217, 'gap_fill', 'A1', 'present_continuous', 'She ___ (not sleep) at the moment.', 'isn''t sleeping', NULL, NULL, NULL, NULL, NULL, 'Negative present continuous: isn''t + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e0ed1a3a-bea4-4cae-8556-514e11cb16e9', 218, 'gap_fill', 'A1', 'present_continuous', 'They ___ (play) football in the park.', 'are playing', NULL, NULL, NULL, NULL, NULL, 'Present continuous with they: are + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f48f58a-2e24-4a1a-ac83-d10bdf57af29', 219, 'gap_fill', 'A2', 'present_continuous', 'What ___ you ___ (do) this weekend?', 'are...doing', NULL, NULL, NULL, NULL, NULL, 'Present continuous for future plans already arranged.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5e10af30-d631-4a90-b515-53b9e7484b00', 220, 'gap_fill', 'A1', 'present_continuous', 'He ___ (sit) in the garden.', 'is sitting', NULL, NULL, NULL, NULL, NULL, 'Present continuous: is + verb-ing. Double the final consonant: sit → sitting.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f586b85e-28a3-477e-8c5c-d5df5ecd8348', 221, 'gap_fill', 'A2', 'present_continuous', 'We ___ (not go) out tonight.', 'aren''t going', NULL, NULL, NULL, NULL, NULL, 'Negative present continuous for changed plans.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f99cec28-4271-48aa-a70e-02664384f24b', 222, 'gap_fill', 'A1', 'present_continuous', 'The children ___ (swim) in the pool.', 'are swimming', NULL, NULL, NULL, NULL, NULL, 'Double the final consonant: swim → swimming.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3cabf6b8-b0f9-40fb-aeb5-961d50e64a99', 223, 'gap_fill', 'A2', 'present_continuous', 'I ___ (learn) Spanish this year.', 'am learning', NULL, NULL, NULL, NULL, NULL, 'Present continuous for ongoing situations around now.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('473bfe91-29b7-4ef2-9eac-aa5d774039d7', 224, 'gap_fill', 'A1', 'present_continuous', 'Look! It ___ (rain).', 'is raining', NULL, NULL, NULL, NULL, NULL, 'Present continuous for things happening at the moment of speaking.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f5a0b974-f97f-4f71-8162-25a91e573800', 225, 'gap_fill', 'A2', 'present_continuous', '___ she ___ (come) to the party tonight?', 'Is...coming', NULL, '["Will...come"]', 'Future simple is also ok here', NULL, NULL, 'Questions in present continuous: Is + subject + verb-ing.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0313df94-795a-495a-b034-ee87503a7ddd', 204, 'gap_fill', 'A1', 'present_simple', '___ you ___ (speak) English?', 'Do...speak', NULL, '["Can...speak", "Can speak"]', NULL, NULL, NULL, 'Questions in present simple: Do + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3fc06722-81b3-418c-86f2-d4cbb84103e4', 1, 'gap_fill', 'B1', 'present_perfect', 'I ___ (never / visit) Scotland, but I''d love to go someday.', 'have never visited', NULL, NULL, NULL, NULL, 'Use present perfect for life experiences up to now', 'Present perfect is used for experiences from the past up to the present moment.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0b307547-ae24-4b1c-8e69-8367cf368f2d', 3, 'gap_fill', 'B2', 'present_perfect_continuous', 'How long ___ (you / work) on this project? It looks nearly finished.', 'have you been working', NULL, '["have u been working", "''ve u been working"]', 'Using ''u'' for ''you'' is understandable but try to write ''you'' in full.', NULL, 'Think about the duration of an ongoing activity', 'Present perfect continuous emphasizes the duration of an activity from the past until now.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('76ca5a2e-6d28-4b1f-98cb-0220e2cb4a97', 11, 'gap_fill', 'B1', 'present_perfect', 'She ___ (just / finish) her homework and now she''s watching TV.', 'has just finished', NULL, NULL, NULL, NULL, 'Use present perfect for recently completed actions', 'Present perfect with ''just'' shows an action that finished very recently. The adverb goes before the main verb.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9f7bdbd2-73c6-4d1f-a6b7-d19389cdab40', 101, 'multiple_choice', 'B1', 'present_perfect', 'I ___ to Paris three times this year.', 'have been', '["was", "go", "went", "have been"]', NULL, NULL, NULL, NULL, 'Present perfect with unfinished time period (''this year'').', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dceae340-7ffd-4442-b83c-903095ae8d08', 130, 'multiple_choice', 'B1', 'present_continuous_future', 'I ___ my grandparents this weekend.', 'am visiting', '["visit", "am visiting", "will visit", "visited"]', NULL, NULL, NULL, NULL, 'Present continuous for fixed future arrangements.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d3e3f97a-718f-45f9-a521-abc0876fac72', 139, 'multiple_choice', 'B1', 'present_simple_habits', 'She ___ to the gym three times a week.', 'goes', '["go", "goes", "is going", "went"]', NULL, NULL, NULL, NULL, 'Present simple for regular habits.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1f9519a7-7d1b-4725-a2dc-1ea1e17ef3bb', 145, 'multiple_choice', 'B1', 'present_perfect_just', 'I ___ finished my homework.', 'have just', '["justly", "have just", "am just", "was just"]', NULL, NULL, NULL, NULL, 'Present perfect with just for recently completed actions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e4f685bd-a066-45f2-baeb-3ad91780e773', 189, 'multiple_choice', 'B1', 'present_simple_routines', 'What time ___ to bed on weekdays?', 'do you go', '["are you going", "do you go", "go you", "you go"]', NULL, NULL, NULL, NULL, 'Present simple questions for routines.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2ef0557b-c715-4d40-93cb-95c928e61b1f', 323, 'multiple_choice', 'A2', 'present_continuous', 'We ___ dinner with friends tonight.', 'are having', '["have", "having", "are having", "has"]', NULL, NULL, NULL, NULL, 'Present continuous for future arrangements.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8ac6d39e-429d-4507-ad51-d0db647bf52a', 324, 'multiple_choice', 'A1', 'present_continuous', '___ it raining outside?', 'Is', '["Does", "Do", "Is", "Are"]', NULL, NULL, NULL, NULL, 'Questions: Is/Are + subject + verb-ing?', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e1cc002d-c26c-4692-abff-f5128cae8f99', 325, 'multiple_choice', 'A2', 'present_continuous', 'Why ___ she crying?', 'is', '["does", "do", "is", "are"]', NULL, NULL, NULL, NULL, 'Why + is + she + verb-ing for present continuous questions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f6c5dd82-4b65-4696-a414-c5d54c2ec82f', 183, 'multiple_choice', 'B1', 'present_perfect_yet', 'Have you finished your homework ___?', 'yet', '["already", "yet", "just", "still"]', NULL, NULL, NULL, NULL, 'Yet in questions (expecting completion). If you used already here it would indicate surprise at how quickly it was completed.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0debcb3d-b6e1-4182-814d-75a5a1cd362f', 108, 'multiple_choice', 'B1', 'present_perfect_for_since', 'They''ve been married ___ ten years.', 'for', '["while", "for", "during", "since"]', NULL, NULL, NULL, NULL, 'For with duration (ten years); since with point in time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e570296b-785b-404e-9b72-3296c2b59693', 61, 'gap_fill', 'B1', 'present_perfect_for_since', 'They''ve lived in this house ___ (for / since) 2010.', 'since', NULL, NULL, NULL, NULL, 'Since is used with a point in time', 'Since is used with a specific point in time when something started.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c11cad2-360d-43b0-a120-273587589e45', 62, 'gap_fill', 'B1', 'present_perfect_for_since', 'I''ve known her ___ (for / since) ten years.', 'for', NULL, NULL, NULL, NULL, 'For is used with a period of time', 'For is used with a period or duration of time.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1add9515-9e10-4286-9145-be0de10c2650', 674, 'error_correction', 'B1', 'present_perfect', 'She has been working here since five years.', 'She has been working here for five years.', '[]', NULL, NULL, NULL, NULL, 'Use "for" with a duration (five years). Use "since" with a point in time (since 2020).', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b5bfd738-597e-42d0-bf1f-c8ba8dd0010a', 238, 'gap_fill', 'A2', 'past_simple', 'She ___ (study) French at university when she was young.', 'studied', NULL, NULL, NULL, NULL, NULL, 'Verbs ending in consonant + y: change y to -ied.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b52cf27d-7547-42c4-b639-f716e94f7f7a', 214, 'gap_fill', 'A2', 'present_simple', 'How often ___ you ___ (exercise)?', 'do...exercise', NULL, NULL, NULL, NULL, NULL, 'Frequency questions: How often + do + subject + verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2daa3c9f-41d7-4aa8-a3a7-f9f71a132ba6', 682, 'error_correction', 'A1', 'present_simple', 'She go to school every day.', 'She goes to school every day.', '[]', NULL, NULL, NULL, NULL, 'Third person singular (she/he/it) needs "goes" in the present simple.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1043b62f-accf-44a5-b2c2-dc4a5dabb428', 672, 'error_correction', 'A1', 'present_continuous', 'They is playing football.', 'They are playing football.', '[]', NULL, NULL, NULL, NULL, '"They" takes "are", not "is".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5529b445-ab6a-4554-9208-a07c94fe26c1', 690, 'error_correction', 'A1', 'present_simple', 'We lives in a big house.', 'We live in a big house.', '[]', NULL, NULL, NULL, NULL, '"We" takes the base form "live", not "lives".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Present tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e3dbc4f-8dec-45fc-bec2-6bf8948d7753', 677, 'odd_one_out', 'B1', 'past_participles', 'Which is NOT a past participle?', 'spoke', '["written", "spoke", "played", "broken"]', NULL, NULL, NULL, NULL, '"Spoke" is the past simple. The past participle is "spoken".', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f3dc7038-a6eb-4298-b34c-fb240fce6a06', 226, 'gap_fill', 'A2', 'past_simple', 'I ___ (go) to London last year.', 'went', NULL, NULL, NULL, NULL, NULL, 'Go is irregular: go → went → gone.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a91212c9-39cc-4e49-a553-94cd30c4eb3e', 229, 'gap_fill', 'A2', 'past_simple', '___ you ___ (enjoy) the concert last week?', 'Did...enjoy', NULL, NULL, NULL, NULL, NULL, 'Past simple questions: Did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('23d16345-056c-43ac-bd94-5fb81e5a92dd', 232, 'gap_fill', 'A2', 'past_simple', 'I ___ (not know) the answer, but now I do.', 'didn''t know', NULL, NULL, NULL, NULL, NULL, 'Past simple negative: didn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('807e35d1-4032-4075-ab45-ec63e38f9e78', 237, 'gap_fill', 'A2', 'past_simple', 'I ___ (wake) up late this morning.', 'woke', NULL, '["got"]', 'Got is fine, but uses a different verb.', NULL, NULL, 'Wake is irregular: wake → woke → woken.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7ce5a51f-b014-4e46-8c88-41b85248696d', 227, 'gap_fill', 'A2', 'past_simple', 'She ___ (not see) the film yesterday.', 'didn''t see', NULL, NULL, NULL, NULL, NULL, 'Past simple negative: didn''t + base verb (not the past form).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('80202748-af2b-49fb-a9b9-38f484d48bdc', 230, 'gap_fill', 'A2', 'past_simple', 'He ___ (buy) a new car last month.', 'bought', NULL, NULL, NULL, NULL, NULL, 'Buy is irregular: buy → bought → bought.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('76f224d8-24d7-4dd7-988f-bad379419658', 231, 'gap_fill', 'A2', 'past_simple', 'They ___ (arrive) at the hotel at midnight.', 'arrived', NULL, NULL, NULL, NULL, NULL, 'Regular past simple: add -ed. Verbs ending in -e: just add -d.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d164a468-cd27-4979-8a70-9465c5f8711c', 233, 'gap_fill', 'A2', 'past_simple', 'She ___ (meet) her husband in 2015.', 'met', NULL, NULL, NULL, NULL, NULL, 'Meet is irregular: meet → met → met.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0a57db4c-c3fd-498b-bbd9-183a20c3f877', 234, 'gap_fill', 'A2', 'past_simple', 'The restaurant ___ (open) last Friday.', 'opened', NULL, NULL, NULL, NULL, NULL, 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('00fda781-5c24-4ac8-887f-9752a213e331', 235, 'gap_fill', 'A2', 'past_simple', 'What ___ you ___ (do) last weekend?', 'did...do', NULL, NULL, NULL, NULL, NULL, 'Past simple questions: did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e36e2f4-6aa8-4d82-a911-055bb9b34ccd', 236, 'gap_fill', 'A2', 'past_simple', 'We ___ (eat) pizza for dinner.', 'ate', NULL, NULL, NULL, NULL, NULL, 'Eat is irregular: eat → ate → eaten.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cdffa396-8a0c-405c-ac27-3d2ca837e80c', 240, 'gap_fill', 'A2', 'past_simple', 'The children ___ (play) in the garden all afternoon.', 'played', NULL, NULL, NULL, NULL, NULL, 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b31aa93e-333a-4a9e-afd6-267efa347391', 2, 'gap_fill', 'B1', 'past_simple', 'We ___ (meet) at university in 2015 and we''ve been friends ever since.', 'met', NULL, NULL, NULL, NULL, 'This happened at a specific time in the past', 'Past simple is used for completed actions at a specific time in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d5dc78ac-8dfd-4fc3-8669-b104954ffde0', 7, 'gap_fill', 'B1', 'past_continuous', 'While I ___ (cook) dinner, the phone rang.', 'was cooking', NULL, NULL, NULL, NULL, 'An action in progress when something else happened', 'Past continuous for an action in progress interrupted by another action.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a35f2cea-a2e6-4ff4-8d40-5e6413911412', 12, 'gap_fill', 'B1', 'past_simple', 'I ___ (lose) my wallet last weekend and I still haven''t found it.', 'lost', NULL, NULL, NULL, NULL, 'A completed action at a specific past time', 'Past simple for completed actions at a specific time in the past.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('03257bfb-cfc4-4a33-bbcf-01b870563ade', 13, 'gap_fill', 'B2', 'past_perfect', 'When I arrived at the cinema, the film ___ (already / start).', 'had already started', NULL, NULL, NULL, NULL, 'One past action happened before another', 'Past perfect shows which of two past actions happened first.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cef75ed9-8a09-49c0-9826-ef8a0aaf22c1', 26, 'gap_fill', 'B2', 'be_used_to', 'Don''t worry about the noise. I ___ (be used to / live) in the city centre.', 'am used to living', NULL, NULL, NULL, NULL, 'Be used to + -ing means accustomed to', 'Be used to + -ing means you are accustomed to something.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ed55b121-f4fa-4bbb-a316-c64f9550d966', 25, 'gap_fill', 'B1', 'used_to', 'I ___ (use to / verb) tennis every weekend, but now I prefer swimming.', 'used to play', NULL, NULL, NULL, NULL, 'Past habit that is no longer true', 'Used to + infinitive describes past habits or states that are no longer true.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8fa5f8f1-67b2-48ea-84a8-c593c9e9c9af', 102, 'multiple_choice', 'B1', 'past_simple', 'She ___ her job two months ago.', 'left', '["has left", "left", "leaves", "is leaving"]', NULL, NULL, NULL, NULL, 'Past simple for completed action at specific time (''two months ago'').', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5a41f461-7b6d-40ad-b74e-de540909c975', 114, 'multiple_choice', 'B2', 'past_perfect', 'When I got to the station, the train ___.', 'had already left', '["already left", "has already left", "had already left", "was already leaving"]', NULL, NULL, NULL, NULL, 'Past perfect shows which of two past actions happened first.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1df5395e-8799-4fd9-8c58-ac7e545f906d', 162, 'multiple_choice', 'B1', 'past_continuous', 'What ___ at 8 o''clock last night?', 'were you doing', '["did you do", "were you doing", "have you done", "do you do"]', NULL, NULL, NULL, NULL, 'Past continuous for actions in progress at specific past time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bc4378a6-2760-417b-b6ba-2ebd3d5c1faa', 326, 'multiple_choice', 'A2', 'past_simple', 'I ___ to the cinema last night.', 'went', '["go", "went", "going", "gone"]', NULL, NULL, NULL, NULL, 'Go is irregular: go → went. Use past form for past events.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f6cb27cb-bc71-47ca-b35e-9456d90187af', 327, 'multiple_choice', 'A2', 'past_simple', 'She ___ her keys yesterday.', 'lost', '["lose", "lost", "losed", "losing"]', NULL, NULL, NULL, NULL, 'Lose is irregular: lose → lost → lost.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3f973436-f9e2-486d-a785-bf8ad8303339', 328, 'multiple_choice', 'A2', 'past_simple', '___ you enjoy the party?', 'Did', '["Do", "Did", "Was", "Were"]', NULL, NULL, NULL, NULL, 'Past simple questions: Did + subject + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2e273d4-ba12-42aa-acdb-706a4aecc7ba', 329, 'multiple_choice', 'A2', 'past_simple', 'We ___ TV last evening.', 'watched', '["watch", "watched", "watching", "watches"]', NULL, NULL, NULL, NULL, 'Regular past simple: add -ed to the base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('a450a45b-a5aa-42b1-b290-b9afaab82194', 330, 'multiple_choice', 'A2', 'past_simple', 'He ___ speak to me at the party.', 'didn''t', '["don''t", "doesn''t", "didn''t", "wasn''t"]', NULL, NULL, NULL, NULL, 'Past simple negative: didn''t + base verb.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4d2fe1ea-41d2-4362-af9a-01199d96100f', 331, 'multiple_choice', 'A2', 'past_simple', 'They ___ married in 2018.', 'got', '["get", "got", "getting", "gets"]', NULL, NULL, NULL, NULL, 'Get is irregular: get → got. Past events with specific dates.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('681558b2-1f7d-4e7f-8ec2-2b7aa84216d9', 332, 'multiple_choice', 'A2', 'past_simple', 'I ___ a sandwich for lunch.', 'had', '["have", "has", "had", "having"]', NULL, NULL, NULL, NULL, 'Have is irregular: have → had. Past actions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('64898632-54e0-4552-bd37-0a5e4ec01d90', 333, 'multiple_choice', 'A2', 'past_simple', 'Where ___ you go on holiday?', 'did', '["do", "did", "was", "were"]', NULL, NULL, NULL, NULL, 'Where did you go? Past simple question structure.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9db424c2-c75f-4386-b91e-5d61db331d7e', 605, 'sentence_building', 'B1', 'past_simple', 'El director aprobó el presupuesto ayer por la tarde.', 'the director approved the budget yesterday afternoon', '["the", "director", "approved", "the", "budget", "yesterday", "afternoon", "rejected", "morning", "manage"]', NULL, NULL, NULL, NULL, '"Approved" = aprobó (past simple for completed past action). "Yesterday afternoon" = ayer por la tarde.', '2026-02-12 15:08:31.507807+00', NULL, NULL, 'both', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f2860a5d-f012-4cb3-bbca-5fb0934ed54d', 334, 'multiple_choice', 'A2', 'past_simple', 'She ___ the exam easily.', 'passed', '["pass", "passed", "passing", "past"]', NULL, NULL, NULL, NULL, 'Regular past simple: add -ed.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9eee24a6-1f8d-4705-8ef9-a15e0be391a2', 335, 'multiple_choice', 'A2', 'past_simple', 'I ___ born in 1990.', 'was', '["am", "was", "were", "is"]', NULL, NULL, NULL, NULL, 'Was born: I/he/she was born. We/they were born.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e29b0bb-49ee-45f9-ba22-dcf2692388e5', 336, 'multiple_choice', 'A2', 'past_simple', 'The film ___ at 8 o''clock.', 'started', '["start", "started", "starting", "starts"]', NULL, NULL, NULL, NULL, 'Regular past simple for completed past actions.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bf212e7f-3819-4d65-ae08-db1e863b3b71', 337, 'multiple_choice', 'A2', 'past_simple', 'We ___ a great holiday in Greece.', 'had', '["have", "has", "had", "having"]', NULL, NULL, NULL, NULL, 'Have is irregular: have → had.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('3b886898-2854-4e95-9bdb-c8042ffd664d', 338, 'multiple_choice', 'A2', 'past_simple', 'He ___ me a present for my birthday.', 'gave', '["give", "gave", "given", "giving"]', NULL, NULL, NULL, NULL, 'Give is irregular: give → gave → given.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('423004e5-75d6-4197-b495-2dd829fe588a', 339, 'multiple_choice', 'A2', 'past_simple', '___ there many people at the concert?', 'Were', '["Was", "Were", "Did", "Do"]', NULL, NULL, NULL, NULL, 'There were (plural) / There was (singular) for past.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cfe6478f-18cb-464c-b55c-b1738dd8cd86', 340, 'multiple_choice', 'A2', 'past_simple', 'I ___ to bed early last night because I was tired.', 'went', '["go", "went", "gone", "going"]', NULL, NULL, NULL, NULL, 'Go is irregular: go → went.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5395a807-a009-4c7e-ae2d-35a2a923c499', 110, 'multiple_choice', 'B1', 'used_to', 'When I was a child, I ___ hate vegetables, but now I love them.', 'used to', '["was used to", "am used to", "use to", "used to"]', NULL, NULL, NULL, NULL, 'Used to for past habits that are no longer true.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('36aa0fbf-d098-4c30-9c39-f2c2b5341cd1', 685, 'error_correction', 'B1', 'be_used_to', 'I am used to get up early.', 'I am used to getting up early.', '[]', NULL, NULL, NULL, NULL, '"Be used to" + verb -ing form when talking about habits you''re accustomed to/typically do.', '2026-02-20 19:09:17.848852+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4e5575f7-076d-4fb8-8e43-0e95d78e77ef', 228, 'gap_fill', 'A2', 'past_simple', 'We ___ (have) a great time at the party last night.', 'had', NULL, NULL, NULL, NULL, NULL, 'Have is irregular: have → had → had.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b2fa88fc-b9f3-453b-8f7e-6399b7a77cbb', 769, 'multiple_choice', 'B2', 'be_used_to', '"She ___ working overtime — she does it every week without complaining."', 'is used to', '["is used to", "used to", "was used to", "gets used to"]', NULL, NULL, NULL, NULL, '"Be used to + -ing" means something is familiar and no longer difficult. "Used to + infinitive" describes past habits. She is used to working overtime = it''s normal for her.', '2026-02-25 20:42:59.110341+00', NULL, NULL, 'en', '{"Past tense"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e9c12728-d3f2-419a-90c9-e76411d94c37', 14, 'gap_fill', 'B1', 'future_will', 'Don''t worry, I ___ (help) you with your bags.', 'will help', NULL, NULL, NULL, NULL, 'Spontaneous decision made at the moment of speaking', 'Will is used for spontaneous decisions and offers.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c2ac69f-4735-46f0-a33a-1b2905db0b22', 16, 'gap_fill', 'B2', 'future_continuous', 'This time tomorrow, I ___ (fly) to New York.', 'will be flying', NULL, NULL, NULL, NULL, 'An action in progress at a specific future time', 'Future continuous for actions in progress at a specific time in the future.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('906ba9d9-6cdc-4b11-95c8-5608c1a0d63b', 15, 'gap_fill', 'B1', 'future_going_to', 'Look at those dark clouds! It ___ (rain) soon.', 'is going to rain', NULL, '["is gonna rain"]', '''Gonna'' reflects spoken English, but technically we shouldn''t write like that.', NULL, 'A prediction based on present evidence', 'Going to is used for predictions based on current evidence.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9755771b-01a8-4844-a2f9-1d57f0f8fb02', 104, 'multiple_choice', 'B1', 'future_continuous', 'Don''t call me at 7pm. I ___ dinner then.', 'will be having', '["will have", "will be having", "have", "am having"]', NULL, NULL, NULL, NULL, 'Future continuous for action in progress at specific future time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1e025b16-90a1-4d54-91de-8a9c81e6cd18', 112, 'multiple_choice', 'B1', 'going_to_vs_will', 'Look at those clouds! It ___ rain.', 'is going to', '["will", "is going to", "rains", "is raining"]', NULL, NULL, NULL, NULL, 'Going to for predictions based on present evidence. if you are looking at the clouds, it''s "going to", if you''re predicting without evidence, use "will".', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9783e477-0b8b-4cee-a237-15b025097bd7', 168, 'multiple_choice', 'B2', 'future_perfect', 'By this time next year, I ___ my degree.', 'will have finished', '["will finish", "will have finished", "am finishing", "finish"]', NULL, NULL, NULL, NULL, 'Future perfect for actions completed by a future time.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('96dfc6ff-bd2a-401b-afe8-0d137d988deb', 177, 'multiple_choice', 'B1', 'going_to_intention', 'I ___ study medicine at university.', 'am going to', '["will", "am going to", "go to", "want"]', NULL, NULL, NULL, NULL, 'Going to for intentions and plans. Native speakers might use will in the same way, but in language teaching they push us to use going to for existing plans. ', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('afa4186f-ae15-4650-8f4f-bb295bf90529', 193, 'multiple_choice', 'B1', 'will_spontaneous', 'The phone''s ringing. I ___ it.', 'will answer', '["answer", "will answer", "am answering", "going to answer"]', NULL, NULL, NULL, NULL, 'Will for spontaneous decisions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('1c215f00-ac5f-43af-982e-7f2409b090bf', 154, 'multiple_choice', 'B1', 'future_simple_prediction', 'I think it ___ be sunny tomorrow.', 'will', '["is", "will", "is going to", "can"]', NULL, NULL, NULL, NULL, 'Will for predictions based on opinion (with ''think''). Contrast with going to for predictions based on evidence.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('94aa452d-905a-40a0-9cec-6e476d1249cc', 250, 'gap_fill', 'A2', 'articles', 'I love ___ chocolate.', 'no article', NULL, NULL, NULL, NULL, NULL, 'No article when talking about things in general.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('091d411a-6295-4eca-9c40-78c2304814aa', 241, 'gap_fill', 'A1', 'articles', 'She is ___ teacher.', 'a', NULL, NULL, NULL, NULL, NULL, 'Use a before singular countable nouns starting with a consonant sound.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('15ef2972-928c-4189-ac04-1ebdbda2f36c', 242, 'gap_fill', 'A1', 'articles', 'He is ___ engineer.', 'an', NULL, NULL, NULL, NULL, NULL, 'Use an before words starting with a vowel sound: an engineer.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f85e3e64-9875-495d-9c30-52a184238f36', 243, 'gap_fill', 'A2', 'articles', 'I want to visit ___ Eiffel Tower.', 'the', NULL, NULL, NULL, NULL, NULL, 'Use the for famous landmarks and unique things.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2e063dbd-85c6-4845-b456-5e8f334ac20f', 244, 'gap_fill', 'A1', 'articles', 'Can I have ___ glass of water?', 'a', NULL, NULL, NULL, NULL, NULL, 'Use a when asking for one of something.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b7d12078-5a5e-4f64-a21b-910d409c5ed7', 245, 'gap_fill', 'A2', 'articles', '___ Amazon is the longest river in South America.', 'The', NULL, NULL, NULL, NULL, NULL, 'Use the with rivers, oceans, and mountain ranges.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('33ab48ed-783f-43a5-875a-05e840645175', 246, 'gap_fill', 'A1', 'articles', 'There is ___ apple on the table.', 'an', NULL, NULL, NULL, NULL, NULL, 'Use an before words starting with a vowel sound.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5d86e507-ad3c-43fa-b505-3faa337f7712', 248, 'gap_fill', 'A2', 'articles', 'She plays ___ guitar very well.', 'the', NULL, NULL, NULL, NULL, NULL, 'Use the with musical instruments: play the guitar, play the piano.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('749beca2-41fa-458d-b9a1-43c68ecf9fe3', 249, 'gap_fill', 'A1', 'articles', 'Is there ___ bank near here?', 'a', NULL, NULL, NULL, NULL, NULL, 'Use a when talking about one of many (any bank).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('456e70e4-0826-497c-b84a-0748a54952f3', 41, 'gap_fill', 'B1', 'articles', 'I need ___ (a / an / the) new phone. Mine is broken.', 'a', NULL, NULL, NULL, NULL, 'Indefinite article for unspecified things', 'A/an is used when mentioning something for the first time or when it''s not specific.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('84ac64a4-264b-4f57-bdd2-c6b5a5d4e5e9', 42, 'gap_fill', 'B1', 'articles', 'Could you pass me ___ (a / an / the) salt, please?', 'the', NULL, NULL, NULL, NULL, 'Definite article when both know which one', 'The is used when both speaker and listener know which specific thing is being referred to.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('0546f1fb-09fc-4f05-8909-2b63ce0dec30', 113, 'multiple_choice', 'B1', 'articles', 'I play ___ piano in my free time.', 'the', '["a", "an", "the", "-"]', NULL, NULL, NULL, NULL, 'Musical instruments take ''the''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f8f731fb-4c3d-4657-b58a-f7ab533c35c2', 147, 'multiple_choice', 'B1', 'articles_geographical', 'Have you ever been to ___ United States?', 'the', '["a", "an", "the", "-"]', NULL, NULL, NULL, NULL, 'The with country names containing plural nouns (States, Emirates, etc.).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b2af8f7c-ad98-45b0-9288-daf0a2027df1', 247, 'gap_fill', 'A2', 'articles', 'I usually have ___ breakfast at 8 am.', 'no article', NULL, NULL, NULL, '["my"]', NULL, 'No article with meals: have breakfast, have lunch, have dinner.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e8a2f4a6-9366-415e-aa62-b8b9d6c51c7f', 43, 'gap_fill', 'B2', 'articles', 'I play ___ (a / an / the / -) piano, but my sister plays ___ (a / an / the / -) tennis.', 'the, -', NULL, NULL, NULL, NULL, 'Musical instruments use ''the'', sports have no article', 'Musical instruments take ''the'', but sports do not use an article.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Article}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7c37832a-0f20-452b-8774-19c145d5bd69', 87, 'gap_fill', 'B1', 'both_neither_either', '___ (Both / Neither / Either) of my brothers live abroad.', 'both', NULL, NULL, NULL, NULL, 'Both means the two together.', 'Both means the two together, neither is the negative here. ', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f03a3726-4999-468a-9225-4262a3bf7f96', 88, 'gap_fill', 'B1', 'both_neither_either', '___ (Both / Neither / Either) restaurant looks good. You choose.', 'either', NULL, NULL, NULL, NULL, 'Either means one or the other (it doesn''t matter which)', 'Either means one or the other, when it doesn''t matter which. Neither is the negative form. Good luck eating in those restaurants... ', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9a5caa2b-5125-4d80-a294-95dbb2a632dd', 44, 'gap_fill', 'B1', 'quantifiers', 'There isn''t ___ (many / much) milk left. We need to buy some.', 'much', NULL, NULL, NULL, NULL, 'Much is used with uncountable nouns', 'Much is used with uncountable nouns in negative sentences and questions.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4ff4e7ad-b770-4379-a2c8-a777789ce45a', 45, 'gap_fill', 'B1', 'quantifiers', 'How ___ (many / much) people are coming to the party?', 'many', NULL, NULL, NULL, NULL, 'Many is used with countable nouns', 'Many is used with countable nouns.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('13efa99e-c3ad-4284-8851-2d001743e11f', 46, 'gap_fill', 'B2', 'quantifiers', 'There are ___ (a few / a little) problems we need to discuss.', 'a few', NULL, NULL, NULL, NULL, 'A few is used with countable nouns', 'A few is used with countable nouns to mean ''some''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b678ad5b-2aed-4d25-98af-2e4c9c08ea22', 47, 'gap_fill', 'B2', 'quantifiers', 'We have ___ (a few / a little) time before the meeting starts.', 'a little', NULL, NULL, NULL, NULL, 'A little is used with uncountable nouns', 'A little is used with uncountable nouns to mean ''some''.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('17b29d2a-b85f-416d-9576-3a59f0254c02', 115, 'multiple_choice', 'B1', 'quantifiers', 'There aren''t ___ people at the party yet.', 'many', '["much", "many", "a lot", "lots"]', NULL, NULL, NULL, NULL, 'Many with countable nouns in negative sentences.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('7a0daf4c-909c-4f4a-a91d-0b9d3bdf0bed', 164, 'multiple_choice', 'B1', 'quantifiers_some_any', 'We don''t have ___ milk. Can you buy some?', 'any', '["some", "any", "a", "one"]', NULL, NULL, NULL, NULL, 'Any in negative sentences and questions.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bc3fa13d-7c7f-471a-9ed1-60b81c2c3294', 185, 'multiple_choice', 'B1', 'other_another', 'This shirt is too small. Can I try ___ one?', 'another', '["other", "another", "these other", "others"]', NULL, NULL, NULL, NULL, 'Another = one more (indefinite).', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e4735508-1259-415e-8877-d1d1119ba1c2', 148, 'multiple_choice', 'B1', 'both_neither_either', '___ of my parents speak English.', 'Both', '["One", "Both", "Either", "All"]', NULL, NULL, NULL, NULL, 'Both means the two together.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Quantifier}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('29ba72dd-3875-4e8f-af82-d11027c05ff6', 83, 'gap_fill', 'B1', 'reflexive_pronouns', 'Be careful! Don''t hurt ___ (you).', 'yourself', NULL, NULL, NULL, NULL, 'Reflexive pronoun', 'Use reflexive pronouns when the subject and object are the same.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('69512d4c-08f9-4943-b79e-8e46cbb68830', 84, 'gap_fill', 'B1', 'reflexive_pronouns', 'She taught ___ (her) to play the piano.', 'herself', NULL, NULL, NULL, NULL, 'Reflexive pronoun', 'Reflexive pronouns show that someone does something to/for themselves.', '2026-02-07 19:21:28.645851+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('dfbbfa36-71fd-4c9c-a42f-1872688d960d', 150, 'multiple_choice', 'B1', 'possessive_pronouns', 'This book is ___. I bought it yesterday.', 'mine', '["my", "mine", "me", "I"]', NULL, NULL, NULL, NULL, 'Possessive pronouns stand alone without a noun.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ffab7b80-b058-4740-8f99-a8cd0bab7d2d', 371, 'multiple_choice', 'A1', 'pronouns', 'This is my brother. ___ name is Carlos.', 'His', '["Its", "Her", "His", "He"]', NULL, NULL, NULL, NULL, 'His = belonging to a male person (my brother).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('71b4936e-ff7c-4ce7-a2ae-4103bca5a01b', 372, 'multiple_choice', 'A1', 'pronouns', 'I love my cats. ___ are very friendly.', 'They', '["He", "She", "It", "They"]', NULL, NULL, NULL, NULL, 'We don''t usually use it for animals.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('24494d0d-205a-4e04-80b1-a15cea338ae7', 373, 'multiple_choice', 'A1', 'pronouns', 'That book is ___. Give it back!', 'mine', '["my", "me", "mine", "I"]', NULL, NULL, NULL, NULL, 'Mine = possessive pronoun (it belongs to me).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('58f5e955-0a80-4d62-ba72-db9056baa1f3', 374, 'multiple_choice', 'A1', 'pronouns', 'Can you help ___? I don''t understand.', 'me', '["I", "my", "mine", "me"]', NULL, NULL, NULL, NULL, 'Me = object pronoun after verbs: help me, tell me.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8a2fd453-aaec-4376-9000-fe58202a128d', 375, 'multiple_choice', 'A2', 'pronouns', 'These are ___ shoes, not yours.', 'my', '["I", "me", "my", "mine"]', NULL, NULL, NULL, NULL, 'My + noun: my shoes, my house, my name.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('48342350-d997-4301-8b00-de22afa038a0', 376, 'multiple_choice', 'A1', 'pronouns', 'Maria is Italian. ___ is from Rome.', 'She', '["He", "She", "Her", "His"]', NULL, NULL, NULL, NULL, 'She = subject pronoun for a female person.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('50f68c91-afb2-4b57-903f-4a140ab64009', 377, 'multiple_choice', 'A2', 'pronouns', 'Is this ___ car or theirs?', 'your', '["you", "your", "yours", "yourself"]', NULL, NULL, NULL, NULL, 'Your + noun: your car. Yours without a noun.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b5171798-5348-4ed2-83c2-56c97260be58', 378, 'multiple_choice', 'A1', 'pronouns', 'We live in Palma. ___ house is near the beach.', 'Our', '["We", "Us", "Our", "Ours"]', NULL, NULL, NULL, NULL, 'Our + noun: Our house, our school.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('02f52afd-b702-4994-972d-3dc0ffc5950f', 379, 'multiple_choice', 'A2', 'pronouns', 'The children did it by ___.', 'themselves', '["they", "their", "theirs", "themselves"]', NULL, NULL, NULL, NULL, 'By themselves = without help (reflexive pronoun).', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c238f8a5-3b97-409e-813b-f945217986eb', 380, 'multiple_choice', 'A1', 'pronouns', 'Look at ___! She''s dancing!', 'her', '["she", "her", "hers", "herself"]', NULL, NULL, NULL, NULL, 'Her = object pronoun: Look at her, tell her, call her.', '2026-02-11 19:05:58.524191+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('75e965d3-ffa1-4260-8a5c-c62496b0f4e8', 167, 'multiple_choice', 'B1', 'reflexive_pronouns', 'Did you enjoy ___ at the party?', 'yourself', '["you", "yourself", "yours", "your"]', NULL, NULL, NULL, NULL, 'Reflexive pronoun for ''enjoy yourself''.', '2026-02-07 19:25:27.652442+00', NULL, NULL, 'en', '{Pronoun}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('13fabdc7-a4cd-4613-9a2a-38f13ecffd44', 1190, 'sentence_building', 'A1', 'routines', 'Cenan a las ocho.', 'They eat dinner at eight o''clock.', '["they", "eat", "dinner", "at", "eight", "o''clock", "have", "lunch", "seven", "eating"]', NULL, NULL, NULL, NULL, 'Use the present simple for a fixed daily routine. Eat dinner and have dinner are both correct.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e3a25aa1-69ff-4362-8e4d-334e9a4a3ad9', 1191, 'sentence_building', 'A2', 'routines', 'A menudo leo antes de dormir.', 'I often read before going to sleep.', '["I", "often", "read", "before", "going", "to", "sleep", "after", "write", "fall"]', NULL, NULL, NULL, NULL, 'Before is a preposition here, so it is followed by a gerund: before going.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('df903c2b-8e60-4ba6-8b4c-0915538268e6', 1192, 'sentence_building', 'A1', 'routines', 'Mi madre cocina la cena todas las tardes.', 'My mother cooks dinner every evening.', '["my", "mother", "cooks", "dinner", "every", "evening", "cook", "lunch", "morning", "his"]', NULL, NULL, NULL, NULL, 'Third person singular (he/she/it) adds -s to the verb in the present simple: cooks, not cook.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('149485b9-e79c-40b0-bb34-22418822618e', 1193, 'sentence_building', 'A2', 'routines', '¿Siempre coges el mismo camino al trabajo?', 'Do you always take the same route to work?', '["do", "you", "always", "take", "the", "same", "route", "to", "work", "go", "usual", "different"]', NULL, NULL, NULL, NULL, 'Form present simple questions with Do/Does + subject + infinitive. Always goes after the subject.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('8cc4581b-5c4f-4a22-b2b9-b7eee51a6598', 1194, 'sentence_building', 'A2', 'routines', 'Ella sale a caminar después de comer.', 'She goes for a walk after lunch.', '["she", "goes", "for", "a", "walk", "after", "lunch", "go", "before", "run", "dinner"]', NULL, NULL, NULL, NULL, 'Go for a walk is a fixed expression. Third person singular: goes, not go.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ad8608a1-033c-46ee-922f-51dd4f7c9dc0', 659, 'sentence_building', 'B2', 'wish_clauses', 'Ojalá me lo hubieras dicho antes.', 'I wish you had told me sooner', '["I", "wish", "you", "had", "told", "me", "sooner", "would", "have", "tell", "after", "later"]', NULL, NULL, NULL, NULL, 'I wish + past perfect: expressing regret about something that happened (or didn''t happen) in the past.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Wish & regret"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5e5ac85b-5662-4975-931a-d0fde7164cb9', 1196, 'sentence_building', 'B1', 'routines', 'Lleva años siguiendo la misma rutina.', 'She has been following the same routine for years.', '["she", "has", "been", "following", "the", "same", "routine", "for", "years", "follow", "since", "doing", "daily"]', NULL, NULL, NULL, NULL, 'The present perfect continuous (has been following) describes a habit that started in the past and continues now. Use for, not since, with a period of time.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b09fcafc-f49a-477a-8695-dcd9d12544ed', 1197, 'sentence_building', 'B2', 'routines', 'Estoy intentando adquirir el hábito de hacer ejercicio con regularidad.', 'I am trying to get into the habit of exercising regularly.', '["I", "am", "trying", "to", "get", "into", "the", "habit", "of", "exercising", "regularly", "exercise", "become", "build"]', NULL, NULL, NULL, NULL, 'Get into the habit of + gerund is a useful phrase for describing a new routine being established.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6e10fde0-0cde-49c5-82c5-0db33958f056', 1198, 'sentence_building', 'B1', 'routines', 'A la mayoría de la gente le resulta difícil cambiar sus hábitos diarios.', 'Most people find it hard to change their daily habits.', '["most", "people", "find", "it", "hard", "to", "change", "their", "daily", "habits", "habit", "difficult", "routine", "very"]', NULL, NULL, NULL, NULL, 'Find it + adjective + to do something is a common structure: find it hard to, find it easy to, find it difficult to.', '2026-03-16 09:04:17.945706+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fc950e85-73c2-4213-ab44-04d17a04f076', 646, 'sentence_building', 'A2', 'going_to_future', '', 'we are going to visit our grandparents next weekend', '["we", "are", "going", "to", "visit", "our", "grandparents", "next", "weekend", "visited", "last", "mine"]', '["next weekend we are going to visit our grandparents.", "we are going to our grandparents next weekend"]', 'If you put the time phrase at the end it is more natural. The ''visit'' isn''t necessary in this sentence, but it is normally used there.', NULL, NULL, 'Going to future: subject + be + going to + verb for planned actions.', '2026-02-17 09:58:54.170896+00', NULL, NULL, 'en', '{"Future form"}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('f608db54-310f-4b4b-b519-1604db620150', 1253, 'gap_fill', 'C1', 'business_phrasal_verbs', 'The new initiative was _____ as a pilot scheme in three regions before a national rollout.', 'rolled out', '[]', NULL, NULL, NULL, NULL, 'Roll out means to launch or introduce a product, scheme, or initiative in stages. The noun rollout is common in business contexts.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('c3157909-b8be-46d3-8d25-5b39462a217c', 1254, 'gap_fill', 'C2', 'business_phrasal_verbs', 'The board is _____ its options before committing to a course of action.', 'weighing up', '[]', NULL, NULL, NULL, NULL, 'Weigh up means to carefully consider the advantages and disadvantages of different options before deciding. Compare: evaluate, assess, deliberate over.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5d3d69c3-deb9-4418-b413-1dd85849e9a5', 1255, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _____ the TV? It''s too loud.', 'turn down', '["turn down", "turn off", "turn up", "turn on"]', NULL, NULL, NULL, NULL, 'Turn down means to reduce the volume or level of something. Turn up means the opposite — to increase it.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d84369bb-d11a-4d75-9cdb-73ae1637660d', 1256, 'multiple_choice', 'A1', 'phrasal_verbs', 'I need to _____ some words in the dictionary.', 'look up', '["look up", "look out", "look after", "look into"]', NULL, NULL, NULL, NULL, 'Look up means to search for information in a reference source such as a dictionary or the internet.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('14d592f5-5069-4c65-b82a-c332e8fbfc65', 1257, 'multiple_choice', 'A2', 'phrasal_verbs', 'She _____ her little brother while their parents were away.', 'looked after', '["looked after", "looked up", "looked into", "looked over"]', NULL, NULL, NULL, NULL, 'Look after means to take care of someone or something.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d3798a08-30f3-4dd9-a3fb-d2bb655101a2', 1258, 'multiple_choice', 'A1', 'phrasal_verbs', 'Don''t forget to _____ the lights when you leave.', 'turn off', '["turn off", "turn on", "turn up", "turn down"]', NULL, NULL, NULL, NULL, 'Turn off means to stop a device or light from working. The opposite is turn on.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5c87ce78-90f6-46c6-9907-c396f86b5b80', 1260, 'multiple_choice', 'A1', 'phrasal_verbs', 'What time do you _____ in the morning?', 'get up', '["get up", "get on", "get out", "get in"]', NULL, NULL, NULL, NULL, 'Get up means to rise from bed in the morning. Compare: wake up (to stop sleeping) and get up (to physically leave the bed).', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2121d310-da0d-41c9-9440-45f07a949356', 1261, 'multiple_choice', 'A2', 'phrasal_verbs', 'We''re _____ of milk — can you buy some?', 'running out', '["running out", "running off", "running over", "running up"]', NULL, NULL, NULL, NULL, 'Run out of means to have no more of something left. Compare: we''ve run out of time / money / ideas.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('ec3483fd-df84-45af-9819-ede7e213a644', 1262, 'multiple_choice', 'A1', 'phrasal_verbs', 'Can you _____ the music? I can''t hear it properly.', 'turn up', '["turn up", "turn on", "turn off", "turn down"]', NULL, NULL, NULL, NULL, 'Turn up means to increase the volume or level of something. The opposite is turn down.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('cf69316f-5699-462d-9850-8453e1329d18', 1264, 'multiple_choice', 'A2', 'phrasal_verbs', 'The flight was _____ by two hours because of bad weather.', 'held up', '["held up", "held on", "held out", "held back"]', NULL, NULL, NULL, NULL, 'Hold up means to delay something or someone. Compare: the traffic held us up / the project was held up by poor weather.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('6ab48fb9-ba06-45dc-ab82-75a25e6c38da', 1242, 'gap_fill', 'B1', 'business_phrasal_verbs', 'The project has been _____ because of a lack of funding.', 'put on the shelf', '[]', NULL, NULL, NULL, NULL, 'Put on the shelf (or shelve) means to postpone or abandon a project indefinitely. It implies the idea has been set aside for later — or permanently.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('74b64e51-177e-4ed0-ad62-3b180b078f3a', 1259, 'multiple_choice', 'A2', 'phrasal_verbs', 'He _____ going to the gym last month. It''s a pity.', 'gave up', '["gave up", "gave in", "gave out", "gave away"]', NULL, NULL, NULL, NULL, 'Give up means to stop doing something, especially a habit. Compare: quit. It can be positive or negative.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('b52dd337-cacd-41da-9cf9-8bc05b963f7a', 1263, 'multiple_choice', 'A2', 'phrasal_verbs', 'I _____ an old friend in the supermarket yesterday.', 'into', '["ran into", "ran over", "ran after", "ran out of"]', NULL, NULL, NULL, NULL, 'Run into someone means to meet them unexpectedly. Compare: bump into, come across.', '2026-03-18 19:58:52.376507+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('518b1589-4031-4ab4-9bee-96b893302450', 1456, 'multiple_choice', 'B1', 'phrasal_verbs', 'She found it hard to _____ her grandmother''s death.', 'get over', '["get over", "get through", "get by", "get away"]', NULL, NULL, NULL, NULL, 'Get over means to recover from something upsetting or difficult, such as an illness, loss, or disappointment.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fe8de01a-df3a-4b09-b15a-4c962e08d03b', 1457, 'multiple_choice', 'B1', 'phrasal_verbs', 'He _____ running last year and now he does a 5k every morning.', 'took up', '["took up", "took on", "took off", "took over"]', NULL, NULL, NULL, NULL, 'Take up means to start a new hobby, sport, or activity.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('44174638-fe46-4ed9-8b7f-4980f0cbda34', 1458, 'multiple_choice', 'B1', 'phrasal_verbs', 'The heating _____ on the coldest night of the year.', 'broke down', '["broke down", "broke up", "broke off", "broke out"]', NULL, NULL, NULL, NULL, 'Break down means to stop working. It can also describe losing emotional control or the failure of a relationship or negotiation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('116e7218-9f00-4d91-a315-13cd7682beab', 1459, 'multiple_choice', 'B1', 'phrasal_verbs', 'Despite the interruptions, she _____ with her presentation.', 'carried on', '["carried on", "carried out", "carried off", "carried over"]', NULL, NULL, NULL, NULL, 'Carry on means to continue doing something despite difficulties or interruptions.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bdccfbd9-790c-4eeb-a426-55be107e6115', 1460, 'multiple_choice', 'B1', 'phrasal_verbs', 'Do you _____ well with your new colleagues?', 'get along', '["get along", "get over", "get through", "get behind"]', NULL, NULL, NULL, NULL, 'Get along (with someone) means to have a friendly, harmonious relationship with them.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('338b08ab-b652-43aa-8c64-bda810d0aa9b', 1461, 'gap_fill', 'B1', 'phrasal_verbs', 'She worked hard to _____ for the time she had missed during her illness.', 'make up', '[]', NULL, NULL, NULL, NULL, 'Make up for means to compensate for something — to do something that reduces the negative effect of an earlier action or situation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e50fc8db-a86c-4ca3-bb3c-69bdfd52866b', 1463, 'gap_fill', 'B1', 'phrasal_verbs', 'I spent all weekend trying to _____ with the work I missed while I was ill.', 'catch up', '[]', NULL, NULL, NULL, NULL, 'Catch up (with) means to reach the same level or position as someone else, or to deal with work that has accumulated.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('65f4c201-6d35-42af-946a-40ed98f933ad', 1464, 'gap_fill', 'B1', 'phrasal_verbs', 'His confidence has really _____ since he started the new job.', 'built up', '[]', NULL, NULL, NULL, NULL, 'Build up means to gradually increase or develop. It can describe confidence, pressure, tension, or a reputation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9279ffa2-1f78-4361-be52-581c13916e7e', 1462, 'gap_fill', 'B1', 'phrasal_verbs', 'Previously he _____ from expressing his opinions in meetings due to his shyness.', 'held back', '[]', NULL, NULL, NULL, NULL, 'Hold back can mean to prevent someone from progressing or expressing themselves. It can also mean to deliberately withhold something.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('2d15d540-0e99-40d2-b706-35049b65ba1f', 1469, 'multiple_choice', 'B2', 'phrasal_verbs', 'She''s been _____ a very difficult time since she lost her job.', 'going through', '["going through", "going over", "going along", "going off"]', NULL, NULL, NULL, NULL, 'Go through means to experience a difficult or unpleasant period or situation.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('d7c80cac-f607-4913-91b3-ef1feddbd3ff', 1470, 'multiple_choice', 'B2', 'phrasal_verbs', 'We need to _____ some money each month for the holiday.', 'set aside', '["set aside", "set up", "set off", "set out"]', NULL, NULL, NULL, NULL, 'Set aside means to reserve time, money, or resources for a specific purpose.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('297b9fe3-16fe-468f-abb9-2a8130a0fe6a', 1471, 'gap_fill', 'B2', 'phrasal_verbs', 'It''s hard to _____ with all the changes in technology — something new appears every week.', 'keep up', '[]', NULL, NULL, NULL, NULL, 'Keep up (with) means to maintain the same pace or level as something or someone that is advancing or changing.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e33e5886-b158-422f-a6cc-edc4bc6c9d7b', 1472, 'gap_fill', 'B2', 'phrasal_verbs', 'The company is slowly _____ its older product lines in favour of digital services.', 'phasing out', '[]', NULL, NULL, NULL, NULL, 'Phase out means to gradually discontinue or eliminate something over a period of time. Compare: wind down, discontinue, do away with.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('225845fd-c230-4cb8-b2ba-59e0fb18d92a', 1473, 'gap_fill', 'B2', 'phrasal_verbs', 'She _____ a convincing excuse to avoid going to the party.', 'made up', '[]', NULL, NULL, NULL, NULL, 'Make up can mean to invent a story, excuse, or explanation — often one that is not true. It can also mean to reconcile after an argument.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('fe68da6f-8dfc-41f3-8411-9ac2244406a4', 1474, 'gap_fill', 'B2', 'phrasal_verbs', 'The situation _____ exactly as she had predicted — nobody listened and the project failed.', 'played out', '[]', NULL, NULL, NULL, NULL, 'Play out means to develop or unfold, especially in a way that was anticipated. It describes how a situation or event progresses over time.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('4a474b40-9654-4b4c-a433-9b1dc7ad05f8', 1475, 'gap_fill', 'B2', 'phrasal_verbs', 'The new manager asked the team to _____ a detailed proposal by Friday.', 'draw up', '[]', NULL, NULL, NULL, NULL, 'Draw up means to prepare a formal document, plan, or list. Compare: put together, draft, produce.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('193bebf6-cb22-4d20-93a0-b9d317bb5aa8', 1476, 'gap_fill', 'C1', 'phrasal_verbs', 'The committee spent two hours trying to _____ the list of candidates to a final shortlist of three.', 'narrow down', '[]', NULL, NULL, NULL, NULL, 'Narrow down means to reduce a large number of options or possibilities to a smaller, more manageable set.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('30ddc3e9-9836-4140-a5b2-7486cbf0fa51', 1477, 'gap_fill', 'C1', 'phrasal_verbs', 'Despite enormous pressure to resign, the minister _____ and refused to leave office.', 'held out', '[]', NULL, NULL, NULL, NULL, 'Hold out means to resist pressure or continue to endure a difficult situation without giving in. Compare: stand firm, hang on.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('9d8c39f6-827a-4d3b-9920-5384b07e14f7', 1478, 'gap_fill', 'C1', 'phrasal_verbs', 'The company has been looking to _____ into new markets in South-East Asia.', 'branch out', '[]', NULL, NULL, NULL, NULL, 'Branch out means to expand into new areas of activity, especially in business. Compare: diversify, move into, expand.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5098bdf7-750b-4f77-8443-e273a28a24a1', 1481, 'gap_fill', 'C2', 'phrasal_verbs', 'The report accused the government of trying to _____ the deeper structural problems with a series of short-term fixes.', 'paper over', '[]', NULL, NULL, NULL, NULL, 'Paper over means to conceal or disguise a problem without actually solving it. Compare: gloss over, brush under the carpet.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('27df9556-4ca5-44c7-9ae3-1c764cf878ef', 1482, 'gap_fill', 'C2', 'phrasal_verbs', 'The chairman tried to _____ the embarrassing findings in his annual report, but journalists noticed immediately.', 'gloss over', '[]', NULL, NULL, NULL, NULL, 'Gloss over means to treat something briefly or superficially in order to avoid drawing attention to it. Compare: paper over, brush aside.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('70d47335-7465-40f4-8f49-928b3642a086', 1465, 'gap_fill', 'B1', 'phrasal_verbs', 'I don''t think it will work — we need to _____ this plan more carefully.', 'think through', '[]', NULL, NULL, NULL, NULL, 'Think through means to consider all aspects of something carefully before deciding. Compare: think over, work out, plan out.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('5cb8b271-e4d8-40b4-8da3-b65e43dbd7d6', 1468, 'multiple_choice', 'B2', 'phrasal_verbs', 'Can you _____ the invoice I sent? I want to make sure the figures are right.', 'go over', '["go over", "go on", "go along", "go back"]', NULL, NULL, NULL, NULL, 'Go over means to check or review something carefully. Compare: look over, go through.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('61ba5ef5-b721-473b-adde-f48d43fb1932', 1479, 'gap_fill', 'C1', 'phrasal_verbs', 'In her speech, she _____  decades of personal experience to make her argument compelling.', 'drew on', '[]', NULL, NULL, NULL, NULL, 'Draw on means to make use of a source of knowledge, experience, or skill. Compare: call on, tap into, leverage.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('bd6cf602-dd75-47da-b5d2-9039ca9f4080', 1480, 'gap_fill', 'C1', 'phrasal_verbs', 'The launch has been _____  to take advantage of the pre-Christmas market.', 'brought forward', '[]', NULL, NULL, NULL, NULL, 'Bring forward means to move an event or deadline to an earlier date. The opposite is push back.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('510450f3-8d37-41ec-9523-c911154f2e75', 1483, 'gap_fill', 'C2', 'phrasal_verbs', 'The evidence presented at the trial fully _____  the prosecution''s original theory.', 'bore out', '[]', NULL, NULL, NULL, NULL, 'Bear out means to confirm or support a claim, theory, or suspicion. Compare: corroborate, back up, substantiate.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('e1899ff4-8ce7-4a32-9314-7c85bf5c9f53', 1484, 'gap_fill', 'C2', 'phrasal_verbs', 'She has a remarkable ability to _____ the most important information from lengthy and complex reports.', 'draw out', '[]', NULL, NULL, NULL, NULL, 'Draw out means to extract the most essential or important elements from a large body of material. Compare: extract, distil (from), boil down to.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
INSERT INTO public.question_bank (id, question_number, type, level, topic, question, correct_answer, options, informal_accepted, informal_feedback, acceptable_alternatives, hint, explanation, created_at, sequence_group, sequence_order, language, tags) VALUES ('466dd080-4775-44fb-a3e3-92c737250c18', 1485, 'gap_fill', 'C2', 'phrasal_verbs', 'His early struggles as an immigrant _____  a fierce determination that defined his entire career.', 'fed into', '[]', NULL, NULL, NULL, NULL, 'Feed into means to contribute to or influence something larger. It describes how one factor or experience becomes part of, and shapes, something else.', '2026-03-18 20:30:31.624632+00', NULL, NULL, 'en', '{}');
